def _expanded_axis_limit(current_limit, values, scale='linear',
                         edge_fraction=0.025, padding_fraction=0.055):
    """Pad only sides containing a marker close to the current axes boundary."""
    values = np.asarray(values, dtype=float).ravel()
    values = values[np.isfinite(values)]
    if values.size == 0:
        return current_limit
    first, second = map(float, current_limit)
    inverted = first > second
    lower, upper = (second, first) if inverted else (first, second)
    if scale == 'log' and lower > 0.0:
        log_lower, log_upper = np.log(lower), np.log(upper)
        span = max(log_upper - log_lower, np.finfo(float).eps)
        positive = values[values > 0.0]
        if positive.size:
            data_lower = float(np.min(np.log(positive)))
            data_upper = float(np.max(np.log(positive)))
            if data_lower <= log_lower + edge_fraction * span:
                log_lower = min(log_lower, data_lower - padding_fraction * span)
            if data_upper >= log_upper - edge_fraction * span:
                log_upper = max(log_upper, data_upper + padding_fraction * span)
            lower, upper = float(np.exp(log_lower)), float(np.exp(log_upper))
    else:
        span = max(upper - lower, np.finfo(float).eps)
        data_lower, data_upper = float(np.min(values)), float(np.max(values))
        if data_lower <= lower + edge_fraction * span:
            lower = min(lower, data_lower - padding_fraction * span)
        if data_upper >= upper - edge_fraction * span:
            upper = max(upper, data_upper + padding_fraction * span)
    return (upper, lower) if inverted else (lower, upper)


def _marked_artist_coordinates(axis):
    """Collect marker coordinates in data space without including image pixels."""
    x_values, y_values, z_values = [], [], []
    for collection in axis.collections:
        collection.set_clip_on(False)
        if hasattr(collection, '_offsets3d'):
            x_data, y_data, z_data = collection._offsets3d
            x_values.extend(np.asarray(x_data, dtype=float).ravel())
            y_values.extend(np.asarray(y_data, dtype=float).ravel())
            z_values.extend(np.asarray(z_data, dtype=float).ravel())
        elif isinstance(collection, PathCollection):
            offsets = np.ma.filled(collection.get_offsets(), np.nan)
            if np.ndim(offsets) == 2 and np.shape(offsets)[1] >= 2:
                try:
                    display = collection.get_offset_transform().transform(offsets[:, :2])
                    data = axis.transData.inverted().transform(display)
                except (ValueError, TypeError, AttributeError):
                    data = np.asarray(offsets[:, :2], dtype=float)
                x_values.extend(data[:, 0])
                y_values.extend(data[:, 1])
    for line in axis.lines:
        marker = line.get_marker()
        if marker in (None, 'None', '', ' '):
            continue
        line.set_clip_on(False)
        if hasattr(line, 'get_data_3d'):
            x_data, y_data, z_data = line.get_data_3d()
            z_values.extend(np.asarray(z_data, dtype=float).ravel())
        else:
            x_data, y_data = line.get_data()
        x_values.extend(np.asarray(x_data, dtype=float).ravel())
        y_values.extend(np.asarray(y_data, dtype=float).ravel())
    return x_values, y_values, z_values


def _wrap_title_artist(title, available_pixels, minimum_characters=24):
    if title is None or not title.get_visible() or not title.get_text().strip():
        return
    if not hasattr(title, '_adaptive_original_text'):
        title._adaptive_original_text = title.get_text()
    original = title._adaptive_original_text
    font_size = max(float(title.get_fontsize()), 1.0)
    original_length = max((len(line) for line in original.splitlines()), default=0)
    if original_length > 90:
        font_size = min(font_size, 10.0)
    elif original_length > 58:
        font_size = min(font_size, 11.0)
    elif original_length > 42:
        font_size = min(font_size, 12.5)
    title.set_fontsize(font_size)
    character_width = max(4.0, 0.56 * font_size)
    width = max(int(minimum_characters), int(available_pixels / character_width))
    wrapped = '\n'.join(
        textwrap.fill(
            paragraph, width=width, break_long_words=False,
            break_on_hyphens=False,
        )
        for paragraph in original.splitlines()
    )
    title.set_text(wrapped)
    title.set_wrap(True)
    title.set_clip_on(False)
    line_count = max(1, wrapped.count('\n') + 1)
    if line_count >= 3:
        title.set_fontsize(max(8.0, min(font_size, 12.0)))


def _separate_overlapping_axis_text(axis, renderer, padding_pixels=3.0):
    """Move colliding annotations toward free axes space in display coordinates."""
    texts = [
        artist for artist in axis.texts
        if artist.get_visible() and artist.get_text().strip()
        and not getattr(artist, '_adaptive_position_adjusted', False)
    ]
    placed = []
    axis_box = axis.get_window_extent(renderer=renderer)
    fixed_title_boxes = []
    for title in (axis.title, getattr(axis, '_left_title', None),
                  getattr(axis, '_right_title', None)):
        if title is not None and title.get_visible() and title.get_text().strip():
            fixed_title_boxes.append(title.get_window_extent(renderer=renderer))
    for number, artist in enumerate(texts):
        artist.set_clip_on(False)
        if hasattr(artist, 'set_annotation_clip'):
            artist.set_annotation_clip(False)
        try:
            box = artist.get_window_extent(renderer=renderer).expanded(1.03, 1.08)
            transform = artist.get_transform()
            position = np.asarray(artist.get_position(), dtype=float)
            display_position = np.asarray(transform.transform(position), dtype=float)
            changed = False
            # Data labels close to the top border must move into the plot rather
            # than upward into a wrapped axes title.
            direction = -1.0 if box.y0 + box.y1 > axis_box.y0 + axis_box.y1 else 1.0
            for title_box in fixed_title_boxes:
                if box.overlaps(title_box):
                    vertical_shift = title_box.y0 - box.y1 - float(padding_pixels)
                    display_position[1] += vertical_shift
                    artist.set_position(transform.inverted().transform(display_position))
                    box = artist.get_window_extent(renderer=renderer).expanded(1.03, 1.08)
                    changed = True
            for _ in range(max(1, len(placed) + 1)):
                collisions = [prior for prior in placed if box.overlaps(prior)]
                if not collisions:
                    break
                if direction > 0.0:
                    vertical_shift = (
                        max(prior.y1 for prior in collisions) - box.y0
                        + float(padding_pixels)
                    )
                else:
                    vertical_shift = (
                        min(prior.y0 for prior in collisions) - box.y1
                        - float(padding_pixels)
                    )
                horizontal_shift = (
                    float(padding_pixels) * (1.0 if number % 2 else -1.0)
                )
                display_position += (horizontal_shift, vertical_shift)
                artist.set_position(transform.inverted().transform(display_position))
                box = artist.get_window_extent(renderer=renderer).expanded(1.03, 1.08)
                changed = True
            artist._adaptive_position_adjusted = changed
            placed.append(box)
        except (ValueError, TypeError, AttributeError, np.linalg.LinAlgError):
            continue


def _rotate_colliding_x_ticklabels(axis, renderer):
    labels = [
        label for label in axis.get_xticklabels()
        if label.get_visible() and label.get_text().strip()
    ]
    if len(labels) < 2:
        return
    boxes = [label.get_window_extent(renderer=renderer) for label in labels]
    collision = any(
        left.overlaps(right) for left, right in zip(boxes[:-1], boxes[1:])
    )
    if collision:
        for label in labels:
            if not hasattr(label, '_adaptive_original_text'):
                label._adaptive_original_text = label.get_text()
            original = label._adaptive_original_text
            if len(original) > 22:
                label.set_text(textwrap.fill(
                    original, width=20, break_long_words=False,
                    break_on_hyphens=False,
                ))
                label.set_fontsize(min(float(label.get_fontsize()), 8.5))
                label.set_rotation(max(22.0, float(label.get_rotation())))
            else:
                label.set_rotation(max(35.0, float(label.get_rotation())))
            label.set_horizontalalignment('right')
            label.set_rotation_mode('anchor')


def _expand_axes_for_data_text(axis, renderer, padding_fraction=0.025):
    """Expand numerical limits until complete data-coordinate labels fit."""
    x_values, y_values = [], []
    for artist in axis.texts:
        if not artist.get_visible() or not artist.get_text().strip():
            continue
        artist.set_clip_on(False)
        transform = artist.get_transform()
        try:
            if not transform.contains_branch(axis.transData):
                continue
            box = artist.get_window_extent(renderer=renderer)
            corners = axis.transData.inverted().transform([
                (box.x0, box.y0), (box.x1, box.y1)
            ])
            x_values.extend(corners[:, 0])
            y_values.extend(corners[:, 1])
        except (ValueError, TypeError, AttributeError, np.linalg.LinAlgError):
            continue

    def include(current_limit, values, scale):
        values = np.asarray(values, dtype=float)
        values = values[np.isfinite(values)]
        if values.size == 0:
            return current_limit
        first, second = map(float, current_limit)
        inverted = first > second
        lower, upper = (second, first) if inverted else (first, second)
        if scale == 'log' and lower > 0.0:
            positive = values[values > 0.0]
            if not positive.size:
                return current_limit
            log_lower, log_upper = np.log(lower), np.log(upper)
            value_lower, value_upper = np.min(np.log(positive)), np.max(np.log(positive))
            span = max(log_upper - log_lower, np.finfo(float).eps)
            log_lower = min(log_lower, float(value_lower) - padding_fraction * span)
            log_upper = max(log_upper, float(value_upper) + padding_fraction * span)
            lower, upper = float(np.exp(log_lower)), float(np.exp(log_upper))
        else:
            span = max(upper - lower, np.finfo(float).eps)
            lower = min(lower, float(np.min(values)) - padding_fraction * span)
            upper = max(upper, float(np.max(values)) + padding_fraction * span)
        return (upper, lower) if inverted else (lower, upper)

    if x_values:
        axis.set_xlim(include(axis.get_xlim(), x_values, axis.get_xscale()))
    if y_values:
        axis.set_ylim(include(axis.get_ylim(), y_values, axis.get_yscale()))


def _grow_crowded_figure_once(figure):
    if getattr(figure, '_adaptive_size_checked', False):
        return
    figure._adaptive_size_checked = True
    long_titles = any(
        len(axis.get_title()) > 58 for axis in figure.axes
    )
    long_ticks = any(
        any(len(label.get_text()) > 22 for label in axis.get_xticklabels())
        for axis in figure.axes
    )
    if long_titles or long_ticks:
        width, height = figure.get_size_inches()
        width_factor = 1.12 if long_titles else 1.06
        height_factor = 1.20 if long_ticks else 1.10
        figure.set_size_inches(
            min(20.0, width * width_factor),
            min(14.0, height * height_factor), forward=True,
        )


def _draw_with_layout_recovery(figure):
    """Freeze a collapsed constrained layout instead of growing without bound."""
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter('always', UserWarning)
        figure.canvas.draw()
    collapsed = any(
        'axes sizes collapsed to zero' in str(item.message).lower()
        for item in caught
    )
    if not collapsed:
        return figure.canvas.get_renderer()
    # The axes retain their last valid, nonzero positions when constrained_layout
    # declines an update.  Freezing those positions plus bbox_inches='tight' is
    # safer than repeatedly enlarging a 300-DPI raster until memory is exhausted.
    if hasattr(figure, 'set_layout_engine'):
        figure.set_layout_engine(None)
    else:
        figure.set_constrained_layout(False)
    figure.canvas.draw()
    return figure.canvas.get_renderer()


def _prepare_figure_for_complete_export(figure):
    """Make all symbols and labels visible immediately before rasterization."""
    try:
        _grow_crowded_figure_once(figure)
        renderer = _draw_with_layout_recovery(figure)
        figure_width_pixels = figure.get_figwidth() * figure.dpi
        if figure._suptitle is not None:
            _wrap_title_artist(
                figure._suptitle, 0.92 * figure_width_pixels,
                minimum_characters=36,
            )
        for axis in figure.axes:
            if not axis.get_visible():
                continue
            axis_width_pixels = max(axis.get_window_extent(renderer).width, 120.0)
            _wrap_title_artist(axis.title, axis_width_pixels)
            for title in (getattr(axis, '_left_title', None),
                          getattr(axis, '_right_title', None)):
                _wrap_title_artist(title, 0.48 * axis_width_pixels)
            # Do not globally disable clipping for area patches.  In particular,
            # a bar on a logarithmic axis starts at y=0, whose display transform
            # is extremely far outside the canvas; including that rectangle in a
            # tight bounding box can request a multi-gigabyte raster.  Scatter
            # markers and marked lines are handled safely below.
            x_values, y_values, z_values = _marked_artist_coordinates(axis)
            fixed_aspect_datalim = (
                axis.get_aspect() != 'auto'
                and axis.get_adjustable() == 'datalim'
            )
            if x_values and not fixed_aspect_datalim:
                axis.set_xlim(_expanded_axis_limit(
                    axis.get_xlim(), x_values, scale=axis.get_xscale()
                ))
            if y_values and not fixed_aspect_datalim:
                axis.set_ylim(_expanded_axis_limit(
                    axis.get_ylim(), y_values, scale=axis.get_yscale()
                ))
            if z_values and hasattr(axis, 'get_zlim3d'):
                axis.set_zlim(_expanded_axis_limit(
                    axis.get_zlim3d(), z_values,
                    scale=axis.get_zscale() if hasattr(axis, 'get_zscale') else 'linear',
                ))
            axis.tick_params(axis='both', which='major', pad=5)
        renderer = _draw_with_layout_recovery(figure)
        for axis in figure.axes:
            if not axis.get_visible():
                continue
            _expand_axes_for_data_text(axis, renderer)
        renderer = _draw_with_layout_recovery(figure)
        for axis in figure.axes:
            if not axis.get_visible():
                continue
            _rotate_colliding_x_ticklabels(axis, renderer)
            _separate_overlapping_axis_text(axis, renderer)
        _draw_with_layout_recovery(figure)
    except Exception as error:
        # Layout protection must never prevent the scientific run from saving an
        # otherwise valid figure.  The warning identifies unusual custom artists.
        warnings.warn(
            f'Adaptive figure layout could not fully process one figure: {error}',
            RuntimeWarning,
        )


_MATPLOTLIB_FIGURE_SAVEFIG = Figure.savefig


