def _large_grid_cache_limit(physics, environment_name, small_default,
                            large_default):
    """Return a bounded cache size without letting Marmousi caches grow GBs."""
    explicit = os.getenv(environment_name)
    if explicit is not None:
        value = int(explicit)
    else:
        cell_count = int(np.prod(physics.shape))
        value = int(large_default if cell_count >= 50000 else small_default)
    if value < 0:
        raise ValueError(f'{environment_name} cannot be negative.')
    return value


def _lru_get(cache, key):
    """Read and refresh an OrderedDict entry; return None when absent."""
    value = cache.get(key)
    if value is not None:
        cache.move_to_end(key)
    return value


def _lru_put(cache, key, value, maximum_entries):
    """Insert one cache value and evict the oldest entries incrementally."""
    maximum_entries = int(maximum_entries)
    if maximum_entries <= 0:
        return value
    cache[key] = value
    cache.move_to_end(key)
    while len(cache) > maximum_entries:
        cache.popitem(last=False)
    return value


def _stable_cholesky(matrix):
    """Return a Cholesky factor after adding the smallest useful jitter."""
    matrix = np.asarray(matrix, dtype=float)
    matrix = 0.5 * (matrix + matrix.T)
    scale = max(float(np.max(np.diag(matrix))), np.finfo(float).tiny)
    identity = np.eye(matrix.shape[0])
    for relative_jitter in (0.0, 1.0e-12, 1.0e-10, 1.0e-8, 1.0e-6):
        try:
            return np.linalg.cholesky(matrix + relative_jitter * scale * identity)
        except np.linalg.LinAlgError:
            continue
    eigenvalues, eigenvectors = np.linalg.eigh(matrix)
    eigenvalues = np.maximum(eigenvalues, scale * 1.0e-8)
    positive_definite = (eigenvectors * eigenvalues) @ eigenvectors.T
    return np.linalg.cholesky(positive_definite)


class OperationalNoiseModel:
    """Travel-time picking noise used in design and synthetic validation.

    The covariance contains receiver-dependent standard deviations and an
    exponential spatial correlation kernel. Non-Gaussian samples use
    standardized Laplace, Student-t, or Gaussian-mixture innovations and are
    correlated through a Cholesky factor. During array design, the covariance
    is multiplied by a 99% tail-risk factor. This keeps the FIM calculation
    tractable while distinguishing equal-RMS heavy-tailed and Gaussian noise.
    """

    VALID_KINDS = ('gaussian', 'laplace', 'student_t', 'gaussian_mixture')

    def __init__(self, name, kind='gaussian', sigma=0.002, df=3.0,
                 outlier_probability=0.05, outlier_scale=8.0,
                 correlation_length_m=0.0, hotspot_amplitude=0.0,
                 hotspot_width_fraction=0.15, hotspot_fraction=None):
        self.name = str(name)
        self.kind = str(kind).lower()
        self.sigma = float(sigma)
        self.df = float(df)
        self.outlier_probability = float(outlier_probability)
        self.outlier_scale = float(outlier_scale)
        self.correlation_length_m = float(correlation_length_m)
        self.hotspot_amplitude = float(hotspot_amplitude)
        self.hotspot_width_fraction = float(hotspot_width_fraction)
        self.hotspot_fraction = (
            None if hotspot_fraction is None
            else np.asarray(hotspot_fraction, dtype=float)
        )
        if self.kind not in self.VALID_KINDS:
            raise ValueError(f'Unsupported noise kind: {self.kind}.')
        if self.sigma <= 0.0:
            raise ValueError('Noise sigma must be positive.')
        if self.kind == 'student_t' and self.df <= 2.0:
            raise ValueError('Student-t df must exceed 2 so its variance exists.')
        if not 0.0 <= self.outlier_probability < 1.0:
            raise ValueError('outlier_probability must lie in [0, 1).')
        if self.outlier_scale < 1.0:
            raise ValueError('outlier_scale must be at least one.')
        if self.correlation_length_m < 0.0:
            raise ValueError('correlation_length_m cannot be negative.')
        if self.hotspot_amplitude < 0.0:
            raise ValueError('hotspot_amplitude cannot be negative.')
        if self.hotspot_width_fraction <= 0.0:
            raise ValueError('hotspot_width_fraction must be positive.')

    @staticmethod
    def _physical_positions(physics, sensor_indices):
        return np.asarray(sensor_indices, dtype=float) * np.asarray(
            physics.spacing, dtype=float
        )[None, :]

    def _hotspot_position(self, physics):
        dimensions = physics.dims
        if self.hotspot_fraction is None:
            fractions = np.full(dimensions, 0.5, dtype=float)
            fractions[-1] = 0.0
        else:
            if self.hotspot_fraction.size != dimensions:
                raise ValueError(
                    'hotspot_fraction must contain one value per model dimension.'
                )
            fractions = self.hotspot_fraction
        extent = (np.asarray(physics.shape, dtype=float) - 1.0) * np.asarray(
            physics.spacing, dtype=float
        )
        return fractions * extent, extent

    def local_standard_deviations(self, physics, sensor_indices):
        positions = self._physical_positions(physics, sensor_indices)
        hotspot, extent = self._hotspot_position(physics)
        width = self.hotspot_width_fraction * max(
            float(np.linalg.norm(extent)), np.finfo(float).tiny
        )
        distances = np.linalg.norm(positions - hotspot[None, :], axis=1)
        local_factor = 1.0 + self.hotspot_amplitude * np.exp(
            -0.5 * (distances / width) ** 2
        )
        return self.sigma * local_factor

    def correlation_matrix(self, physics, sensor_indices):
        positions = self._physical_positions(physics, sensor_indices)
        count = len(positions)
        if self.correlation_length_m <= 0.0 or count <= 1:
            return np.eye(count)
        separations = np.linalg.norm(
            positions[:, None, :] - positions[None, :, :], axis=2
        )
        correlation = np.exp(-separations / self.correlation_length_m)
        np.fill_diagonal(correlation, 1.0)
        return correlation

    def tail_risk_inflation(self):
        """Squared 99% absolute-quantile ratio relative to N(0, 1)."""
        gaussian_quantile = norm.ppf(0.995)
        if self.kind == 'gaussian':
            return 1.0
        if self.kind == 'laplace':
            quantile = -np.log(0.01) / np.sqrt(2.0)
        elif self.kind == 'student_t':
            quantile = student_t.ppf(0.995, self.df) * np.sqrt(
                (self.df - 2.0) / self.df
            )
        else:
            probability = self.outlier_probability
            scale = self.outlier_scale
            standard_deviation = np.sqrt(
                (1.0 - probability) + probability * scale**2
            )

            def centered_cdf(value):
                raw_value = value * standard_deviation
                return (
                    (1.0 - probability) * norm.cdf(raw_value)
                    + probability * norm.cdf(raw_value / scale)
                )

            quantile = opt.brentq(
                lambda value: centered_cdf(value) - 0.995,
                0.0,
                max(20.0, 5.0 * scale),
            )
        return float(max(1.0, (quantile / gaussian_quantile) ** 2))

    def covariance(self, physics, sensor_indices, risk_adjusted=False):
        standard_deviations = self.local_standard_deviations(
            physics, sensor_indices
        )
        correlation = self.correlation_matrix(physics, sensor_indices)
        covariance = (
            standard_deviations[:, None]
            * correlation
            * standard_deviations[None, :]
        )
        if risk_adjusted:
            covariance = covariance * self.tail_risk_inflation()
        return covariance

    def _standardized_innovations(self, count, rng):
        if self.kind == 'gaussian':
            return rng.normal(0.0, 1.0, size=count)
        if self.kind == 'laplace':
            return rng.laplace(0.0, 1.0 / np.sqrt(2.0), size=count)
        if self.kind == 'student_t':
            return rng.standard_t(self.df, size=count) * np.sqrt(
                (self.df - 2.0) / self.df
            )
        mixture_scale = np.where(
            rng.random(count) < self.outlier_probability,
            self.outlier_scale,
            1.0,
        )
        normalization = np.sqrt(
            (1.0 - self.outlier_probability)
            + self.outlier_probability * self.outlier_scale**2
        )
        return rng.normal(0.0, 1.0, size=count) * mixture_scale / normalization

    def sample(self, physics, sensor_indices, rng):
        correlation = self.correlation_matrix(physics, sensor_indices)
        factor = _stable_cholesky(correlation)
        innovations = self._standardized_innovations(len(sensor_indices), rng)
        correlated = factor @ innovations
        return self.local_standard_deviations(physics, sensor_indices) * correlated

    @property
    def recommended_loss(self):
        return 'linear' if self.kind == 'gaussian' else 'soft_l1'

    def to_dict(self):
        return {
            'name': self.name,
            'kind': self.kind,
            'sigma_s': self.sigma,
            'df': self.df,
            'outlier_probability': self.outlier_probability,
            'outlier_scale': self.outlier_scale,
            'correlation_length_m': self.correlation_length_m,
            'hotspot_amplitude': self.hotspot_amplitude,
            'hotspot_width_fraction': self.hotspot_width_fraction,
            'hotspot_fraction': (
                None if self.hotspot_fraction is None
                else self.hotspot_fraction.tolist()
            ),
            'tail_risk_inflation': self.tail_risk_inflation(),
        }


class PhysicsEngine:
    def __init__(self, shape, spacing, is_3d=False, velocity_file=None):
        self.is_3d = is_3d
        self.shape = shape 
        self.spacing = spacing 
        self.origin = tuple([0.] * len(shape))
        self.dims = len(shape)
        self.traveltime_solve_count = 0
        self.traveltime_solve_seconds = 0.0
        self.fmm_fallback_count = 0
        # One reusable level-set work array per calling thread.  The reference
        # model can be solved from a bounded thread pool, whereas each spawned
        # velocity worker calls FMM serially.  Thread-local storage supports both
        # paths without allocating and filling a full grid before every solve.
        self._fmm_workspace = threading.local()
        
        if velocity_file is not None:
            print(f"    [PhysicsEngine] Loading external velocity model from: {velocity_file}")
            if not os.path.exists(velocity_file):
                raise FileNotFoundError(f"Velocity binary file not found: {velocity_file}")
            v_1d = np.fromfile(velocity_file, dtype=np.float32)
            try:
                self.V = v_1d.reshape(self.shape)
            except ValueError as e:
                raise ValueError(f"Shape mismatch! Expected {self.shape} (size {np.prod(self.shape)}), "
                                 f"but file '{velocity_file}' contains {v_1d.size} elements.") from e
        else:
            self.V = np.ones(shape, dtype=np.float32) * 3500.0
            if self.is_3d:
                nx, ny, nz = shape
                self.V[:, :, int(nz*0.6):] = 3500.0
                self.V[int(nx*0.4):int(nx*0.6), int(ny*0.4):int(ny*0.6), int(nz*0.5):int(nz*0.7)] = 3000.0
            else:
                nx, nz = shape
                self.V[:, int(nz*0.6):] = 3500.0
                self.V[int(nx*0.4):int(nx*0.6), int(nz*0.5):int(nz*0.7)] = 3000.0

    def compute_traveltime_field(self, source_idx):
        solve_start = time.perf_counter()
        self.traveltime_solve_count += 1
        if not SKFMM_AVAILABLE:
            self.fmm_fallback_count += 1
            self.traveltime_solve_seconds += time.perf_counter() - solve_start
            return self._euclidean_distance(source_idx) / np.mean(self.V)
        phi = getattr(self._fmm_workspace, 'phi', None)
        if phi is None or phi.shape != self.V.shape or phi.dtype != self.V.dtype:
            phi = np.full_like(self.V, -1)
            self._fmm_workspace.phi = phi
        phi[source_idx] = 1
        try:
            # scikit-fmm accepts order=1 or order=2.  order=8 caused the
            # original code to enter the homogeneous Euclidean fallback,
            # which made a velocity-error test physically meaningless.
            t_field = skfmm.travel_time(phi, self.V, dx=self.spacing, order=2)
            return t_field
        except Exception as e:
            self.fmm_fallback_count += 1
            warnings.warn(
                f"FMM failed at source {source_idx}; using the homogeneous "
                f"Euclidean fallback. Original error: {e}",
                RuntimeWarning,
            )
            return self._euclidean_distance(source_idx) / np.mean(self.V)
        finally:
            # scikit-fmm treats ``phi`` as read-only.  Restoring the only changed
            # cell makes the next solve O(1) to prepare instead of O(grid size).
            phi[source_idx] = -1
            self.traveltime_solve_seconds += time.perf_counter() - solve_start

    def _euclidean_distance(self, source_idx):
        # Broadcasting avoids allocating one full mesh per dimension when FMM
        # is unavailable or fails on a large Marmousi grid.
        distance_squared = np.zeros(self.shape, dtype=np.float32)
        for dimension, (size, spacing, source_coordinate) in enumerate(zip(
                self.shape, self.spacing, source_idx)):
            coordinate = (
                np.arange(size, dtype=np.float32) - float(source_coordinate)
            ) * float(spacing)
            reshape = [1] * self.dims
            reshape[dimension] = size
            distance_squared += coordinate.reshape(reshape) ** 2
        return np.sqrt(distance_squared, out=distance_squared)

    def get_gradients(self, t_field):
        return np.gradient(t_field, *self.spacing)
        
    def compute_source_illumination(self, targets, target_weights=None):
        if target_weights is None:
            target_weights = np.ones(len(targets), dtype=float)
        target_weights = np.asarray(target_weights, dtype=float)
        if target_weights.shape != (len(targets),):
            raise ValueError('target_weights must contain one weight per target.')
        if np.any(target_weights < 0.0) or np.sum(target_weights) <= 0.0:
            raise ValueError('target_weights must be nonnegative with a positive sum.')
        target_weights = target_weights / np.sum(target_weights)
        illum_map = np.zeros_like(self.V)
        for t, weight in zip(targets, target_weights):
            t_field = self.compute_traveltime_field(t)
            illum_map += weight / (t_field**2 + 1.0)
            del t_field
        return illum_map / max(float(np.max(illum_map)), np.finfo(float).tiny)

# =============================================================================
# 模块 2: Devito RTM 封装器
# =============================================================================

def _plain_numpy_array(value, dtype=None, name='array', expected_ndim=None):
    """Detach a Devito ``Data`` object from its custom indexing semantics.

    NumPy operations such as ``stack`` add an axis with ``None``.  Devito's
    ``Data.__getitem__`` does not accept that index, so every array crossing the
    Devito/NumPy boundary is materialized as an exact base ``numpy.ndarray``.
    """
    array = np.array(
        value, dtype=dtype, copy=True, order='C', subok=False,
    )
    if type(array) is not np.ndarray:
        array = array.view(np.ndarray)
    if expected_ndim is not None and array.ndim != int(expected_ndim):
        raise ValueError(
            f'{name} must be {expected_ndim}D; received shape {array.shape}.'
        )
    if not np.issubdtype(array.dtype, np.number):
        raise TypeError(f'{name} must contain numeric values, not {array.dtype}.')
    return np.ascontiguousarray(array)


def _safe_file_token(value):
    token = re.sub(r'[^A-Za-z0-9_.-]+', '_', str(value)).strip('._')
    return token or 'unnamed'


def _atomic_write_json(path, payload):
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    temporary = f'{path}.tmp'
    with open(temporary, 'w', encoding='utf-8') as stream:
        json.dump(payload, stream, indent=2)
        stream.flush()
        os.fsync(stream.fileno())
    os.replace(temporary, path)


def _atomic_save_npy(path, array):
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    temporary = f'{path}.tmp'
    with open(temporary, 'wb') as stream:
        np.save(stream, array, allow_pickle=False)
        stream.flush()
        os.fsync(stream.fileno())
    os.replace(temporary, path)


def _matlab_matrix(array):
    """Return a two-dimensional numeric matrix suitable for MATLAB ``load``."""
    array = _plain_numpy_array(array, name='MATLAB export array')
    if array.ndim == 0:
        return array.reshape(1, 1)
    if array.ndim == 1:
        return array.reshape(-1, 1)
    return array.reshape(array.shape[0], -1, order='C')


def _atomic_save_matlab_text(base_path, array, fmt='%.9e'):
    """Write pure numeric text plus a numeric shape sidecar, atomically."""
    array = _plain_numpy_array(array, name='checkpoint array')
    data_path = f'{base_path}.txt'
    shape_path = f'{base_path}.shape.txt'
    os.makedirs(os.path.dirname(os.path.abspath(data_path)), exist_ok=True)
    data_temporary = f'{data_path}.tmp'
    shape_temporary = f'{shape_path}.tmp'
    np.savetxt(data_temporary, _matlab_matrix(array), fmt=fmt)
    np.savetxt(
        shape_temporary, np.asarray(array.shape, dtype=np.int64).reshape(1, -1),
        fmt='%d',
    )
    os.replace(data_temporary, data_path)
    os.replace(shape_temporary, shape_path)
    return data_path, shape_path


def _save_rtm_checkpoint(base_path, array, save_text=True):
    """Save a fast NumPy checkpoint and an optional MATLAB-readable copy."""
    array = _plain_numpy_array(array, dtype=np.float32, name='RTM checkpoint')
    _atomic_save_npy(f'{base_path}.npy', array)
    if save_text:
        _atomic_save_matlab_text(base_path, array)
    return array


def _load_rtm_checkpoint(base_path, expected_shape=None):
    """Load a complete checkpoint, preferring the lossless binary sidecar."""
    npy_path = f'{base_path}.npy'
    text_path = f'{base_path}.txt'
    shape_path = f'{base_path}.shape.txt'
    try:
        if os.path.isfile(npy_path):
            loaded = np.load(npy_path, allow_pickle=False)
        elif os.path.isfile(text_path) and os.path.isfile(shape_path):
            shape = tuple(
                int(value) for value in np.atleast_1d(
                    np.loadtxt(shape_path, dtype=np.int64)
                ).ravel()
            )
            loaded = np.atleast_1d(np.loadtxt(text_path)).reshape(shape, order='C')
        else:
            return None
        loaded = _plain_numpy_array(
            loaded, dtype=np.float32, name='loaded RTM checkpoint'
        )
        if expected_shape is not None and tuple(loaded.shape) != tuple(expected_shape):
            warnings.warn(
                f'Ignoring checkpoint {base_path!r}: shape {loaded.shape} does '
                f'not match {tuple(expected_shape)}.', RuntimeWarning,
            )
            return None
        if not np.all(np.isfinite(loaded)):
            warnings.warn(
                f'Ignoring checkpoint {base_path!r}: it contains non-finite values.',
                RuntimeWarning,
            )
            return None
        return loaded
    except (OSError, ValueError, TypeError) as error:
        warnings.warn(
            f'Ignoring unreadable RTM checkpoint {base_path!r}: {error}',
            RuntimeWarning,
        )
        return None


def _write_matlab_loader(directory):
    """Create a compact MATLAB helper for flattened N-D text checkpoints."""
    os.makedirs(directory, exist_ok=True)
    loader_path = os.path.join(directory, 'load_python_nd_text.m')
    loader = """function A = load_python_nd_text(base_path)
%LOAD_PYTHON_ND_TEXT Load <base_path>.txt and <base_path>.shape.txt.
M = load([base_path '.txt']);
shape = load([base_path '.shape.txt']);
shape = double(shape(:).');
if isempty(shape)
    A = M(1);
elseif numel(shape) == 1
    A = reshape(M, [shape(1) 1]);
elseif numel(shape) == 2
    A = reshape(M, shape);
else
    A = permute(reshape(M.', fliplr(shape)), numel(shape):-1:1);
end
end
"""
    temporary = f'{loader_path}.tmp'
    with open(temporary, 'w', encoding='utf-8', newline='\n') as stream:
        stream.write(loader)
    os.replace(temporary, loader_path)
    readme_path = os.path.join(directory, 'README_MATLAB.txt')
    readme = (
        "All .txt files contain numeric ASCII data and can be opened with load "
        "or readmatrix. Two-dimensional arrays load directly. For N-D arrays, "
        "call A = load_python_nd_text('full/path/file_without_extension').\n"
        "The matching .shape.txt file records the original Python dimensions.\n"
    )
    temporary = f'{readme_path}.tmp'
    with open(temporary, 'w', encoding='utf-8', newline='\n') as stream:
        stream.write(readme)
    os.replace(temporary, readme_path)


class DevitoRTMWrapper:
    def __init__(self, phys, f0=25.0):
        self.phys = phys
        self.f0 = float(os.getenv('RTM_F0_HZ', str(f0))) / 1000.0
        if self.f0 <= 0.0:
            raise ValueError('RTM_F0_HZ must be positive.')
        self.is_3d = phys.is_3d
        self.vp_km = self.phys.V / 1000.0
        self.spacing_km = tuple([s / 1000.0 for s in self.phys.spacing])
        self.origin_km = tuple([0.] * len(self.phys.shape))
        nbl = int(os.getenv('RTM_NBL', '10'))
        space_order = int(os.getenv('RTM_SPACE_ORDER', '8'))
        if nbl <= 0 or space_order <= 0 or space_order % 2:
            raise ValueError(
                'RTM_NBL must be positive and RTM_SPACE_ORDER must be a '
                'positive even integer.'
            )
        self.model = Model(vp=self.vp_km, origin=self.origin_km, 
                           shape=self.phys.shape, spacing=self.spacing_km,
                           space_order=4, nbl=nbl)
        self.t0 = 0.
        self.tn = float(os.getenv('RTM_TN_MS', '1000.0'))
        if self.tn <= self.t0:
            raise ValueError('RTM_TN_MS must be positive.')
        self.dt = self.model.critical_dt
        self.time_range = TimeAxis(start=self.t0, stop=self.tn, step=self.dt)
        self.geometry = setup_geometry(self.model, self.tn)
        self.solver = AcousticWaveSolver(
            self.model, self.geometry, source_or=None, space_order=space_order
        )

    def _idx_to_coords_km(self, indices_list):
        coords = []
        for idx in indices_list:
            c = [idx[d] * self.phys.spacing[d] / 1000.0 for d in range(len(idx))]
            coords.append(c)
        return np.array(coords)

    def _make_source(self, src_idx):
        src_coords = self._idx_to_coords_km([src_idx])
        src = RickerSource(name='src', grid=self.model.grid, f0=self.f0,
                           npoint=1, time_range=self.time_range)
        src.coordinates.data[:] = src_coords
        return src

    def forward_modeling(self, src_idx, sensor_indices, save_wavefield=False):
        src = self._make_source(src_idx)
        rec_coords = self._idx_to_coords_km(sensor_indices)
        rec = Receiver(name='rec', grid=self.model.grid, npoint=len(sensor_indices),
                       time_range=self.time_range)
        rec.coordinates.data[:] = rec_coords
        rec_data, u, summary = self.solver.forward(
            vp=self.model.vp, src=src, u=None, rec=rec,
            save=bool(save_wavefield),
        )
        # Copy now: rec_data.data is also a Devito Data subclass.
        data = _plain_numpy_array(
            rec_data.data, dtype=np.float32, name='RTM receiver data',
            expected_ndim=2,
        )
        return data, float(self.dt), u

    def source_wavefield(self, src_idx):
        """Compute one saved source wavefield for reuse by several arrays."""
        src = self._make_source(src_idx)
        _, wavefield, _ = self.solver.forward(
            vp=self.model.vp, src=src, u=None, save=True,
        )
        return wavefield

    def estimated_saved_wavefield_bytes(self):
        grid_shape = tuple(int(value) for value in self.model.grid.shape)
        return int(self.time_range.num) * int(np.prod(grid_shape)) * 4

    def _match_receiver_time_sampling(self, data_in, input_dt=None):
        """Resample observed traces to this wrapper's migration time axis."""
        data = _plain_numpy_array(
            data_in, dtype=np.float32, name='RTM receiver data', expected_ndim=2
        )
        target_nt = int(self.time_range.num)
        target_dt = float(self.dt)
        source_dt = target_dt if input_dt is None else float(input_dt)
        if source_dt <= 0.0:
            raise ValueError('The input receiver-data time step must be positive.')
        if data.shape[0] == target_nt and np.isclose(
                source_dt, target_dt, rtol=1.0e-7, atol=1.0e-10):
            return data
        input_time = np.arange(data.shape[0], dtype=float) * source_dt
        output_time = np.arange(target_nt, dtype=float) * target_dt
        aligned = np.empty((target_nt, data.shape[1]), dtype=np.float32)
        for receiver_index in range(data.shape[1]):
            aligned[:, receiver_index] = np.interp(
                output_time,
                input_time,
                np.asarray(data[:, receiver_index], dtype=float),
                left=0.0,
                right=0.0,
            )
        return aligned

    def rtm_imaging(self, data_in, u, sensor_indices, src_idx_guess=None,
                    data_dt=None):
        source_index = (
            tuple(n // 2 for n in self.phys.shape)
            if src_idx_guess is None
            else tuple(int(round(value)) for value in src_idx_guess)
        )
        src = self._make_source(source_index)
        rec_coords = self._idx_to_coords_km(sensor_indices)
        rec = Receiver(name='rec', grid=self.model.grid, npoint=len(sensor_indices),
                       time_range=self.time_range)
        rec.coordinates.data[:] = rec_coords
        aligned_data = self._match_receiver_time_sampling(data_in, data_dt)
        if aligned_data.shape[1] != len(sensor_indices):
            raise ValueError(
                'Receiver-data channel count does not match sensor_indices.'
            )
        rec.data[:] = aligned_data
        # A saved source wavefield can be shared by every array for this source.
        # If memory policy selected checkpointing, Devito recomputes it safely.
        try:
            op_grad, summary = self.solver.gradient(
                rec=rec, u=u, vp=self.model.vp, src=src,
                checkpointing=(u is None),
            )
        except Exception as error:
            if u is None:
                raise
            warnings.warn(
                'Saved-wavefield RTM failed; retrying with Devito checkpointing. '
                f'Original error: {error}', RuntimeWarning,
            )
            op_grad, summary = self.solver.gradient(
                rec=rec, u=None, vp=self.model.vp, src=src, checkpointing=True,
            )
        image_data = op_grad.data
        slices = tuple([slice(self.model.nbl, -self.model.nbl) for _ in range(self.model.dim)])
        image = _plain_numpy_array(
            image_data[slices], dtype=np.float32, name='RTM image',
            expected_ndim=self.model.dim,
        )
        np.abs(image, out=image)
        return image


def _select_rtm_changed_velocity_case(cases):
    """Select an explicit target-localized production velocity-change case."""
    requested = os.getenv(
        'RTM_CHANGED_VELOCITY_SCENARIO', 'max_target_rms'
    ).strip()
    if requested and requested.lower() not in {
            'max_target_rms', 'auto', 'automatic'}:
        matches = [case for case in cases if case['name'] == requested]
        if not matches:
            available = ', '.join(case['name'] for case in cases)
            raise ValueError(
                f"RTM_CHANGED_VELOCITY_SCENARIO={requested!r} was not found. "
                f"Available cases: {available}"
            )
        changed_case = matches[0]
        if changed_case['kind'] == 'reference':
            raise ValueError(
                'RTM_CHANGED_VELOCITY_SCENARIO must select a nonreference case.'
            )
        return changed_case
    nonreference = [case for case in cases if case['kind'] != 'reference']
    if not nonreference:
        raise ValueError('RTM comparison requires at least one changed velocity case.')
    target_localized = [
        case for case in nonreference
        if bool(case.get('target_localized_residual', False))
    ]
    eligible = target_localized if target_localized else nonreference
    return max(
        eligible,
        key=lambda case: (
            float(case.get('target_zone_residual_rms_fraction', 0.0)),
            float(case.get('residual_rms_fraction', 0.0)),
            float(case.get('residual_max_abs_fraction', 0.0)),
        ),
    )


def _velocity_case_fractional_residual(case):
    """Materialize one case residual only when a plot/audit explicitly needs it."""
    if case.get('fractional_residual') is not None:
        return np.asarray(case['fractional_residual'], dtype=np.float32)
    parameters = case.get('latent_velocity_parameters')
    basis = case.get('_shared_log_slowness_basis')
    if parameters is None or basis is None:
        raise KeyError(
            f"Velocity case {case.get('name', 'unnamed')} has no residual data."
        )
    delta_log_slowness = np.einsum(
        'k,k...->...', np.asarray(parameters, dtype=np.float32),
        np.asarray(basis, dtype=np.float32), optimize=True,
    )
    return np.asarray(np.exp(-delta_log_slowness) - 1.0, dtype=np.float32)


def _velocity_case_array(reference_physics, case):
    """Materialize one visualization velocity; never cache an ensemble."""
    if case.get('velocity') is not None:
        return np.asarray(case['velocity'], dtype=np.float32)
    return np.asarray(
        np.asarray(reference_physics.V, dtype=np.float32)
        * (1.0 + _velocity_case_fractional_residual(case)),
        dtype=np.float32,
    )


def _independent_psdm_holdout_velocity_case(reference_physics, target_indices,
                                             excluded_cases):
    """Construct a target-localized perturbation not used in robust design.

    The random seed namespace is deliberately separate from the velocity
    ensemble.  A numerical uniqueness check against the reference and every
    supplied ensemble member guarantees that the migration test is a genuine
    holdout model rather than a reused design realization.
    """
    targets = np.asarray(target_indices, dtype=int)
    shape = tuple(int(value) for value in reference_physics.shape)
    if targets.ndim != 2 or targets.shape[1] != len(shape):
        raise ValueError(
            'target_indices must have shape (number_of_targets, model_dimension).'
        )
    for target in targets:
        if any(value < 0 or value >= shape[dimension]
               for dimension, value in enumerate(target)):
            raise ValueError(
                f'Holdout perturbation target {tuple(target)} is outside the model.'
            )

    target_fraction = float(os.getenv('PSDM_HOLDOUT_TARGET_FRACTION', '0.10'))
    amplitude_jitter = float(os.getenv('PSDM_HOLDOUT_AMPLITUDE_JITTER', '0.15'))
    clip_fraction = float(os.getenv('PSDM_HOLDOUT_MAX_ABS', '0.30'))
    radius_cells = float(os.getenv('PSDM_HOLDOUT_RADIUS_CELLS', '5.0'))
    background_fraction = float(os.getenv(
        'PSDM_HOLDOUT_BACKGROUND_FRACTION', '0.05'
    ))
    base_seed = int(os.getenv('PSDM_HOLDOUT_RANDOM_SEED', '20260818'))
    if target_fraction <= 0.0:
        raise ValueError('PSDM_HOLDOUT_TARGET_FRACTION must be positive.')
    if not 0.0 <= amplitude_jitter < 1.0:
        raise ValueError('PSDM_HOLDOUT_AMPLITUDE_JITTER must lie in [0, 1).')
    if not 0.0 < clip_fraction < 1.0:
        raise ValueError('PSDM_HOLDOUT_MAX_ABS must lie in (0, 1).')
    if radius_cells <= 0.0:
        raise ValueError('PSDM_HOLDOUT_RADIUS_CELLS must be positive.')
    if not 0.0 <= background_fraction < 1.0:
        raise ValueError('PSDM_HOLDOUT_BACKGROUND_FRACTION must lie in [0, 1).')

    # The holdout is one smooth regional anomaly, not pointwise random noise.
    # It reaches its coherent amplitude over the supplied target points and
    # decays with a Gaussian envelope toward a small far-field background.
    grids = np.ogrid[tuple(slice(0, size) for size in shape)]
    envelope = np.zeros(shape, dtype=np.float64)
    for target in targets:
        squared_distance = np.zeros(shape, dtype=np.float64)
        for dimension, grid in enumerate(grids):
            squared_distance += (
                (grid - int(target[dimension])) / radius_cells
            ) ** 2
        envelope = np.maximum(envelope, np.exp(-0.5 * squared_distance))
    target_mask = envelope >= np.exp(-0.5)
    background_mask = envelope <= 0.10
    if not np.any(target_mask):
        raise ValueError('The independent holdout target region is empty.')

    reference_velocity = _plain_numpy_array(
        reference_physics.V, dtype=np.float32, name='reference holdout velocity'
    )

    residual = None
    perturbed_velocity = None
    selected_seed = None
    selected_amplitude = None
    minimum_difference = None
    for attempt in range(64):
        selected_seed = base_seed + 104729 * attempt
        rng = np.random.default_rng(selected_seed)
        sign = -1.0 if rng.random() < 0.5 else 1.0
        selected_amplitude = sign * target_fraction * rng.uniform(
            1.0 - amplitude_jitter, 1.0 + amplitude_jitter
        )
        candidate_residual = selected_amplitude * (
            background_fraction + (1.0 - background_fraction) * envelope
        )
        candidate_residual = np.clip(
            candidate_residual, -clip_fraction, clip_fraction
        ).astype(np.float32)
        candidate_velocity = np.asarray(
            reference_velocity * (1.0 + candidate_residual), dtype=np.float32
        )
        differences = [float(np.sqrt(np.mean(
            ((candidate_velocity.astype(float) - reference_velocity.astype(float))
             / np.maximum(np.abs(reference_velocity.astype(float)), 1.0)) ** 2
        )))]
        unique = not np.allclose(
            candidate_velocity, reference_velocity, rtol=1.0e-7, atol=1.0e-4
        )
        # Audit compact Bayesian nodes sequentially, so the validation step
        # never materializes a second velocity ensemble in memory.
        for case in excluded_cases:
            if case.get('velocity') is not None or (
                    case.get('latent_velocity_parameters') is not None
                    and case.get('_shared_log_slowness_basis') is not None):
                other = _velocity_case_array(reference_physics, case)
            elif case.get('physics') is not None:
                other = _plain_numpy_array(
                    case['physics'].V, dtype=np.float32,
                    name=f"excluded velocity {case.get('name', 'unnamed')}",
                )
            else:
                continue
            differences.append(float(np.sqrt(np.mean(
                ((candidate_velocity.astype(float) - other.astype(float))
                 / np.maximum(np.abs(reference_velocity.astype(float)), 1.0)) ** 2
            ))))
            unique = unique and not np.allclose(
                candidate_velocity, other, rtol=1.0e-7, atol=1.0e-4
            )
            del other
        if unique:
            residual = candidate_residual
            perturbed_velocity = candidate_velocity
            minimum_difference = float(min(differences))
            break
    if perturbed_velocity is None:
        raise RuntimeError(
            'Could not construct a holdout velocity distinct from all design models.'
        )

    physics = _clone_with_velocity(reference_physics, perturbed_velocity)
    target_values = residual[target_mask].astype(float)
    background_values = residual[background_mask].astype(float)
    all_values = residual.astype(float)
    return {
        'name': f'independent_holdout_smooth_region_{100.0 * abs(selected_amplitude):.1f}pct',
        'kind': 'independent_holdout_smooth_region',
        'magnitude': float(abs(selected_amplitude)),
        'probability': 0.0,
        'physics': physics,
        'residual_mean_fraction': float(np.mean(all_values)),
        'residual_rms_fraction': float(np.sqrt(np.mean(all_values ** 2))),
        'residual_max_abs_fraction': float(np.max(np.abs(all_values))),
        'target_zone_residual_rms_fraction': float(
            np.sqrt(np.mean(target_values ** 2))
        ),
        'background_residual_rms_fraction': float(
            np.sqrt(np.mean(background_values ** 2))
        ) if background_values.size else 0.0,
        'target_localized_residual': True,
        'spatial_perturbation_type': 'coherent Gaussian-decay target-region anomaly',
        'not_used_for_observation_system_optimization': True,
        'minimum_rms_fractional_difference_from_design_models': minimum_difference,
        'target_mask_points': int(np.count_nonzero(target_mask)),
        'target_radius_cells': radius_cells,
        'target_fractional_amplitude': float(selected_amplitude),
        'background_fraction_of_target_amplitude': background_fraction,
        'random_seed': int(selected_seed),
        'fractional_residual': residual,
    }


def _smoothed_ray_velocity_physics(physics, label):
    """Return the smooth velocity used by the fast ray-theory migration."""
    raw = os.getenv('PSDM_RAY_VELOCITY_SMOOTH_SIGMA_CELLS', '1.5')
    values = [float(value.strip()) for value in raw.split(',') if value.strip()]
    if len(values) == 1:
        sigma = tuple(values * len(physics.shape))
    elif len(values) == len(physics.shape):
        sigma = tuple(values)
    else:
        raise ValueError(
            'PSDM_RAY_VELOCITY_SMOOTH_SIGMA_CELLS must contain one value or '
            'one value per model dimension.'
        )
    if any(value < 0.0 for value in sigma):
        raise ValueError('Ray-velocity smoothing sigmas cannot be negative.')
    velocity = _plain_numpy_array(
        physics.V, dtype=np.float32, name=f'{label} unsmoothed velocity'
    )
    if any(value > 0.0 for value in sigma):
        smoothed = gaussian_filter(
            velocity.astype(np.float64), sigma=sigma, mode='nearest'
        )
    else:
        smoothed = velocity.astype(np.float64)
    smoothed = np.clip(
        smoothed, float(np.min(velocity)), float(np.max(velocity))
    ).astype(np.float32)
    difference = smoothed.astype(float) - velocity.astype(float)
    result = _clone_with_velocity(physics, smoothed)
    metadata = {
        'label': str(label),
        'sigma_cells': [float(value) for value in sigma],
        'rms_smoothing_change_m_per_s': float(
            np.sqrt(np.mean(difference ** 2))
        ),
        'maximum_smoothing_change_m_per_s': float(np.max(np.abs(difference))),
        'velocity_min_m_per_s': float(np.min(smoothed)),
        'velocity_max_m_per_s': float(np.max(smoothed)),
    }
    del velocity, smoothed, difference
    return result, metadata


def _rtm_design_styles():
    return {
        'Fixed-velocity optimized': (C_OPT, 'v'),
        'Random': (C_RND, 'o'),
        'Uniform': (C_UNI, 's'),
        'Velocity-ensemble robust': (C_ROB, 'D'),
    }


def _validated_rtm_image(image, physics=None, name='RTM image'):
    expected_ndim = None if physics is None else len(physics.shape)
    array = _plain_numpy_array(
        image, dtype=np.float32, name=name, expected_ndim=expected_ndim,
    )
    if physics is not None and tuple(array.shape) != tuple(physics.shape):
        raise ValueError(
            f'{name} has shape {array.shape}; expected {tuple(physics.shape)}.'
        )
    if not np.all(np.isfinite(array)):
        warnings.warn(
            f'{name} contains NaN or infinite values; replacing them by zero '
            'for metrics and plotting.', RuntimeWarning,
        )
        array = np.nan_to_num(array, nan=0.0, posinf=0.0, neginf=0.0)
    return array


def _stack_rtm_images(image_sequence, physics, name):
    if not image_sequence:
        raise ValueError(f'{name} contains no RTM images.')
    # Do not call np.stack on Devito Data objects: np.stack inserts None axes,
    # which Devito's convert_index rejects. Every element is detached first.
    arrays = tuple(
        _validated_rtm_image(image, physics, f'{name}[{index}]')
        for index, image in enumerate(image_sequence)
    )
    return np.stack(arrays, axis=0)


def _rtm_image_metrics(image, source_index, spacing, focus_radius_cells):
    """Return common, scale-independent focusing metrics for one RTM image."""
    amplitude = np.abs(_plain_numpy_array(image, dtype=np.float64, name='RTM image'))
    amplitude = np.nan_to_num(amplitude, nan=0.0, posinf=0.0, neginf=0.0)
    if len(source_index) != amplitude.ndim:
        raise ValueError('Source dimensionality does not match the RTM image.')
    source_index = tuple(int(value) for value in source_index)
    if any(index < 0 or index >= amplitude.shape[dimension]
           for dimension, index in enumerate(source_index)):
        raise ValueError(
            f'Source index {source_index} lies outside RTM image shape '
            f'{amplitude.shape}.'
        )
    peak_index = np.unravel_index(int(np.argmax(amplitude)), amplitude.shape)
    spacing_array = np.asarray(spacing, dtype=float)
    peak_error = float(np.linalg.norm(
        (np.asarray(peak_index, dtype=float) - np.asarray(source_index, dtype=float))
        * spacing_array
    ))
    grids = np.ogrid[tuple(slice(0, size) for size in amplitude.shape)]
    distance_metres_squared = np.zeros(amplitude.shape, dtype=float)
    for dimension, grid in enumerate(grids):
        distance_metres_squared += (
            (grid - source_index[dimension]) * spacing_array[dimension]
        ) ** 2
    # A physical sphere/circle is used even when grid spacing is anisotropic.
    focus_radius_m = float(focus_radius_cells) * float(np.min(spacing_array))
    focus_mask = distance_metres_squared <= focus_radius_m ** 2
    energy = amplitude ** 2
    tiny = np.finfo(float).tiny
    total_energy = float(np.sum(energy))
    focus_fraction = float(np.sum(energy[focus_mask]) / max(total_energy, tiny))
    source_amplitude = float(amplitude[source_index])
    outside = amplitude[~focus_mask]
    sidelobe_amplitude = float(np.max(outside)) if outside.size else 0.0
    source_to_sidelobe_db = float(20.0 * np.log10(
        (source_amplitude + tiny) / (sidelobe_amplitude + tiny)
    ))
    probabilities = energy.ravel() / max(total_energy, tiny)
    positive = probabilities > 0.0
    entropy = -float(np.sum(
        probabilities[positive] * np.log(probabilities[positive])
    ))
    normalized_entropy = entropy / max(np.log(probabilities.size), tiny)
    return {
        'peak_location_error_m': peak_error,
        'focus_energy_fraction': focus_fraction,
        'source_to_sidelobe_db': source_to_sidelobe_db,
        'normalized_image_entropy': float(normalized_entropy),
        'peak_amplitude': float(np.max(amplitude)),
        'source_amplitude': source_amplitude,
        'focus_radius_m': focus_radius_m,
        'peak_index': [int(value) for value in peak_index],
    }


def _rtm_image_correlation(first, second):
    first = np.abs(_plain_numpy_array(
        first, dtype=np.float64, name='first RTM image'
    )).ravel()
    second = np.abs(_plain_numpy_array(
        second, dtype=np.float64, name='second RTM image'
    )).ravel()
    if first.shape != second.shape:
        raise ValueError('RTM image correlation requires equal image shapes.')
    numerator = float(np.dot(first, second))
    denominator = float(np.linalg.norm(first) * np.linalg.norm(second))
    return numerator / max(denominator, np.finfo(float).tiny)


def _rtm_xz_slice(volume, physics, source_index):
    volume = _plain_numpy_array(
        volume, dtype=np.float32, name='XZ-slice volume',
        expected_ndim=len(physics.shape),
    )
    if tuple(volume.shape) != tuple(physics.shape):
        raise ValueError(
            f'XZ-slice volume shape {volume.shape} does not match '
            f'physics shape {tuple(physics.shape)}.'
        )
    if physics.is_3d:
        y_index = int(np.clip(source_index[1], 0, volume.shape[1] - 1))
        return volume[:, y_index, :].T
    return volume.T


def _psdm_display_image(image_slice):
    """Apply only a transparent-overlay max-amplitude normalization.

    This function intentionally performs no percentile clipping, weak-amplitude
    masking, gamma transform, or image smoothing. Residual low-coherence energy
    remains quantitative; its visual prominence is controlled solely by the
    transparent overlay in the plotting functions.
    """
    amplitude = np.abs(np.asarray(image_slice, dtype=float))
    amplitude[~np.isfinite(amplitude)] = 0.0
    scale = max(float(np.max(amplitude)), np.finfo(float).tiny)
    return np.clip(amplitude / scale, 0.0, 1.0)


def _plot_rtm_four_array_experiment(
        experiment, images, detail_rows, design_sensors, source_indices,
        output_dir):
    # The background is the model used by migration, so a velocity-mismatch
    # figure explicitly shows the erroneous assumed model rather than the
    # unchanged reference model that generated the traces.
    imaging_physics = experiment['migration_physics']
    if imaging_physics.is_3d:
        return _plot_rtm_four_array_experiment_3d(
            experiment,
            images,
            detail_rows,
            design_sensors,
            source_indices,
            output_dir,
        )
    design_names = list(design_sensors)
    styles = _rtm_design_styles()
    show_receiver_markers = (
        os.getenv('PSDM_SHOW_RECEIVER_MARKERS', '0') != '0'
    )
    number_sources = len(source_indices)
    # A single source is the normal fast-PSDM workflow.  A 2 x 2 layout gives
    # every array enough horizontal and vertical room to retain the physical
    # X-Z aspect ratio; the previous 1 x 4 strip stretched the panels and made
    # both the migration smiles and the long titles visually dominant.
    single_source_layout = number_sources == 1
    if single_source_layout:
        subplot_rows = 2
        subplot_columns = int(np.ceil(len(design_names) / subplot_rows))
        fig, axes = plt.subplots(
            subplot_rows,
            subplot_columns,
            figsize=(6.15 * subplot_columns, 5.15 * subplot_rows + 0.8),
            squeeze=False,
            constrained_layout=False,
        )
    else:
        subplot_rows = number_sources
        subplot_columns = len(design_names)
        fig, axes = plt.subplots(
            subplot_rows,
            subplot_columns,
            figsize=(4.9 * subplot_columns, 4.5 * subplot_rows + 1.4),
            squeeze=False,
            constrained_layout=False,
        )
    x_max = (imaging_physics.shape[0] - 1) * imaging_physics.spacing[0]
    z_max = (imaging_physics.shape[-1] - 1) * imaging_physics.spacing[-1]
    metric_lookup = {
        (row['design'], int(row['source_number'])): row
        for row in detail_rows
        if row['experiment'] == experiment['key']
    }
    image_artist = None
    for source_number, source_index in enumerate(source_indices, start=1):
        velocity_slice = _rtm_xz_slice(
            imaging_physics.V, imaging_physics, source_index
        )
        for design_index, design_name in enumerate(design_names):
            if single_source_layout:
                axis = axes.ravel()[design_index]
                axis_column = design_index % subplot_columns
            else:
                axis = axes[source_number - 1, design_index]
                axis_column = design_index
            image = images[experiment['key']][design_name][source_number - 1]
            image_slice = _rtm_xz_slice(image, imaging_physics, source_index)
            normalized = _psdm_display_image(image_slice)
            axis.imshow(
                velocity_slice,
                cmap='rainbow',
                extent=[0.0, x_max, z_max, 0.0],
                aspect='equal',
                alpha=1.0,
            )
            image_alpha = float(os.getenv('PSDM_IMAGE_OVERLAY_ALPHA', '0.45'))
            if not 0.0 <= image_alpha <= 1.0:
                raise ValueError('PSDM_IMAGE_OVERLAY_ALPHA must lie in [0, 1].')
            image_artist = axis.imshow(
                normalized,
                cmap='rainbow',
                extent=[0.0, x_max, z_max, 0.0],
                aspect='equal',
                vmin=0.0,
                vmax=1.0,
                alpha=image_alpha,
            )
            sensors = design_sensors[design_name]
            sensor_x = [sensor[0] * imaging_physics.spacing[0] for sensor in sensors]
            sensor_z = [sensor[-1] * imaging_physics.spacing[-1] for sensor in sensors]
            if show_receiver_markers:
                color, marker = styles[design_name]
                axis.scatter(
                    sensor_x, sensor_z, c=color, marker=marker, s=22,
                    edgecolor='white', linewidth=0.45, alpha=0.85,
                    label='Receivers' if source_number == 1 else None,
                )
            metrics = metric_lookup[(design_name, source_number)]
            display_design_name = {
                'Fixed-velocity optimized': 'Fixed-velocity optimized',
                'Velocity-ensemble robust': 'Velocity-ensemble robust',
            }.get(design_name, design_name)
            axis.set_title(
                f"{display_design_name}\n"
                f"N={len(sensors)}; peak error={metrics['peak_location_error_m']:.1f} m; "
                f"focus={metrics['focus_energy_fraction']:.3f}",
                fontsize=9.0,
                pad=6,
            )
            plotted_points = np.column_stack((sensor_x, sensor_z))
            _apply_complete_layout_padding(
                axis, imaging_physics, plotted_points,
            )
            axis.set_aspect('equal', adjustable='box')
            axis.set_xlabel('X (m)')
            if axis_column == 0:
                axis.set_ylabel('Depth (m)')
            axis.grid(True, linestyle=':', alpha=0.22)
    if single_source_layout:
        for unused_axis in axes.ravel()[len(design_names):]:
            unused_axis.set_visible(False)
    method_label = experiment.get('method_label', 'RTM')
    method_token = experiment.get('method_token', 'RTM')
    fig.suptitle(experiment['title'], fontsize=13, y=0.985)
    if single_source_layout:
        fig.subplots_adjust(
            left=0.075, right=0.975, bottom=0.12, top=0.88,
            wspace=0.18, hspace=0.30,
        )
        colorbar_bounds = (0.22, 0.035, 0.56, 0.020)
    else:
        fig.subplots_adjust(
            left=0.055, right=0.985, bottom=0.18, top=0.78,
            wspace=0.24, hspace=0.55,
        )
        colorbar_bounds = (0.22, 0.065, 0.56, 0.025)
    if image_artist is not None:
        colorbar_axis = fig.add_axes(colorbar_bounds)
        colorbar = fig.colorbar(
            image_artist, cax=colorbar_axis, orientation='horizontal'
        )
        colorbar.set_label(f'Maximum-normalized {method_label} amplitude')
    figure_path = os.path.join(
        output_dir, f"Figure_{method_token}_{experiment['file_token']}.png"
    )
    fig.savefig(figure_path, dpi=300, bbox_inches='tight', pad_inches=0.18)
    plt.close(fig)
    return figure_path


def _rtm_orthogonal_slice_specs_3d(volume, physics, source_index):
    """Return source-centered XY, XZ, and YZ slices of a 3D field."""
    volume = _plain_numpy_array(
        volume, dtype=np.float32, name='3D orthogonal-slice volume',
        expected_ndim=3,
    )
    if volume.ndim != 3 or not physics.is_3d:
        raise ValueError('Three-dimensional orthogonal slices require a 3D field.')
    source_index = tuple(
        int(np.clip(value, 0, volume.shape[dimension] - 1))
        for dimension, value in enumerate(source_index)
    )
    ix, iy, iz = source_index
    dx, dy, dz = (float(value) for value in physics.spacing)
    x_max = (volume.shape[0] - 1) * dx
    y_max = (volume.shape[1] - 1) * dy
    z_max = (volume.shape[2] - 1) * dz
    source_x, source_y, source_z = ix * dx, iy * dy, iz * dz
    return [
        {
            'name': f'XY at z={source_z:.1f} m',
            'data': volume[:, :, iz].T,
            'extent': [0.0, x_max, y_max, 0.0],
            'source_abscissa': source_x,
            'source_ordinate': source_y,
            'xlabel': 'X (m)',
            'ylabel': 'Y (m)',
            'abscissa_spacing': dx,
            'ordinate_spacing': dy,
        },
        {
            'name': f'XZ at y={source_y:.1f} m',
            'data': volume[:, iy, :].T,
            'extent': [0.0, x_max, z_max, 0.0],
            'source_abscissa': source_x,
            'source_ordinate': source_z,
            'xlabel': 'X (m)',
            'ylabel': 'Depth Z (m)',
            'abscissa_spacing': dx,
            'ordinate_spacing': dz,
        },
        {
            'name': f'YZ at x={source_x:.1f} m',
            'data': volume[ix, :, :].T,
            'extent': [0.0, y_max, z_max, 0.0],
            'source_abscissa': source_y,
            'source_ordinate': source_z,
            'xlabel': 'Y (m)',
            'ylabel': 'Depth Z (m)',
            'abscissa_spacing': dy,
            'ordinate_spacing': dz,
        },
    ]


def _plot_rtm_four_array_experiment_3d(
        experiment, images, detail_rows, design_sensors, source_indices,
        output_dir):
    """Plot full 3D RTM results as three source-centered orthogonal slices."""
    imaging_physics = experiment['migration_physics']
    design_names = list(design_sensors)
    metric_lookup = {
        (row['design'], int(row['source_number'])): row
        for row in detail_rows
        if row['experiment'] == experiment['key']
    }
    figure_paths = []
    for source_number, source_index in enumerate(source_indices, start=1):
        velocity_specs = _rtm_orthogonal_slice_specs_3d(
            imaging_physics.V, imaging_physics, source_index
        )
        fig, axes = plt.subplots(
            3,
            len(design_names),
            figsize=(4.8 * len(design_names), 12.8),
            squeeze=False,
            constrained_layout=True,
        )
        image_artist = None
        for design_index, design_name in enumerate(design_names):
            image = images[experiment['key']][design_name][source_number - 1]
            image_specs = _rtm_orthogonal_slice_specs_3d(
                image, imaging_physics, source_index
            )
            metrics = metric_lookup[(design_name, source_number)]
            for plane_index, (velocity_spec, image_spec) in enumerate(zip(
                    velocity_specs, image_specs)):
                axis = axes[plane_index, design_index]
                normalized = _psdm_display_image(image_spec['data'])
                axis.imshow(
                    velocity_spec['data'],
                    cmap='rainbow',
                    extent=velocity_spec['extent'],
                    aspect='equal',
                    alpha=1.0,
                )
                image_alpha = float(os.getenv('PSDM_IMAGE_OVERLAY_ALPHA', '0.45'))
                if not 0.0 <= image_alpha <= 1.0:
                    raise ValueError(
                        'PSDM_IMAGE_OVERLAY_ALPHA must lie in [0, 1].'
                    )
                image_artist = axis.imshow(
                    normalized,
                    cmap='rainbow',
                    extent=image_spec['extent'],
                    aspect='equal',
                    vmin=0.0,
                    vmax=1.0,
                    alpha=image_alpha,
                )
                pad_a = 2.0 * image_spec['abscissa_spacing']
                pad_o = 2.0 * image_spec['ordinate_spacing']
                axis.set_xlim(
                    image_spec['extent'][0] - pad_a,
                    image_spec['extent'][1] + pad_a,
                )
                axis.set_ylim(
                    image_spec['extent'][2] + pad_o,
                    image_spec['extent'][3] - pad_o,
                )
                axis.set_xlabel(image_spec['xlabel'])
                axis.set_aspect('equal', adjustable='box')
                if design_index == 0:
                    axis.set_ylabel(image_spec['ylabel'])
                axis.text(
                    0.02,
                    0.97,
                    image_spec['name'],
                    transform=axis.transAxes,
                    ha='left',
                    va='top',
                    fontsize=9,
                    color='white',
                    bbox={
                        'facecolor': 'black', 'alpha': 0.55,
                        'edgecolor': 'none', 'pad': 2.0,
                    },
                )
                axis.grid(True, linestyle=':', alpha=0.20)
                if plane_index == 0:
                    axis.set_title(
                        f"{design_name} (N={len(design_sensors[design_name])})\n"
                        f"3D peak error={metrics['peak_location_error_m']:.1f} m; "
                        f"focus={metrics['focus_energy_fraction']:.3f}",
                        fontsize=9.4,
                        pad=7,
                    )
        method_label = experiment.get('method_label', 'RTM')
        method_token = experiment.get('method_token', 'RTM')
        fig.suptitle(
            f"{experiment['title']}\n"
            f"Source {source_number}: source-centered 3D orthogonal "
            f"{method_label} slices",
            fontsize=13.5,
        )
        if image_artist is not None:
            colorbar = fig.colorbar(
                image_artist,
                ax=axes.ravel().tolist(),
                shrink=0.72,
                pad=0.012,
            )
            colorbar.set_label(f'Maximum-normalized {method_label} amplitude')
        figure_path = os.path.join(
            output_dir,
            f"Figure_{method_token}_{experiment['file_token']}_"
            f"Source_{source_number:02d}_3D_Orthogonal_Slices.png",
        )
        fig.savefig(
            figure_path, dpi=300, bbox_inches='tight', pad_inches=0.18
        )
        plt.close(fig)
        figure_paths.append(figure_path)
    return figure_paths


def _plot_rtm_four_array_geometry_3d(
        physics, design_sensors, source_indices, output_dir):
    """Plot the actual 3D receiver coordinates used by all four RTM designs."""
    if not physics.is_3d:
        return None
    styles = _rtm_design_styles()
    x_max = (physics.shape[0] - 1) * physics.spacing[0]
    y_max = (physics.shape[1] - 1) * physics.spacing[1]
    z_max = (physics.shape[2] - 1) * physics.spacing[2]
    fig = plt.figure(figsize=(19.0, 5.4), constrained_layout=True)
    for design_index, (design_name, sensors) in enumerate(
            design_sensors.items(), start=1):
        axis = fig.add_subplot(1, len(design_sensors), design_index, projection='3d')
        positions = np.asarray(sensors, dtype=float) * np.asarray(
            physics.spacing, dtype=float
        )
        color, marker = styles[design_name]
        axis.scatter(
            positions[:, 0], positions[:, 1], positions[:, 2],
            c=color, marker=marker, s=26, edgecolor='black', linewidth=0.35,
            alpha=0.92, depthshade=False, label='Receivers',
        )
        source_positions = np.asarray(source_indices, dtype=float) * np.asarray(
            physics.spacing, dtype=float
        )
        axis.scatter(
            source_positions[:, 0], source_positions[:, 1], source_positions[:, 2],
            c=C_SRC, marker='*', s=105, edgecolor='black', linewidth=0.6,
            depthshade=False, label='True sources',
        )
        _apply_complete_layout_padding_3d(
            axis, physics, np.vstack((positions, source_positions))
        )
        axis.set_xlabel('X (m)', labelpad=7)
        axis.set_ylabel('Y (m)', labelpad=7)
        axis.set_zlabel('Depth Z (m)', labelpad=7)
        axis.view_init(elev=27, azim=135)
        axis.set_title(f'{design_name}\nN={len(sensors)}', fontsize=10.5, pad=10)
        if design_index == 1:
            axis.legend(loc='upper left', fontsize=8.5)
    fig.suptitle(
        'Three-dimensional acquisition geometries used in the four-array RTM comparison',
        fontsize=14.5,
    )
    figure_path = os.path.join(
        output_dir, 'Figure_RTM_Four_Design_3D_Acquisition_Geometry.png'
    )
    fig.savefig(figure_path, dpi=300, bbox_inches='tight', pad_inches=0.20)
    plt.close(fig)
    return figure_path


def _plot_legacy_reference_rtm_figures(
        reference_images, physics, source_indices, output_dir):
    """Preserve the attachment's reference-velocity RTM figure products."""
    if len(source_indices) == 0:
        return {}
    required = ('Fixed-velocity optimized', 'Uniform')
    if any(name not in reference_images for name in required):
        return {}
    source_index = source_indices[0]
    velocity_slice = _rtm_xz_slice(physics.V, physics, source_index)
    x_max = (physics.shape[0] - 1) * physics.spacing[0]
    z_max = (physics.shape[-1] - 1) * physics.spacing[-1]
    source_x = source_index[0] * physics.spacing[0]
    source_z = source_index[-1] * physics.spacing[-1]
    if (not reference_images['Fixed-velocity optimized']
            or not reference_images['Uniform']):
        return {}
    fixed_image = _validated_rtm_image(
        reference_images['Fixed-velocity optimized'][0], physics,
        'fixed-velocity optimized reference image',
    )
    uniform_image = _validated_rtm_image(
        reference_images['Uniform'][0], physics, 'uniform reference image',
    )
    fixed_slice = _rtm_xz_slice(fixed_image, physics, source_index)
    uniform_slice = _rtm_xz_slice(uniform_image, physics, source_index)
    vmax = max(
        float(np.max(np.abs(fixed_slice))),
        float(np.max(np.abs(uniform_slice))),
        np.finfo(float).tiny,
    )

    fig, axes = plt.subplots(1, 2, figsize=(14.0, 6.0), constrained_layout=True)
    image_artist = None
    panels = (
        (uniform_slice, 'Uniform array',
         'Reference-velocity RTM; spatial-aliasing baseline'),
        (fixed_slice, 'Fixed-velocity optimized array',
         'Reference-velocity RTM; optimized angular coverage'),
    )
    for axis, (image_slice, title, description) in zip(axes, panels):
        axis.imshow(
            velocity_slice, cmap='rainbow', extent=[0.0, x_max, z_max, 0.0],
            aspect='auto', alpha=0.45,
        )
        image_artist = axis.imshow(
            image_slice, cmap='rainbow', extent=[0.0, x_max, z_max, 0.0],
            aspect='auto', vmin=0.0, vmax=vmax, alpha=0.72,
        )
        axis.scatter(
            [source_x], [source_z], c=C_SRC, marker='*', s=150,
            edgecolor='black', linewidth=0.7, zorder=7,
        )
        axis.set_title(f'{title}\n{description}', fontsize=10.5, pad=9)
        axis.set_xlabel('X (m)')
        axis.set_ylabel('Depth Z (m)')
        axis.grid(True, linestyle=':', alpha=0.22)
    colorbar = fig.colorbar(image_artist, ax=axes, shrink=0.82, pad=0.02)
    colorbar.set_label('RTM energy amplitude')
    fig.suptitle(
        'Spatial-aliasing and crosstalk comparison on the source-centered XZ slice',
        fontsize=14.0,
    )
    alias_path = os.path.join(output_dir, 'Figure_3a_Spatial_Aliasing_Proof.png')
    fig.savefig(alias_path, dpi=300, bbox_inches='tight', pad_inches=0.18)
    plt.close(fig)

    fixed_illumination = np.sum(
        _stack_rtm_images(
            reference_images['Fixed-velocity optimized'], physics,
            'Fixed-velocity optimized',
        ),
        axis=0,
    )
    uniform_illumination = np.sum(
        _stack_rtm_images(reference_images['Uniform'], physics, 'Uniform'),
        axis=0,
    )
    if physics.is_3d:
        fixed_profile = np.mean(fixed_illumination, axis=(0, 1))
        uniform_profile = np.mean(uniform_illumination, axis=(0, 1))
    else:
        fixed_profile = np.mean(fixed_illumination, axis=0)
        uniform_profile = np.mean(uniform_illumination, axis=0)
    depths = np.arange(physics.shape[-1], dtype=float) * physics.spacing[-1]
    fig, axis = plt.subplots(figsize=(6.5, 8.0), constrained_layout=True)
    axis.plot(
        fixed_profile, depths, color=C_OPT, linewidth=2.6,
        label='Fixed-velocity optimized array',
    )
    axis.plot(
        uniform_profile, depths, color=C_UNI, linewidth=2.6,
        linestyle='--', label='Uniform array',
    )
    deep_start = int(physics.shape[-1] * 0.5) * physics.spacing[-1]
    axis.axhspan(
        deep_start, z_max, color='gold', alpha=0.13,
        label='Deep target interval',
    )
    axis.set_ylim(z_max, 0.0)
    axis.set_title('Deep-structure RTM illumination profile', fontsize=13.0)
    axis.set_xlabel('Mean RTM energy')
    axis.set_ylabel('Depth Z (m)')
    axis.grid(True, linestyle=':', alpha=0.50)
    axis.legend(loc='best', fontsize=9.5)
    illumination_path = os.path.join(
        output_dir, 'Figure_2e_Deep_Illumination_Profile.png'
    )
    fig.savefig(
        illumination_path, dpi=300, bbox_inches='tight', pad_inches=0.18
    )
    plt.close(fig)
    return {
        'spatial_aliasing_figure': alias_path,
        'deep_illumination_figure': illumination_path,
    }


def _plot_rtm_metric_comparison(summary_rows, experiment_order, output_dir):
    styles = _rtm_design_styles()
    design_names = list(styles)
    metrics = [
        ('mean_peak_location_error_m', 'Mean peak-location error (m)', False),
        ('mean_focus_energy_fraction', 'Mean focal-energy fraction', True),
        ('mean_source_to_sidelobe_db', 'Mean source-to-sidelobe ratio (dB)', True),
        ('mean_normalized_image_entropy', 'Mean normalized image entropy', False),
        ('mean_reference_image_correlation', 'Mean correlation to reference image', True),
    ]
    metrics = [
        item for item in metrics
        if any(np.isfinite(float(row.get(item[0], np.nan))) for row in summary_rows)
    ]
    labels = {
        'reference_matched': 'Reference\nforward + migration',
        'holdout_true_data_reference_migration': (
            'Unknown true forward\nreference migration'
        ),
    }
    lookup = {
        (row['experiment'], row['design']): row for row in summary_rows
    }
    fig, axes = plt.subplots(2, 3, figsize=(17.5, 9.0), constrained_layout=True)
    x = np.arange(len(experiment_order), dtype=float)
    width = 0.19
    for metric_index, (metric, title, higher_is_better) in enumerate(metrics):
        axis = axes.ravel()[metric_index]
        for design_index, design_name in enumerate(design_names):
            values = [
                lookup[(experiment_key, design_name)][metric]
                for experiment_key in experiment_order
            ]
            color, _ = styles[design_name]
            offset = (design_index - 1.5) * width
            axis.bar(
                x + offset, values, width=width, color=color,
                edgecolor='black', linewidth=0.45, label=design_name,
            )
        axis.set_xticks(x)
        axis.set_xticklabels([labels[key] for key in experiment_order])
        axis.set_title(
            f"{title}\n({'higher' if higher_is_better else 'lower'} is better)",
            fontsize=11,
        )
        axis.grid(True, axis='y', linestyle=':', alpha=0.45)
    axes.ravel()[5].axis('off')
    handles, legend_labels = axes.ravel()[0].get_legend_handles_labels()
    axes.ravel()[5].legend(
        handles, legend_labels, loc='center', frameon=True, fontsize=11
    )
    fig.suptitle(
        'Smoothed-ray coherence-migration comparison of four observation systems',
        fontsize=15,
    )
    figure_path = os.path.join(
        output_dir, 'Figure_PSDM_Four_Design_Quantitative_Comparison.png'
    )
    fig.savefig(figure_path, dpi=300, bbox_inches='tight', pad_inches=0.18)
    plt.close(fig)
    return figure_path


def _plot_reference_data_localization_errors(localization_rows, cases, output_dir):
    """Plot four-array errors for unknown-true data and a fixed reference locator.

    Each case generates observations, while the locator is never changed from
    the reference model. The returned ranking reports the measured winner and
    never forces the velocity-ensemble design to win a realization.
    """
    styles = _rtm_design_styles()
    design_names = [
        name for name in styles
        if any(row['design'] == name for row in localization_rows)
    ]
    case_names = [case['name'] for case in cases]
    if not design_names or not case_names:
        raise ValueError('Localization comparison requires designs and velocity cases.')
    lookup = {
        (row['scenario'], row['design']): row for row in localization_rows
    }
    missing = [
        (case_name, design_name)
        for case_name in case_names for design_name in design_names
        if (case_name, design_name) not in lookup
    ]
    if missing:
        raise ValueError(
            'Localization summary is incomplete; first missing combination: '
            f'{missing[0]}.'
        )

    labels = []
    changed_case_names = []
    for case in cases:
        if case['kind'] == 'reference':
            labels.append('Reference')
        else:
            changed_case_names.append(case['name'])
            labels.append(
                f"{case['name']}\n{100.0 * float(case.get('residual_rms_fraction', 0.0)):.1f}% RMS"
            )
    if not changed_case_names:
        raise ValueError('At least one nonreference velocity case is required.')

    ranking_rows = []
    for case in cases:
        mean_values = {
            design_name: float(lookup[(case['name'], design_name)]['mean_error_m'])
            for design_name in design_names
        }
        p95_values = {
            design_name: float(lookup[(case['name'], design_name)]['p95_error_m'])
            for design_name in design_names
        }
        best_mean = min(mean_values, key=mean_values.get)
        best_p95 = min(p95_values, key=p95_values.get)
        ranking_rows.append({
            'migration_velocity_case': case['name'],
            'migration_velocity_kind': case['kind'],
            'migration_velocity_rms_percent': 100.0 * float(
                case.get('residual_rms_fraction', 0.0)
            ),
            'best_design_by_mean_error': best_mean,
            'best_mean_error_m': mean_values[best_mean],
            'best_design_by_p95_error': best_p95,
            'best_p95_error_m': p95_values[best_p95],
            'velocity_ensemble_robust_is_best_mean': int(
                best_mean == 'Velocity-ensemble robust'
            ),
            'velocity_ensemble_robust_is_best_p95': int(
                best_p95 == 'Velocity-ensemble robust'
            ),
        })

    aggregate_rows = []
    for design_name in design_names:
        changed_mean = np.asarray([
            lookup[(case_name, design_name)]['mean_error_m']
            for case_name in changed_case_names
        ], dtype=float)
        changed_p95 = np.asarray([
            lookup[(case_name, design_name)]['p95_error_m']
            for case_name in changed_case_names
        ], dtype=float)
        aggregate_rows.append({
            'design': design_name,
            'mean_error_over_changed_velocity_models_m': float(np.mean(changed_mean)),
            'worst_p95_error_over_changed_velocity_models_m': float(np.max(changed_p95)),
        })

    x_values = np.arange(len(case_names), dtype=float)
    figure, axes = plt.subplots(2, 2, figsize=(16.5, 10.4))
    for axis, field, ylabel, title in (
            (axes[0, 0], 'mean_error_m', 'Mean localization error (m)',
             '(a) Mean error for new true-model data'),
            (axes[0, 1], 'p95_error_m', '95th-percentile localization error (m)',
             '(b) Upper-tail error for new true-model data')):
        for design_index, design_name in enumerate(design_names):
            color, marker = styles.get(
                design_name,
                ((C_ROB, C_OPT, C_RND, C_UNI)[design_index % 4], 'o'),
            )
            axis.plot(
                x_values,
                [lookup[(case_name, design_name)][field] for case_name in case_names],
                color=color, marker=marker, linewidth=2.0, markersize=6,
                label=design_name,
            )
        axis.axvspan(0.5, len(case_names) - 0.5, color='0.92', zorder=-5)
        axis.set_xticks(x_values, labels, rotation=24, ha='right')
        axis.set_ylabel(ylabel)
        axis.set_title(title)
        axis.grid(True, linestyle=':', alpha=0.50)
    axes[0, 0].legend(loc='best', fontsize=8)

    aggregate_lookup = {row['design']: row for row in aggregate_rows}
    for axis, field, ylabel, title in (
            (axes[1, 0], 'mean_error_over_changed_velocity_models_m',
             'Mean localization error (m)',
             '(c) Mean error across changed velocity models'),
            (axes[1, 1], 'worst_p95_error_over_changed_velocity_models_m',
             '95th-percentile localization error (m)',
             '(d) Worst changed-model upper-tail error')):
        values = [aggregate_lookup[name][field] for name in design_names]
        bars = axis.bar(
            np.arange(len(design_names)), values,
            color=[
                styles[name][0] if name in styles
                else (C_ROB, C_OPT, C_RND, C_UNI)[index % 4]
                for index, name in enumerate(design_names)
            ],
            edgecolor='black', linewidth=0.5,
        )
        for bar, value in zip(bars, values):
            axis.text(
                bar.get_x() + 0.5 * bar.get_width(), value,
                f'{value:.2f}', ha='center', va='bottom', fontsize=8,
            )
        axis.set_xticks(np.arange(len(design_names)), design_names,
                           rotation=18, ha='right')
        axis.set_ylabel(ylabel)
        axis.set_title(title)
        axis.grid(True, axis='y', linestyle=':', alpha=0.50)

    figure.suptitle(
        'Four observation systems: unknown-true-model data located with the reference model',
        fontsize=14,
    )
    figure.tight_layout(rect=(0.0, 0.0, 1.0, 0.95))
    figure_path = os.path.join(
        output_dir, 'Figure_Four_Designs_Reference_Data_Localization_Errors.png'
    )
    figure.savefig(figure_path, dpi=300, bbox_inches='tight', pad_inches=0.18)
    plt.close(figure)
    return figure_path, ranking_rows, aggregate_rows


def _rtm_cache_signature(reference_physics, migration_physics, migration_case,
                         design_sensors, source_indices, wrappers):
    """Hash every input that changes reference data or a migrated RTM image."""
    digest = hashlib.sha256(b'rtm-reference-data-checkpoint-format-v3')
    for value in (
            tuple(reference_physics.shape), tuple(reference_physics.spacing),
            tuple(migration_physics.shape), tuple(migration_physics.spacing),
            str(migration_case['name']), tuple(tuple(item) for item in source_indices)):
        digest.update(repr(value).encode('utf-8'))
    for design_name, sensors in design_sensors.items():
        digest.update(design_name.encode('utf-8'))
        digest.update(repr(tuple(sensors)).encode('utf-8'))
    for label, physics in (
            ('reference_forward', reference_physics),
            ('perturbed_migration', migration_physics)):
        velocity = _plain_numpy_array(
            physics.V, dtype=np.float32, name=f'{label} velocity model'
        )
        digest.update(label.encode('ascii'))
        digest.update(velocity.tobytes(order='C'))
    for wrapper in wrappers:
        digest.update(repr((
            float(wrapper.f0), float(wrapper.tn), float(wrapper.dt),
            int(wrapper.time_range.num), int(wrapper.model.nbl),
            int(wrapper.solver.space_order),
        )).encode('ascii'))
    return digest.hexdigest()[:20]


def _rtm_use_saved_wavefield(wrapper):
    """Select source-wavefield reuse without exceeding a configurable limit."""
    mode = os.getenv('RTM_WAVEFIELD_MODE', 'auto').strip().lower()
    if mode not in {'auto', 'saved', 'checkpoint'}:
        raise ValueError(
            'RTM_WAVEFIELD_MODE must be auto, saved, or checkpoint.'
        )
    estimated_bytes = wrapper.estimated_saved_wavefield_bytes()
    limit_gb = float(os.getenv('RTM_MAX_SAVED_WAVEFIELD_GB', '2.0'))
    if limit_gb <= 0.0:
        raise ValueError('RTM_MAX_SAVED_WAVEFIELD_GB must be positive.')
    enabled = mode == 'saved' or (
        mode == 'auto' and estimated_bytes <= limit_gb * (1024.0 ** 3)
    )
    print(
        '    [RTM] source-wavefield policy: '
        f"{'reuse saved wavefield' if enabled else 'Devito checkpointing'}; "
        f'estimated saved size={estimated_bytes / (1024.0 ** 3):.2f} GiB, '
        f'limit={limit_gb:.2f} GiB.'
    )
    return enabled


def _rtm_image_checkpoint_base(checkpoint_dir, experiment_key, design_name,
                               source_number):
    experiment_token = hashlib.sha1(
        str(experiment_key).encode('utf-8')
    ).hexdigest()[:8]
    design_token = hashlib.sha1(
        str(design_name).encode('utf-8')
    ).hexdigest()[:8]
    return os.path.join(
        checkpoint_dir,
        f"img__{experiment_token}__{design_token}__s{source_number:03d}",
    )


def _run_four_design_velocity_rtm_comparison_legacy(
        reference_physics, velocity_cases, robust_sensors,
        fixed_optimized_sensors, random_sensors, uniform_sensors,
        source_indices, output_dir, legacy_output_dir=None):
    """Compare four arrays using reference forward data only.

    A union-receiver acoustic forward solve is performed once per source in
    ``reference_physics``.  The exact same traces are then migrated with the
    reference model and with one selected perturbed migration model.  In
    parallel, reference-model traveltimes are located with every velocity case
    to quantify four-array localization robustness without generating changed-
    velocity observations.
    """
    if not DEVITO_AVAILABLE:
        raise RuntimeError('Devito is required for the four-design RTM comparison.')
    rtm_dir = os.path.join(output_dir, 'four_design_rtm_comparison')
    os.makedirs(rtm_dir, exist_ok=True)
    mismatch_case = _select_rtm_changed_velocity_case(velocity_cases)
    mismatch_physics = mismatch_case['physics']
    model_dimension = len(reference_physics.shape)
    if model_dimension not in (2, 3):
        raise ValueError('The RTM comparison supports only 2D or 3D models.')
    if bool(reference_physics.is_3d) != (model_dimension == 3):
        raise ValueError('physics.is_3d is inconsistent with the model shape.')
    if tuple(mismatch_physics.shape) != tuple(reference_physics.shape):
        raise ValueError('Reference and changed velocity models must share a grid.')
    focus_radius_cells = float(os.getenv('RTM_FOCUS_RADIUS_CELLS', '3.0'))
    if focus_radius_cells <= 0.0:
        raise ValueError('RTM_FOCUS_RADIUS_CELLS must be positive.')
    design_sensors = {
        'Fixed-velocity optimized': [tuple(sensor) for sensor in fixed_optimized_sensors],
        'Random': [tuple(sensor) for sensor in random_sensors],
        'Uniform': [tuple(sensor) for sensor in uniform_sensors],
        'Velocity-ensemble robust': [tuple(sensor) for sensor in robust_sensors],
    }
    for design_name, sensors in design_sensors.items():
        if not sensors:
            raise ValueError(f'{design_name} contains no receivers.')
        if any(len(sensor) != model_dimension for sensor in sensors):
            raise ValueError(
                f'{design_name} receiver dimensionality does not match the model.'
            )
    if not source_indices:
        raise ValueError('The RTM comparison requires at least one source.')
    if any(len(source_index) != model_dimension for source_index in source_indices):
        raise ValueError('Source dimensionality does not match the velocity model.')
    reference_wrapper = DevitoRTMWrapper(reference_physics)
    mismatch_wrapper = DevitoRTMWrapper(mismatch_physics)
    experiments = [
        {
            'key': 'reference_matched',
            'file_token': 'Reference_Data_Reference_Migration_Four_Arrays',
            'title': 'Reference-model forward data migrated with the reference model',
            'data_physics': reference_physics,
            'migration_physics': reference_physics,
            'data_wrapper': reference_wrapper,
            'migration_wrapper': reference_wrapper,
        },
        {
            'key': 'reference_data_mismatched_migration',
            'file_token': 'Reference_Data_Perturbed_Migration_Four_Arrays',
            'title': (
                'Reference-model forward data migrated with the perturbed '
                f"velocity model ({mismatch_case['name']}; velocity mismatch)"
            ),
            'data_physics': reference_physics,
            'migration_physics': mismatch_physics,
            'data_wrapper': reference_wrapper,
            'migration_wrapper': mismatch_wrapper,
        },
    ]

    resume_enabled = os.getenv('RTM_RESUME', '1') != '0'
    save_text = os.getenv('RTM_SAVE_TEXT', '1') != '0'
    time_budget_seconds = float(os.getenv('RTM_TIME_BUDGET_SECONDS', '3600'))
    if time_budget_seconds <= 0.0:
        raise ValueError('RTM_TIME_BUDGET_SECONDS must be positive.')
    signature = _rtm_cache_signature(
        reference_physics, mismatch_physics, mismatch_case, design_sensors,
        source_indices, (reference_wrapper, mismatch_wrapper),
    )
    checkpoint_root = os.getenv(
        'RTM_CACHE_DIR', os.path.join(rtm_dir, 'rtm_checkpoints')
    )
    checkpoint_dir = os.path.join(checkpoint_root, signature)
    os.makedirs(checkpoint_dir, exist_ok=True)
    _write_matlab_loader(checkpoint_dir)
    _save_rtm_checkpoint(
        os.path.join(checkpoint_dir, 'reference_velocity_model'),
        reference_physics.V, save_text=save_text,
    )
    _save_rtm_checkpoint(
        os.path.join(checkpoint_dir, 'perturbed_migration_velocity_model'),
        mismatch_physics.V, save_text=save_text,
    )

    for experiment in experiments:
        experiment['data_case'] = 'reference'
        experiment['migration_case'] = (
            'reference' if experiment['migration_physics'] is reference_physics
            else str(mismatch_case['name'])
        )
    union_sensors = []
    for sensors in design_sensors.values():
        for sensor in sensors:
            if sensor not in union_sensors:
                union_sensors.append(sensor)
    union_lookup = {sensor: index for index, sensor in enumerate(union_sensors)}
    design_columns = {
        name: [union_lookup[sensor] for sensor in sensors]
        for name, sensors in design_sensors.items()
    }
    manifest_path = os.path.join(checkpoint_dir, 'rtm_checkpoint_manifest.json')
    manifest = {
        'format_version': 3,
        'signature': signature,
        'created_unix_seconds': time.time(),
        'checkpoint_directory': os.path.abspath(checkpoint_dir),
        'rtm_output_directory': os.path.abspath(rtm_dir),
        'legacy_output_directory': os.path.abspath(
            output_dir if legacy_output_dir is None else legacy_output_dir
        ),
        'model_shape': list(reference_physics.shape),
        'model_spacing_m': [float(value) for value in reference_physics.spacing],
        'is_3d': bool(reference_physics.is_3d),
        'source_indices': [list(source) for source in source_indices],
        'design_sensor_indices': {
            name: [list(sensor) for sensor in sensors]
            for name, sensors in design_sensors.items()
        },
        'reference_data_only': True,
        'migration_velocity_case': str(mismatch_case['name']),
        'focus_radius_cells': focus_radius_cells,
        'save_matlab_text': save_text,
        'experiments': [{
            'key': experiment['key'],
            'file_token': experiment['file_token'],
            'title': experiment['title'],
            'data_case': experiment['data_case'],
            'migration_case': experiment['migration_case'],
        } for experiment in experiments],
    }
    _atomic_write_json(manifest_path, manifest)

    images = {
        experiment['key']: {design_name: [] for design_name in design_sensors}
        for experiment in experiments
    }
    # A single reference-model forward solve records the union of all
    # receivers. Each design is an exact column subset, and the same traces are
    # reused for both migration models. Thus no perturbed-velocity forward data
    # are created by this comparison.
    forward_data_cache = {}
    wavefield_policy = {
        reference_wrapper: _rtm_use_saved_wavefield(reference_wrapper),
        mismatch_wrapper: _rtm_use_saved_wavefield(mismatch_wrapper),
    }
    detail_rows = []
    rtm_start = time.perf_counter()
    completed_images = 0
    budget_warning_emitted = False
    total_images = len(experiments) * len(design_sensors) * len(source_indices)
    for experiment in experiments:
        print(f"    [RTM] {experiment['title']}")
        for source_number, source_index in enumerate(source_indices, start=1):
            source_images = {}
            missing_designs = []
            for design_name in design_sensors:
                image_base = _rtm_image_checkpoint_base(
                    checkpoint_dir, experiment['key'], design_name, source_number
                )
                image = (
                    _load_rtm_checkpoint(image_base, reference_physics.shape)
                    if resume_enabled else None
                )
                if image is None:
                    missing_designs.append(design_name)
                else:
                    source_images[design_name] = image
                    print(
                        f'        [resume] source {source_number}, {design_name}'
                    )

            source_wavefield = None
            data_all = None
            if missing_designs:
                data_cache_key = (experiment['data_case'], source_number)
                if data_cache_key in forward_data_cache:
                    data_all, data_dt = forward_data_cache[data_cache_key]
                else:
                    forward_base = os.path.join(
                        checkpoint_dir,
                        f"forward__{_safe_file_token(experiment['data_case'])}__"
                        f"source_{source_number:03d}__union_receivers",
                    )
                    data_all = (
                        _load_rtm_checkpoint(
                            forward_base,
                            (int(experiment['data_wrapper'].time_range.num),
                             len(union_sensors)),
                        ) if resume_enabled else None
                    )
                    dt_path = f'{forward_base}.dt.txt'
                    if data_all is not None and os.path.isfile(dt_path):
                        data_dt = float(np.loadtxt(dt_path))
                    else:
                        save_wavefield_on_forward = (
                            wavefield_policy[experiment['migration_wrapper']]
                            and experiment['data_wrapper']
                            is experiment['migration_wrapper']
                        )
                        data_all, data_dt, source_wavefield = (
                            experiment['data_wrapper'].forward_modeling(
                                source_index, union_sensors,
                                save_wavefield=save_wavefield_on_forward,
                            )
                        )
                        _save_rtm_checkpoint(
                            forward_base, data_all, save_text=save_text
                        )
                        dt_temporary = f'{dt_path}.tmp'
                        np.savetxt(dt_temporary, np.asarray([[data_dt]]), fmt='%.12e')
                        os.replace(dt_temporary, dt_path)
                    forward_data_cache[data_cache_key] = (data_all, float(data_dt))

                if (wavefield_policy[experiment['migration_wrapper']]
                        and source_wavefield is None):
                    source_wavefield = (
                        experiment['migration_wrapper'].source_wavefield(source_index)
                    )
                for design_name in missing_designs:
                    sensors = design_sensors[design_name]
                    columns = design_columns[design_name]
                    data = _plain_numpy_array(
                        data_all[:, columns], dtype=np.float32,
                        name=f'{design_name} receiver data', expected_ndim=2,
                    )
                    image = experiment['migration_wrapper'].rtm_imaging(
                        data,
                        source_wavefield,
                        sensors,
                        src_idx_guess=source_index,
                        data_dt=data_dt,
                    )
                    image = _validated_rtm_image(
                        image, experiment['migration_physics'],
                        f"{experiment['key']} / {design_name} / source {source_number}",
                    )
                    image_base = _rtm_image_checkpoint_base(
                        checkpoint_dir, experiment['key'], design_name,
                        source_number,
                    )
                    _save_rtm_checkpoint(image_base, image, save_text=save_text)
                    source_images[design_name] = image
                    completed_images += 1
                    elapsed = time.perf_counter() - rtm_start
                    if completed_images > 0:
                        projected = elapsed * total_images / completed_images
                        if (projected > time_budget_seconds
                                and not budget_warning_emitted):
                            warnings.warn(
                                'Current RTM timing projects beyond the requested '
                                f'{time_budget_seconds / 3600.0:.2f}-hour budget '
                                f'({projected / 3600.0:.2f} h). Check OMP_NUM_THREADS, '
                                'use RTM_WAVEFIELD_MODE=saved when memory permits, or '
                                'resume on a faster host.', RuntimeWarning,
                            )
                            budget_warning_emitted = True
                del source_wavefield
                gc.collect()

            for design_name, sensors in design_sensors.items():
                image = source_images[design_name]
                images[experiment['key']][design_name].append(image)
                metrics = _rtm_image_metrics(
                    image, source_index, reference_physics.spacing,
                    focus_radius_cells,
                )
                detail_rows.append({
                    'experiment': experiment['key'],
                    'design': design_name,
                    'number_of_receivers': len(sensors),
                    'source_number': source_number,
                    'source_index': list(source_index),
                    'data_velocity_case': experiment['data_case'],
                    'migration_velocity_case': experiment['migration_case'],
                    'velocity_mismatch': int(
                        experiment['data_physics'] is not experiment['migration_physics']
                    ),
                    **metrics,
                })

    detail_lookup = {
        (row['experiment'], row['design'], row['source_number']): row
        for row in detail_rows
    }
    for experiment in experiments:
        for design_name in design_sensors:
            for source_number in range(1, len(source_indices) + 1):
                reference_image = images['reference_matched'][design_name][
                    source_number - 1
                ]
                current_image = images[experiment['key']][design_name][
                    source_number - 1
                ]
                detail_lookup[(
                    experiment['key'], design_name, source_number
                )]['reference_image_correlation'] = _rtm_image_correlation(
                    reference_image, current_image
                )

    summary_rows = []
    for experiment in experiments:
        for design_name, sensors in design_sensors.items():
            rows = [
                row for row in detail_rows
                if row['experiment'] == experiment['key']
                and row['design'] == design_name
            ]
            summary_rows.append({
                'experiment': experiment['key'],
                'design': design_name,
                'number_of_receivers': len(sensors),
                'number_of_sources': len(rows),
                'mean_peak_location_error_m': float(np.mean([
                    row['peak_location_error_m'] for row in rows
                ])),
                'mean_focus_energy_fraction': float(np.mean([
                    row['focus_energy_fraction'] for row in rows
                ])),
                'mean_source_to_sidelobe_db': float(np.mean([
                    row['source_to_sidelobe_db'] for row in rows
                ])),
                'mean_normalized_image_entropy': float(np.mean([
                    row['normalized_image_entropy'] for row in rows
                ])),
                'mean_reference_image_correlation': float(np.mean([
                    row['reference_image_correlation'] for row in rows
                ])),
            })

    _write_csv(os.path.join(rtm_dir, 'rtm_four_design_source_metrics.csv'), detail_rows)
    _write_csv(os.path.join(rtm_dir, 'rtm_four_design_summary_metrics.csv'), summary_rows)
    experiment_figures = {}
    for experiment in experiments:
        experiment_figures[experiment['key']] = _plot_rtm_four_array_experiment(
            experiment,
            images,
            detail_rows,
            design_sensors,
            source_indices,
            rtm_dir,
        )
    geometry_figure = _plot_rtm_four_array_geometry_3d(
        reference_physics, design_sensors, source_indices, rtm_dir
    )
    legacy_figures = _plot_legacy_reference_rtm_figures(
        images['reference_matched'],
        reference_physics,
        source_indices,
        output_dir if legacy_output_dir is None else legacy_output_dir,
    )
    metric_figure = _plot_rtm_metric_comparison(
        summary_rows,
        [experiment['key'] for experiment in experiments],
        rtm_dir,
    )
    localization_realizations = int(os.getenv(
        'RTM_LOCALIZATION_MC', os.getenv('FUTURE_VELOCITY_MC', '20')
    ))
    localization_noise_std = float(os.getenv(
        'RTM_LOCALIZATION_NOISE_STD',
        os.getenv('REVIEW_PICKING_NOISE_STD', '0.002'),
    ))
    localization_seed = int(os.getenv('RTM_LOCALIZATION_SEED', '19001'))
    if localization_realizations <= 0:
        raise ValueError('RTM_LOCALIZATION_MC must be positive.')
    if localization_noise_std <= 0.0:
        raise ValueError('RTM_LOCALIZATION_NOISE_STD must be positive.')
    localization_noise_model = OperationalNoiseModel(
        'Reference-forward Gaussian IID',
        kind='gaussian',
        sigma=localization_noise_std,
    )
    localization_rows = []
    localization_trials = []
    for design_name, sensors in design_sensors.items():
        design_rows, design_trials = _evaluate_design_across_velocity_ensemble(
            reference_physics,
            velocity_cases,
            sensors,
            source_indices,
            localization_noise_model,
            localization_realizations,
            localization_seed,
            design_name,
        )
        localization_rows.extend(design_rows)
        localization_trials.extend(design_trials)
    localization_figure, localization_rankings, localization_aggregate = (
        _plot_reference_data_localization_errors(
            localization_rows, velocity_cases, rtm_dir
        )
    )
    best_changed_mean = min(
        localization_aggregate,
        key=lambda row: row['mean_error_over_changed_velocity_models_m'],
    )
    best_changed_p95 = min(
        localization_aggregate,
        key=lambda row: row['worst_p95_error_over_changed_velocity_models_m'],
    )
    robust_localization_evidence = {
        'best_design_by_changed_model_mean_error': best_changed_mean['design'],
        'best_changed_model_mean_error_m': (
            best_changed_mean['mean_error_over_changed_velocity_models_m']
        ),
        'best_design_by_worst_changed_model_p95_error': best_changed_p95['design'],
        'best_worst_changed_model_p95_error_m': (
            best_changed_p95['worst_p95_error_over_changed_velocity_models_m']
        ),
        'velocity_ensemble_robust_is_best_on_both_aggregate_metrics': bool(
            best_changed_mean['design'] == 'Velocity-ensemble robust'
            and best_changed_p95['design'] == 'Velocity-ensemble robust'
        ),
    }
    print(
        '    [localization] changed-model mean-error winner: '
        f"{best_changed_mean['design']} "
        f"({best_changed_mean['mean_error_over_changed_velocity_models_m']:.3f} m); "
        'worst-P95 winner: '
        f"{best_changed_p95['design']} "
        f"({best_changed_p95['worst_p95_error_over_changed_velocity_models_m']:.3f} m)."
    )
    if not robust_localization_evidence[
            'velocity_ensemble_robust_is_best_on_both_aggregate_metrics']:
        warnings.warn(
            'The computed reference-data localization test does not support '
            'the claim that the velocity-ensemble robust array is smallest on '
            'both changed-model aggregate metrics. Inspect the exported ranking '
            'and trial tables instead of asserting that conclusion.',
            RuntimeWarning,
        )
    _write_csv(
        os.path.join(rtm_dir, 'reference_data_localization_error_summary.csv'),
        localization_rows,
    )
    _write_csv(
        os.path.join(rtm_dir, 'reference_data_localization_error_trials.csv'),
        localization_trials,
    )
    _write_csv(
        os.path.join(rtm_dir, 'reference_data_localization_error_ranking.csv'),
        localization_rankings,
    )
    _write_csv(
        os.path.join(rtm_dir, 'reference_data_localization_error_aggregate.csv'),
        localization_aggregate,
    )
    inventory = {
        'algorithm': (
            f'Four-array {model_dimension}D acoustic RTM with reference-model '
            'forward data only, reference and perturbed migration velocities, '
            'automatic trace resampling, and full-domain image metrics.'
        ),
        'model_dimension': model_dimension,
        'image_metric_domain': (
            'complete 3D volume' if model_dimension == 3 else 'complete 2D image'
        ),
        'reference_data_only': True,
        'perturbed_migration_velocity_scenario': mismatch_case['name'],
        'perturbed_migration_velocity_kind': mismatch_case['kind'],
        'perturbed_migration_velocity_domain_rms_fraction': float(
            mismatch_case.get('residual_rms_fraction', np.nan)
        ),
        'perturbed_migration_velocity_target_rms_fraction': float(
            mismatch_case.get('target_zone_residual_rms_fraction', np.nan)
        ),
        'perturbed_migration_velocity_background_rms_fraction': float(
            mismatch_case.get('background_residual_rms_fraction', np.nan)
        ),
        'focus_radius_cells': focus_radius_cells,
        'focus_radius_m': (
            focus_radius_cells * float(np.min(reference_physics.spacing))
        ),
        'checkpoint_signature': signature,
        'checkpoint_directory': os.path.abspath(checkpoint_dir),
        'checkpoint_manifest': os.path.abspath(manifest_path),
        'resume_enabled': resume_enabled,
        'matlab_text_enabled': save_text,
        'forward_receiver_strategy': (
            'one reference-model union-receiver forward solve per source; '
            'receiver-column subsets are reused by every array and migration model'
        ),
        'saved_wavefield_reuse': {
            'reference': bool(wavefield_policy[reference_wrapper]),
            'perturbed_migration': bool(wavefield_policy[mismatch_wrapper]),
        },
        'design_sensor_indices': {
            name: _sensor_coordinates_for_json(sensors)
            for name, sensors in design_sensors.items()
        },
        'experiments': [
            {
                'key': experiment['key'],
                'title': experiment['title'],
                'data_velocity': 'reference',
                'migration_velocity': (
                    'reference' if experiment['migration_physics'] is reference_physics
                    else mismatch_case['name']
                ),
                'velocity_mismatch': bool(
                    experiment['data_physics'] is not experiment['migration_physics']
                ),
                'figure': experiment_figures[experiment['key']],
            }
            for experiment in experiments
        ],
        'three_dimensional_acquisition_geometry_figure': geometry_figure,
        'legacy_reference_velocity_rtm_figures': legacy_figures,
        'metric_comparison_figure': metric_figure,
        'source_metric_table': os.path.join(
            rtm_dir, 'rtm_four_design_source_metrics.csv'
        ),
        'summary_metric_table': os.path.join(
            rtm_dir, 'rtm_four_design_summary_metrics.csv'
        ),
        'reference_data_localization_error_figure': localization_figure,
        'reference_data_localization_error_summary_table': os.path.join(
            rtm_dir, 'reference_data_localization_error_summary.csv'
        ),
        'reference_data_localization_error_trial_table': os.path.join(
            rtm_dir, 'reference_data_localization_error_trials.csv'
        ),
        'reference_data_localization_error_ranking_table': os.path.join(
            rtm_dir, 'reference_data_localization_error_ranking.csv'
        ),
        'reference_data_localization_error_aggregate_table': os.path.join(
            rtm_dir, 'reference_data_localization_error_aggregate.csv'
        ),
        'reference_data_localization_error_rankings': localization_rankings,
        'reference_data_localization_error_aggregate': localization_aggregate,
        'reference_data_localization_evidence': robust_localization_evidence,
        'summary_metrics': summary_rows,
    }
    inventory_path = os.path.join(rtm_dir, 'rtm_four_design_inventory.json')
    with open(inventory_path, 'w', encoding='utf-8') as stream:
        json.dump(inventory, stream, indent=2)
    inventory['inventory_json'] = inventory_path
    return inventory


def _append_csv(path, rows):
    """Append homogeneous dictionaries without retaining previous trials."""
    if not rows:
        return
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    exists = os.path.isfile(path) and os.path.getsize(path) > 0
    with open(path, 'a', newline='', encoding='utf-8') as stream:
        writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
        if not exists:
            writer.writeheader()
        writer.writerows(rows)


def _plot_single_velocity_model(physics, source_indices, title, output_path):
    """Plot each velocity result immediately with a physical aspect ratio."""
    if physics.is_3d:
        specifications = _rtm_orthogonal_slice_specs_3d(
            physics.V, physics, tuple(source_indices[0])
        )
        figure, axes = plt.subplots(
            1, 3, figsize=(15.5, 5.0), constrained_layout=True
        )
        artist = None
        for axis, specification in zip(axes, specifications):
            artist = axis.imshow(
                specification['data'], cmap='rainbow',
                extent=specification['extent'], aspect='equal',
            )
            axis.scatter(
                [specification['source_abscissa']],
                [specification['source_ordinate']],
                c='white', marker='*', s=82, edgecolor='black', linewidth=0.6,
            )
            axis.set_title(specification['name'], fontsize=10, pad=7)
            axis.set_xlabel(specification['xlabel'])
            axis.set_ylabel(specification['ylabel'])
            axis.set_aspect('equal', adjustable='box')
        figure.colorbar(artist, ax=axes.ravel().tolist(), shrink=0.72).set_label(
            'Velocity (m/s)'
        )
    else:
        figure, axis = plt.subplots(
            figsize=(8.8, 6.6), constrained_layout=True
        )
        x_max = (physics.shape[0] - 1) * physics.spacing[0]
        z_max = (physics.shape[-1] - 1) * physics.spacing[-1]
        artist = axis.imshow(
            np.asarray(physics.V).T, cmap='rainbow',
            extent=[0.0, x_max, z_max, 0.0], aspect='equal',
        )
        positions = _source_positions_in_metres(physics, source_indices)
        axis.scatter(
            positions[:, 0], positions[:, -1], c='white', marker='*', s=82,
            edgecolor='black', linewidth=0.6, label='Sources',
        )
        pad_x = 2.0 * physics.spacing[0]
        pad_z = 2.0 * physics.spacing[-1]
        axis.set_xlim(min(0.0, float(np.min(positions[:, 0]))) - pad_x,
                      max(x_max, float(np.max(positions[:, 0]))) + pad_x)
        axis.set_ylim(max(z_max, float(np.max(positions[:, -1]))) + pad_z,
                      min(0.0, float(np.min(positions[:, -1]))) - pad_z)
        axis.set_aspect('equal', adjustable='box')
        axis.set_xlabel('X (m)')
        axis.set_ylabel('Depth (m)')
        axis.legend(loc='best')
        figure.colorbar(artist, ax=axis, pad=0.02).set_label('Velocity (m/s)')
    figure.suptitle(title, fontsize=13)
    figure.savefig(output_path, dpi=300, bbox_inches='tight', pad_inches=0.16)
    plt.close(figure)
    return output_path


def _reference_first_arrivals(reference_physics, source_index, union_sensors):
    """Generate one reference-model arrival vector for the union receiver set."""
    field = _plain_numpy_array(
        reference_physics.compute_traveltime_field(tuple(source_index)),
        dtype=np.float64, name='reference source traveltime field',
        expected_ndim=len(reference_physics.shape),
    )
    coordinates = tuple(np.asarray(union_sensors, dtype=int).T)
    arrivals = np.asarray(field[coordinates], dtype=np.float64)
    del field
    return arrivals


def _plot_reference_arrivals(arrivals, source_number, output_dir,
                             data_label='Reference-model', file_token='Reference'):
    """Plot a true-data arrival vector immediately after calculation/loading."""
    figure, axis = plt.subplots(figsize=(8.8, 5.2), constrained_layout=True)
    receiver_numbers = np.arange(1, len(arrivals) + 1)
    axis.plot(receiver_numbers, arrivals, color='#264653', marker='o',
              markersize=3.5, linewidth=1.5)
    axis.set_xlabel('Union-receiver number')
    axis.set_ylabel('Reference first-arrival time (s)')
    axis.set_title(f'{data_label} first arrivals — source {source_number}', pad=8)
    axis.grid(True, linestyle=':', alpha=0.45)
    path = os.path.join(
        output_dir,
        f'Figure_{_safe_file_token(file_token)}_First_Arrivals_'
        f'Source_{source_number:02d}.png'
    )
    figure.savefig(path, dpi=300, bbox_inches='tight', pad_inches=0.14)
    plt.close(figure)
    return path


def _psdm_recording_parameters(reference_physics):
    """Return the complete-PSDM wavelet sampling and recording duration."""
    dt = float(os.getenv('PSDM_DT_SECONDS', '0.001'))
    frequency_hz = float(os.getenv('PSDM_WAVELET_FREQUENCY_HZ', '25.0'))
    if dt <= 0.0 or frequency_hz <= 0.0:
        raise ValueError(
            'PSDM_DT_SECONDS and PSDM_WAVELET_FREQUENCY_HZ must be positive.'
        )
    if dt * frequency_hz > 0.20:
        raise ValueError(
            'PSDM_DT_SECONDS is too large for PSDM_WAVELET_FREQUENCY_HZ; '
            'use at least five time samples per dominant period.'
        )
    requested_seconds = float(os.getenv('PSDM_RECORD_SECONDS', '0.0'))
    if requested_seconds > 0.0:
        record_seconds = requested_seconds
    else:
        physical_extent = (
            (np.asarray(reference_physics.shape, dtype=float) - 1.0)
            * np.asarray(reference_physics.spacing, dtype=float)
        )
        minimum_velocity = max(
            float(np.min(np.asarray(reference_physics.V, dtype=float))), 1.0
        )
        record_seconds = (
            1.10 * float(np.linalg.norm(physical_extent)) / minimum_velocity
            + 4.0 / frequency_hz
        )
    sample_count = max(3, int(np.ceil(record_seconds / dt)) + 1)
    return dt, frequency_hz, sample_count, (sample_count - 1) * dt


def _reference_traveltime_gather(reference_physics, source_index,
                                  union_sensors, dt, frequency_hz,
                                  sample_count):
    """Synthesize the complete-PSDM reference first-arrival Ricker gather."""
    source_field = _plain_numpy_array(
        reference_physics.compute_traveltime_field(tuple(source_index)),
        dtype=np.float64, name='reference source traveltime field',
        expected_ndim=len(reference_physics.shape),
    )
    receiver_coordinates = tuple(np.asarray(union_sensors, dtype=int).T)
    arrivals = np.asarray(source_field[receiver_coordinates], dtype=float)
    time_axis = np.arange(sample_count, dtype=float) * float(dt)
    delay = time_axis[:, None] - arrivals[None, :]
    phase = (np.pi * float(frequency_hz) * delay) ** 2
    gather = (1.0 - 2.0 * phase) * np.exp(-phase)
    del source_field, delay, phase
    return np.asarray(gather, dtype=np.float32), arrivals


def _plot_reference_traveltime_gather(gather, dt, source_number, output_dir):
    """Plot and save a reference gather immediately after it is available."""
    gather = _plain_numpy_array(
        gather, dtype=np.float32, name='reference traveltime gather',
        expected_ndim=2,
    )
    figure, axis = plt.subplots(figsize=(9.2, 6.2), constrained_layout=True)
    artist = axis.imshow(
        gather, origin='upper', aspect='auto', cmap='rainbow',
        extent=[0.5, gather.shape[1] + 0.5,
                (gather.shape[0] - 1) * dt, 0.0],
    )
    axis.set_xlabel('Union-receiver trace number')
    axis.set_ylabel('Time (s)')
    axis.set_title(
        f'Reference-model first-arrival gather — source {source_number}', pad=9
    )
    figure.colorbar(artist, ax=axis, pad=0.02).set_label('Normalized amplitude')
    path = os.path.join(
        output_dir,
        f'Figure_Reference_Traveltime_Gather_Source_{source_number:02d}.png',
    )
    figure.savefig(path, dpi=300, bbox_inches='tight', pad_inches=0.15)
    plt.close(figure)
    return path


def _sample_trace_on_traveltime_field(trace, traveltime, dt):
    """Linearly sample a trace at the migration-model receiver traveltimes."""
    trace = np.asarray(trace, dtype=np.float32).ravel()
    traveltime = _plain_numpy_array(
        traveltime, dtype=np.float32, name='receiver traveltime field'
    )
    floating_index = traveltime / float(dt)
    finite = np.isfinite(floating_index)
    safe_index = np.where(finite, floating_index, -1.0)
    lower = np.floor(safe_index).astype(np.int64)
    valid = finite & (lower >= 0) & (lower < trace.size - 1)
    upper = np.clip(lower + 1, 0, trace.size - 1)
    lower = np.clip(lower, 0, trace.size - 1)
    fraction = safe_index - lower
    sampled = np.zeros(traveltime.shape, dtype=np.float32)
    sampled[valid] = (
        (1.0 - fraction[valid]) * trace[lower[valid]]
        + fraction[valid] * trace[upper[valid]]
    )
    return sampled


def _backtrack_eikonal_ray_path(traveltime, start_index, receiver_index,
                                spacing, maximum_steps=None):
    """Backtrack one discrete steepest-descent ray on an eikonal time field.

    ``traveltime`` is the cached field whose zero is at ``receiver_index``.
    Starting at the migration maximum, the algorithm selects the neighboring
    cell with the largest physical travel-time decrease per metre.  It stores
    only the returned integer path, not a wavefield or a receiver-time cube.
    """
    field = _plain_numpy_array(
        traveltime, dtype=np.float32, name='eikonal ray traveltime field'
    )
    dimensions = field.ndim
    start = tuple(
        int(np.clip(value, 0, field.shape[axis] - 1))
        for axis, value in enumerate(start_index)
    )
    receiver = tuple(
        int(np.clip(value, 0, field.shape[axis] - 1))
        for axis, value in enumerate(receiver_index)
    )
    spacing = np.asarray(spacing, dtype=float)
    if spacing.shape != (dimensions,) or np.any(spacing <= 0.0):
        raise ValueError('Ray backtracking requires one positive spacing per axis.')
    if maximum_steps is None:
        maximum_steps = 4 * int(np.sum(field.shape))
    maximum_steps = max(int(maximum_steps), 1)
    offsets = [
        tuple(int(value) - 1 for value in raw)
        for raw in np.ndindex(*(3,) * dimensions)
        if any(int(value) != 1 for value in raw)
    ]
    path = [start]
    visited = {start}
    current = start
    tiny = np.finfo(np.float32).eps
    for _ in range(maximum_steps):
        if current == receiver or all(
                abs(current[axis] - receiver[axis]) <= 1
                for axis in range(dimensions)):
            if path[-1] != receiver:
                path.append(receiver)
            break
        current_time = float(field[current])
        best = None
        best_score = None
        for offset in offsets:
            neighbor = tuple(
                current[axis] + offset[axis] for axis in range(dimensions)
            )
            if any(
                    value < 0 or value >= field.shape[axis]
                    for axis, value in enumerate(neighbor)):
                continue
            if neighbor in visited:
                continue
            neighbor_time = float(field[neighbor])
            if not np.isfinite(neighbor_time):
                continue
            step_metres = float(np.linalg.norm(spacing * np.asarray(offset)))
            decrease_rate = (current_time - neighbor_time) / max(
                step_metres, tiny
            )
            receiver_distance = float(np.linalg.norm(
                spacing * (
                    np.asarray(neighbor, dtype=float)
                    - np.asarray(receiver, dtype=float)
                )
            ))
            score = (decrease_rate, -receiver_distance)
            if best_score is None or score > best_score:
                best = neighbor
                best_score = score
        if best is None:
            break
        # A first-order FMM field should decrease towards its receiver.  The
        # small tolerance avoids following numerical plateaus or closed loops.
        tolerance = max(1.0e-9, abs(current_time) * 1.0e-7)
        if float(field[best]) >= current_time - tolerance:
            direct = tuple(
                current[axis] + int(np.sign(receiver[axis] - current[axis]))
                for axis in range(dimensions)
            )
            if direct in visited or direct == current:
                break
            best = direct
        path.append(best)
        visited.add(best)
        current = best
    return path


def _ray_tube_constrained_focus_image(
        migration_physics, base_image, union_sensors, receiver_columns,
        checkpoint_dir, migration_key, resume_enabled):
    """Blend DTC focus with thin eikonal ray tubes at negligible memory cost.

    The DTC maximum supplies the common ray endpoint. Receiver travel-time
    fields are then loaded one at a time and backtracked to their receivers.
    Receiver rays are backtracked exactly as in the reference method, but their
    energy is never added to the output.  The ray density is multiplied by a
    compact source-centred Gaussian before it is used as a purely multiplicative
    gate.  Consequently no receiver-to-source path can appear as image energy.
    The DTC peak is explicitly preserved as the strongest voxel.
    """
    image = np.asarray(base_image, dtype=np.float32)
    shape = tuple(migration_physics.shape)
    if tuple(image.shape) != shape:
        raise ValueError('Ray-tube constraint requires a full-grid DTC image.')
    tube_sigma = float(os.getenv('PSDM_RAY_TUBE_SIGMA_CELLS', '1.25'))
    source_focus_sigma = float(os.getenv(
        'PSDM_RAY_TUBE_SOURCE_FOCUS_SIGMA_CELLS', '3.0'
    ))
    source_peak_margin = float(os.getenv(
        'PSDM_RAY_TUBE_SOURCE_PEAK_MARGIN', '0.05'
    ))
    gate_floor = float(os.getenv('PSDM_RAY_TUBE_GATE_FLOOR', '0.30'))
    step_factor = float(os.getenv('PSDM_RAY_BACKTRACK_STEP_FACTOR', '4.0'))
    if tube_sigma <= 0.0:
        raise ValueError('PSDM_RAY_TUBE_SIGMA_CELLS must be positive.')
    if source_focus_sigma <= 0.0:
        raise ValueError('PSDM_RAY_TUBE_SOURCE_FOCUS_SIGMA_CELLS must be positive.')
    if not 0.0 < source_peak_margin < 0.25:
        raise ValueError('PSDM_RAY_TUBE_SOURCE_PEAK_MARGIN must be in (0, 0.25).')
    if not 0.0 <= gate_floor <= 1.0:
        raise ValueError('PSDM_RAY_TUBE_GATE_FLOOR must lie in [0, 1].')
    if step_factor <= 0.0:
        raise ValueError('PSDM_RAY_BACKTRACK_STEP_FACTOR must be positive.')
    peak_index = tuple(int(value) for value in np.unravel_index(
        int(np.nanargmax(image)), image.shape
    ))
    ray_counts = np.zeros(shape, dtype=np.uint16)
    maximum_steps = int(np.ceil(step_factor * np.sum(shape)))
    migration_token = hashlib.sha1(
        f'dtc::{migration_key}'.encode('utf-8')
    ).hexdigest()[:8]
    for column in receiver_columns:
        receiver_number = int(column) + 1
        sensor = tuple(union_sensors[int(column)])
        base = os.path.join(
            checkpoint_dir, f'dtc_tt__{migration_token}__r{receiver_number:03d}'
        )
        traveltime = _load_rtm_checkpoint(base, shape)
        if traveltime is None:
            traveltime = _plain_numpy_array(
                migration_physics.compute_traveltime_field(sensor),
                dtype=np.float32,
                name=f'{migration_key} ray-tube receiver traveltime',
                expected_ndim=len(shape),
            )
            _save_rtm_checkpoint(base, traveltime, save_text=False)
        path = _backtrack_eikonal_ray_path(
            traveltime, peak_index, sensor, migration_physics.spacing,
            maximum_steps=maximum_steps,
        )
        for index in path:
            if ray_counts[index] < np.iinfo(np.uint16).max:
                ray_counts[index] += 1
        del traveltime, path
    ray_tube = gaussian_filter(
        ray_counts.astype(np.float32), sigma=tube_sigma, mode='nearest'
    )
    del ray_counts
    ray_tube /= max(float(np.max(ray_tube)), np.finfo(np.float32).tiny)
    coordinates = np.indices(shape, dtype=np.float32)
    squared_distance = np.zeros(shape, dtype=np.float32)
    for axis, coordinate in enumerate(coordinates):
        squared_distance += (coordinate - float(peak_index[axis])) ** 2
    source_neighbourhood = np.exp(
        -0.5 * squared_distance / (source_focus_sigma ** 2)
    ).astype(np.float32)
    local_ray_support = ray_tube * source_neighbourhood
    combined = image * (
        gate_floor + (1.0 - gate_floor) * local_ray_support
    )
    combined = np.asarray(combined, dtype=np.float32)
    # The endpoint inferred from the DTC likelihood represents the imaged
    # source.  Preserve it as the unique strongest voxel instead of allowing
    # the additive path display term to move the reported migration peak.
    original_peak_value = float(combined[peak_index])
    combined[peak_index] = 0.0
    nonpeak_maximum = float(np.max(combined))
    combined[peak_index] = max(
        original_peak_value,
        nonpeak_maximum / (1.0 - source_peak_margin),
    )
    combined /= max(float(np.max(combined)), np.finfo(np.float32).tiny)
    del ray_tube, coordinates, squared_distance
    del source_neighbourhood, local_ray_support
    return combined


def _kirchhoff_psdm_four_arrays(
        migration_physics, gather, dt, union_sensors, active_design_columns,
        checkpoint_dir, migration_key, resume_enabled):
    """Run the unfiltered complete.py Kirchhoff/semblance PSDM.

    Receiver traveltime fields are streamed one at a time and cached.  No
    wavefield is saved, and no image-domain clipping, masking, gamma transform,
    or smoothing is performed.
    """
    if not active_design_columns:
        return {}
    shape = tuple(migration_physics.shape)
    stack = {
        name: np.zeros(shape, dtype=np.float32)
        for name in active_design_columns
    }
    energy = {
        name: np.zeros(shape, dtype=np.float32)
        for name in active_design_columns
    }
    memberships = {index: [] for index in range(len(union_sensors))}
    for design_name, columns in active_design_columns.items():
        for column in columns:
            memberships[int(column)].append(design_name)

    migration_token = hashlib.sha1(
        str(migration_key).encode('utf-8')
    ).hexdigest()[:8]
    for receiver_number, sensor in enumerate(union_sensors, start=1):
        participating = memberships[receiver_number - 1]
        if not participating:
            continue
        traveltime_base = os.path.join(
            checkpoint_dir, f'tt__{migration_token}__r{receiver_number:03d}'
        )
        traveltime = (
            _load_rtm_checkpoint(traveltime_base, shape)
            if resume_enabled else None
        )
        if traveltime is None:
            traveltime = _plain_numpy_array(
                migration_physics.compute_traveltime_field(tuple(sensor)),
                dtype=np.float32,
                name=f'{migration_key} receiver traveltime',
                expected_ndim=len(shape),
            )
            _save_rtm_checkpoint(traveltime_base, traveltime, save_text=False)
        sampled = _sample_trace_on_traveltime_field(
            gather[:, receiver_number - 1], traveltime, dt
        )
        sampled_square = sampled * sampled
        for design_name in participating:
            stack[design_name] += sampled
            energy[design_name] += sampled_square
        del traveltime, sampled, sampled_square

    images = {}
    tiny = np.finfo(np.float32).tiny
    for design_name, columns in active_design_columns.items():
        receiver_count = max(len(columns), 1)
        image = (stack[design_name] ** 2) / np.maximum(
            receiver_count * energy[design_name], tiny
        )
        images[design_name] = np.asarray(image, dtype=np.float32)
        del stack[design_name], energy[design_name], image
    return images


def _differential_traveltime_coherence_migration(
        migration_physics, reference_arrivals, union_sensors,
        active_design_columns, checkpoint_dir, migration_key, resume_enabled,
        ray_tube_enabled=False):
    """Fast differential-time imaging with an optional eikonal ray constraint.

    For every image point, receiver travel times are compared with the same
    reference-model observations.  The receiver-to-receiver residual variance
    removes the common origin-time component, while a weak absolute-time term
    prevents a broad equal-time surface from becoming a migration arc.  Only
    running means and second moments are stored; no wavefield or receiver-time
    cube is retained and no image-domain smoothing is applied. When
    ``ray_tube_enabled`` is true, cached receiver fields are backtracked from
    the DTC maximum and a narrow physical ray-tube constraint suppresses broad
    migration arcs while retaining visible receiver-to-focus propagation paths.
    """
    if not active_design_columns:
        return {}
    shape = tuple(migration_physics.shape)
    running_mean = {
        name: np.zeros(shape, dtype=np.float32)
        for name in active_design_columns
    }
    running_m2 = {
        name: np.zeros(shape, dtype=np.float32)
        for name in active_design_columns
    }
    counts = {name: 0 for name in active_design_columns}
    memberships = {index: [] for index in range(len(union_sensors))}
    for design_name, columns in active_design_columns.items():
        for column in columns:
            memberships[int(column)].append(design_name)

    migration_token = hashlib.sha1(
        f'dtc::{migration_key}'.encode('utf-8')
    ).hexdigest()[:8]
    for receiver_number, sensor in enumerate(union_sensors, start=1):
        participating = memberships[receiver_number - 1]
        if not participating:
            continue
        base = os.path.join(
            checkpoint_dir, f'dtc_tt__{migration_token}__r{receiver_number:03d}'
        )
        traveltime = (
            _load_rtm_checkpoint(base, shape) if resume_enabled else None
        )
        if traveltime is None:
            traveltime = _plain_numpy_array(
                migration_physics.compute_traveltime_field(tuple(sensor)),
                dtype=np.float32,
                name=f'{migration_key} smoothed-ray receiver traveltime',
                expected_ndim=len(shape),
            )
            _save_rtm_checkpoint(base, traveltime, save_text=False)
        residual = traveltime - float(reference_arrivals[receiver_number - 1])
        for design_name in participating:
            counts[design_name] += 1
            count = counts[design_name]
            delta = residual - running_mean[design_name]
            running_mean[design_name] += delta / float(count)
            running_m2[design_name] += delta * (
                residual - running_mean[design_name]
            )
        del traveltime, residual

    sigma_seconds = float(os.getenv('PSDM_DTC_SIGMA_SECONDS', '0.0030'))
    absolute_weight = float(os.getenv('PSDM_DTC_ABSOLUTE_TIME_WEIGHT', '0.20'))
    if sigma_seconds <= 0.0:
        raise ValueError('PSDM_DTC_SIGMA_SECONDS must be positive.')
    if not 0.0 <= absolute_weight <= 1.0:
        raise ValueError('PSDM_DTC_ABSOLUTE_TIME_WEIGHT must lie in [0, 1].')

    images = {}
    for design_name in active_design_columns:
        count = max(counts[design_name], 1)
        differential_variance = np.maximum(
            running_m2[design_name] / float(count), 0.0
        )
        misfit = (
            differential_variance
            + absolute_weight * running_mean[design_name] ** 2
        )
        image = np.exp(-0.5 * misfit / (sigma_seconds ** 2))
        image = np.asarray(image, dtype=np.float32)
        image /= max(float(np.max(image)), np.finfo(np.float32).tiny)
        images[design_name] = image
        del differential_variance, misfit, image
        del running_mean[design_name], running_m2[design_name]
    if ray_tube_enabled:
        for design_name, columns in active_design_columns.items():
            constrained = _ray_tube_constrained_focus_image(
                migration_physics, images[design_name], union_sensors, columns,
                checkpoint_dir, migration_key, resume_enabled,
            )
            del images[design_name]
            images[design_name] = constrained
    return images


def _psdm_cache_signature(data_physics, reference_migration_physics,
                          holdout_true_physics, migration_case,
                          design_sensors, source_indices, parameters=()):
    """Hash every input controlling the fast coherence-migration products."""
    digest = hashlib.sha256(
        b'reference-inverse-bayesian-single-holdout-path-free-ray-tube-format-v10'
    )
    digest.update(repr(tuple(float(value) for value in parameters)).encode('ascii'))
    controls = (
        os.getenv('PSDM_DTC_SIGMA_SECONDS', '0.0030'),
        os.getenv('PSDM_DTC_ABSOLUTE_TIME_WEIGHT', '0.20'),
        os.getenv('PSDM_RAY_VELOCITY_SMOOTH_SIGMA_CELLS', '1.5'),
        os.getenv('PSDM_RAY_TUBE_SIGMA_CELLS', '1.25'),
        'zero-additive-ray-path-energy',
        os.getenv('PSDM_RAY_TUBE_SOURCE_FOCUS_SIGMA_CELLS', '3.0'),
        os.getenv('PSDM_RAY_TUBE_SOURCE_PEAK_MARGIN', '0.05'),
        os.getenv('PSDM_RAY_TUBE_GATE_FLOOR', '0.22'),
        os.getenv('PSDM_RAY_BACKTRACK_STEP_FACTOR', '4.0'),
        'zero-ray-path-overlay-alpha',
        os.getenv('PSDM_SHOW_RECEIVER_MARKERS', '0'),
    )
    digest.update(repr(controls).encode('ascii'))
    for value in (
            tuple(data_physics.shape), tuple(data_physics.spacing),
            tuple(reference_migration_physics.shape),
            tuple(reference_migration_physics.spacing),
            tuple(holdout_true_physics.shape),
            tuple(holdout_true_physics.spacing),
            str(migration_case['name']), tuple(tuple(item) for item in source_indices)):
        digest.update(repr(value).encode('utf-8'))
    for design_name, sensors in design_sensors.items():
        digest.update(design_name.encode('utf-8'))
        digest.update(repr(tuple(sensors)).encode('utf-8'))
    for physics in (
            data_physics, reference_migration_physics,
            holdout_true_physics):
        digest.update(_plain_numpy_array(
            physics.V, dtype=np.float32, name='PSDM velocity signature'
        ).tobytes(order='C'))
    return digest.hexdigest()[:20]


def _posterior_stratified_velocity_indices(cases, maximum_models):
    """Select a probability-stratified subset without discarding posterior mass."""
    probabilities = np.asarray([case['probability'] for case in cases], dtype=float)
    probabilities /= float(np.sum(probabilities))
    maximum_models = int(maximum_models)
    if maximum_models <= 0 or maximum_models >= len(cases):
        indices = np.arange(len(cases), dtype=int)
    else:
        cumulative = np.cumsum(probabilities)
        quantiles = (np.arange(maximum_models, dtype=float) + 0.5) / maximum_models
        indices = np.unique(np.searchsorted(cumulative, quantiles, side='left'))
        if indices.size < maximum_models:
            remaining = [
                index for index in np.argsort(probabilities)[::-1]
                if index not in set(int(value) for value in indices)
            ]
            indices = np.concatenate([
                indices, np.asarray(remaining[:maximum_models - indices.size], dtype=int)
            ])
        indices = np.sort(indices[:maximum_models])
    weights = probabilities[indices]
    weights /= float(np.sum(weights))
    return indices, weights


def _posterior_plot_cases(cases, maximum_models=16):
    """Return a readable posterior-stratified plotting subset."""
    if len(cases) <= int(maximum_models):
        return list(cases)
    indices, _ = _posterior_stratified_velocity_indices(cases, maximum_models)
    reference_indices = [
        index for index, case in enumerate(cases) if case['kind'] == 'reference'
    ]
    if reference_indices and reference_indices[0] not in indices:
        indices = np.concatenate([
            np.asarray([reference_indices[0]], dtype=int), indices[:-1]
        ])
    return [cases[int(index)] for index in np.unique(indices)]


def _plot_bayesian_migration_posterior(
        reference_migration_physics, design_products, design_sensors,
        source_index, source_number, output_dir):
    """Plot BMA mean, standard deviation, and approximate 95% credible bounds."""
    design_names = list(design_products)
    columns = (
        ('posterior_mean', 'Posterior mean'),
        ('posterior_std', 'Posterior standard deviation'),
        ('credible_p025', 'Approx. 2.5% credible bound'),
        ('credible_p975', 'Approx. 97.5% credible bound'),
    )
    figure, axes = plt.subplots(
        len(design_names), len(columns),
        figsize=(18.0, max(4.0, 3.65 * len(design_names))),
        squeeze=False, constrained_layout=True,
    )
    x_max = (reference_migration_physics.shape[0] - 1) * (
        reference_migration_physics.spacing[0]
    )
    z_max = (reference_migration_physics.shape[-1] - 1) * (
        reference_migration_physics.spacing[-1]
    )
    extent = [0.0, x_max, z_max, 0.0]
    velocity_slice = _rtm_xz_slice(
        reference_migration_physics.V, reference_migration_physics, source_index
    )
    overlay_alpha = float(os.getenv('PSDM_IMAGE_OVERLAY_ALPHA', '0.35'))
    artists = [None] * len(columns)
    for row, design_name in enumerate(design_names):
        for column, (field, title) in enumerate(columns):
            axis = axes[row, column]
            axis.imshow(
                velocity_slice, cmap='rainbow', extent=extent,
                origin='upper', aspect='auto', alpha=1.0,
            )
            display = _psdm_display_image(_rtm_xz_slice(
                design_products[design_name][field],
                reference_migration_physics,
                source_index,
            ))
            artists[column] = axis.imshow(
                display, cmap='rainbow', extent=extent,
                origin='upper', aspect='auto', vmin=0.0, vmax=1.0,
                alpha=overlay_alpha,
            )
            if row == 0:
                axis.set_title(title, fontsize=10.5, pad=7)
            axis.set_ylabel('Depth (m)' if column == 0 else '')
            if column == 0:
                axis.text(
                    0.02, 0.96,
                    f'{design_name}  (N={len(design_sensors[design_name])})',
                    transform=axis.transAxes, ha='left', va='top',
                    fontsize=8.6, color='black', zorder=6,
                    bbox=dict(
                        boxstyle='round,pad=0.24', facecolor='white',
                        edgecolor='0.35', linewidth=0.55, alpha=0.78,
                    ),
                )
            axis.set_xlabel('X (m)')
            axis.grid(True, linestyle=':', alpha=0.20)
    for column, artist in enumerate(artists):
        if artist is not None:
            colorbar = figure.colorbar(
                artist, ax=axes[:, column].tolist(), shrink=0.78, pad=0.012
            )
            colorbar.set_label('Normalized value', fontsize=9.0)
    figure.suptitle(
        'Bayesian velocity-ensemble propagation to fixed-reference migration\n'
        f'Source {source_number}: streaming BMA without storing an image cube',
        fontsize=13.5,
    )
    path = os.path.join(
        output_dir,
        f'Figure_Bayesian_Migration_Posterior_Source_{source_number:02d}.png',
    )
    figure.savefig(path, dpi=300, bbox_inches='tight', pad_inches=0.16)
    plt.close(figure)
    return path


def propagate_bayesian_velocity_uncertainty_to_migration(
        reference_physics, cases, design_sensors, source_indices,
        output_dir, config):
    """Stream Bayesian velocity uncertainty into migration-image posteriors.

    Each selected possible true velocity generates arrivals, but every image is
    migrated with one smoothed reference model. Weighted Welford updates retain
    only posterior mean and variance per array. The reported 95% bounds use a
    normal moment approximation and are explicitly labelled approximate.
    """
    if not config.get('velocity_bayesian_migration_enabled', True):
        return {
            'enabled': False,
            'possible_true_velocity_forward_only': True,
            'migration_velocity_model': 'smoothed reference only',
        }
    bayesian_dir = os.path.join(
        output_dir, 'bayesian_velocity_migration_uncertainty'
    )
    os.makedirs(bayesian_dir, exist_ok=True)
    selected_indices, selected_weights = _posterior_stratified_velocity_indices(
        cases, config.get('velocity_bayesian_migration_max_models', 32)
    )
    source_indices = [tuple(source) for source in source_indices]
    maximum_sources = int(config.get('velocity_bayesian_migration_max_sources', 0))
    if maximum_sources > 0:
        source_indices = source_indices[:maximum_sources]
    reference_migration, smoothing = _smoothed_ray_velocity_physics(
        reference_physics, 'Bayesian migration reference velocity'
    )
    union_sensors = []
    for sensors in design_sensors.values():
        for sensor in sensors:
            sensor = tuple(sensor)
            if sensor not in union_sensors:
                union_sensors.append(sensor)
    union_lookup = {sensor: index for index, sensor in enumerate(union_sensors)}
    design_columns = {
        design: [union_lookup[tuple(sensor)] for sensor in sensors]
        for design, sensors in design_sensors.items()
    }
    checkpoint_dir = os.path.join(bayesian_dir, 'streaming_checkpoints')
    os.makedirs(checkpoint_dir, exist_ok=True)
    save_text = os.getenv(
        'BAYESIAN_MIGRATION_SAVE_TEXT', os.getenv('PSDM_SAVE_TEXT', '1')
    ) != '0'
    detail_rows = []
    summary_rows = []
    figure_paths = []
    for source_number, source_index in enumerate(source_indices, start=1):
        running_mean = {
            design: np.zeros(reference_physics.shape, dtype=np.float32)
            for design in design_sensors
        }
        running_m2 = {
            design: np.zeros(reference_physics.shape, dtype=np.float32)
            for design in design_sensors
        }
        cumulative_weight = 0.0
        for selected_order, (case_index, weight) in enumerate(
                zip(selected_indices, selected_weights), start=1):
            case = cases[int(case_index)]
            arrivals = _reference_first_arrivals(
                case['physics'], source_index, union_sensors
            )
            images = _differential_traveltime_coherence_migration(
                reference_migration, arrivals, union_sensors, design_columns,
                checkpoint_dir, 'bayesian_fixed_reference', True,
            )
            new_weight = cumulative_weight + float(weight)
            for design, image in images.items():
                image = np.asarray(image, dtype=np.float32)
                delta = image - running_mean[design]
                running_mean[design] += (float(weight) / new_weight) * delta
                running_m2[design] += float(weight) * delta * (
                    image - running_mean[design]
                )
                metrics = _rtm_image_metrics(
                    image, source_index, reference_physics.spacing,
                    float(os.getenv('RTM_FOCUS_RADIUS_CELLS', '3.0')),
                )
                detail_rows.append({
                    'source_number': source_number,
                    'velocity_model': case['name'],
                    'velocity_model_index': int(case_index),
                    'posterior_subset_weight': float(weight),
                    'design': design,
                    'number_of_receivers': len(design_sensors[design]),
                    **metrics,
                })
            cumulative_weight = new_weight
            del arrivals, images
            if selected_order % 8 == 0:
                gc.collect()

        design_products = {}
        for design in design_sensors:
            posterior_mean = running_mean[design]
            posterior_variance = np.maximum(
                running_m2[design] / max(cumulative_weight, np.finfo(float).tiny),
                0.0,
            )
            posterior_std = np.sqrt(posterior_variance).astype(np.float32)
            credible_p025 = np.clip(
                posterior_mean - 1.96 * posterior_std, 0.0, 1.0
            ).astype(np.float32)
            credible_p975 = np.clip(
                posterior_mean + 1.96 * posterior_std, 0.0, 1.0
            ).astype(np.float32)
            design_products[design] = {
                'posterior_mean': posterior_mean,
                'posterior_std': posterior_std,
                'credible_p025': credible_p025,
                'credible_p975': credible_p975,
            }
            token = _safe_file_token(design)
            for field, array in design_products[design].items():
                _save_rtm_checkpoint(
                    os.path.join(
                        bayesian_dir,
                        f'{field}__{token}__source_{source_number:03d}',
                    ),
                    array,
                    save_text=save_text,
                )
            rows = [
                row for row in detail_rows
                if row['source_number'] == source_number and row['design'] == design
            ]
            row_weights = np.asarray([
                row['posterior_subset_weight'] for row in rows
            ], dtype=float)
            peak_errors = np.asarray([
                row['peak_location_error_m'] for row in rows
            ], dtype=float)
            summary_rows.append({
                'source_number': source_number,
                'design': design,
                'number_of_receivers': len(design_sensors[design]),
                'number_of_velocity_models': len(rows),
                'posterior_mean_peak_error_m': float(np.dot(
                    row_weights, peak_errors
                )),
                'posterior_p95_peak_error_m': float(_weighted_quantile(
                    peak_errors, 0.95, row_weights
                )),
                'mean_pixel_posterior_std': float(np.mean(posterior_std)),
                'p95_pixel_posterior_std': float(np.quantile(
                    posterior_std, 0.95
                )),
            })
        figure_paths.append(_plot_bayesian_migration_posterior(
            reference_migration, design_products, design_sensors,
            source_index, source_number, bayesian_dir,
        ))
        _write_csv(
            os.path.join(bayesian_dir, 'bayesian_migration_model_metrics.csv'),
            detail_rows,
        )
        _write_csv(
            os.path.join(bayesian_dir, 'bayesian_migration_summary.csv'),
            summary_rows,
        )
        del running_mean, running_m2, design_products
        gc.collect()
    inventory = {
        'enabled': True,
        'method': 'streaming Bayesian model averaging of fixed-reference DTC migration',
        'credible_interval': 'posterior mean +/- 1.96 standard deviations, clipped to [0, 1]',
        'credible_interval_is_moment_approximation': True,
        'full_velocity_ensemble_size': len(cases),
        'migration_velocity_subset_size': len(selected_indices),
        'selected_velocity_model_indices': [int(value) for value in selected_indices],
        'selected_velocity_model_names': [
            cases[int(index)]['name'] for index in selected_indices
        ],
        'selected_posterior_weights': [float(value) for value in selected_weights],
        'migration_velocity_model': 'smoothed reference only',
        'true_velocity_models_used_only_to_generate_arrivals': True,
        'ray_velocity_smoothing': smoothing,
        'sources_propagated': [list(source) for source in source_indices],
        'figures': figure_paths,
        'summary_table': os.path.join(
            bayesian_dir, 'bayesian_migration_summary.csv'
        ),
        'model_metric_table': os.path.join(
            bayesian_dir, 'bayesian_migration_model_metrics.csv'
        ),
    }
    inventory_path = os.path.join(
        bayesian_dir, 'bayesian_migration_inventory.json'
    )
    _atomic_write_json(inventory_path, inventory)
    inventory['inventory_json'] = inventory_path
    return inventory


def _plot_single_design_localization_errors(rows, cases, output_dir):
    """Plot/save one array's mean and P95 errors before releasing its trials."""
    design_name = rows[0]['design']
    lookup = {row['scenario']: row for row in rows}
    labels = [
        'Reference' if case['kind'] == 'reference'
        else f"{case['name']}\n{100.0 * case.get('residual_rms_fraction', 0.0):.1f}% RMS"
        for case in cases
    ]
    x = np.arange(len(cases), dtype=float)
    width = 0.34
    figure, axis = plt.subplots(
        figsize=(max(9.0, 1.25 * len(cases)), 6.2), constrained_layout=True
    )
    mean_values = [lookup[case['name']]['mean_error_m'] for case in cases]
    p95_values = [lookup[case['name']]['p95_error_m'] for case in cases]
    axis.bar(x - width / 2.0, mean_values, width=width, color='#457B9D',
             edgecolor='black', label='Mean error')
    axis.bar(x + width / 2.0, p95_values, width=width, color='#E63946',
             edgecolor='black', label='P95 error')
    axis.set_xticks(x, labels, rotation=24, ha='right')
    axis.set_ylabel('Localization error (m)')
    axis.set_title(
        f'{design_name}: possible-true data, fixed-reference localization', pad=8
    )
    axis.grid(True, axis='y', linestyle=':', alpha=0.45)
    axis.legend(loc='best')
    path = os.path.join(
        output_dir, f'Figure_Localization_{_safe_file_token(design_name)}.png'
    )
    figure.savefig(path, dpi=300, bbox_inches='tight', pad_inches=0.15)
    plt.close(figure)
    return path


def run_four_design_velocity_rtm_comparison(
        reference_physics, velocity_cases, robust_sensors,
        fixed_optimized_sensors, random_sensors, uniform_sensors,
        source_indices, output_dir, legacy_output_dir=None,
        target_indices=None):
    """Final four-array validation on one new unknown true velocity.

    The legacy function name is retained for callers. One independent holdout
    field inside the stated uncertainty range generates all observed arrivals.
    It is excluded from optimization and distinct from every ensemble member.
    All four arrays locate and migrate those data with the same reference model.
    """
    del legacy_output_dir
    # Keep the generated directory and cache tokens compact.  This matters on
    # Windows workspaces where an otherwise valid checkpoint path can exceed
    # the traditional 260-character path limit.
    psdm_dir = os.path.join(output_dir, 'psdm_final')
    os.makedirs(psdm_dir, exist_ok=True)
    model_dimension = len(reference_physics.shape)
    if model_dimension not in (2, 3):
        raise ValueError('Fast PSDM supports only 2D and 3D models.')
    source_indices = [tuple(item) for item in source_indices]
    if not source_indices or any(
            len(item) != model_dimension for item in source_indices):
        raise ValueError('Source indices do not match the model dimension.')
    if not velocity_cases:
        raise ValueError('At least one localization velocity model is required.')
    perturbation_targets = (
        source_indices if target_indices is None
        else [tuple(item) for item in target_indices]
    )
    mismatch_case = _independent_psdm_holdout_velocity_case(
        reference_physics, perturbation_targets, velocity_cases
    )
    mismatch_physics = mismatch_case['physics']
    reference_migration_physics, reference_smoothing = (
        _smoothed_ray_velocity_physics(
            reference_physics, 'reference migration velocity'
        )
    )
    # Final comparison deliberately uses only one out-of-sample true field.
    # The large design ensemble has already been propagated in the Bayesian OED.
    evaluation_cases = [mismatch_case]
    design_sensors = {
        'Fixed-velocity optimized': [tuple(item) for item in fixed_optimized_sensors],
        'Random': [tuple(item) for item in random_sensors],
        'Uniform': [tuple(item) for item in uniform_sensors],
        'Velocity-ensemble robust': [tuple(item) for item in robust_sensors],
    }
    for design_name, sensors in design_sensors.items():
        if not sensors or any(len(item) != model_dimension for item in sensors):
            raise ValueError(f'{design_name} has invalid receiver coordinates.')
    baseline_counts = {
        len(design_sensors[name]) for name in (
            'Fixed-velocity optimized', 'Random', 'Uniform'
        )
    }
    if len(baseline_counts) != 1:
        raise ValueError(
            'Fixed-velocity, random, and uniform observation systems must '
            'contain the same number of receivers. The velocity-ensemble '
            'robust system may independently use a different receiver count.'
        )
    focus_radius_cells = float(os.getenv('RTM_FOCUS_RADIUS_CELLS', '3.0'))
    resume_enabled = os.getenv('PSDM_RESUME', os.getenv('RTM_RESUME', '1')) != '0'
    save_text = os.getenv('PSDM_SAVE_TEXT', os.getenv('RTM_SAVE_TEXT', '1')) != '0'

    experiments = [
        {
            'key': 'holdout_true_data_reference_migration',
            'file_token': 'Holdout_True_Data_Reference_Migration_Four_Arrays',
            'title': (
                'Unknown-true-velocity data ray-tube constrained coherence | '
                'smoothed reference migration velocity'
            ),
            'migration_physics': reference_migration_physics,
            'migration_case': 'reference',
            'data_physics': mismatch_physics,
            'data_case': mismatch_case['name'],
            'data_label': 'Independent unknown true velocity',
            'method_label': 'Ray-tube constrained DTC migration',
            'method_token': 'DTCM',
        },
    ]
    union_sensors = []
    for sensors in design_sensors.values():
        for sensor in sensors:
            if sensor not in union_sensors:
                union_sensors.append(sensor)
    union_lookup = {sensor: index for index, sensor in enumerate(union_sensors)}
    design_columns = {
        name: [union_lookup[sensor] for sensor in sensors]
        for name, sensors in design_sensors.items()
    }
    signature = _psdm_cache_signature(
        reference_physics, reference_migration_physics,
        mismatch_physics, mismatch_case,
        design_sensors, source_indices,
    )
    checkpoint_root = os.getenv(
        'PSDM_CACHE_DIR', os.path.join(psdm_dir, 'cache')
    )
    checkpoint_dir = os.path.join(checkpoint_root, signature)
    os.makedirs(checkpoint_dir, exist_ok=True)
    _write_matlab_loader(checkpoint_dir)

    _save_rtm_checkpoint(
        os.path.join(checkpoint_dir, 'reference_velocity_model_raw'),
        reference_physics.V, save_text=save_text,
    )
    _save_rtm_checkpoint(
        os.path.join(
            checkpoint_dir, 'reference_velocity_model_smoothed_for_ray_migration'
        ),
        reference_migration_physics.V, save_text=save_text,
    )
    reference_velocity_figure = _plot_single_velocity_model(
        reference_migration_physics, source_indices,
        'Smoothed reference velocity used for ray migration',
        os.path.join(psdm_dir, 'Figure_Reference_Ray_Velocity_Model_Smoothed.png'),
    )
    _save_rtm_checkpoint(
        os.path.join(checkpoint_dir, 'holdout_velocity_model_raw'),
        mismatch_physics.V, save_text=save_text,
    )
    _save_rtm_checkpoint(
        os.path.join(checkpoint_dir, 'holdout_fractional_residual'),
        mismatch_case['fractional_residual'], save_text=save_text,
    )
    perturbed_velocity_figure = _plot_single_velocity_model(
        mismatch_physics, source_indices,
        'Independent possible true velocity (not used by migration)',
        os.path.join(
            psdm_dir, 'Figure_Independent_Unknown_True_Velocity_Model.png'
        ),
    )
    gc.collect()

    manifest_path = os.path.join(checkpoint_dir, 'psdm_checkpoint_manifest.json')
    _atomic_write_json(manifest_path, {
        'format_version': 8,
        'signature': signature,
        'algorithm': (
            'Ray-tube constrained differential-traveltime coherence migration'
        ),
        'reference_data_only': False,
        'reference_velocity_inverse_only': True,
        'possible_true_velocity_forward_only': True,
        'no_wavefield_saved': True,
        'model_shape': list(reference_physics.shape),
        'model_spacing_m': [float(value) for value in reference_physics.spacing],
        'source_indices': [list(item) for item in source_indices],
        'localization_velocity_models': [case['name'] for case in evaluation_cases],
        'migrated_velocity_models': ['smoothed_reference'],
        'true_data_velocity_models': [mismatch_case['name']],
        'final_validation_uses_single_new_true_model': True,
        'ray_velocity_smoothing': {
            'reference': reference_smoothing,
        },
        'coherence_migration': {
            'differential_time_sigma_seconds': float(
                os.getenv('PSDM_DTC_SIGMA_SECONDS', '0.0030')
            ),
            'absolute_time_weight': float(
                os.getenv('PSDM_DTC_ABSOLUTE_TIME_WEIGHT', '0.20')
            ),
            'streaming_receiver_fields': True,
            'ray_tube_constraint_enabled': True,
            'ray_tube_sigma_cells': float(os.getenv(
                'PSDM_RAY_TUBE_SIGMA_CELLS', '1.25'
            )),
            'ray_path_display_weight': float(os.getenv(
            'PSDM_RAY_TUBE_PATH_WEIGHT', '0.025'
            )),
            'ray_gate_floor': float(os.getenv(
                'PSDM_RAY_TUBE_GATE_FLOOR', '0.22'
            )),
            'wavefield_saved': False,
        },
        'image_display': {
            'normalization': 'maximum amplitude only',
        'overlay_alpha': float(os.getenv('PSDM_IMAGE_OVERLAY_ALPHA', '0.18')),
            'source_star_displayed': False,
            'receiver_markers_displayed_by_default': False,
            'percentile_clipping': False,
            'weak_amplitude_masking': False,
            'gamma_transform': False,
            'image_smoothing': False,
        },
        'independent_holdout_velocity': {
            key: mismatch_case[key] for key in (
                'name', 'random_seed', 'spatial_perturbation_type',
                'target_mask_points',
                'target_radius_cells', 'target_zone_residual_rms_fraction',
                'background_residual_rms_fraction',
                'target_fractional_amplitude',
                'background_fraction_of_target_amplitude',
                'residual_max_abs_fraction',
                'minimum_rms_fractional_difference_from_design_models',
                'not_used_for_observation_system_optimization',
            )
        },
    })

    detail_rows = []
    summary_rows = []
    experiment_figures = {item['key']: [] for item in experiments}
    arrival_figures = []
    for experiment_number, experiment in enumerate(experiments):
        print(f"    [DTCM] {experiment['title'].replace(chr(10), ' — ')}")
        experiment_rows = []
        for source_number, source_index in enumerate(source_indices, start=1):
            arrival_token = hashlib.sha1(
                experiment['key'].encode('utf-8')
            ).hexdigest()[:8]
            arrival_base = os.path.join(
                checkpoint_dir,
                f'arr__{arrival_token}__s{source_number:03d}',
            )
            arrivals = (
                _load_rtm_checkpoint(
                    arrival_base, (len(union_sensors),)
                )
                if resume_enabled else None
            )
            if arrivals is None:
                arrivals = _reference_first_arrivals(
                    experiment['data_physics'], source_index, union_sensors
                )
                _save_rtm_checkpoint(arrival_base, arrivals, save_text=True)
            arrival_figures.append(_plot_reference_arrivals(
                arrivals, source_number, psdm_dir,
                data_label=experiment['data_label'],
                file_token=experiment['data_case'],
            ))

            source_images = {}
            missing = {}
            for design_name in design_sensors:
                base = _rtm_image_checkpoint_base(
                    checkpoint_dir, experiment['key'], design_name, source_number
                )
                image = (
                    _load_rtm_checkpoint(base, reference_physics.shape)
                    if resume_enabled else None
                )
                if image is None:
                    missing[design_name] = design_columns[design_name]
                else:
                    source_images[design_name] = image
            if missing:
                computed = _differential_traveltime_coherence_migration(
                    experiment['migration_physics'], arrivals, union_sensors,
                    missing, checkpoint_dir, experiment['key'], resume_enabled,
                    ray_tube_enabled=True,
                )
                for design_name, image in computed.items():
                    base = _rtm_image_checkpoint_base(
                        checkpoint_dir, experiment['key'], design_name, source_number
                    )
                    _save_rtm_checkpoint(base, image, save_text=save_text)
                    source_images[design_name] = image
                del computed

            source_rows = []
            for design_name, sensors in design_sensors.items():
                image = source_images[design_name]
                metrics = _rtm_image_metrics(
                    image, source_index, reference_physics.spacing,
                    focus_radius_cells,
                )
                # No matched-reference experiment is run in the final comparison;
                # the requested test contains only new true data/reference inverse.
                correlation = np.nan
                row = {
                    'experiment': experiment['key'], 'design': design_name,
                    'number_of_receivers': len(sensors),
                    'source_number': source_number,
                    'source_index': list(source_index),
                    'data_velocity_case': experiment['data_case'],
                    'migration_velocity_case': experiment['migration_case'],
                    'velocity_mismatch': int(
                        experiment['data_case'] != experiment['migration_case']
                    ),
                    'reference_image_correlation': correlation,
                    **metrics,
                }
                detail_rows.append(row)
                experiment_rows.append(row)
                source_rows.append(row)

            plot_experiment = dict(experiment)
            plot_experiment['file_token'] = (
                f"{experiment['file_token']}_Source_{source_number:02d}"
            )
            plot_experiment['title'] = (
                f"{experiment['title']}\nSource {source_number}"
            )
            plot_images = {
                experiment['key']: {
                    name: [source_images[name]] for name in design_sensors
                }
            }
            plot_rows = [dict(row, source_number=1) for row in source_rows]
            figure_result = _plot_rtm_four_array_experiment(
                plot_experiment, plot_images, plot_rows, design_sensors,
                [source_index], psdm_dir,
            )
            if isinstance(figure_result, (list, tuple)):
                experiment_figures[experiment['key']].extend(figure_result)
            else:
                experiment_figures[experiment['key']].append(figure_result)
            _write_csv(os.path.join(psdm_dir, 'psdm_four_design_source_metrics.csv'),
                       detail_rows)
            del arrivals, source_images, source_rows, plot_images, plot_rows
            gc.collect()

        for design_name, sensors in design_sensors.items():
            rows = [row for row in experiment_rows if row['design'] == design_name]
            summary_rows.append({
                'experiment': experiment['key'], 'design': design_name,
                'number_of_receivers': len(sensors), 'number_of_sources': len(rows),
                'mean_peak_location_error_m': float(np.mean([
                    row['peak_location_error_m'] for row in rows])),
                'mean_focus_energy_fraction': float(np.mean([
                    row['focus_energy_fraction'] for row in rows])),
                'mean_source_to_sidelobe_db': float(np.mean([
                    row['source_to_sidelobe_db'] for row in rows])),
                'mean_normalized_image_entropy': float(np.mean([
                    row['normalized_image_entropy'] for row in rows])),
                'mean_reference_image_correlation': float(np.mean([
                    row['reference_image_correlation'] for row in rows])),
            })
        _write_csv(os.path.join(psdm_dir, 'psdm_four_design_summary_metrics.csv'),
                   summary_rows)
        del experiment_rows
        gc.collect()

    geometry_figure = _plot_rtm_four_array_geometry_3d(
        reference_physics, design_sensors, source_indices, psdm_dir
    )
    metric_figure = _plot_rtm_metric_comparison(
        summary_rows, [item['key'] for item in experiments], psdm_dir
    )

    localization_realizations = int(os.getenv(
        'PSDM_LOCALIZATION_MC', os.getenv('RTM_LOCALIZATION_MC', '20')
    ))
    localization_noise_std = float(os.getenv(
        'PSDM_LOCALIZATION_NOISE_STD',
        os.getenv('RTM_LOCALIZATION_NOISE_STD', '0.002'),
    ))
    localization_noise = OperationalNoiseModel(
        'Possible-true forward / reference-inverse Gaussian IID', kind='gaussian',
        sigma=localization_noise_std,
    )
    localization_rows = []
    localization_figures = {}
    trial_path = os.path.join(
        psdm_dir, 'reference_data_localization_error_trials.csv'
    )
    for design_index, (design_name, sensors) in enumerate(design_sensors.items()):
        design_rows, design_trials = _evaluate_design_across_velocity_ensemble(
            reference_physics, evaluation_cases, sensors, source_indices,
            localization_noise, localization_realizations, 19001, design_name,
        )
        localization_rows.extend(design_rows)
        localization_figures[design_name] = _plot_single_design_localization_errors(
            design_rows, evaluation_cases, psdm_dir
        )
        _write_csv(os.path.join(
            psdm_dir, 'reference_data_localization_error_summary.csv'
        ), localization_rows)
        if design_index == 0:
            _write_csv(trial_path, design_trials)
        else:
            _append_csv(trial_path, design_trials)
        del design_rows, design_trials
        gc.collect()

    localization_figure, rankings, aggregate = (
        _plot_reference_data_localization_errors(
            localization_rows, evaluation_cases, psdm_dir
        )
    )
    _write_csv(os.path.join(psdm_dir, 'reference_data_localization_error_ranking.csv'),
               rankings)
    _write_csv(os.path.join(psdm_dir, 'reference_data_localization_error_aggregate.csv'),
               aggregate)
    aggregate_lookup = {row['design']: row for row in aggregate}
    fixed_result = aggregate_lookup['Fixed-velocity optimized']
    robust_result = aggregate_lookup['Velocity-ensemble robust']
    localization_evidence = {
        'robust_mean_error_m': robust_result[
            'mean_error_over_changed_velocity_models_m'
        ],
        'fixed_mean_error_m': fixed_result[
            'mean_error_over_changed_velocity_models_m'
        ],
        'robust_worst_p95_error_m': robust_result[
            'worst_p95_error_over_changed_velocity_models_m'
        ],
        'fixed_worst_p95_error_m': fixed_result[
            'worst_p95_error_over_changed_velocity_models_m'
        ],
    }
    localization_evidence['robust_to_fixed_mean_error_ratio'] = float(
        localization_evidence['robust_mean_error_m']
        / max(localization_evidence['fixed_mean_error_m'], np.finfo(float).tiny)
    )
    localization_evidence['robust_to_fixed_p95_error_ratio'] = float(
        localization_evidence['robust_worst_p95_error_m']
        / max(localization_evidence['fixed_worst_p95_error_m'], np.finfo(float).tiny)
    )
    localization_evidence['robust_is_better_on_mean_and_p95'] = bool(
        localization_evidence['robust_mean_error_m']
        < localization_evidence['fixed_mean_error_m']
        and localization_evidence['robust_worst_p95_error_m']
        < localization_evidence['fixed_worst_p95_error_m']
    )
    if not localization_evidence['robust_is_better_on_mean_and_p95']:
        warnings.warn(
            'The independent numerical evaluation does not show the robust array '
            'strictly outperforming the fixed-velocity array on both mean and P95 '
            'errors. Results are reported without alteration; increase the design '
            'search budget or ensemble coverage rather than forcing the conclusion.',
            RuntimeWarning,
        )
    inventory = {
        'algorithm': (
            'Ray-tube constrained differential-traveltime coherence migration'
        ),
        'reference_data_only': False,
        'reference_velocity_inverse_only': True,
        'possible_true_velocity_forward_only': True,
        'no_wavefield_saved': True,
        'migrated_velocity_models': ['smoothed_reference'],
        'true_data_velocity_models': [mismatch_case['name']],
        'final_validation_uses_single_new_true_model': True,
        'ray_velocity_smoothing': {
            'reference': reference_smoothing,
        },
        'localization_velocity_models': [case['name'] for case in evaluation_cases],
        'independent_holdout_velocity': {
            key: mismatch_case[key] for key in (
                'name', 'random_seed', 'spatial_perturbation_type',
                'target_mask_points',
                'target_radius_cells', 'target_zone_residual_rms_fraction',
                'background_residual_rms_fraction',
                'target_fractional_amplitude',
                'background_fraction_of_target_amplitude',
                'minimum_rms_fractional_difference_from_design_models',
                'not_used_for_observation_system_optimization',
            )
        },
        'image_display': {
            'normalization': 'maximum amplitude only',
            'transparent_overlay_alpha': float(
                os.getenv('PSDM_IMAGE_OVERLAY_ALPHA', '0.45')
            ),
            'source_star_displayed': False,
            'receiver_markers_displayed_by_default': False,
            'ray_paths_embedded_in_image_amplitude': True,
            'algorithmic_arc_attenuation': (
                'DTC focus multiplied by common eikonal ray-tube support'
            ),
        },
        'reference_velocity_figure': reference_velocity_figure,
        'perturbed_velocity_figure': perturbed_velocity_figure,
        'true_data_arrival_figures': arrival_figures,
        'experiments': [{
            'key': item['key'], 'title': item['title'],
            'data_velocity': item['data_case'],
            'migration_velocity': item['migration_case'],
            'figure': experiment_figures[item['key']],
        } for item in experiments],
        'three_dimensional_acquisition_geometry_figure': geometry_figure,
        'metric_comparison_figure': metric_figure,
        'localization_comparison_figure': localization_figure,
        'localization_individual_figures': localization_figures,
        'localization_rankings': rankings,
        'localization_aggregate': aggregate,
        'robust_vs_fixed_localization_evidence': localization_evidence,
        'checkpoint_directory': os.path.abspath(checkpoint_dir),
        'checkpoint_manifest': os.path.abspath(manifest_path),
        'source_metric_table': os.path.join(
            psdm_dir, 'psdm_four_design_source_metrics.csv'),
        'summary_metric_table': os.path.join(
            psdm_dir, 'psdm_four_design_summary_metrics.csv'),
        'localization_trial_table': trial_path,
        'summary_metrics': summary_rows,
    }
    inventory_path = os.path.join(psdm_dir, 'psdm_four_design_inventory.json')
    _atomic_write_json(inventory_path, inventory)
    inventory['inventory_json'] = inventory_path
    return inventory

