def format_3d_axes(ax, x_max, y_max, z_max, margin):
    ax.view_init(elev=30, azim=135) 
    ax.set_xlim(-margin, x_max + margin)
    ax.set_ylim(-margin, y_max + margin)
    ax.set_zlim(z_max + margin, -margin)
    ax.set_xlabel('X (m)', labelpad=15)
    ax.set_ylabel('Y (m)', labelpad=15)
    ax.set_zlabel('Depth Z (m)', labelpad=15)
    ax.tick_params(pad=5)
    ax.set_box_aspect((x_max + 2*margin, y_max + 2*margin, z_max + 2*margin)) 
    ax.zaxis._axinfo['juggled'] = (1, 2, 0)

def draw_3d_box_faces(ax, xmin, xmax, ymin, ymax, zmin, zmax, color, alpha):
    kwargs = {'color': color, 'alpha': alpha, 'linewidth': 0, 'antialiased': True, 'shade': True, 'edgecolor': 'none'}
    X, Y = np.meshgrid([xmin, xmax], [ymin, ymax])
    ax.plot_surface(X, Y, np.full_like(X, zmin), **kwargs)
    ax.plot_surface(X, Y, np.full_like(X, zmax), **kwargs)
    Y, Z = np.meshgrid([ymin, ymax], [zmin, zmax])
    ax.plot_surface(np.full_like(Y, xmin), Y, Z, **kwargs)
    ax.plot_surface(np.full_like(Y, xmax), Y, Z, **kwargs)
    X, Z = np.meshgrid([xmin, xmax], [zmin, zmax])
    ax.plot_surface(X, np.full_like(X, ymin), Z, **kwargs)
    ax.plot_surface(X, np.full_like(X, ymax), Z, **kwargs)

def plot_solid_velocity_model(ax, phys, shape, spacing):
    nx, ny, nz = shape
    xmax, ymax, zmax = nx*spacing[0], ny*spacing[1], nz*spacing[2]
    v_min, v_max = phys.V.min(), phys.V.max()
    cmap = plt.get_cmap('rainbow')
    norm = plt.Normalize(vmin=v_min, vmax=v_max)
    c_bg = cmap(norm((v_max + v_min) / 2)) 
    c_anom = cmap(norm(v_min))             
    draw_3d_box_faces(ax, 0, xmax, 0, ymax, 0, zmax, color=c_bg, alpha=0.0)
    if len(np.unique(phys.V)) <= 3:  
        axmin, axmax = int(nx*0.4)*spacing[0], int(nx*0.6)*spacing[0]
        aymin, aymax = int(ny*0.4)*spacing[1], int(ny*0.6)*spacing[1]
        azmin, azmax = int(nz*0.5)*spacing[2], int(nz*0.7)*spacing[2]
        draw_3d_box_faces(ax, axmin, axmax, aymin, aymax, azmin, azmax, color=c_anom, alpha=0.6)
    return plt.cm.ScalarMappable(norm=norm, cmap=cmap)

def plot_3d_orthogonal_slices(ax, volume, spacing, center_idx, vmax, cmap='rainbow', alpha=0.6):
    nx, ny, nz = volume.shape
    x = np.arange(nx) * spacing[0]
    y = np.arange(ny) * spacing[1]
    z = np.arange(nz) * spacing[2]
    ix, iy, iz = center_idx
    norm = plt.Normalize(vmin=0, vmax=vmax)
    m = plt.cm.ScalarMappable(norm=norm, cmap=cmap)
    kwargs = {'rstride': 1, 'cstride': 1, 'shade': False, 'linewidth': 0, 'antialiased': True, 'edgecolor': 'none'}
    X, Y = np.meshgrid(x, y, indexing='ij')
    Z_plane = np.full_like(X, z[iz])
    colors_z = m.to_rgba(volume[:, :, iz])
    colors_z[..., 3] = alpha 
    ax.plot_surface(X, Y, Z_plane, facecolors=colors_z, **kwargs)
    X, Z_grid = np.meshgrid(x, z, indexing='ij')
    Y_plane = np.full_like(X, y[iy])
    colors_y = m.to_rgba(volume[:, iy, :])
    colors_y[..., 3] = alpha
    ax.plot_surface(X, Y_plane, Z_grid, facecolors=colors_y, **kwargs)
    Y, Z_grid = np.meshgrid(y, z, indexing='ij')
    X_plane = np.full_like(Y, x[ix])
    colors_x = m.to_rgba(volume[ix, :, :])
    colors_x[..., 3] = alpha
    ax.plot_surface(X_plane, Y, Z_grid, facecolors=colors_x, **kwargs)

