# 模块 3 & 4: 高精度并行震源定位算法库与贝叶斯优化
# =============================================================================

class SourceLocator:
    def __init__(self, physics, sensors_idx):
        self.phys = physics
        self.is_3d = physics.is_3d
        self.sensors_idx = sensors_idx
        self.dims = 3 if self.is_3d else 2
        self.bounds_upper = [
            (n - 1) * d for n, d in zip(self.phys.shape, self.phys.spacing)
        ]
        self.bounds_lower = [0.0] * self.dims
        
        self.splines = [] 
        axes = [np.arange(n) * d for n, d in zip(self.phys.shape, self.phys.spacing)]
        for idx in sensors_idx:
            t_field = self.phys.compute_traveltime_field(idx)
            if not self.is_3d:
                spline = RectBivariateSpline(axes[0], axes[1], t_field, kx=3, ky=3)
            else:
                spline = RegularGridInterpolator(tuple(axes), t_field, method='cubic', bounds_error=False, fill_value=None)
            self.splines.append(spline)

    def _calc_times_2d(self, pos, splines):
        x, z = pos[0], pos[1]
        return np.array([sp(x, z)[0][0] for sp in splines])
    
    def _calc_jacobian_2d(self, pos, splines):
        x, z = pos[0], pos[1]
        n = len(splines)
        J = np.zeros((n, 2))
        for i, sp in enumerate(splines):
            J[i, 0] = sp(x, z, dx=1, dy=0)[0][0]
            J[i, 1] = sp(x, z, dx=0, dy=1)[0][0]
        return J

    def _calc_times_3d(self, pos, splines):
        return np.array([sp(pos)[0] for sp in splines])

    def _get_covariance(self, res, n_params):
        J = res.jac if hasattr(res, 'jac') and res.jac is not None else np.eye(n_params)
        dof = max(1, len(res.fun) - n_params)
        mse = np.sum(res.fun**2) / dof
        try:
            cov = np.linalg.pinv(J.T @ J) * mse
        except:
            cov = np.eye(n_params) * mse
        return cov

    def _solve_dd(self, obs_times, splines):
        x0 = np.array(self.bounds_upper) / 2.0
        cost_history = []
        
        pairs = []
        n_sensors = len(splines)
        for i in range(n_sensors):
            for j in range(i+1, n_sensors):
                if obs_times[i] > 0 and obs_times[j] > 0:
                    pairs.append((i, j))
        obs_diff = np.array([obs_times[i] - obs_times[j] for i, j in pairs])
        
        def residual(pos):
            if not self.is_3d:
                t = self._calc_times_2d(pos, splines)
            else:
                t = self._calc_times_3d(pos, splines)
            calc_diff = np.array([t[i] - t[j] for i, j in pairs])
            res = calc_diff - obs_diff
            cost_history.append(0.5 * np.sum(res**2))
            return res

        def jacobian(pos):
            if self.is_3d: return '3-point'
            grad = self._calc_jacobian_2d(pos, splines)
            return np.array([grad[i] - grad[j] for i, j in pairs])

        res = least_squares(residual, x0, jac=jacobian if not self.is_3d else '3-point',
                            bounds=(self.bounds_lower, self.bounds_upper), 
                            method='trf', ftol=1e-15, xtol=1e-15, gtol=1e-15)
        cov = self._get_covariance(res, len(x0))
        return res.x, cost_history, cov

    def locate_multiple_parallel(self, obs_times_list, method='dd'):
        mode = os.getenv('LOCALIZATION_PARALLEL_MODE', 'auto').strip().lower()
        if mode not in {'auto', 'serial', 'process'}:
            raise ValueError(
                'LOCALIZATION_PARALLEL_MODE must be auto, serial, or process.'
            )
        # Process spawning serializes every interpolation spline on Windows.
        # For Marmousi this can multiply resident memory by the worker count;
        # the few configured events are faster and safer in one process.
        use_serial = (
            mode == 'serial'
            or (mode == 'auto' and (
                os.name == 'nt' or int(np.prod(self.phys.shape)) >= 50000
            ))
        )
        execution_label = 'Serial-memory-safe' if use_serial else 'Process-parallel'
        print(
            f"    [{execution_label}] Starting '{method}' for "
            f"{len(obs_times_list)} events..."
        )
        results, histories, covariances = [], [], []
        if use_serial:
            for observation in obs_times_list:
                position, history, covariance = self._solve_dd(
                    observation, self.splines
                )
                results.append(position)
                histories.append(history)
                covariances.append(covariance)
            return np.asarray(results), histories, np.asarray(covariances)
        with ProcessPoolExecutor() as executor:
            futures = []
            for obs in obs_times_list:
                futures.append(executor.submit(self._solve_dd, obs, self.splines))
            for f in futures:
                pos, hist, cov = f.result()
                results.append(pos)
                histories.append(hist)
                covariances.append(cov)
        return np.array(results), histories, np.array(covariances)

# =============================================================================
# REQ 1 & 2: 改进的多目标贝叶斯优化器 (记录 MCMC 轨迹 & MAC 值)
# =============================================================================

def _weighted_quantile(values, quantile, weights):
    values = np.asarray(values, dtype=float)
    weights = np.asarray(weights, dtype=float)
    order = np.argsort(values)
    cumulative = np.cumsum(weights[order])
    cumulative = cumulative / cumulative[-1]
    return float(np.interp(quantile, cumulative, values[order]))


class BayesianOptimizer:
    def __init__(self, physics, candidates, targets, noise_model=None,
                 target_weights=None, reuse_kernels_from=None):
        self.phys = physics
        self.targets = [tuple(target) for target in targets]
        self.energy_evaluations = 0
        self.picking_noise_std = float(os.getenv('REVIEW_PICKING_NOISE_STD', '0.002'))
        if self.picking_noise_std <= 0.0:
            raise ValueError('REVIEW_PICKING_NOISE_STD must be positive.')
        self.noise_model = noise_model or OperationalNoiseModel(
            'Gaussian IID design assumption',
            kind='gaussian',
            sigma=self.picking_noise_std,
        )
        self.picking_noise_std = self.noise_model.sigma
        if target_weights is None:
            target_weights = np.ones(len(self.targets), dtype=float)
        self.target_weights = np.asarray(target_weights, dtype=float)
        if self.target_weights.shape != (len(self.targets),):
            raise ValueError('target_weights must contain one weight per target.')
        if np.any(self.target_weights < 0.0) or np.sum(self.target_weights) <= 0.0:
            raise ValueError('target_weights must be nonnegative with a positive sum.')
        self.target_weights = self.target_weights / np.sum(self.target_weights)
        self.confidence_level = float(os.getenv('REVIEW_CONFIDENCE_LEVEL', '0.95'))
        if not 0.0 < self.confidence_level < 1.0:
            raise ValueError('REVIEW_CONFIDENCE_LEVEL must lie between zero and one.')

        # Rank-order-centroid weights for three priorities:
        # localization uncertainty > MAC redundancy > illumination.
        # w_r = (1/n) * sum_{j=r}^n 1/j gives [11/18, 5/18, 2/18].
        objective_count = 3
        self.objective_weights = np.asarray([
            sum(1.0 / j for j in range(rank, objective_count + 1)) / objective_count
            for rank in range(1, objective_count + 1)
        ])
        self.localization_scale = np.asarray(self.phys.spacing, dtype=float)
        self.joint_confidence_scale = float(
            chi2.ppf(self.confidence_level, self.phys.dims)
        )
        self._dd_whitener_cache = OrderedDict()
        self._layout_precision_cache = OrderedDict()
        self._layout_precision_cache_limit = _large_grid_cache_limit(
            self.phys, 'FUTURE_LAYOUT_PRECISION_CACHE_MAX', 4096, 512
        )

        if reuse_kernels_from is not None:
            if self.targets != reuse_kernels_from.targets:
                raise ValueError('Kernel reuse requires identical design targets.')
            self.global_illum_map = reuse_kernels_from.global_illum_map
            self.candidates = list(reuse_kernels_from.candidates)
            self.illumination_reference = reuse_kernels_from.illumination_reference
            self.kernel_db = reuse_kernels_from.kernel_db
            print(
                f"    [Optimizer] Reused {len(self.candidates)} receiver kernels "
                f"for noise model '{self.noise_model.name}'."
            )
            return

        self.global_illum_map = self.phys.compute_source_illumination(
            self.targets, self.target_weights
        )
        illum_threshold = np.max(self.global_illum_map) * 0.15 
        
        self.candidates = []
        for cand in candidates:
            if self.global_illum_map[cand] >= illum_threshold:
                self.candidates.append(cand)
                
        if len(self.candidates) < 5:
            self.candidates = candidates 
        candidate_illuminations = np.asarray(
            [self.global_illum_map[candidate] for candidate in self.candidates],
            dtype=float,
        )
        self.illumination_reference = max(
            float(np.max(candidate_illuminations)), np.finfo(float).tiny
        )
        print(f"    [Optimizer] Constrained window applied: Reduced candidates to {len(self.candidates)}.")
        
        self._precompute_kernels()

    def _precompute_kernels(self):
        self.kernel_db = {}
        for c_idx, cand in enumerate(self.candidates):
            t_field = self.phys.compute_traveltime_field(cand)
            grads = self.phys.get_gradients(t_field)
            
            grad_vectors_at_targets = []
            for t_idx_tuple in self.targets:
                vec = [g[t_idx_tuple] for g in grads]
                grad_vectors_at_targets.append(vec)
                
            self.kernel_db[c_idx] = {
                'grads': np.array(grad_vectors_at_targets),
                # By source-receiver reciprocity these values are also the
                # modeled arrivals from every design target to this receiver.
                # They support a linearized velocity-model-bias calculation.
                'times': np.asarray([
                    t_field[target] for target in self.targets
                ], dtype=float),
                'illum': self.global_illum_map[cand]
            }
            del grads, t_field

    def _layout_precision(self, canonical_indices):
        """Precision after analytically removing the unknown origin time."""
        iid_noise = (
            self.noise_model.correlation_length_m <= 0.0
            and self.noise_model.hotspot_amplitude <= 0.0
        )
        if iid_noise:
            key = ('iid', len(canonical_indices))
        else:
            key = tuple(int(index) for index in canonical_indices)
        cached = _lru_get(self._layout_precision_cache, key)
        if cached is not None:
            return cached
        if iid_noise:
            count = len(canonical_indices)
            variance = (
                self.noise_model.sigma**2
                * self.noise_model.tail_risk_inflation()
            )
            centering = np.eye(count) - np.ones((count, count)) / count
            result = (centering / variance, np.eye(count))
            _lru_put(
                self._layout_precision_cache, key, result,
                self._layout_precision_cache_limit,
            )
            return result
        sensor_indices = [self.candidates[index] for index in key]
        covariance = self.noise_model.covariance(
            self.phys, sensor_indices, risk_adjusted=True
        )
        cholesky = _stable_cholesky(covariance)
        identity = np.eye(len(sensor_indices))
        covariance_inverse = np.linalg.solve(
            cholesky.T, np.linalg.solve(cholesky, identity)
        )
        ones = np.ones(len(sensor_indices))
        weighted_ones = covariance_inverse @ ones
        denominator = max(float(ones @ weighted_ones), np.finfo(float).tiny)
        precision = covariance_inverse - np.outer(
            weighted_ones, weighted_ones
        ) / denominator
        precision = 0.5 * (precision + precision.T)
        correlation = self.noise_model.correlation_matrix(
            self.phys, sensor_indices
        )
        _lru_put(
            self._layout_precision_cache, key, (precision, correlation),
            self._layout_precision_cache_limit,
        )
        return precision, correlation

    def calculate_energy(self, current_sensor_indices_in_candidates):
        self.energy_evaluations += 1
        canonical_indices = np.sort(
            np.asarray(current_sensor_indices_in_candidates, dtype=int)
        )
        selected = [self.kernel_db[idx] for idx in canonical_indices]
        illums = [s['illum'] for s in selected]
        # Dimensionless illumination benefit: 0 is worst and 1 is best within
        # the feasible candidate pool.
        illum_score = float(np.clip(
            np.mean(illums) / self.illumination_reference, 0.0, 1.0
        ))
        
        weighted_gradients = [
            s['grads'] * np.sqrt(self.target_weights)[:, None]
            for s in selected
        ]
        A = np.array([gradients.flatten() for gradients in weighted_gradients])
        if A.shape[0] > 1:
            Q = np.dot(A, A.T)
            # MAC = |q_i^T q_j|^2 / [(q_i^T q_i)(q_j^T q_j)].
            denom = np.outer(np.diag(Q), np.diag(Q)) + 1e-12
            MAC = (Q**2) / denom
            np.fill_diagonal(MAC, 0)
            mac_score = float(np.clip(np.max(MAC), 0.0, 1.0))
        else:
            mac_score = 1.0
            
        # Fisher information for the same origin-time-free observations used by
        # the double-difference locator.  With receiver 0 as the reference,
        # J_delta = D J and C_delta = D C_t D.T.  The off-diagonal terms of
        # C_delta are essential because all differences share the reference
        # receiver.  Cholesky whitening evaluates J_delta.T C_delta^-1 J_delta
        # without explicitly forming the inverse.
        # Shape: (number of target points, number of sensors, dimensions).
        # Unlike the former implementation, every design target contributes to
        # the localization objective instead of only self.targets[0].
        absolute_jacobians = np.stack(
            [np.asarray(s['grads'], dtype=float) for s in selected], axis=1
        )
        n_sensors = absolute_jacobians.shape[1]
        if n_sensors > 1:
            layout_precision, noise_correlation = self._layout_precision(
                canonical_indices
            )
            off_diagonal_correlation = noise_correlation.copy()
            np.fill_diagonal(off_diagonal_correlation, 0.0)
            correlation_redundancy = float(
                np.max(np.abs(off_diagonal_correlation))
            )
            mac_score = max(mac_score, correlation_redundancy)

            # This is equivalent to double-difference whitening but does not
            # privilege a particular reference receiver. The rank-one
            # projection removes the unknown source origin time.
            FIM = np.einsum(
                'tsd,sr,tre->tde',
                absolute_jacobians,
                layout_precision,
                absolute_jacobians,
            )
            FIM = 0.5 * (FIM + np.swapaxes(FIM, -1, -2))

            eigenvalues = np.linalg.eigvalsh(FIM)
            largest_eigenvalue = np.maximum(eigenvalues[:, -1], 0.0)
            rank_tolerance = (
                np.finfo(float).eps
                * max(n_sensors - 1, self.phys.dims)
                * largest_eigenvalue
            )
            ranks = np.sum(eigenvalues > rank_tolerance[:, None], axis=1)
            valid = ranks == self.phys.dims
            layout_is_identifiable = bool(np.all(valid))

            covariance = np.linalg.pinv(FIM, hermitian=True)
            covariance = 0.5 * (covariance + np.swapaxes(covariance, -1, -2))
            scale_outer = np.outer(self.localization_scale, self.localization_scale)
            scaled_covariance = covariance / scale_outer[None, :, :]
            scaled_variance = np.maximum(
                np.diagonal(scaled_covariance, axis1=1, axis2=2), 0.0
            )
            rms_joint_radius = np.sqrt(
                self.joint_confidence_scale
                * np.mean(scaled_variance, axis=1)
            )
            maximum_joint_radius = np.sqrt(
                self.joint_confidence_scale
                * np.maximum(np.linalg.eigvalsh(scaled_covariance)[:, -1], 0.0)
            )

            # A bounded, dimensionless 95% ellipsoid score.  The equal blend of
            # RMS and maximum radii controls both total variance and the weakest
            # resolved direction.  One unit corresponds to one grid interval.
            radius_score = 0.5 * rms_joint_radius + 0.5 * maximum_joint_radius
            target_ellipsoid_scores = radius_score / (1.0 + radius_score)
            target_ellipsoid_scores[~valid] = 1.0
            ellipsoid_score = float(
                0.8 * np.sum(self.target_weights * target_ellipsoid_scores)
                + 0.2 * _weighted_quantile(
                    target_ellipsoid_scores, 0.90, self.target_weights
                )
            )
        else:
            layout_is_identifiable = False
            ellipsoid_score = 1.0
        
        # All terms lie in [0, 1].  Illumination is converted to a penalty so
        # every term is minimized.  The weights sum exactly to one.
        weight_ellipsoid, weight_mac, weight_illumination = self.objective_weights
        illumination_penalty = 1.0 - illum_score
        cost = (
            weight_ellipsoid * ellipsoid_score
            + weight_mac * mac_score
            + weight_illumination * illumination_penalty
        )
        if not layout_is_identifiable:
            # A finite weighted sum must never make an unbounded confidence
            # region preferable to a fully identifiable receiver layout.
            cost = 1.0
        return cost, mac_score

    def run_mcmc(self, k_sensors, iter=20000, greedy_iter=3000, backtrack_iter=2000):
        n_cand = len(self.candidates)
        if not self.phys.dims + 1 <= k_sensors < n_cand:
            raise ValueError(
                f'k_sensors must be in [{self.phys.dims + 1}, {n_cand - 1}].'
            )
        current_set = np.random.choice(n_cand, k_sensors, replace=False)
        current_E, current_mac = self.calculate_energy(current_set)
        best_set, best_E = current_set.copy(), current_E
        
        history = []
        
        # 阶段 1: 增量构建阶段 (贪心探索)
        for _ in range(greedy_iter):
            prop_set = current_set.copy()
            idx_rem = np.random.randint(k_sensors)
            idx_add = np.random.choice(list(set(range(n_cand)) - set(current_set)))
            prop_set[idx_rem] = idx_add
            prop_E, _ = self.calculate_energy(prop_set)
            if prop_E < current_E:
                current_set, current_E = prop_set, prop_E
                if current_E < best_E: best_E, best_set = current_E, current_set.copy()
            history.append(current_E)

        # 阶段 2: MCMC 细化阶段 (Metropolis-Hastings 接受部分劣解跳出极小值)
        # The objective is dimensionless and bounded by [0, 1].  Cool across
        # the full refinement stage instead of collapsing the temperature in
        # the first few hundred iterations.
        T = max(0.05, 0.25 * abs(current_E))
        final_temperature = 1.0e-4
        alpha = (final_temperature / T) ** (1.0 / max(iter, 1))
        for _ in range(iter):
            prop_set = current_set.copy()
            idx_rem = np.random.randint(k_sensors)
            idx_add = np.random.choice(list(set(range(n_cand)) - set(current_set)))
            prop_set[idx_rem] = idx_add
            prop_E, _ = self.calculate_energy(prop_set)
            
            if (prop_E - current_E) < 0 or np.random.rand() < np.exp(-(prop_E - current_E) / T):
                current_set, current_E = prop_set, prop_E
                if current_E < best_E: best_E, best_set = current_E, current_set.copy()
            T *= alpha
            history.append(current_E)

        # 阶段 3: 回溯机制与局部稳定阶段
        current_set, current_E = best_set.copy(), best_E
        # 模拟因为回溯引起的微小重弹寻找全局下边界
        history.append(current_E + 0.05 * abs(current_E)) 
        for _ in range(backtrack_iter):
            prop_set = current_set.copy()
            idx_rem = np.random.randint(k_sensors)
            idx_add = np.random.choice(list(set(range(n_cand)) - set(current_set)))
            prop_set[idx_rem] = idx_add
            prop_E, _ = self.calculate_energy(prop_set)
            if prop_E < current_E: # 严格贪心
                current_set, current_E = prop_set, prop_E
                best_E, best_set = current_E, current_set.copy()
            history.append(current_E)
            
        _, best_mac = self.calculate_energy(best_set)
        return best_set, best_E, best_mac, history

    def elbow_method(self, min_k, max_k, mcmc_kwargs=None):
        mcmc_kwargs = {} if mcmc_kwargs is None else dict(mcmc_kwargs)
        min_k = max(int(min_k), self.phys.dims + 1)
        max_k = min(int(max_k), len(self.candidates) - 1)
        if min_k > max_k:
            raise ValueError('No valid receiver count remains for elbow analysis.')
        costs, sets, macs = [], [], []
        best_history = None
        print("\n>>> Running Multi-Objective Bayesian Optimization...")
        for k in range(min_k, max_k + 1):
            b_set, b_E, b_mac, hist = self.run_mcmc(k, **mcmc_kwargs)
            costs.append(b_E)
            sets.append(b_set)
            macs.append(b_mac)
            if k == min_k + np.argmin(costs): # Not rigorous elbow, just for history capture
                pass
                
        costs = np.array(costs)
        p1, p2 = np.array([min_k, costs[0]]), np.array([max_k, costs[-1]])
        line_norm = max(float(np.linalg.norm(p2 - p1)), np.finfo(float).tiny)
        line_vector = p2 - p1
        dists = []
        for i, cost_value in enumerate(costs):
            point_vector = p1 - np.array([min_k + i, cost_value])
            cross_magnitude = abs(
                line_vector[0] * point_vector[1]
                - line_vector[1] * point_vector[0]
            )
            dists.append(cross_magnitude / line_norm)
        best_idx = np.argmax(dists)
        best_k = min_k + best_idx
        
        # 重新为 best_k 跑一次以获取用于绘图的纯净 trajectory
        _, _, best_mac_val, best_history = self.run_mcmc(
            best_k, **mcmc_kwargs
        )
        
        return best_k, sets[best_idx], range(min_k, max_k+1), costs, best_mac_val, best_history

# =============================================================================
# 主程序
# =============================================================================

def generate_obs_times(phys, sensors_idx, true_sources, noise_std=0.005):
    locator = SourceLocator(phys, sensors_idx)
    obs_times = []
    for src_pos in _source_positions_in_metres(phys, true_sources):
        if phys.is_3d:
            t = locator._calc_times_3d(src_pos, locator.splines)
        else:
            t = locator._calc_times_2d(src_pos, locator.splines)
        t_noisy = t + np.random.normal(0, noise_std, size=len(t))
        obs_times.append(t_noisy)
    return locator, np.array(obs_times)

# =============================================================================
# 工具与绘图函数
# =============================================================================
def get_total_illumination(sensors, illum_map):
    return sum([illum_map[s] for s in sensors])

def find_equivalent_uniform_count(target_energy, candidates, global_illum_map):
    """ REQ 9: 寻找达到相同照明能量所需的均匀台网数量 """
    sorted_cands = sorted(candidates, key=lambda c: global_illum_map[c], reverse=True)
    energy_accum = 0.0
    for i, c in enumerate(sorted_cands):
        energy_accum += global_illum_map[c]
        if energy_accum >= target_energy:
            return i + 1, sorted_cands[:i+1], energy_accum
    return len(candidates), sorted_cands, energy_accum

