def _space_filling_subsample(points, maximum_count):
    """Deterministic maximin subset preserving the spatial support."""
    points = [tuple(int(value) for value in point) for point in points]
    maximum_count = int(maximum_count)
    if maximum_count < 1:
        raise ValueError('A space-filling subset size must be positive.')
    if len(points) <= maximum_count:
        return points
    coordinates = np.asarray(points, dtype=float)
    span = np.ptp(coordinates, axis=0)
    span = np.where(span > 0.0, span, 1.0)
    normalized = (coordinates - np.min(coordinates, axis=0)) / span
    centroid = np.mean(normalized, axis=0)
    first = int(np.argmax(np.sum((normalized - centroid) ** 2, axis=1)))
    selected = [first]
    minimum_distance = np.sum(
        (normalized - normalized[first][None, :]) ** 2, axis=1
    )
    while len(selected) < maximum_count:
        minimum_distance[np.asarray(selected, dtype=int)] = -np.inf
        next_index = int(np.argmax(minimum_distance))
        selected.append(next_index)
        distance = np.sum(
            (normalized - normalized[next_index][None, :]) ** 2, axis=1
        )
        minimum_distance = np.minimum(minimum_distance, distance)
    return [points[index] for index in sorted(selected)]


def _apply_marmousi_resource_profile(config, model_type, candidates, targets):
    """Bound repeated FMM/MCMC work while keeping the scientific workflow."""
    report = {
        'enabled': False,
        'model_type': str(model_type),
        'original_candidate_count': len(candidates),
        'original_target_count': len(targets),
    }
    if (str(model_type) != 'Marmousi_2D'
            or not bool(config.get('marmousi_resource_profile', True))):
        report.update({
            'design_candidate_count': len(candidates),
            'design_target_count': len(targets),
        })
        return list(candidates), list(targets), report

    candidates = _space_filling_subsample(
        candidates, config['marmousi_max_candidate_sites']
    )
    targets = _space_filling_subsample(
        targets, config['marmousi_max_design_targets']
    )
    config['baseline_max_k'] = min(
        config['baseline_max_k'], config['marmousi_baseline_max_k'],
        len(candidates) - 1,
    )
    config['baseline_mcmc_iterations'] = min(
        config['baseline_mcmc_iterations'],
        config['marmousi_baseline_mcmc_iterations'],
    )
    config['baseline_greedy_iterations'] = min(
        config['baseline_greedy_iterations'],
        config['marmousi_baseline_greedy_iterations'],
    )
    config['baseline_backtrack_iterations'] = min(
        config['baseline_backtrack_iterations'],
        config['marmousi_baseline_backtrack_iterations'],
    )
    config['velocity_ensemble_max_k'] = min(
        config['velocity_ensemble_max_k'],
        config['marmousi_velocity_max_k'], len(candidates) - 1,
    )
    config['velocity_ensemble_mcmc_iterations'] = min(
        config['velocity_ensemble_mcmc_iterations'],
        config['marmousi_velocity_mcmc_iterations'],
    )
    config['velocity_ensemble_greedy_iterations'] = min(
        config['velocity_ensemble_greedy_iterations'],
        config['marmousi_velocity_greedy_iterations'],
    )
    config['velocity_ensemble_backtrack_iterations'] = min(
        config['velocity_ensemble_backtrack_iterations'],
        config['marmousi_velocity_backtrack_iterations'],
    )
    quadrature_count = int(config['marmousi_velocity_quadrature_models'])
    config['velocity_bayesian_representative_models'] = min(
        config['velocity_bayesian_representative_models'], quadrature_count
    )
    config['velocity_bayesian_migration_max_models'] = min(
        config['velocity_bayesian_migration_max_models'], quadrature_count
    )
    config['velocity_ensemble_monte_carlo_realizations'] = min(
        config['velocity_ensemble_monte_carlo_realizations'], 10
    )
    if 'RUN_REVIEWER_ANALYSES' not in os.environ:
        config['run'] = False
    report.update({
        'enabled': True,
        'design_candidate_count': len(candidates),
        'design_target_count': len(targets),
        'velocity_prior_realizations': (
            1 + len(config['velocity_ensemble_spatial_rms'])
            * int(config['velocity_residual_realizations'])
        ),
        'exact_velocity_quadrature_models': quadrature_count,
        'baseline_search_budget': {
            'maximum_k': config['baseline_max_k'],
            'mcmc': config['baseline_mcmc_iterations'],
            'greedy': config['baseline_greedy_iterations'],
            'backtrack': config['baseline_backtrack_iterations'],
        },
        'velocity_search_budget': {
            'maximum_k': config['velocity_ensemble_max_k'],
            'mcmc': config['velocity_ensemble_mcmc_iterations'],
            'greedy': config['velocity_ensemble_greedy_iterations'],
            'backtrack': config['velocity_ensemble_backtrack_iterations'],
        },
    })
    return candidates, targets, report


def _source_positions_in_metres(phys, source_indices):
    """Convert configured grid-node source indices to physical coordinates.

    This is the single authoritative conversion used by the synthetic-data
    generator, error calculation, confidence-interval tables, and the black
    true-coordinate reference lines.  PhysicsEngine defines node coordinates
    as ``origin + index * spacing``.
    """
    indices = np.asarray(source_indices, dtype=float)
    spacing = np.asarray(phys.spacing, dtype=float)
    origin = np.asarray(phys.origin, dtype=float)
    if indices.ndim != 2 or indices.shape[1] != phys.dims:
        raise ValueError(
            'source_indices must have shape (number_of_sources, phys.dims).'
        )
    return origin[None, :] + indices * spacing[None, :]


def _predict_times(locator, position):
    if locator.is_3d:
        return locator._calc_times_3d(position, locator.splines)
    return locator._calc_times_2d(position, locator.splines)


def simulate_observations(phys, sensors, source_indices, noise_std, rng):
    """Generate observations with an explicit random generator.

    This function is used by the new tests so identical random seeds can be
    applied to optimized, random, and uniform arrays.
    """
    locator = SourceLocator(phys, sensors)
    observations = []
    for position in _source_positions_in_metres(phys, source_indices):
        clean = _predict_times(locator, position)
        observations.append(clean + rng.normal(0.0, noise_std, size=clean.size))
    return np.asarray(observations)


def _reference_difference_matrix(n_sensors):
    """Independent double differences relative to receiver zero."""
    if n_sensors < 2:
        raise ValueError('At least two receivers are required for double differences.')
    matrix = np.zeros((n_sensors - 1, n_sensors), dtype=float)
    matrix[:, 0] = -1.0
    matrix[np.arange(n_sensors - 1), np.arange(1, n_sensors)] = 1.0
    return matrix


def _traveltime_jacobian(locator, position):
    """Numerical Jacobian of absolute travel times in s/m.

    A numerical derivative is used for both 2D and 3D so the condition-number
    definition is identical in every numerical example.
    """
    position = np.asarray(position, dtype=float)
    upper = np.asarray([
        (size - 1) * spacing
        for size, spacing in zip(locator.phys.shape, locator.phys.spacing)
    ], dtype=float)
    jacobian = np.zeros((len(locator.splines), locator.dims), dtype=float)
    for dim, spacing in enumerate(locator.phys.spacing):
        step = max(0.25 * float(spacing), 1.0e-6)
        plus = position.copy()
        minus = position.copy()
        plus[dim] = min(upper[dim], position[dim] + step)
        minus[dim] = max(0.0, position[dim] - step)
        denominator = plus[dim] - minus[dim]
        if denominator <= 0.0:
            continue
        jacobian[:, dim] = (
            _predict_times(locator, plus) - _predict_times(locator, minus)
        ) / denominator
    return jacobian


def condition_number_metrics(locator, position, noise_std):
    """Condition numbers used for the revised Figure 10.

    The reported Jacobian is the whitened, independent double-difference
    Jacobian Jw = L^{-1} D J.  The normal matrix is F = Jw.T @ Jw.  Therefore,
    for a full-rank problem, cond(F) is approximately cond(Jw)**2.
    """
    absolute_jacobian = _traveltime_jacobian(locator, position)
    difference = _reference_difference_matrix(absolute_jacobian.shape[0])
    dd_jacobian = difference @ absolute_jacobian
    pick_covariance = (float(noise_std) ** 2) * np.eye(absolute_jacobian.shape[0])
    dd_covariance = difference @ pick_covariance @ difference.T
    jitter = max(float(noise_std) ** 2, 1.0e-16) * 1.0e-12
    cholesky = np.linalg.cholesky(dd_covariance + jitter * np.eye(dd_covariance.shape[0]))
    whitened_jacobian = np.linalg.solve(cholesky, dd_jacobian)
    singular_values = np.linalg.svd(whitened_jacobian, compute_uv=False)
    tolerance = (
        np.finfo(float).eps * max(whitened_jacobian.shape) * singular_values[0]
        if singular_values.size else np.inf
    )
    positive = singular_values[singular_values > tolerance]
    rank = int(positive.size)
    if rank < locator.dims:
        jacobian_condition = np.inf
        normal_condition = np.inf
    else:
        jacobian_condition = float(positive.max() / positive.min())
        normal_matrix = whitened_jacobian.T @ whitened_jacobian
        normal_condition = float(np.linalg.cond(normal_matrix, 2))
    return {
        'jacobian_condition_number': jacobian_condition,
        'normal_matrix_condition_number': normal_condition,
        'rank': rank,
        'n_double_differences': int(dd_jacobian.shape[0]),
    }


def _write_csv(path, rows):
    if not rows:
        return
    fieldnames = []
    for row in rows:
        for key in row:
            if key not in fieldnames:
                fieldnames.append(key)
    with open(path, 'w', newline='', encoding='utf-8') as stream:
        writer = csv.DictWriter(stream, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)


def locate_source_noise_aware(locator, observed_times, noise_model,
                              initial_position=None):
    """Locate one event with covariance whitening and a robust loss.

    Reference differences form an independent origin-time-free data vector.
    The Gaussian case uses generalized least squares; heavy-tailed cases use a
    soft-L1 loss after whitening. The same estimator is used for every array in
    a comparison, avoiding an estimator-induced advantage.
    """
    observed_times = np.asarray(observed_times, dtype=float)
    if observed_times.shape != (len(locator.sensors_idx),):
        raise ValueError('observed_times has the wrong receiver dimension.')
    difference = _reference_difference_matrix(len(locator.sensors_idx))
    pick_covariance = noise_model.covariance(
        locator.phys, locator.sensors_idx, risk_adjusted=False
    )
    dd_covariance = difference @ pick_covariance @ difference.T
    cholesky = _stable_cholesky(dd_covariance)
    observed_difference = difference @ observed_times

    def residual(position):
        predicted_difference = difference @ _predict_times(locator, position)
        return np.linalg.solve(
            cholesky, predicted_difference - observed_difference
        )

    if locator.is_3d:
        jacobian = '3-point'
    else:
        def jacobian(position):
            absolute = locator._calc_jacobian_2d(position, locator.splines)
            return np.linalg.solve(cholesky, difference @ absolute)

    lower = np.asarray(locator.bounds_lower, dtype=float)
    upper = np.asarray(locator.bounds_upper, dtype=float)
    if initial_position is None:
        initial_position = 0.5 * (lower + upper)
    initial_position = np.clip(np.asarray(initial_position, dtype=float), lower, upper)
    result = least_squares(
        residual,
        initial_position,
        jac=jacobian,
        bounds=(lower, upper),
        method='trf',
        loss=noise_model.recommended_loss,
        f_scale=1.0,
        ftol=1.0e-10,
        xtol=1.0e-10,
        gtol=1.0e-10,
        max_nfev=400,
    )
    return {
        'estimate': result.x,
        'success': bool(result.success and np.all(np.isfinite(result.x))),
        'cost': float(result.cost),
        'nfev': int(result.nfev),
        'optimality': float(result.optimality),
    }








def _sensor_coordinates_for_json(sensors):
    return [[int(value) for value in sensor] for sensor in sensors]


def design_stage_confidence_metrics(locator, position, noise_std,
                                    confidence_level=0.95):
    """Predict localization uncertainty from the observation system alone.

    The calculation uses the same independent double differences as the source
    inversion.  It is therefore available immediately after receiver geometry
    is fixed and before any noisy observations are inverted.  Coordinate-wise
    intervals use the Gaussian linearization of the Cramer-Rao covariance,
    while ``joint_semi_axes_m`` describes the joint confidence ellipsoid.
    """
    confidence_level = float(confidence_level)
    noise_std = float(noise_std)
    if not 0.0 < confidence_level < 1.0:
        raise ValueError('confidence_level must lie strictly between zero and one.')
    if noise_std <= 0.0:
        raise ValueError('noise_std must be positive.')

    absolute_jacobian = _traveltime_jacobian(locator, position)
    difference = _reference_difference_matrix(absolute_jacobian.shape[0])
    dd_jacobian = difference @ absolute_jacobian
    pick_covariance = noise_std**2 * np.eye(absolute_jacobian.shape[0])
    dd_covariance = difference @ pick_covariance @ difference.T
    jitter = noise_std**2 * 1.0e-12
    cholesky = np.linalg.cholesky(
        dd_covariance + jitter * np.eye(dd_covariance.shape[0])
    )
    whitened_jacobian = np.linalg.solve(cholesky, dd_jacobian)
    singular_values = np.linalg.svd(whitened_jacobian, compute_uv=False)
    tolerance = (
        np.finfo(float).eps * max(whitened_jacobian.shape) * singular_values[0]
        if singular_values.size else np.inf
    )
    rank = int(np.sum(singular_values > tolerance))
    fisher_information = whitened_jacobian.T @ whitened_jacobian

    if rank < locator.dims:
        covariance = np.full((locator.dims, locator.dims), np.nan)
        standard_deviation = np.full(locator.dims, np.inf)
        marginal_half_width = np.full(locator.dims, np.inf)
        joint_semi_axes = np.full(locator.dims, np.inf)
        principal_directions = np.full((locator.dims, locator.dims), np.nan)
        condition_number = np.inf
        region_measure = np.inf
    else:
        covariance = np.linalg.pinv(fisher_information, hermitian=True)
        covariance = 0.5 * (covariance + covariance.T)
        standard_deviation = np.sqrt(np.maximum(np.diag(covariance), 0.0))
        marginal_scale = norm.ppf(0.5 + confidence_level / 2.0)
        marginal_half_width = marginal_scale * standard_deviation
        eigenvalues, principal_directions = np.linalg.eigh(covariance)
        order = np.argsort(eigenvalues)[::-1]
        eigenvalues = np.maximum(eigenvalues[order], 0.0)
        principal_directions = principal_directions[:, order]
        joint_scale = chi2.ppf(confidence_level, locator.dims)
        joint_semi_axes = np.sqrt(joint_scale * eigenvalues)
        condition_number = float(np.linalg.cond(fisher_information, 2))
        if locator.dims == 2:
            region_measure = float(np.pi * np.prod(joint_semi_axes))
        else:
            region_measure = float((4.0 / 3.0) * np.pi * np.prod(joint_semi_axes))

    return {
        'position': np.asarray(position, dtype=float),
        'absolute_jacobian': absolute_jacobian,
        'double_difference_jacobian': dd_jacobian,
        'double_difference_covariance': dd_covariance,
        'fisher_information': fisher_information,
        'covariance': covariance,
        'standard_deviation_m': standard_deviation,
        'marginal_half_width_m': marginal_half_width,
        'joint_semi_axes_m': joint_semi_axes,
        'principal_directions': principal_directions,
        'joint_region_measure_m2_or_m3': region_measure,
        'normal_matrix_condition_number': condition_number,
        'rank': rank,
        'confidence_level': confidence_level,
        'picking_noise_std_s': noise_std,
    }


def _draw_confidence_ellipse(axis, covariance, confidence_level, color, label):
    eigenvalues, eigenvectors = np.linalg.eigh(covariance)
    order = np.argsort(eigenvalues)[::-1]
    eigenvalues = np.maximum(eigenvalues[order], 0.0)
    eigenvectors = eigenvectors[:, order]
    semi_axes = np.sqrt(chi2.ppf(confidence_level, 2) * eigenvalues)
    angle = np.degrees(np.arctan2(eigenvectors[1, 0], eigenvectors[0, 0]))
    ellipse = Ellipse(
        (0.0, 0.0), width=2.0 * semi_axes[0], height=2.0 * semi_axes[1],
        angle=angle, facecolor='none', edgecolor=color, linewidth=2.0,
        label=label,
    )
    axis.add_patch(ellipse)
    return float(np.max(semi_axes))


def run_design_stage_uncertainty_analysis(locator_records, design_positions,
                                          noise_std, output_dir,
                                          confidence_level=0.95):
    """Export design-stage 95% intervals, confidence regions, and figures."""
    os.makedirs(output_dir, exist_ok=True)
    design_positions = np.asarray(design_positions, dtype=float)
    axis_names = ['X', 'Y', 'Z'] if design_positions.shape[1] == 3 else ['X', 'Z']
    colors = {'Optimized': C_OPT, 'Random': C_RND, 'Uniform': C_UNI}
    results = {}
    rows = []
    json_payload = {
        'analysis_stage': 'observation-system design before source inversion',
        'confidence_level': float(confidence_level),
        'picking_noise_std_s': float(noise_std),
        'systems': {},
    }

    for label, locator in locator_records.items():
        results[label] = []
        json_payload['systems'][label] = []
        for source_index, position in enumerate(design_positions):
            metrics = design_stage_confidence_metrics(
                locator, position, noise_std, confidence_level
            )
            results[label].append(metrics)
            row = {
                'system': label,
                'source': source_index + 1,
                'analysis_stage': 'observation-system design before source inversion',
                'number_of_geophones': len(locator.splines),
                'confidence_level': float(confidence_level),
                'picking_noise_std_s': float(noise_std),
                'rank': metrics['rank'],
                'normal_matrix_condition_number': metrics[
                    'normal_matrix_condition_number'
                ],
                'joint_95_max_semi_axis_m': float(
                    np.max(metrics['joint_semi_axes_m'])
                ),
                'joint_95_region_measure_m2_or_m3': metrics[
                    'joint_region_measure_m2_or_m3'
                ],
            }
            for dim, axis_name in enumerate(axis_names):
                center = float(position[dim])
                half_width = float(metrics['marginal_half_width_m'][dim])
                row[f'{axis_name}_nominal_m'] = center
                row[f'{axis_name}_standard_deviation_m'] = float(
                    metrics['standard_deviation_m'][dim]
                )
                row[f'{axis_name}_lower_95_m'] = center - half_width
                row[f'{axis_name}_upper_95_m'] = center + half_width
                row[f'{axis_name}_half_width_95_m'] = half_width
                for other_dim, other_name in enumerate(axis_names):
                    row[f'covariance_{axis_name}{other_name}_m2'] = float(
                        metrics['covariance'][dim, other_dim]
                    )
            for axis_index, semi_axis in enumerate(metrics['joint_semi_axes_m']):
                row[f'joint_95_semi_axis_{axis_index + 1}_m'] = float(semi_axis)
            rows.append(row)
            json_payload['systems'][label].append({
                'source': source_index + 1,
                'nominal_position_m': position.tolist(),
                'covariance_m2': metrics['covariance'].tolist(),
                'marginal_half_width_95_m': metrics[
                    'marginal_half_width_m'
                ].tolist(),
                'joint_semi_axes_95_m': metrics['joint_semi_axes_m'].tolist(),
                'principal_directions': metrics['principal_directions'].tolist(),
                'rank': metrics['rank'],
                'normal_matrix_condition_number': metrics[
                    'normal_matrix_condition_number'
                ],
            })

    _write_csv(
        os.path.join(output_dir, 'design_stage_95_percent_confidence_intervals.csv'),
        rows,
    )
    with open(os.path.join(
            output_dir, 'design_stage_95_percent_confidence_regions.json'),
            'w', encoding='utf-8') as stream:
        json.dump(json_payload, stream, indent=2)

    labels = list(locator_records)
    fig, axes = plt.subplots(
        1, len(design_positions), figsize=(5.0 * len(design_positions), 4.8),
        squeeze=False,
    )
    axes = axes.ravel()
    x_positions = np.arange(len(labels), dtype=float)
    bar_width = 0.78 / len(axis_names)
    for source_index, axis in enumerate(axes):
        for dim, axis_name in enumerate(axis_names):
            values = [
                results[label][source_index]['marginal_half_width_m'][dim]
                for label in labels
            ]
            offset = (dim - (len(axis_names) - 1) / 2.0) * bar_width
            axis.bar(
                x_positions + offset, values, width=bar_width,
                label=axis_name, edgecolor='black', linewidth=0.7,
                alpha=0.82,
            )
        axis.set_xticks(x_positions, labels, rotation=15)
        axis.set_title(f'Source {source_index + 1}')
        axis.set_ylabel('Marginal 95% half-width (m)')
        axis.grid(axis='y', linestyle=':', alpha=0.5)
    axes[0].legend(title='Coordinate')
    fig.suptitle('Design-stage localization uncertainty from receiver geometry')
    fig.tight_layout()
    fig.savefig(
        os.path.join(output_dir, 'Figure_DesignStage_95CI_Summary.png'),
        bbox_inches='tight', dpi=300,
    )
    plt.close(fig)

    coordinate_pairs = [(0, 1)] if len(axis_names) == 2 else [(0, 1), (0, 2), (1, 2)]
    for source_index in range(len(design_positions)):
        fig, axes = plt.subplots(
            1, len(coordinate_pairs),
            figsize=(5.2 * len(coordinate_pairs), 4.8), squeeze=False,
        )
        axes = axes.ravel()
        for axis, (first_dim, second_dim) in zip(axes, coordinate_pairs):
            extent = 0.0
            for label in labels:
                covariance = results[label][source_index]['covariance']
                pair_covariance = covariance[np.ix_(
                    [first_dim, second_dim], [first_dim, second_dim]
                )]
                if not np.all(np.isfinite(pair_covariance)):
                    continue
                extent = max(
                    extent,
                    _draw_confidence_ellipse(
                        axis, pair_covariance, confidence_level,
                        colors.get(label, 'black'), label,
                    ),
                )
            extent = max(extent, 1.0e-6)
            axis.scatter(0.0, 0.0, marker='+', s=70, color='black', zorder=5)
            axis.set_xlim(-1.15 * extent, 1.15 * extent)
            axis.set_ylim(-1.15 * extent, 1.15 * extent)
            axis.set_aspect('equal', adjustable='box')
            axis.set_xlabel(f'{axis_names[first_dim]} error (m)')
            axis.set_ylabel(f'{axis_names[second_dim]} error (m)')
            axis.set_title(
                f'{axis_names[first_dim]}-{axis_names[second_dim]} marginal plane'
            )
            axis.grid(True, linestyle=':', alpha=0.5)
        axes[0].legend(loc='upper right')
        fig.suptitle(
            f'Source {source_index + 1}: design-stage 95% confidence ellipses'
        )
        fig.tight_layout()
        fig.savefig(
            os.path.join(
                output_dir,
                f'Figure_DesignStage_95CI_Source_{source_index + 1}.png',
            ),
            bbox_inches='tight', dpi=300,
        )
        plt.close(fig)
    return results




def plot_mean_localization_error(mean_errors, output_dir):
    """Plot mean localization errors for the three receiver arrays."""
    labels = ['Optimized Array', 'Random Array', 'Uniform Array']
    values = np.asarray([mean_errors[label] for label in labels], dtype=float)
    colors = [C_OPT, C_RND, C_UNI]

    fig, axis = plt.subplots(figsize=(7.0, 5.2))
