def _dd_log_posterior(locator, observed_times, noise_std):
    difference = _reference_difference_matrix(len(observed_times))
    observed_difference = difference @ np.asarray(observed_times, dtype=float)
    pick_covariance = (float(noise_std) ** 2) * np.eye(len(observed_times))
    dd_covariance = difference @ pick_covariance @ difference.T
    covariance_inverse = np.linalg.pinv(dd_covariance, hermitian=True)
    upper = np.asarray([
        (size - 1) * spacing
        for size, spacing in zip(locator.phys.shape, locator.phys.spacing)
    ], dtype=float)

    def log_posterior(position):
        position = np.asarray(position, dtype=float)
        if np.any(position < 0.0) or np.any(position > upper):
            return -np.inf
        calculated_difference = difference @ _predict_times(locator, position)
        residual = calculated_difference - observed_difference
        return float(-0.5 * residual @ covariance_inverse @ residual)

    return log_posterior, upper


def _run_source_chain(log_posterior, start, upper, proposal_scale,
                      n_steps, burn, rng):
    current = np.clip(np.asarray(start, dtype=float), 0.0, upper)
    current_log_probability = log_posterior(current)
    scale = np.asarray(proposal_scale, dtype=float).copy()
    retained = np.empty((n_steps - burn, current.size), dtype=float)
    accepted_total = 0
    accepted_window = 0
    retained_index = 0
    for iteration in range(n_steps):
        proposal = current + rng.normal(0.0, scale, size=current.size)
        proposal_log_probability = log_posterior(proposal)
        log_ratio = proposal_log_probability - current_log_probability
        if np.log(rng.random()) < min(0.0, log_ratio):
            current = proposal
            current_log_probability = proposal_log_probability
            accepted_total += 1
            accepted_window += 1
        if iteration < burn and (iteration + 1) % 100 == 0:
            window_rate = accepted_window / 100.0
            if window_rate < 0.15:
                scale *= 0.70
            elif window_rate > 0.50:
                scale *= 1.30
            accepted_window = 0
        if iteration >= burn:
            retained[retained_index] = current
            retained_index += 1
    return retained, accepted_total / float(n_steps)


def _gelman_rubin(chains):
    chains = np.asarray(chains, dtype=float)
    n_chains, n_samples, _ = chains.shape
    if n_chains < 2 or n_samples < 2:
        return np.full(chains.shape[-1], np.nan)
    chain_means = np.mean(chains, axis=1)
    between = n_samples * np.var(chain_means, axis=0, ddof=1)
    within = np.mean(np.var(chains, axis=1, ddof=1), axis=0)
    variance_hat = ((n_samples - 1.0) / n_samples) * within + between / n_samples
    return np.sqrt(np.divide(variance_hat, within,
                             out=np.full_like(variance_hat, np.inf),
                             where=within > 0.0))


def _effective_sample_size_1d(values):
    values = np.asarray(values, dtype=float)
    values = values - np.mean(values)
    n_values = values.size
    variance = np.var(values)
    if n_values < 4 or variance <= 0.0:
        return float(n_values)
    fft_size = 1 << (2 * n_values - 1).bit_length()
    spectrum = np.fft.rfft(values, n=fft_size)
    autocovariance = np.fft.irfft(spectrum * np.conjugate(spectrum), n=fft_size)[:n_values]
    autocovariance /= np.arange(n_values, 0, -1)
    autocorrelation = autocovariance / autocovariance[0]
    correlation_sum = 0.0
    for lag in range(1, min(n_values - 1, 2000), 2):
        pair = autocorrelation[lag] + autocorrelation[lag + 1]
        if pair <= 0.0:
            break
        correlation_sum += pair
    return float(max(1.0, n_values / (1.0 + 2.0 * correlation_sum)))


def sample_source_posterior(locator, observed_times, map_estimate, noise_std,
                            n_steps, burn, n_chains, seed):
    """Independent source-location MCMC; not the receiver-layout chain."""
    log_posterior, upper = _dd_log_posterior(locator, observed_times, noise_std)
    rng = np.random.default_rng(seed)
    base_scale = np.maximum(0.5 * np.asarray(locator.phys.spacing, dtype=float), 0.5)
    chains = []
    acceptance_rates = []
    for chain_index in range(n_chains):
        if chain_index == 0:
            start = np.asarray(map_estimate, dtype=float)
        else:
            start = np.asarray(map_estimate, dtype=float) + rng.normal(
                0.0, 2.0 * np.asarray(locator.phys.spacing), size=locator.dims
            )
        chain, acceptance = _run_source_chain(
            log_posterior, start, upper, base_scale,
            n_steps, burn, rng
        )
        chains.append(chain)
        acceptance_rates.append(acceptance)
    chains = np.asarray(chains)
    samples = chains.reshape(-1, locator.dims)
    r_hat = _gelman_rubin(chains)
    ess = np.asarray([
        _effective_sample_size_1d(samples[:, dim])
        for dim in range(locator.dims)
    ])
    return {
        'samples': samples,
        'mean': np.mean(samples, axis=0),
        'median': np.median(samples, axis=0),
        'lower': np.quantile(samples, 0.025, axis=0),
        'upper': np.quantile(samples, 0.975, axis=0),
        'covariance': np.cov(samples, rowvar=False),
        'acceptance_rate': float(np.mean(acceptance_rates)),
        'r_hat': r_hat,
        'effective_sample_size': ess,
    }


def run_posterior_uncertainty_analysis(array_records, true_positions, noise_std,
                                       output_dir, config):
    true_positions = np.asarray(true_positions, dtype=float)
    if true_positions.ndim != 2:
        raise ValueError('true_positions must be a two-dimensional array.')
    rows = []
    posterior_results = {}
    axis_names = ['X', 'Y', 'Z'] if true_positions.shape[1] == 3 else ['X', 'Z']
    for system_index, (label, record) in enumerate(array_records.items()):
        posterior_results[label] = []
        for source_index, (observed, estimate) in enumerate(
                zip(record['observations'], record['estimates'])):
            result = sample_source_posterior(
                record['locator'], observed, estimate, noise_std,
                config['posterior_steps'], config['posterior_burn'],
                config['posterior_chains'],
                config['seed'] + system_index * 1000 + source_index * 37,
            )
            truth = true_positions[source_index]
            row = {
                'system': label,
                'source': source_index + 1,
                'posterior_mean_error_m': float(np.linalg.norm(result['mean'] - truth)),
                'acceptance_rate': result['acceptance_rate'],
                'r_hat_max': float(np.nanmax(result['r_hat'])),
                'effective_sample_size_min': float(np.min(result['effective_sample_size'])),
                'true_location_inside_coordinatewise_95_percent_interval': bool(
                    np.all((truth >= result['lower']) & (truth <= result['upper']))
                ),
            }
            for dim, axis_name in enumerate(axis_names):
                row[f'{axis_name}_mean_m'] = float(result['mean'][dim])
                row[f'{axis_name}_lower_95_m'] = float(result['lower'][dim])
                row[f'{axis_name}_upper_95_m'] = float(result['upper'][dim])
                row[f'{axis_name}_true_m'] = float(truth[dim])
            rows.append(row)
            posterior_results[label].append(result)

    _write_csv(os.path.join(output_dir, 'localization_95_percent_credible_intervals.csv'), rows)

    significance_rows = []
    if 'Optimized' in posterior_results:
        for source_index in range(len(true_positions)):
            truth = true_positions[source_index]
            optimized_error = np.linalg.norm(
                posterior_results['Optimized'][source_index]['samples'] - truth, axis=1
            )
            for competitor in ('Random', 'Uniform'):
                if competitor not in posterior_results:
                    continue
                competitor_error = np.linalg.norm(
                    posterior_results[competitor][source_index]['samples'] - truth, axis=1
                )
                sample_count = min(optimized_error.size, competitor_error.size)
                difference = competitor_error[:sample_count] - optimized_error[:sample_count]
                significance_rows.append({
                    'source': source_index + 1,
                    'comparison': f'Optimized vs {competitor}',
                    'probability_optimized_has_smaller_error': float(np.mean(difference > 0.0)),
                    'median_error_difference_m': float(np.median(difference)),
                    'difference_lower_95_m': float(np.quantile(difference, 0.025)),
                    'difference_upper_95_m': float(np.quantile(difference, 0.975)),
                })
    _write_csv(os.path.join(output_dir, 'localization_statistical_comparisons.csv'), significance_rows)

    labels = list(array_records)
    colors = {'Optimized': C_OPT, 'Random': C_RND, 'Uniform': C_UNI}
    markers = {'Optimized': 'o', 'Random': 's', 'Uniform': '^'}
    for source_index, truth in enumerate(true_positions):
        truth = np.asarray(truth, dtype=float).copy()
        fig, axes = plt.subplots(1, len(axis_names), figsize=(5.0 * len(axis_names), 4.5))
        axes = np.atleast_1d(axes)
        for dim, (axis, axis_name) in enumerate(zip(axes, axis_names)):
            for system_index, label in enumerate(labels):
                result = posterior_results[label][source_index]
                mean = result['mean'][dim]
                errors = np.asarray([[mean - result['lower'][dim]],
                                     [result['upper'][dim] - mean]])
                axis.errorbar(system_index, mean, yerr=errors,
                              color=colors.get(label, 'black'),
                              marker=markers.get(label, 'o'), capsize=5,
                              markersize=7, linewidth=1.8)
            true_coordinate = float(truth[dim])
            axis.axhline(
                y=true_coordinate, color='black', linestyle='--',
                linewidth=1.2, label='True coordinate', zorder=6,
            )
            axis.set_xticks(range(len(labels)), labels, rotation=15)
            axis.set_ylabel(f'{axis_name} coordinate (m)')
            axis.set_title(f'{axis_name} coordinate')
            axis.grid(True, linestyle=':', alpha=0.5)
        axes[0].legend(loc='best')
        fig.suptitle(
            f'Source {source_index + 1}: posterior mean and 95% credible intervals'
        )
        fig.tight_layout(rect=(0.0, 0.0, 1.0, 0.92))
        fig.savefig(os.path.join(output_dir,
                                 f'Figure_95CI_Source_{source_index + 1}.png'),
                    bbox_inches='tight', dpi=300)
        plt.close(fig)
    return posterior_results


def polarization_angular_residual(observed_vector, predicted_vector):
    """Sign-invariant P-wave polarization angle for future elastic 3C data."""
    observed = np.asarray(observed_vector, dtype=float)
    predicted = np.asarray(predicted_vector, dtype=float)
    observed_norm = np.linalg.norm(observed)
    predicted_norm = np.linalg.norm(predicted)
    if observed_norm == 0.0 or predicted_norm == 0.0:
        raise ValueError('Polarization vectors must have nonzero length.')
    cosine = np.clip(
        np.abs(np.dot(observed / observed_norm, predicted / predicted_norm)),
        0.0, 1.0,
    )
    return float(np.arccos(cosine))


def write_polarization_scope_note(output_dir):
    note = (
        'Polarization is not used in the current implementation because the '
        'forward wavefield is scalar acoustic pressure and the observations '
        'contain first-arrival travel times rather than calibrated three-component '
        'particle motion. A physically consistent joint travel-time/polarization '
        'likelihood requires an elastic (and, where necessary, anisotropic) forward '
        'model, receiver-orientation calibration, P/S separation, and polarization '
        'uncertainty. The function polarization_angular_residual() is supplied only '
        'as a validated interface for future 3C elastic data; it is intentionally '
        'not activated for the present acoustic examples.'
    )
    with open(os.path.join(output_dir, 'polarization_scope.txt'),
              'w', encoding='utf-8') as stream:
        stream.write(note + '\n')
    plot_polarization_scope_and_extension(output_dir)


def plot_polarization_scope_and_extension(output_dir):
    """Plot data compatibility and the future sign-invariant angle residual.

    This is a methods/scope figure, not a claim that polarization observations
    were synthesized by the scalar acoustic examples.
    """
    angles_deg = np.linspace(0.0, 180.0, 361)
    observed = np.array([1.0, 0.0])
    residual_deg = []
    for angle_deg in angles_deg:
        angle_rad = np.deg2rad(angle_deg)
        predicted = np.array([np.cos(angle_rad), np.sin(angle_rad)])
        residual_deg.append(np.rad2deg(
            polarization_angular_residual(observed, predicted)
        ))
    rows = [
        {'vector_misorientation_deg': float(angle),
         'sign_invariant_residual_deg': float(residual)}
        for angle, residual in zip(angles_deg, residual_deg)
    ]
    _write_csv(os.path.join(output_dir, 'polarization_angular_residual.csv'), rows)

    fig, axes = plt.subplots(1, 2, figsize=(13.0, 5.2))
    flow_axis, curve_axis = axes
    flow_axis.set_xlim(0.0, 1.0)
    flow_axis.set_ylim(0.0, 1.0)
    flow_axis.axis('off')
    box = dict(boxstyle='round,pad=0.45', linewidth=1.4)
    flow_axis.text(0.06, 0.78, 'Current data\nScalar acoustic pressure',
                   ha='left', va='center', fontsize=10,
                   bbox={**box, 'facecolor': '#E8F5E9', 'edgecolor': C_UNI})
    flow_axis.text(0.62, 0.78, 'Used in this study\nFirst-arrival travel times',
                   ha='left', va='center', fontsize=10,
                   bbox={**box, 'facecolor': '#E8F5E9', 'edgecolor': C_UNI})
    flow_axis.annotate('', xy=(0.60, 0.78), xytext=(0.40, 0.78),
                       arrowprops=dict(arrowstyle='->', color=C_UNI, lw=2.0))
    flow_axis.text(0.06, 0.30, 'Required future data\nElastic 3C particle motion',
                   ha='left', va='center', fontsize=10,
                   bbox={**box, 'facecolor': '#EAF2F8', 'edgecolor': C_RND})
    flow_axis.text(0.62, 0.30,
                   'Future extension\nJoint time–polarization likelihood',
                   ha='left', va='center', fontsize=10,
                   bbox={**box, 'facecolor': '#EAF2F8', 'edgecolor': C_RND})
    flow_axis.annotate('', xy=(0.60, 0.30), xytext=(0.40, 0.30),
                       arrowprops=dict(arrowstyle='->', color=C_RND, lw=2.0))
    flow_axis.text(0.50, 0.52,
                   'Not inferred from scalar pressure:\nrequires receiver orientation,\nP/S separation, and error covariance',
                   ha='center', va='center', fontsize=9, color=C_OPT)
    flow_axis.set_title('(a) Data and forward-model compatibility')

    curve_axis.plot(angles_deg, residual_deg, color=C_RND, linewidth=2.5)
    curve_axis.axvline(90.0, color='0.45', linestyle='--', linewidth=1.2)
    curve_axis.scatter([0.0, 90.0, 180.0], [0.0, 90.0, 0.0],
                       color=[C_UNI, C_OPT, C_UNI], zorder=3)
    curve_axis.set_xlim(0.0, 180.0)
    curve_axis.set_ylim(0.0, 95.0)
    curve_axis.set_xticks(np.arange(0, 181, 30))
    curve_axis.set_xlabel('Vector misorientation (degrees)')
    curve_axis.set_ylabel('Sign-invariant polarization residual (degrees)')
    curve_axis.set_title('(b) Residual proposed for future 3C data')
    curve_axis.grid(True, linestyle='--', alpha=0.45)
    fig.suptitle('Role and scope of polarization information', fontsize=13)
    fig.tight_layout()
    fig.savefig(os.path.join(output_dir,
                             'Figure_Polarization_Scope_and_Extension.png'),
                bbox_inches='tight', dpi=300)
    plt.close(fig)


def _clone_with_velocity(reference_phys, velocity):
    clone = PhysicsEngine(
        reference_phys.shape, reference_phys.spacing,
        is_3d=reference_phys.is_3d, velocity_file=None,
    )
    clone.V = np.asarray(velocity, dtype=np.float32).copy()
    return clone


def _spatial_velocity_perturbation(reference_velocity, rms_fraction, rng,
                                   correlation_fraction=0.05,
                                   clip_fraction=0.50,
                                   return_residual=False):
    """Add a zero-mean correlated residual to a reference velocity model.

    ``rms_fraction`` is the requested RMS of ``delta_v / v_reference``.  The
    Gaussian smoothing length is a fraction of each model dimension, and the
    fractional residual is clipped to keep all ensemble members physical.
    """
    rms_fraction = float(rms_fraction)
    correlation_fraction = float(correlation_fraction)
    clip_fraction = float(clip_fraction)
    if rms_fraction < 0.0:
        raise ValueError('Velocity-residual RMS cannot be negative.')
    if correlation_fraction <= 0.0:
        raise ValueError('Velocity-residual correlation fraction must be positive.')
    if not 0.0 < clip_fraction < 1.0:
        raise ValueError('Velocity-residual clipping fraction must lie in (0, 1).')
    random_field = rng.normal(size=reference_velocity.shape)
    sigma = tuple(
        max(1.0, size * correlation_fraction)
        for size in reference_velocity.shape
    )
    random_field = gaussian_filter(random_field, sigma=sigma, mode='reflect')
    random_field -= np.mean(random_field)
    standard_deviation = np.std(random_field)
    if standard_deviation > 0.0:
        random_field /= standard_deviation
    fractional_residual = rms_fraction * random_field
    # Alternating projection keeps the field nearly zero mean, close to its
    # requested RMS, and inside the physical clipping bounds simultaneously.
    for _ in range(6):
        fractional_residual = np.clip(
            fractional_residual, -clip_fraction, clip_fraction
        )
        fractional_residual -= np.mean(fractional_residual)
        realized_rms = float(np.sqrt(np.mean(fractional_residual**2)))
        if rms_fraction > 0.0 and realized_rms > np.finfo(float).tiny:
            fractional_residual *= rms_fraction / realized_rms
    fractional_residual = np.clip(
        fractional_residual, -clip_fraction, clip_fraction
    )
    perturbed_velocity = reference_velocity * (1.0 + fractional_residual)
    if return_residual:
        return perturbed_velocity, fractional_residual
    return perturbed_velocity


def _target_localized_random_smoothed_velocity_perturbation(
        reference_velocity, targets, target_rms_fraction, rng,
        correlation_fraction=0.05, target_radius_fraction=0.14,
        background_fraction=0.06, clip_fraction=0.30):
    """Generate one target-localized random-smoothed velocity realization.

    The construction follows four explicit steps.

    1. Draw an independent standard-normal perturbation at *every* velocity-grid
       point.  No deterministic anomaly template is imposed.
    2. Smooth that pointwise random field with a Gaussian kernel.  The kernel
       width is ``correlation_fraction`` of each grid dimension.
    3. Multiply the smoothed field by a Gaussian target taper.  Its amplitude is
       one near the target body and ``background_fraction`` far away.
    4. Rescale the target-zone RMS to ``target_rms_fraction`` and clip the final
       fractional perturbation so that all velocities remain positive.

    Thus every realization is independently random, spatially correlated only
    after smoothing, and explicitly more uncertain around the monitored target.
    """
    reference_velocity = np.asarray(reference_velocity, dtype=np.float32)
    target_rms_fraction = float(target_rms_fraction)
    correlation_fraction = float(correlation_fraction)
    target_radius_fraction = float(target_radius_fraction)
    background_fraction = float(background_fraction)
    clip_fraction = float(clip_fraction)
    if target_rms_fraction < 0.0:
        raise ValueError('Target-zone velocity RMS cannot be negative.')
    if correlation_fraction <= 0.0:
        raise ValueError('Velocity correlation fraction must be positive.')
    if target_radius_fraction <= 0.0:
        raise ValueError('Target localization radius must be positive.')
    if not 0.0 <= background_fraction < 1.0:
        raise ValueError('Velocity background fraction must lie in [0, 1).')
    if not 0.0 < clip_fraction < 1.0:
        raise ValueError('Velocity clipping fraction must lie in (0, 1).')

    # Every grid point receives an independent random draw before smoothing.
    # float32 bounds memory for large Marmousi and SEAM velocity ensembles.
    pointwise_random = rng.normal(
        0.0, 1.0, size=reference_velocity.shape
    ).astype(np.float32)
    smoothing_sigma_cells = tuple(
        max(0.75, float(size) * correlation_fraction)
        for size in reference_velocity.shape
    )
    smoothed_random = gaussian_filter(
        pointwise_random, sigma=smoothing_sigma_cells, mode='reflect'
    ).astype(np.float32)

    base_localization_taper = _target_localization_taper(
        reference_velocity.shape, targets, target_radius_fraction,
        background_fraction,
    ).astype(np.float32)
    # Squaring the normalized Gaussian taper preserves one at the target centre
    # while making its remote tail decay rapidly toward the background floor.
    normalized_taper = np.clip(
        (base_localization_taper - background_fraction)
        / max(1.0 - background_fraction, np.finfo(float).tiny),
        0.0, 1.0,
    )
    localization_taper = np.asarray(
        background_fraction
        + (1.0 - background_fraction) * normalized_taper ** 2,
        dtype=np.float32,
    )
    target_threshold = background_fraction + 0.50 * (
        1.0 - background_fraction
    )
    background_threshold = background_fraction + 0.02 * (
        1.0 - background_fraction
    )
    target_mask = localization_taper >= target_threshold
    background_mask = localization_taper <= background_threshold
    if not np.any(target_mask):
        raise ValueError('The target localization taper contains no target cells.')
    if not np.any(background_mask):
        background_mask = ~target_mask
    if not np.any(background_mask):
        background_mask = np.ones_like(target_mask, dtype=bool)

    # Target-zone standardization prevents a remote fluctuation from setting the
    # amplitude of the physically important perturbation around the target body.
    smoothed_random -= float(np.mean(smoothed_random[target_mask]))
    target_standard_deviation = float(np.std(smoothed_random[target_mask]))
    if target_standard_deviation <= np.finfo(float).tiny:
        smoothed_random.fill(0.0)
    else:
        smoothed_random /= target_standard_deviation
    smoothed_random = np.clip(smoothed_random, -3.0, 3.0)
    fractional_residual = np.asarray(
        smoothed_random * localization_taper, dtype=np.float32
    )
    # The taper-dependent three-sigma envelope guarantees weak background
    # perturbations for each realization, rather than only in ensemble average.
    local_residual_bound = np.minimum(
        clip_fraction,
        3.0 * target_rms_fraction * localization_taper,
    ).astype(np.float32)

    # Alternating scale-and-clip iterations retain the requested target RMS and
    # the target/background contrast while enforcing positive velocity.
    for _ in range(10):
        fractional_residual = np.clip(
            fractional_residual, -local_residual_bound, local_residual_bound
        )
        realized_target_rms = float(np.sqrt(np.mean(
            fractional_residual[target_mask] ** 2
        )))
        if target_rms_fraction <= 0.0:
            fractional_residual.fill(0.0)
            break
        if realized_target_rms > np.finfo(float).tiny:
            fractional_residual *= target_rms_fraction / realized_target_rms
    fractional_residual = np.clip(
        fractional_residual, -local_residual_bound, local_residual_bound
    ).astype(np.float32)
    perturbed_velocity = reference_velocity * (1.0 + fractional_residual)
    diagnostics = {
        'generation_method': (
            'independent pointwise Gaussian draws, Gaussian smoothing, '
            'target-localization taper, and target-zone RMS calibration'
        ),
        'pointwise_random_draw_count': int(reference_velocity.size),
        'smoothing_sigma_cells': [
            float(value) for value in smoothing_sigma_cells
        ],
        'target_radius_fraction_of_grid': target_radius_fraction,
        'background_amplitude_fraction': background_fraction,
        'realized_target_rms_fraction': float(np.sqrt(np.mean(
            fractional_residual[target_mask] ** 2
        ))),
        'realized_background_rms_fraction': float(np.sqrt(np.mean(
            fractional_residual[background_mask] ** 2
        ))),
        'target_cell_count': int(np.count_nonzero(target_mask)),
        'background_cell_count': int(np.count_nonzero(background_mask)),
    }
    return (
        np.asarray(perturbed_velocity, dtype=np.float32),
        fractional_residual,
        diagnostics,
    )


def _normalized_physical_candidate_coordinates(candidates, physics):
    """Map feasible receiver sites to a unit physical-coordinate box."""
    coordinates = (
        np.asarray(candidates, dtype=float)
        * np.asarray(physics.spacing, dtype=float)
    )
    minimum = np.min(coordinates, axis=0)
    span = np.ptp(coordinates, axis=0)
    span = np.where(span > np.finfo(float).eps, span, 1.0)
    return (coordinates - minimum) / span


def _select_uniform_maximin_layout(candidates, number_of_receivers, physics):
    """Select a reproducible space-filling baseline by farthest-point sampling.

    Candidate coordinates are normalized by their physical extent before the
    Euclidean distances are calculated.  This removes dependence on grid-cell
    aspect ratio and, unlike slicing the candidate list at a fixed step, makes
    the uniform comparator independent of candidate ordering density.
    """
    number_of_receivers = int(number_of_receivers)
    if not 0 < number_of_receivers <= len(candidates):
        raise ValueError('Uniform-layout receiver count is outside the candidate pool.')
    normalized = _normalized_physical_candidate_coordinates(candidates, physics)
    centroid = np.mean(normalized, axis=0)
    first = int(np.argmin(np.sum((normalized - centroid) ** 2, axis=1)))
    selected = [first]
    minimum_squared_distance = np.sum(
        (normalized - normalized[first]) ** 2, axis=1
    )
    minimum_squared_distance[first] = -np.inf
    while len(selected) < number_of_receivers:
        next_index = int(np.argmax(minimum_squared_distance))
        selected.append(next_index)
        distance_to_new_site = np.sum(
            (normalized - normalized[next_index]) ** 2, axis=1
        )
        minimum_squared_distance = np.minimum(
            minimum_squared_distance, distance_to_new_site
        )
        minimum_squared_distance[np.asarray(selected, dtype=int)] = -np.inf
    selected = np.asarray(selected, dtype=int)
    sensors = [candidates[index] for index in selected]
    return selected, sensors


def _select_reproducible_random_layout(candidates, number_of_receivers, seed):
    """Draw a fixed-seed random baseline without consuming optimizer RNG state."""
    number_of_receivers = int(number_of_receivers)
    if not 0 < number_of_receivers <= len(candidates):
        raise ValueError('Random-layout receiver count is outside the candidate pool.')
    rng = np.random.default_rng(int(seed))
    selected = np.sort(
        rng.choice(len(candidates), number_of_receivers, replace=False)
    ).astype(int)
    sensors = [candidates[index] for index in selected]
    return selected, sensors


def _target_localization_taper(model_shape, targets, radius_fraction,
                               background_fraction):
    """Return a smooth taper: maximum near targets, reduced elsewhere."""
    radius_fraction = float(radius_fraction)
    background_fraction = float(background_fraction)
    if radius_fraction <= 0.0:
        raise ValueError('Target-localized velocity radius fraction must be positive.')
    if not 0.0 <= background_fraction <= 1.0:
        raise ValueError('Velocity background fraction must lie in [0, 1].')
    target_coordinates = np.asarray(targets, dtype=float)
    if target_coordinates.ndim != 2 or target_coordinates.shape[1] != len(model_shape):
        raise ValueError('Targets must have one coordinate per model dimension.')
    radius = np.maximum(
        radius_fraction * (np.asarray(model_shape, dtype=float) - 1.0), 1.0
    )
    grids = np.meshgrid(
        *[np.arange(size, dtype=float) for size in model_shape], indexing='ij'
    )
    target_taper = np.zeros(model_shape, dtype=float)
    for target in target_coordinates:
        squared_distance = np.zeros(model_shape, dtype=float)
        for grid, coordinate, scale in zip(grids, target, radius):
            squared_distance += ((grid - coordinate) / scale) ** 2
        target_taper = np.maximum(
            target_taper, np.exp(-0.5 * squared_distance)
        )
    return background_fraction + (1.0 - background_fraction) * target_taper


def _rescale_fractional_residual(fractional_residual, requested_rms,
                                 clip_fraction):
    """Enforce zero mean, requested RMS, and physical clipping after tapering."""
    residual = np.asarray(fractional_residual, dtype=float).copy()
    requested_rms = float(requested_rms)
    for _ in range(8):
        residual -= np.mean(residual)
        realized_rms = float(np.sqrt(np.mean(residual ** 2)))
        if requested_rms > 0.0 and realized_rms > np.finfo(float).tiny:
            residual *= requested_rms / realized_rms
        residual = np.clip(residual, -clip_fraction, clip_fraction)
    return residual


def _rescale_tapered_residual(fractional_residual, localization_taper,
                              requested_target_rms, clip_fraction,
                              background_fraction):
    """Scale target-zone RMS without inflating the reduced background."""
    taper = np.asarray(localization_taper, dtype=float)
    residual = np.asarray(fractional_residual, dtype=float) * taper
    target_mask = taper >= (
        float(background_fraction) + 0.50 * (1.0 - float(background_fraction))
    )
    if not np.any(target_mask):
        raise ValueError('The target-zone velocity perturbation mask is empty.')
    for _ in range(8):
        realized = float(np.sqrt(np.mean(residual[target_mask] ** 2)))
        if realized > np.finfo(float).tiny:
            residual *= float(requested_target_rms) / realized
        residual = np.clip(residual, -clip_fraction, clip_fraction)
    return residual


def _run_mcmc_for_sensitivity(optimizer, k_sensors, config):
    try:
        result = optimizer.run_mcmc(
            k_sensors,
            iter=config['velocity_mcmc_iterations'],
            greedy_iter=config['velocity_greedy_iterations'],
            backtrack_iter=config['velocity_backtrack_iterations'],
        )
    except TypeError:
        result = optimizer.run_mcmc(
            k_sensors, iter=config['velocity_mcmc_iterations']
        )
    return np.asarray(result[0], dtype=int), float(result[1])


def _normalized_curvature_elbow(sensor_counts, costs):
    sensor_counts = np.asarray(sensor_counts, dtype=float)
    costs = np.minimum.accumulate(np.asarray(costs, dtype=float))
    if sensor_counts.size < 3 or np.ptp(costs) <= np.finfo(float).eps:
        return int(np.argmin(costs)), np.zeros_like(costs)
    normalized_x = (sensor_counts - sensor_counts.min()) / np.ptp(sensor_counts)
    normalized_y = (costs - costs.min()) / np.ptp(costs)
    first = np.gradient(normalized_y, normalized_x)
    second = np.gradient(first, normalized_x)
    curvature = np.abs(second) / np.power(1.0 + first ** 2, 1.5)
    curvature[[0, -1]] = -np.inf
    return int(np.argmax(curvature)), curvature


def _locate_sequential(locator, observations):
    estimates = []
    covariances = []
    for observed in observations:
        estimate, _, covariance = locator._solve_dd(observed, locator.splines)
        estimates.append(estimate)
        covariances.append(covariance)
    return np.asarray(estimates), np.asarray(covariances)


def run_velocity_sensitivity_analysis(reference_phys, candidates, targets,
                                      true_sources, min_k, max_k, noise_std,
                                      output_dir, config):
    """End-to-end design and localization under erroneous velocity models."""
    rng = np.random.default_rng(config['seed'])
    cases = []
    for fraction in config['velocity_levels']:
        cases.append((f'systematic_{fraction:+.0%}', 'systematic', fraction,
                      reference_phys.V * (1.0 + fraction)))
    for rms_fraction in config['spatial_velocity_rms']:
        perturbed = _spatial_velocity_perturbation(
            reference_phys.V, rms_fraction, rng
        )
        cases.append((f'spatial_rms_{rms_fraction:.0%}', 'spatial', rms_fraction,
                      perturbed))

    true_positions = _source_positions_in_metres(reference_phys, true_sources)
    rows = []
    curves = []
    for case_index, (case_name, error_type, error_fraction, velocity) in enumerate(cases):
        case_start = time.perf_counter()
        assumed_phys = _clone_with_velocity(reference_phys, velocity)
        optimizer = BayesianOptimizer(assumed_phys, candidates, targets)
        effective_max_k = min(max_k, len(optimizer.candidates) - 1)
        effective_min_k = min(min_k, effective_max_k)
        sensor_counts = np.arange(effective_min_k, effective_max_k + 1)
        costs = []
        sensor_sets = []
        for k_sensors in sensor_counts:
            selected, cost = _run_mcmc_for_sensitivity(optimizer, int(k_sensors), config)
            sensor_sets.append(selected)
            costs.append(cost)
        elbow_index, curvature = _normalized_curvature_elbow(sensor_counts, costs)
        optimized_count = int(sensor_counts[elbow_index])
        optimized_sensors = [optimizer.candidates[index]
                             for index in sensor_sets[elbow_index]]
        design_wall_seconds = float(time.perf_counter() - case_start)
        random_rng = np.random.default_rng(config['seed'] + case_index * 101)
        random_indices = random_rng.choice(len(candidates), optimized_count, replace=False)
        random_sensors = [candidates[index] for index in random_indices]
        uniform_step = max(1, len(candidates) // optimized_count)
        uniform_sensors = candidates[::uniform_step][:optimized_count]
        systems = {
            'Optimized': optimized_sensors,
            'Random': random_sensors,
            'Uniform': uniform_sensors,
        }

        for system_index, (label, sensors) in enumerate(systems.items()):
            # Reuse the same seed so the three systems have matched noise draws.
            observation_rng = np.random.default_rng(
                config['seed'] + case_index * 1000
            )
            observations = simulate_observations(
                reference_phys, sensors, true_sources, noise_std, observation_rng
            )
            locator = SourceLocator(assumed_phys, sensors)
            localization_start = time.perf_counter()
            estimates, _ = _locate_sequential(locator, observations)
            localization_wall_seconds = float(time.perf_counter() - localization_start)
            errors = np.linalg.norm(estimates - true_positions, axis=1)
            conditions = [
                condition_number_metrics(locator, estimate, noise_std)[
                    'normal_matrix_condition_number'
                ]
                for estimate in estimates
            ]
            finite_conditions = [value for value in conditions if np.isfinite(value)]
            rows.append({
                'case': case_name,
                'error_type': error_type,
                'velocity_error_percent': 100.0 * error_fraction,
                'system': label,
                'optimized_number_of_geophones': optimized_count,
                'mean_location_error_m': float(np.mean(errors)),
                'median_location_error_m': float(np.median(errors)),
                'maximum_location_error_m': float(np.max(errors)),
                'mean_normal_matrix_condition_number': (
                    float(np.mean(finite_conditions)) if finite_conditions else np.inf
                ),
                'design_wall_seconds': design_wall_seconds,
                'localization_wall_seconds': localization_wall_seconds,
                'fmm_solves': assumed_phys.traveltime_solve_count,
                'objective_evaluations': optimizer.energy_evaluations,
            })
        curves.append({
            'case': case_name,
            'sensor_counts': sensor_counts.tolist(),
            'costs': np.asarray(costs, dtype=float).tolist(),
            'curvature': np.asarray(curvature, dtype=float).tolist(),
            'selected_number': optimized_count,
        })

    _write_csv(os.path.join(output_dir, 'velocity_error_sensitivity.csv'), rows)
    with open(os.path.join(output_dir, 'velocity_error_elbow_curves.json'),
              'w', encoding='utf-8') as stream:
        json.dump(curves, stream, indent=2)

    systematic_rows = [row for row in rows if row['error_type'] == 'systematic']
    spatial_rows = [row for row in rows if row['error_type'] == 'spatial']
    fig, axes = plt.subplots(1, 2, figsize=(13.5, 5.5))
    axis_error, spatial_axis = axes
    color_map = {'Optimized': C_OPT, 'Random': C_RND, 'Uniform': C_UNI}
    for label in ('Optimized', 'Uniform', 'Random'):
        selected_rows = sorted(
            (row for row in systematic_rows if row['system'] == label),
            key=lambda row: row['velocity_error_percent'],
        )
        axis_error.plot(
            [row['velocity_error_percent'] for row in selected_rows],
            [row['mean_location_error_m'] for row in selected_rows],
            marker='o', linewidth=2.0, color=color_map[label], label=label,
        )
    axis_error.set_xlabel('Assumed velocity error (%)')
    axis_error.set_ylabel('Mean source-location error (m)')
    axis_error.grid(True, linestyle='--', alpha=0.5)
    axis_count = axis_error.twinx()
    optimized_rows = sorted(
        (row for row in systematic_rows if row['system'] == 'Optimized'),
        key=lambda row: row['velocity_error_percent'],
    )
    axis_count.step(
        [row['velocity_error_percent'] for row in optimized_rows],
        [row['optimized_number_of_geophones'] for row in optimized_rows],
        where='mid', color='black', linestyle=':', linewidth=2.0,
        label='Optimized count',
    )
    axis_count.set_ylabel('Optimized number of geophones')
    handles_1, labels_1 = axis_error.get_legend_handles_labels()
    handles_2, labels_2 = axis_count.get_legend_handles_labels()
    axis_error.legend(handles_1 + handles_2, labels_1 + labels_2, loc='best')
    axis_error.set_title('(a) Systematic velocity errors')

    if spatial_rows:
        rms_levels = sorted(set(row['velocity_error_percent'] for row in spatial_rows))
        x_positions = np.arange(len(rms_levels), dtype=float)
        bar_width = 0.24
        offsets = {'Optimized': -bar_width, 'Uniform': 0.0, 'Random': bar_width}
        for label in ('Optimized', 'Uniform', 'Random'):
            values = []
            for rms_level in rms_levels:
                matching = [row for row in spatial_rows
                            if row['system'] == label and
                            row['velocity_error_percent'] == rms_level]
                values.append(matching[0]['mean_location_error_m'] if matching else np.nan)
            spatial_axis.bar(x_positions + offsets[label], values,
                             width=bar_width, color=color_map[label],
                             edgecolor='black', label=label)
        spatial_axis.set_xticks(x_positions,
                                [f'{level:.0f}% RMS' for level in rms_levels])
        spatial_axis.set_ylabel('Mean source-location error (m)')
        spatial_axis.grid(axis='y', linestyle='--', alpha=0.5)
        spatial_count_axis = spatial_axis.twinx()
        count_values = []
        for rms_level in rms_levels:
            matching = [row for row in spatial_rows
                        if row['system'] == 'Optimized' and
                        row['velocity_error_percent'] == rms_level]
            count_values.append(matching[0]['optimized_number_of_geophones']
                                if matching else np.nan)
        spatial_count_axis.plot(x_positions, count_values, color='black',
                                marker='D', linestyle=':', linewidth=1.8,
                                label='Optimized count')
        spatial_count_axis.set_ylabel('Optimized number of geophones')
        handles_1, labels_1 = spatial_axis.get_legend_handles_labels()
        handles_2, labels_2 = spatial_count_axis.get_legend_handles_labels()
        spatial_axis.legend(handles_1 + handles_2, labels_1 + labels_2,
                            loc='best')
    else:
        spatial_axis.text(0.5, 0.5,
                          'Spatial perturbation cases are disabled\nin this run configuration.',
                          ha='center', va='center', transform=spatial_axis.transAxes)
        spatial_axis.set_xticks([])
        spatial_axis.set_yticks([])
    spatial_axis.set_title('(b) Spatially correlated velocity errors')
    fig.suptitle('Velocity-model sensitivity of array size and localization')
    fig.tight_layout()
    fig.savefig(os.path.join(output_dir, 'Figure_Velocity_Error_Sensitivity.png'),
                bbox_inches='tight', dpi=300)
    plt.close(fig)
    return rows


def _upper_tail_cvar(losses, probabilities, alpha):
    """Return discrete upper-tail CVaR with exact fractional boundary mass."""
    losses = np.asarray(losses, dtype=float)
    probabilities = np.asarray(probabilities, dtype=float)
    if losses.ndim != 1 or probabilities.shape != losses.shape:
        raise ValueError('losses and probabilities must be equal-length vectors.')
    if not 0.0 <= alpha < 1.0:
        raise ValueError('CVaR alpha must lie in [0, 1).')
    if np.any(probabilities < 0.0) or np.sum(probabilities) <= 0.0:
        raise ValueError('Scenario probabilities must be nonnegative and nonzero.')
    probabilities = probabilities / np.sum(probabilities)
    tail_mass = 1.0 - float(alpha)
    order = np.argsort(losses)[::-1]
    remaining = tail_mass
    weighted_tail_loss = 0.0
    for index in order:
        accepted_mass = min(float(probabilities[index]), remaining)
        weighted_tail_loss += accepted_mass * float(losses[index])
        remaining -= accepted_mass
        if remaining <= np.finfo(float).eps:
            break
    if remaining > np.finfo(float).eps:
        weighted_tail_loss += remaining * float(losses[order[-1]])
    return float(weighted_tail_loss / tail_mass)


def _restrict_optimizer_candidates(optimizer, common_candidates):
    """Align a velocity-scenario optimizer to a shared feasible site list."""
    old_lookup = {
        tuple(candidate): index
        for index, candidate in enumerate(optimizer.candidates)
    }
    missing = [
        tuple(candidate) for candidate in common_candidates
        if tuple(candidate) not in old_lookup
    ]
    if missing:
        raise ValueError(
            f'{len(missing)} common candidates are absent from one ensemble member.'
        )
    optimizer.candidates = [tuple(candidate) for candidate in common_candidates]
    optimizer.kernel_db = {
        new_index: optimizer.kernel_db[old_lookup[tuple(candidate)]]
        for new_index, candidate in enumerate(optimizer.candidates)
    }
    optimizer.illumination_reference = max(
        max(float(item['illum']) for item in optimizer.kernel_db.values()),
        np.finfo(float).tiny,
    )
    optimizer._dd_whitener_cache.clear()
    optimizer._layout_precision_cache.clear()


class FixedReferenceVelocityScenarioOptimizer(BayesianOptimizer):
    """Scenario objective for unknown true velocity and fixed reference inverse.

    Geometry, gradients, covariance, localization, and migration assumptions are
    always those of ``reference_optimizer``. ``true_optimizer`` contributes only
    possible true traveltimes. Their origin-time-projected difference is mapped
    through the reference Jacobian into a first-order position bias. Thus each
    scenario-optimal array minimizes the error that would actually remain when
    the unknown true medium generated the data but the reference model was used.
    """

    def __init__(self, reference_optimizer, true_optimizer, model_bias_weight):
        super().__init__(
            reference_optimizer.phys,
            reference_optimizer.candidates,
            reference_optimizer.targets,
            noise_model=reference_optimizer.noise_model,
            target_weights=reference_optimizer.target_weights,
            reuse_kernels_from=reference_optimizer,
        )
        if true_optimizer.candidates != self.candidates:
            raise ValueError(
                'True-velocity and reference-velocity kernels must share sites.'
            )
        self.true_optimizer = true_optimizer
        self.true_kernel_db = true_optimizer.kernel_db
        self.model_bias_weight = float(model_bias_weight)
        if not 0.0 <= self.model_bias_weight <= 1.0:
            raise ValueError('Scenario model-bias weight must lie in [0, 1].')
        self._velocity_bias_cache = OrderedDict()
        self._velocity_bias_cache_limit = _large_grid_cache_limit(
            self.phys, 'FUTURE_SCENARIO_BIAS_CACHE_MAX', 1024, 64
        )

    def velocity_error_bias_components(self, sensor_indices):
        """Propagate true-minus-reference traveltimes to position bias."""
        canonical = tuple(sorted(int(value) for value in sensor_indices))
        cached = _lru_get(self._velocity_bias_cache, canonical)
        if cached is not None:
            return cached
        reference_selected = [self.kernel_db[index] for index in canonical]
        true_selected = [self.true_kernel_db[index] for index in canonical]
        jacobians = np.stack([
            np.asarray(item['grads'], dtype=float)
            for item in reference_selected
        ], axis=1)
        reference_times = np.stack([
            np.asarray(item['times'], dtype=float)
            for item in reference_selected
        ], axis=1)
        true_times = np.stack([
            np.asarray(item['times'], dtype=float)
            for item in true_selected
        ], axis=1)
        time_error = true_times - reference_times
        precision, _ = self._layout_precision(canonical)
        fisher = np.einsum('tsd,sr,tre->tde', jacobians, precision, jacobians)
        fisher = 0.5 * (fisher + np.swapaxes(fisher, -1, -2))
        right_hand_side = np.einsum(
            'tsd,sr,tr->td', jacobians, precision, time_error
        )
        position_bias = np.einsum(
            'tde,te->td', np.linalg.pinv(fisher, hermitian=True),
            right_hand_side,
        )
        bias_norm_m = np.linalg.norm(position_bias, axis=1)
        scale_m = max(
            float(np.mean(self.phys.spacing)), np.finfo(float).tiny
        )
        normalized = bias_norm_m / scale_m
        bounded = normalized / (1.0 + normalized)
        bias_score = float(
            0.75 * np.sum(self.target_weights * bounded)
            + 0.25 * _weighted_quantile(bounded, 0.95, self.target_weights)
        )
        result = {
            'position_bias_m': position_bias,
            'bias_norm_m': bias_norm_m,
            'mean_bias_m': float(np.sum(self.target_weights * bias_norm_m)),
            'p95_bias_m': float(_weighted_quantile(
                bias_norm_m, 0.95, self.target_weights
            )),
            'bias_score': bias_score,
        }
        _lru_put(
            self._velocity_bias_cache, canonical, result,
            self._velocity_bias_cache_limit,
        )
        return result

    def calculate_energy(self, sensor_indices):
        reference_geometry_loss, mac_score = super().calculate_energy(
            sensor_indices
        )
        bias_score = self.velocity_error_bias_components(
            sensor_indices
        )['bias_score']
        # The multiplicative-survival form preserves the reference objective
        # when velocity bias is zero and stays bounded by one.
        loss = 1.0 - (1.0 - reference_geometry_loss) * (
            1.0 - self.model_bias_weight * bias_score
        )
        return float(np.clip(loss, 0.0, 1.0)), mac_score


class EnsembleVelocityRobustOptimizer:
    """Receiver optimizer for a probability-weighted velocity-model ensemble.

    Each ensemble member retains the original BayesianOptimizer objective. For
    a candidate layout S, member m returns loss L_m(S). The robust objective is

        R_L(S) = (1-lambda) E_p[L_m(S)]
                 + lambda CVaR_alpha[L_m(S)],

        G_m(S) = max(0, L_m(S) - L_m(S_m^*)) / max(1 - L_m(S_m^*), eps),

        R_G(S) = (1-lambda) E_p[G_m(S)]
                 + lambda CVaR_alpha[G_m(S)],

        D_m(S) = 1 - |S intersect S_m^*| / |S|,

        R_D(S) = (1-lambda_D) E_p[D_m(S)]
                 + lambda_D CVaR_alpha[D_m(S)],

        R_A(S) = (1-rho) R_L(S) + rho R_G(S),

        Sigma_total(S) = Sigma_pick(S) + Cov_p[b_m(S)],

        R_C(S) = (1-omega) R_pick-CI(S) + omega R_model-aware-CI(S),

        R_F(S) = risk from the Schur-complement location--velocity FIM,

        R_M(S) = fixed-reference local migration-focus/sidelobe risk,

        R_P(S) = (1-zeta_F-zeta_M) R_uncertainty(S)
                 + zeta_F R_F(S) + zeta_M R_M(S),

        J(S) = (1-eta) R_P(S) + eta R_D(S).

    S_m^* is the array optimized independently for velocity scenario m at the
    same receiver count. G_m is its bounded relative performance regret and
    D_m is the fraction of installed receivers that would be replaced after
    that model update. Their expectations control routine adaptation, whereas
    their CVaRs control adverse models. The possible-true-minus-reference
    traveltime differences are projected through the fixed-reference Jacobian to
    obtain b_m. Their probability-weighted covariance is added to picking-noise
    covariance, so the optimized 95% intervals include both uncertainty sources.
    The original search is retained. Setting rho=xi=eta=0 recovers the former
    mean-CVaR loss.
    """

    def __init__(self, scenario_optimizers, probabilities, cvar_alpha=0.80,
                 tail_weight=0.50, regret_weight=0.25,
                 confidence_geometry_weight=0.30,
                 model_bias_weight=0.35,
                 confidence_interval_weight=0.50,
                 confidence_scale_cells=1.00,
                 model_uncertainty_confidence_weight=0.65,
                 probability_draws=None,
                 bayesian_weight_tail=0.25,
                 layout_stability_weight=0.35,
                 layout_tail_weight=0.50,
                 joint_fisher_weight=0.20,
                  migration_quality_weight=0.20,
                  migration_proxy_radius_cells=3.0,
                  receiver_certainty_scores=None,
                  receiver_certainty_weight=0.15,
                  empirical_target_time_jacobian=None,
                  empirical_velocity_samples=None,
                  empirical_bootstrap_sample_weights=None):
        self.scenario_optimizers = list(scenario_optimizers)
        if not self.scenario_optimizers:
            raise ValueError('At least one velocity scenario is required.')
        self.candidates = list(self.scenario_optimizers[0].candidates)
        for optimizer in self.scenario_optimizers[1:]:
            if optimizer.candidates != self.candidates:
                raise ValueError('All ensemble members must share candidate ordering.')
        self.phys = self.scenario_optimizers[0].phys
        self.probabilities = np.asarray(probabilities, dtype=float)
        if self.probabilities.shape != (len(self.scenario_optimizers),):
            raise ValueError('One probability is required per velocity scenario.')
        if np.any(self.probabilities < 0.0) or np.sum(self.probabilities) <= 0.0:
            raise ValueError('Velocity-scenario probabilities are invalid.')
        self.probabilities /= np.sum(self.probabilities)
        if probability_draws is None:
            self.probability_draws = self.probabilities[None, :].copy()
        else:
            self.probability_draws = np.asarray(probability_draws, dtype=float)
            if (self.probability_draws.ndim != 2
                    or self.probability_draws.shape[1] != len(self.probabilities)
                    or np.any(self.probability_draws < 0.0)):
                raise ValueError(
                    'Bayesian probability draws must have shape '
                    '(draws, velocity scenarios) and be nonnegative.'
                )
            row_sums = np.sum(self.probability_draws, axis=1)
            if np.any(row_sums <= 0.0):
                raise ValueError('Every Bayesian probability draw must have positive mass.')
            self.probability_draws = self.probability_draws / row_sums[:, None]
        self.cvar_alpha = float(cvar_alpha)
        self.tail_weight = float(tail_weight)
        self.regret_weight = float(regret_weight)
        self.confidence_geometry_weight = float(confidence_geometry_weight)
        self.model_bias_weight = float(model_bias_weight)
        self.confidence_interval_weight = float(confidence_interval_weight)
        self.confidence_scale_cells = float(confidence_scale_cells)
        self.model_uncertainty_confidence_weight = float(
            model_uncertainty_confidence_weight
        )
        self.bayesian_weight_tail = float(bayesian_weight_tail)
        self.layout_stability_weight = float(layout_stability_weight)
        self.layout_tail_weight = float(layout_tail_weight)
        self.joint_fisher_weight = float(joint_fisher_weight)
        self.migration_quality_weight = float(migration_quality_weight)
        self.migration_proxy_radius_cells = float(migration_proxy_radius_cells)
        self.receiver_certainty_weight = float(receiver_certainty_weight)
        if receiver_certainty_scores is None:
            self.receiver_certainty_scores = np.ones(
                len(self.candidates), dtype=float
            )
        else:
            self.receiver_certainty_scores = np.asarray(
                receiver_certainty_scores, dtype=float
            ).ravel()
            if self.receiver_certainty_scores.shape != (len(self.candidates),):
                raise ValueError(
                    'Receiver certainty scores must match the candidate count.'
                )
            if np.any(~np.isfinite(self.receiver_certainty_scores)):
                raise ValueError('Receiver certainty scores must be finite.')
            self.receiver_certainty_scores = np.clip(
                self.receiver_certainty_scores, 0.0, 1.0
            )
        self.empirical_target_time_jacobian = None
        self.empirical_velocity_samples = None
        self.empirical_bootstrap_sample_weights = None
        self.empirical_velocity_mean = None
        self.empirical_velocity_covariance = None
        self.bootstrap_velocity_means = None
        self.bootstrap_velocity_covariances = None
        if empirical_target_time_jacobian is not None:
            jacobian = np.asarray(
                empirical_target_time_jacobian, dtype=np.float32
            )
            samples = np.asarray(empirical_velocity_samples, dtype=np.float32)
            bootstrap = np.asarray(
                empirical_bootstrap_sample_weights, dtype=np.float32
            )
            expected_jacobian_shape = (
                len(self.candidates),
                len(self.scenario_optimizers[0].targets),
            )
            if jacobian.ndim != 3 or jacobian.shape[:2] != expected_jacobian_shape:
                raise ValueError(
                    'Empirical target-time Jacobian does not match candidates/targets.'
                )
            if samples.ndim != 2 or samples.shape[1] != jacobian.shape[2]:
                raise ValueError('Empirical velocity samples do not match Jacobian modes.')
            if bootstrap.ndim != 2 or bootstrap.shape[1] != len(samples):
                raise ValueError('Empirical Bayesian weights do not match samples.')
            if np.any(bootstrap < 0.0) or np.any(
                    np.sum(bootstrap, axis=1) <= 0.0):
                raise ValueError('Empirical Bayesian weights are invalid.')
            bootstrap = bootstrap / np.sum(bootstrap, axis=1, keepdims=True)
            self.empirical_target_time_jacobian = jacobian
            self.empirical_velocity_samples = samples
            self.empirical_bootstrap_sample_weights = bootstrap
            self.empirical_velocity_mean = np.mean(samples, axis=0)
            centered = samples - self.empirical_velocity_mean[None, :]
            self.empirical_velocity_covariance = np.asarray(
                centered.T @ centered / float(max(len(samples) - 1, 1)),
                dtype=np.float64,
            )
            self.bootstrap_velocity_means = bootstrap @ samples
            bootstrap_second_moments = np.einsum(
                'bm,mk,ml->bkl', bootstrap, samples, samples, optimize=True
            )
            self.bootstrap_velocity_covariances = np.asarray(
                bootstrap_second_moments
                - np.einsum(
                    'bk,bl->bkl', self.bootstrap_velocity_means,
                    self.bootstrap_velocity_means,
                ),
                dtype=np.float32,
            )
            del centered, bootstrap_second_moments
        if not 0.0 <= self.cvar_alpha < 1.0:
            raise ValueError('cvar_alpha must lie in [0, 1).')
        if not 0.0 <= self.tail_weight <= 1.0:
            raise ValueError('tail_weight must lie in [0, 1].')
        if not 0.0 <= self.regret_weight <= 1.0:
            raise ValueError('regret_weight must lie in [0, 1].')
        if not 0.0 <= self.confidence_geometry_weight <= 1.0:
            raise ValueError('confidence_geometry_weight must lie in [0, 1].')
        if not 0.0 <= self.model_bias_weight <= 1.0:
            raise ValueError('model_bias_weight must lie in [0, 1].')
        if not 0.0 <= self.confidence_interval_weight <= 1.0:
            raise ValueError('confidence_interval_weight must lie in [0, 1].')
        if self.confidence_scale_cells <= 0.0:
            raise ValueError('confidence_scale_cells must be positive.')
        if not 0.0 <= self.model_uncertainty_confidence_weight <= 1.0:
            raise ValueError(
                'model_uncertainty_confidence_weight must lie in [0, 1].'
            )
        if not 0.0 <= self.bayesian_weight_tail <= 1.0:
            raise ValueError('FUTURE_BAYESIAN_WEIGHT_TAIL must lie in [0, 1].')
        if not 0.0 <= self.layout_stability_weight <= 1.0:
            raise ValueError('layout_stability_weight must lie in [0, 1].')
        if not 0.0 <= self.layout_tail_weight <= 1.0:
            raise ValueError('layout_tail_weight must lie in [0, 1].')
        if self.joint_fisher_weight < 0.0 or self.migration_quality_weight < 0.0:
            raise ValueError('Joint-Fisher and migration weights cannot be negative.')
        if self.joint_fisher_weight + self.migration_quality_weight > 1.0:
            raise ValueError(
                'FUTURE_JOINT_FISHER_WEIGHT + FUTURE_MIGRATION_QUALITY_WEIGHT '
                'must not exceed one.'
            )
        if self.migration_proxy_radius_cells <= 0.0:
            raise ValueError('FUTURE_MIGRATION_PROXY_RADIUS_CELLS must be positive.')
        if not 0.0 <= self.receiver_certainty_weight < 1.0:
            raise ValueError(
                'FUTURE_RECEIVER_CERTAINTY_OBJECTIVE_WEIGHT must lie in [0, 1).'
            )
        self.energy_evaluations = 0
        self._energy_cache = OrderedDict()
        self._confidence_geometry_cache = OrderedDict()
        self._joint_fisher_cache = OrderedDict()
        self._migration_quality_cache = OrderedDict()
        self._scenario_time_error_cache = OrderedDict()
        self._empirical_time_error_cache = OrderedDict()
        self._energy_cache_limit = _large_grid_cache_limit(
            self.phys, 'FUTURE_ENSEMBLE_ENERGY_CACHE_MAX', 4096, 768
        )
        self._confidence_cache_limit = _large_grid_cache_limit(
            self.phys, 'FUTURE_CONFIDENCE_CACHE_MAX', 512, 48
        )
        self._joint_fisher_cache_limit = _large_grid_cache_limit(
            self.phys, 'FUTURE_JOINT_FISHER_CACHE_MAX', 1024, 192
        )
        self._migration_cache_limit = _large_grid_cache_limit(
            self.phys, 'FUTURE_MIGRATION_PROXY_CACHE_MAX', 1024, 192
        )
        # Each entry has shape velocity-model x target x receiver. Keeping the
        # former 20,000 entries is the largest Marmousi memory failure mode.
        self._time_error_cache_limit = _large_grid_cache_limit(
            self.phys, 'FUTURE_TIME_ERROR_CACHE_MAX', 64, 4
        )
        self._scenario_reference_layouts = {}
        self._scenario_reference_losses = {}

    def _empirical_posterior_risk(self, values, tail_weight=None):
        """Mean-CVaR and Bayesian-bootstrap upper expectation for all samples."""
        values = np.asarray(values, dtype=float).ravel()
        if self.empirical_bootstrap_sample_weights is None or (
                values.shape != (len(self.empirical_velocity_samples),)):
            raise ValueError('Empirical risk values do not match velocity samples.')
        weights = np.full(len(values), 1.0 / len(values), dtype=float)
        expected = float(np.mean(values))
        cvar = float(_upper_tail_cvar(values, weights, self.cvar_alpha))
        if tail_weight is None:
            tail_weight = self.tail_weight
        base_risk = float((1.0 - tail_weight) * expected + tail_weight * cvar)
        posterior_expectations = self.empirical_bootstrap_sample_weights @ values
        credible_upper = float(np.quantile(posterior_expectations, 0.95))
        return {
            'expected': expected,
            'cvar': cvar,
            'posterior_expected_mean': float(np.mean(posterior_expectations)),
            'posterior_expected_p95': credible_upper,
            'risk': float(
                (1.0 - self.bayesian_weight_tail) * base_risk
                + self.bayesian_weight_tail * credible_upper
            ),
        }

    def _bootstrap_draw_risk(self, values, tail_weight=None):
        """Risk of one output value per Bayesian-bootstrap posterior draw."""
        values = np.asarray(values, dtype=float).ravel()
        if self.bootstrap_velocity_means is None or (
                values.shape != (len(self.bootstrap_velocity_means),)):
            raise ValueError('Bootstrap output values have the wrong shape.')
        weights = np.full(len(values), 1.0 / len(values), dtype=float)
        expected = float(np.mean(values))
        cvar = float(_upper_tail_cvar(values, weights, self.cvar_alpha))
        if tail_weight is None:
            tail_weight = self.tail_weight
        base = float((1.0 - tail_weight) * expected + tail_weight * cvar)
        credible_upper = float(np.quantile(values, 0.95))
        return {
            'expected': expected,
            'cvar': cvar,
            'posterior_expected_mean': expected,
            'posterior_expected_p95': credible_upper,
            'risk': float(
                (1.0 - self.bayesian_weight_tail) * base
                + self.bayesian_weight_tail * credible_upper
            ),
        }

    def _posterior_weight_risk(self, values, tail_weight=None):
        """Blend mean-CVaR risk with a Bayesian upper credible expectation."""
        values = np.asarray(values, dtype=float)
        if values.shape != self.probabilities.shape:
            raise ValueError('Scenario values do not match velocity probabilities.')
        expected = float(np.dot(self.probabilities, values))
        cvar = _upper_tail_cvar(values, self.probabilities, self.cvar_alpha)
        if tail_weight is None:
            tail_weight = self.tail_weight
        base_risk = float((1.0 - tail_weight) * expected + tail_weight * cvar)
        posterior_expectations = self.probability_draws @ values
        credible_upper = float(np.quantile(posterior_expectations, 0.95))
        risk = float(
            (1.0 - self.bayesian_weight_tail) * base_risk
            + self.bayesian_weight_tail * credible_upper
        )
        return {
            'expected': expected,
            'cvar': float(cvar),
            'posterior_expected_mean': float(np.mean(posterior_expectations)),
            'posterior_expected_p95': credible_upper,
            'risk': risk,
        }

    def set_scenario_reference_layouts(self, reference_layouts,
                                       reference_losses=None):
        """Register model-conditioned optimal arrays for one receiver count.

        Parameters
        ----------
        reference_layouts : sequence of index sequences
            One candidate-index set per velocity model.  All sets must have
            the same positive size.  The cached physics losses remain valid;
            the layout-change penalty is evaluated from these references.
        """
        if reference_layouts is None:
            self._scenario_reference_layouts = {}
            self._scenario_reference_losses = {}
            return
        if len(reference_layouts) != len(self.scenario_optimizers):
            raise ValueError(
                'One reference layout is required per velocity scenario.'
            )
        canonical_layouts = []
        reference_size = None
        for layout in reference_layouts:
            canonical = tuple(sorted(int(index) for index in layout))
            if len(canonical) == 0 or len(set(canonical)) != len(canonical):
                raise ValueError(
                    'Each scenario reference layout must contain unique sites.'
                )
            if min(canonical) < 0 or max(canonical) >= len(self.candidates):
                raise ValueError('A scenario reference site is out of range.')
            if reference_size is None:
                reference_size = len(canonical)
            elif len(canonical) != reference_size:
                raise ValueError(
                    'All scenario reference layouts must have the same size.'
                )
            canonical_layouts.append(frozenset(canonical))
        self._scenario_reference_layouts[reference_size] = canonical_layouts
        if reference_losses is not None:
            reference_losses = np.asarray(reference_losses, dtype=float)
            if reference_losses.shape != (len(self.scenario_optimizers),):
                raise ValueError(
                    'One reference loss is required per velocity scenario.'
                )
            if np.any(~np.isfinite(reference_losses)):
                raise ValueError('Scenario reference losses must be finite.')
            self._scenario_reference_losses[reference_size] = (
                reference_losses.copy()
            )

    def layout_replacement_fractions(self, sensor_indices):
        """Return scenario-wise fractions of receivers requiring relocation."""
        canonical = tuple(sorted(int(index) for index in sensor_indices))
        if not canonical:
            raise ValueError('A layout must contain at least one receiver.')
        references = self._scenario_reference_layouts.get(len(canonical))
        if references is None:
            return np.zeros(len(self.scenario_optimizers), dtype=float)
        selected = frozenset(canonical)
        return np.asarray([
            1.0 - len(selected.intersection(reference)) / len(canonical)
            for reference in references
        ], dtype=float)

    def scenario_regrets(self, sensor_indices, losses=None):
        """Return bounded loss degradation from each model-specific optimum."""
        canonical = tuple(sorted(int(index) for index in sensor_indices))
        reference_losses = self._scenario_reference_losses.get(len(canonical))
        if reference_losses is None:
            return np.zeros(len(self.scenario_optimizers), dtype=float)
        if losses is None:
            losses, _ = self.scenario_losses(canonical)
        losses = np.asarray(losses, dtype=float)
        denominator = np.maximum(
            1.0 - reference_losses, np.sqrt(np.finfo(float).eps)
        )
        return np.clip(
            np.maximum(losses - reference_losses, 0.0) / denominator,
            0.0, 1.0,
        )

    def scenario_losses(self, sensor_indices):
        canonical = tuple(sorted(int(index) for index in sensor_indices))
        cached = _lru_get(self._energy_cache, canonical)
        if cached is not None:
            return cached
        losses = []
        mac_values = []
        for optimizer in self.scenario_optimizers:
            loss, mac = optimizer.calculate_energy(canonical)
            losses.append(float(loss))
            mac_values.append(float(mac))
        result = (np.asarray(losses, dtype=float), np.asarray(mac_values, dtype=float))
        _lru_put(
            self._energy_cache, canonical, result, self._energy_cache_limit
        )
        return result

    @staticmethod
    def _bounded_scale(value):
        value = np.maximum(np.asarray(value, dtype=float), 0.0)
        return value / (1.0 + value)

    def scenario_confidence_geometry_scores(self, sensor_indices):
        """Return scenario scores for marginal CIs and joint error regions.

        The calculation uses the same origin-time-projected Fisher information
        and target weights as BayesianOptimizer.calculate_energy, so compact
        confidence intervals and compact error ellipses affect site selection
        rather than being reported only after optimization.
        """
        canonical = np.sort(np.asarray(sensor_indices, dtype=int))
        cache_key = tuple(int(index) for index in canonical)
        cached = _lru_get(self._confidence_geometry_cache, cache_key)
        if cached is not None:
            return cached
        interval_scores = []
        ellipse_scores = []
        maximum_axes_m = []
        mean_half_widths_m = []
        region_measures = []
        joint_scale = float(chi2.ppf(
            self.scenario_optimizers[0].confidence_level, self.phys.dims
        ))
        marginal_scale = float(norm.ppf(
            0.5 + self.scenario_optimizers[0].confidence_level / 2.0
        ))
        physical_scale = np.asarray(self.phys.spacing, dtype=float)
        normalization = self.confidence_scale_cells * physical_scale
        for optimizer in self.scenario_optimizers:
            selected = [optimizer.kernel_db[index] for index in canonical]
            jacobians = np.stack(
                [np.asarray(item['grads'], dtype=float) for item in selected],
                axis=1,
            )
            precision, _ = optimizer._layout_precision(canonical)
            fisher = np.einsum(
                'tsd,sr,tre->tde', jacobians, precision, jacobians
            )
            fisher = 0.5 * (fisher + np.swapaxes(fisher, -1, -2))
            eigenvalues = np.linalg.eigvalsh(fisher)
            tolerance = (
                np.finfo(float).eps * max(len(canonical) - 1, self.phys.dims)
                * np.maximum(eigenvalues[:, -1], 0.0)
            )
            valid = np.sum(eigenvalues > tolerance[:, None], axis=1) == self.phys.dims
            covariance = np.linalg.pinv(fisher, hermitian=True)
            covariance = 0.5 * (covariance + np.swapaxes(covariance, -1, -2))
            variances = np.maximum(
                np.diagonal(covariance, axis1=1, axis2=2), 0.0
            )
            marginal_half_widths = marginal_scale * np.sqrt(variances)
            normalized_half_widths = marginal_half_widths / normalization[None, :]
            target_interval = np.mean(
                self._bounded_scale(normalized_half_widths), axis=1
            )

            covariance_eigenvalues = np.maximum(
                np.linalg.eigvalsh(covariance), 0.0
            )
            semi_axes = np.sqrt(joint_scale * covariance_eigenvalues)
            maximum_axis = semi_axes[:, -1]
            normalized_maximum_axis = maximum_axis / float(
                self.confidence_scale_cells * np.mean(physical_scale)
            )
            # Dimensionless area/volume ratio relative to a confidence region
            # whose every semi-axis equals the selected physical scale.
            normalized_region = np.prod(
                semi_axes / normalization[None, :], axis=1
            )
            target_ellipse = 0.65 * self._bounded_scale(
                normalized_maximum_axis
            ) + 0.35 * self._bounded_scale(normalized_region)
            target_interval[~valid] = 1.0
            target_ellipse[~valid] = 1.0
            maximum_axis[~valid] = np.inf
            marginal_half_widths[~valid] = np.inf
            normalized_region[~valid] = np.inf

            weights = optimizer.target_weights
            interval_scores.append(float(
                0.8 * np.sum(weights * target_interval)
                + 0.2 * _weighted_quantile(target_interval, 0.90, weights)
            ))
            ellipse_scores.append(float(
                0.8 * np.sum(weights * target_ellipse)
                + 0.2 * _weighted_quantile(target_ellipse, 0.90, weights)
            ))
            maximum_axes_m.append(float(_weighted_quantile(
                maximum_axis, 0.95, weights
            )))
            target_mean_half_width = np.mean(marginal_half_widths, axis=1)
            mean_half_widths_m.append(float(_weighted_quantile(
                target_mean_half_width, 0.95, weights
            )))
            region_measures.append(float(_weighted_quantile(
                normalized_region, 0.95, weights
            )))
        result = {
            'scenario_confidence_interval_scores': np.asarray(
                interval_scores, dtype=float
            ),
            'scenario_error_ellipse_scores': np.asarray(
                ellipse_scores, dtype=float
            ),
            'scenario_p95_maximum_95_semi_axis_m': np.asarray(
                maximum_axes_m, dtype=float
            ),
            'scenario_p95_mean_marginal_95_half_width_m': np.asarray(
                mean_half_widths_m, dtype=float
            ),
            'scenario_p95_normalized_region_measure': np.asarray(
                region_measures, dtype=float
            ),
        }
        _lru_put(
            self._confidence_geometry_cache, cache_key, result,
            self._confidence_cache_limit,
        )
        return result

    def _confidence_geometry_risk(self, sensor_indices):
        components = self.scenario_confidence_geometry_scores(sensor_indices)
        combined = (
            self.confidence_interval_weight
            * components['scenario_confidence_interval_scores']
            + (1.0 - self.confidence_interval_weight)
            * components['scenario_error_ellipse_scores']
        )
        posterior_risk = self._posterior_weight_risk(combined)
        components.update({
            'scenario_confidence_geometry_scores': combined,
            'expected_confidence_geometry_score': posterior_risk['expected'],
            'cvar_confidence_geometry_score': posterior_risk['cvar'],
            'posterior_p95_confidence_geometry_score': posterior_risk[
                'posterior_expected_p95'
            ],
            'confidence_geometry_risk': posterior_risk['risk'],
        })
        return components

    def scenario_velocity_bias_scores(self, sensor_indices):
        """Propagate unknown true velocities through the fixed reference inverse.

        Besides scenario mean/P95 bias, this calculates the across-model bias
        covariance and adds it to the reference-model picking-noise covariance.
        The resulting model-aware 95% interval enters the design objective.
        """
        canonical = np.sort(np.asarray(sensor_indices, dtype=int))
        reference_optimizer = self.scenario_optimizers[0]
        scores = []
        p95_bias_m = []
        mean_bias_m = []
        scenario_position_bias = []
        scale_m = float(
            self.confidence_scale_cells * np.mean(self.phys.spacing)
        )
        for optimizer in self.scenario_optimizers:
            components = optimizer.velocity_error_bias_components(canonical)
            position_bias = np.asarray(components['position_bias_m'], dtype=float)
            bias_norm = np.asarray(components['bias_norm_m'], dtype=float)
            scenario_position_bias.append(position_bias)
            normalized = self._bounded_scale(bias_norm / scale_m)
            weights = optimizer.target_weights
            scores.append(float(
                0.8 * np.sum(weights * normalized)
                + 0.2 * _weighted_quantile(normalized, 0.90, weights)
            ))
            p95_bias_m.append(float(_weighted_quantile(
                bias_norm, 0.95, weights
            )))
            mean_bias_m.append(float(np.sum(weights * bias_norm)))
        scores = np.asarray(scores, dtype=float)
        scenario_position_bias = np.stack(scenario_position_bias, axis=0)
        posterior_bias_risk = self._posterior_weight_risk(scores)

        # Law of total covariance: picking-noise covariance from the fixed
        # reference inverse plus covariance of the velocity-induced biases.
        probability_mean_bias = np.einsum(
            's,std->td', self.probabilities, scenario_position_bias
        )
        centered_bias = scenario_position_bias - probability_mean_bias[None, :, :]
        between_model_covariance = np.einsum(
            's,std,ste->tde', self.probabilities,
            centered_bias, centered_bias,
        )
        # The posterior probability vector is itself uncertain. The covariance
        # of posterior-draw mixture means is an additional epistemic term.
        posterior_mean_biases = np.einsum(
            'bs,std->btd', self.probability_draws, scenario_position_bias
        )
        posterior_mean_center = np.mean(posterior_mean_biases, axis=0)
        posterior_mean_offsets = (
            posterior_mean_biases - posterior_mean_center[None, :, :]
        )
        probability_weight_covariance = np.einsum(
            'btd,bte->tde', posterior_mean_offsets, posterior_mean_offsets
        ) / float(max(self.probability_draws.shape[0], 1))
        model_covariance = between_model_covariance + probability_weight_covariance
        selected_reference = [
            reference_optimizer.kernel_db[index] for index in canonical
        ]
        reference_jacobians = np.stack([
            np.asarray(item['grads'], dtype=float)
            for item in selected_reference
        ], axis=1)
        precision, _ = reference_optimizer._layout_precision(canonical)
        # The compact representative velocity nodes remain useful for the
        # scenario diagnostics above, but they must not define the uncertainty
        # interval that constrains the receiver design.  Propagate the moments
        # of every uncompressed design perturbation through the linearized
        # reference-velocity inverse instead.  The independent holdout bank is
        # deliberately excluded here and is reserved for nonlinear validation.
        uses_uncompressed_empirical_moments = (
            self.empirical_target_time_jacobian is not None
            and self.empirical_velocity_covariance is not None
        )
        if uses_uncompressed_empirical_moments:
            selected_velocity_jacobian = self.empirical_target_time_jacobian[
                np.asarray(canonical, dtype=int)
            ]
            empirical_mean_bias = []
            empirical_between_covariance = []
            empirical_weight_covariance = []
            for target_index in range(reference_jacobians.shape[0]):
                gradient = reference_jacobians[target_index]
                fisher_target = gradient.T @ precision @ gradient
                inverse_map = (
                    np.linalg.pinv(fisher_target, hermitian=True)
                    @ gradient.T @ precision
                )
                time_sensitivity = selected_velocity_jacobian[
                    :, target_index, :
                ]
                position_sensitivity = inverse_map @ time_sensitivity
                empirical_mean_bias.append(
                    position_sensitivity @ self.empirical_velocity_mean
                )
                empirical_between_covariance.append(
                    position_sensitivity
                    @ self.empirical_velocity_covariance
                    @ position_sensitivity.T
                )
                bootstrap_position_means = (
                    self.bootstrap_velocity_means @ position_sensitivity.T
                )
                bootstrap_offsets = (
                    bootstrap_position_means
                    - np.mean(bootstrap_position_means, axis=0, keepdims=True)
                )
                empirical_weight_covariance.append(
                    bootstrap_offsets.T @ bootstrap_offsets
                    / float(max(len(bootstrap_offsets), 1))
                )
            probability_mean_bias = np.asarray(empirical_mean_bias, dtype=float)
            between_model_covariance = np.asarray(
                empirical_between_covariance, dtype=float
            )
            probability_weight_covariance = np.asarray(
                empirical_weight_covariance, dtype=float
            )
            model_covariance = (
                between_model_covariance + probability_weight_covariance
            )
        reference_fisher = np.einsum(
            'tsd,sr,tre->tde',
            reference_jacobians, precision, reference_jacobians,
        )
        reference_fisher = 0.5 * (
            reference_fisher + np.swapaxes(reference_fisher, -1, -2)
        )
        picking_covariance = np.linalg.pinv(reference_fisher, hermitian=True)
        total_covariance = picking_covariance + model_covariance
        total_covariance = 0.5 * (
            total_covariance + np.swapaxes(total_covariance, -1, -2)
        )
        confidence_scale = float(chi2.ppf(
            reference_optimizer.confidence_level, self.phys.dims
        ))
        total_eigenvalues = np.maximum(
            np.linalg.eigvalsh(total_covariance), 0.0
        )
        maximum_95_axes_m = np.sqrt(
            confidence_scale * total_eigenvalues[:, -1]
        )
        marginal_variances = np.maximum(
            np.diagonal(total_covariance, axis1=1, axis2=2), 0.0
        )
        marginal_multiplier = float(norm.ppf(
            0.5 + reference_optimizer.confidence_level / 2.0
        ))
        marginal_half_widths_m = marginal_multiplier * np.sqrt(
            marginal_variances
        )
        interval_measure_m = (
            0.5 * np.mean(marginal_half_widths_m, axis=1)
            + 0.5 * maximum_95_axes_m
        )
        interval_bounded = self._bounded_scale(interval_measure_m / scale_m)
        model_aware_interval_risk = float(
            0.75 * np.sum(reference_optimizer.target_weights * interval_bounded)
            + 0.25 * _weighted_quantile(
                interval_bounded, 0.95, reference_optimizer.target_weights
            )
        )
        return {
            'scenario_velocity_bias_scores': scores,
            'scenario_mean_velocity_bias_m': np.asarray(mean_bias_m),
            'scenario_p95_velocity_bias_m': np.asarray(p95_bias_m),
            'expected_velocity_bias_score': posterior_bias_risk['expected'],
            'cvar_velocity_bias_score': posterior_bias_risk['cvar'],
            'posterior_p95_expected_velocity_bias_score': posterior_bias_risk[
                'posterior_expected_p95'
            ],
            'velocity_bias_risk': posterior_bias_risk['risk'],
            'model_aware_confidence_risk': model_aware_interval_risk,
            'mean_model_aware_marginal_95_half_width_m': float(np.sum(
                reference_optimizer.target_weights
                * np.mean(marginal_half_widths_m, axis=1)
            )),
            'p95_model_aware_maximum_95_axis_m': float(_weighted_quantile(
                maximum_95_axes_m, 0.95, reference_optimizer.target_weights
            )),
            'model_error_covariance_trace_m2': float(np.sum(
                reference_optimizer.target_weights
                * np.trace(model_covariance, axis1=1, axis2=2)
            )),
            'between_velocity_model_covariance_trace_m2': float(np.sum(
                reference_optimizer.target_weights
                * np.trace(between_model_covariance, axis1=1, axis2=2)
            )),
            'posterior_weight_covariance_trace_m2': float(np.sum(
                reference_optimizer.target_weights
                * np.trace(probability_weight_covariance, axis1=1, axis2=2)
            )),
            'posterior_mean_position_bias_m': probability_mean_bias,
            'target_model_position_covariances_m2': model_covariance,
            'target_total_position_covariances_m2': total_covariance,
            'target_maximum_95_axes_m': maximum_95_axes_m,
            'confidence_interval_uses_uncompressed_empirical_samples': bool(
                uses_uncompressed_empirical_moments
            ),
            'confidence_interval_velocity_samples_used': int(
                len(self.empirical_velocity_samples)
                if uses_uncompressed_empirical_moments else len(self.probabilities)
            ),
        }

    def _scenario_time_error_tensor(self, sensor_indices):
        """Return true-minus-reference target times for every velocity model."""
        canonical = tuple(sorted(int(value) for value in sensor_indices))
        cached = _lru_get(self._scenario_time_error_cache, canonical)
        if cached is not None:
            return cached
        reference_optimizer = self.scenario_optimizers[0]
        reference_times = np.stack([
            np.asarray(reference_optimizer.kernel_db[index]['times'], dtype=float)
            for index in canonical
        ], axis=1)
        scenario_errors = []
        for optimizer in self.scenario_optimizers:
            true_database = getattr(
                optimizer, 'true_kernel_db', optimizer.kernel_db
            )
            true_times = np.stack([
                np.asarray(true_database[index]['times'], dtype=float)
                for index in canonical
            ], axis=1)
            scenario_errors.append(true_times - reference_times)
        result = np.stack(scenario_errors, axis=0)
        _lru_put(
            self._scenario_time_error_cache, canonical, result,
            self._time_error_cache_limit,
        )
        return result

    def _empirical_time_error_tensor(self, sensor_indices):
        """Return all empirical velocity-induced target-time errors compactly."""
        if self.empirical_target_time_jacobian is None:
            return None
        canonical = tuple(sorted(int(value) for value in sensor_indices))
        cached = _lru_get(self._empirical_time_error_cache, canonical)
        if cached is not None:
            return cached
        selected_jacobian = self.empirical_target_time_jacobian[
            np.asarray(canonical, dtype=int)
        ]
        # sample x target x receiver; full-grid velocity fields are never made.
        result = np.einsum(
            'stk,mk->mts', selected_jacobian,
            self.empirical_velocity_samples, optimize=True,
        ).astype(np.float32)
        _lru_put(
            self._empirical_time_error_cache, canonical, result,
            2 if int(np.prod(self.phys.shape)) >= 500000 else 8,
        )
        return result

    def joint_location_velocity_fisher_scores(self, sensor_indices):
        """Marginalize posterior velocity modes with a joint Fisher matrix.

        For each target, all uncompressed empirical perturbations form the
        receiver-space velocity-error covariance. Its eigenvectors are velocity
        nuisance modes B. The source-location information after marginalizing
        velocity is the Schur complement

            F_x|v = F_xx - F_xv (F_vv + I)^-1 F_vx.

        This directly penalizes receiver geometries for which a velocity update
        is easily confused with a source displacement.
        """
        canonical = tuple(sorted(int(value) for value in sensor_indices))
        cached = _lru_get(self._joint_fisher_cache, canonical)
        if cached is not None:
            return cached
        reference_optimizer = self.scenario_optimizers[0]
        selected = [reference_optimizer.kernel_db[index] for index in canonical]
        jacobians = np.stack([
            np.asarray(item['grads'], dtype=float) for item in selected
        ], axis=1)
        precision, _ = reference_optimizer._layout_precision(canonical)
        uses_empirical = self.empirical_target_time_jacobian is not None
        if uses_empirical:
            selected_velocity_jacobian = self.empirical_target_time_jacobian[
                np.asarray(canonical, dtype=int)
            ]
            time_errors = None
        else:
            selected_velocity_jacobian = None
            time_errors = self._scenario_time_error_tensor(canonical)
        scale_m = max(
            self.confidence_scale_cells * float(np.mean(self.phys.spacing)),
            np.finfo(float).tiny,
        )
        confidence_scale = float(chi2.ppf(
            reference_optimizer.confidence_level, self.phys.dims
        ))
        maximum_axes = []
        information_retention = []
        target_scores = []
        for target_index in range(jacobians.shape[0]):
            gradient = jacobians[target_index]
            if uses_empirical:
                velocity_sensitivity = selected_velocity_jacobian[
                    :, target_index, :
                ]
                velocity_covariance = (
                    velocity_sensitivity
                    @ self.empirical_velocity_covariance
                    @ velocity_sensitivity.T
                )
            else:
                errors = time_errors[:, target_index, :]
                mean_error = np.einsum('m,ms->s', self.probabilities, errors)
                centered = errors - mean_error[None, :]
                velocity_covariance = np.einsum(
                    'm,ms,mr->sr', self.probabilities, centered, centered
                )
            velocity_covariance = 0.5 * (
                velocity_covariance + velocity_covariance.T
            )
            values, vectors = np.linalg.eigh(velocity_covariance)
            tolerance = max(
                float(np.max(values, initial=0.0)) * 1.0e-10,
                np.finfo(float).eps,
            )
            retained = values > tolerance
            velocity_modes = (
                vectors[:, retained] * np.sqrt(values[retained])[None, :]
                if np.any(retained)
                else np.empty((len(canonical), 0), dtype=float)
            )
            fisher_xx = gradient.T @ precision @ gradient
            fisher_xx = 0.5 * (fisher_xx + fisher_xx.T)
            if velocity_modes.shape[1]:
                fisher_xv = gradient.T @ precision @ velocity_modes
                fisher_vv = (
                    velocity_modes.T @ precision @ velocity_modes
                    + np.eye(velocity_modes.shape[1], dtype=float)
                )
                marginal_fisher = (
                    fisher_xx
                    - fisher_xv @ np.linalg.pinv(
                        fisher_vv, hermitian=True
                    ) @ fisher_xv.T
                )
            else:
                marginal_fisher = fisher_xx
            marginal_fisher = 0.5 * (
                marginal_fisher + marginal_fisher.T
            )
            marginal_eigenvalues = np.linalg.eigvalsh(marginal_fisher)
            identifiable = bool(np.all(marginal_eigenvalues > 1.0e-14))
            if identifiable:
                covariance = np.linalg.pinv(marginal_fisher, hermitian=True)
                axis_m = float(np.sqrt(
                    confidence_scale
                    * max(float(np.max(np.linalg.eigvalsh(covariance))), 0.0)
                ))
                base_minimum = max(
                    float(np.min(np.linalg.eigvalsh(fisher_xx))),
                    np.finfo(float).tiny,
                )
                retained_minimum = max(
                    float(np.min(marginal_eigenvalues)), 0.0
                )
                retention = float(np.clip(
                    retained_minimum / base_minimum, 0.0, 1.0
                ))
                axis_score = float(self._bounded_scale(axis_m / scale_m))
                score = 0.80 * axis_score + 0.20 * (1.0 - retention)
            else:
                axis_m = np.inf
                retention = 0.0
                score = 1.0
            maximum_axes.append(axis_m)
            information_retention.append(retention)
            target_scores.append(score)
        target_scores = np.asarray(target_scores, dtype=float)
        weights = reference_optimizer.target_weights
        risk = float(
            0.80 * np.sum(weights * target_scores)
            + 0.20 * _weighted_quantile(target_scores, 0.95, weights)
        )
        finite_axes = np.asarray(maximum_axes, dtype=float)
        finite_axes = np.where(np.isfinite(finite_axes), finite_axes, 1.0e12)
        result = {
            'joint_position_velocity_fisher_risk': risk,
            'joint_fisher_mean_maximum_95_axis_m': float(np.sum(
                weights * finite_axes
            )),
            'joint_fisher_p95_maximum_95_axis_m': float(_weighted_quantile(
                finite_axes, 0.95, weights
            )),
            'joint_fisher_mean_information_retention': float(np.sum(
                weights * np.asarray(information_retention, dtype=float)
            )),
            'joint_fisher_velocity_samples_used': int(
                len(self.empirical_velocity_samples)
                if uses_empirical else time_errors.shape[0]
            ),
            'joint_fisher_uses_uncompressed_empirical_samples': bool(
                uses_empirical
            ),
        }
        _lru_put(
            self._joint_fisher_cache, canonical, result,
            self._joint_fisher_cache_limit,
        )
        return result

    def migration_quality_scores(self, sensor_indices):
        """Fast local proxy for fixed-reference migration focus and sidelobes.

        The possible true model supplies the observed target arrivals.  The
        reference Jacobian predicts arrivals at the target and at +/- one local
        imaging radius along every coordinate. Differential-time quadratic
        misfits are converted to a normalized local coherence distribution.
        A good layout concentrates probability at the true target rather than
        at the neighboring samples, suppressing the local migration-arc proxy.
        """
        canonical = tuple(sorted(int(value) for value in sensor_indices))
        cached = _lru_get(self._migration_quality_cache, canonical)
        if cached is not None:
            return cached
        reference_optimizer = self.scenario_optimizers[0]
        selected = [reference_optimizer.kernel_db[index] for index in canonical]
        jacobians = np.stack([
            np.asarray(item['grads'], dtype=float) for item in selected
        ], axis=1)
        precision, _ = reference_optimizer._layout_precision(canonical)
        uses_empirical = self.bootstrap_velocity_covariances is not None
        if uses_empirical:
            selected_velocity_jacobian = self.empirical_target_time_jacobian[
                np.asarray(canonical, dtype=int)
            ]
            time_errors = None
        else:
            selected_velocity_jacobian = None
            time_errors = self._scenario_time_error_tensor(canonical)
        offsets = [np.zeros(self.phys.dims, dtype=float)]
        for dimension, spacing in enumerate(self.phys.spacing):
            displacement = np.zeros(self.phys.dims, dtype=float)
            displacement[dimension] = (
                self.migration_proxy_radius_cells * float(spacing)
            )
            offsets.extend((displacement.copy(), -displacement.copy()))
        offsets = np.asarray(offsets, dtype=float)
        if uses_empirical:
            target_loss_columns = []
            for target_index in range(jacobians.shape[0]):
                predicted_offsets = (
                    jacobians[target_index] @ offsets.T
                ).T
                velocity_sensitivity = selected_velocity_jacobian[
                    :, target_index, :
                ]
                mean_errors = np.einsum(
                    'bk,sk->bs', self.bootstrap_velocity_means,
                    velocity_sensitivity, optimize=True,
                )
                error_covariances = np.einsum(
                    'sk,bkl,rl->bsr', velocity_sensitivity,
                    self.bootstrap_velocity_covariances,
                    velocity_sensitivity, optimize=True,
                )
                covariance_quadratic = np.einsum(
                    'sr,brs->b', precision, error_covariances, optimize=True
                )
                residual_means = (
                    predicted_offsets[None, :, :]
                    - mean_errors[:, None, :]
                )
                expected_quadratic = np.einsum(
                    'bos,sr,bor->bo', residual_means, precision,
                    residual_means,
                    optimize=True,
                ) + covariance_quadratic[:, None]
                logits = -0.5 * expected_quadratic
                shifted = logits - np.max(logits, axis=1, keepdims=True)
                focus_probabilities = np.exp(np.clip(shifted, -700.0, 0.0))
                focus_probabilities /= np.sum(
                    focus_probabilities, axis=1, keepdims=True
                )
                true_focus_loss = 1.0 - focus_probabilities[:, 0]
                neighbor_advantage = (
                    np.max(logits[:, 1:], axis=1) - logits[:, 0]
                )
                sidelobe_ratio = np.exp(np.clip(
                    neighbor_advantage, -60.0, 60.0
                ))
                bounded_sidelobe = sidelobe_ratio / (1.0 + sidelobe_ratio)
                target_loss_columns.append(
                    0.70 * true_focus_loss + 0.30 * bounded_sidelobe
                )
                del mean_errors, error_covariances, covariance_quadratic
                del residual_means, expected_quadratic, logits, shifted
                del focus_probabilities
            target_losses = np.stack(target_loss_columns, axis=1)
            scenario_scores = (
                0.80 * (
                    target_losses @ reference_optimizer.target_weights
                )
                + 0.20 * np.quantile(target_losses, 0.95, axis=1)
            )
            posterior = self._bootstrap_draw_risk(scenario_scores)
            del target_losses, target_loss_columns
        else:
            scenario_scores = []
            for scenario_index in range(time_errors.shape[0]):
                target_losses = []
                for target_index in range(jacobians.shape[0]):
                    residuals = (
                        jacobians[target_index] @ offsets.T
                    ).T - time_errors[scenario_index, target_index][None, :]
                    quadratic = np.einsum(
                        'os,sr,or->o', residuals, precision, residuals
                    )
                    logits = -0.5 * quadratic
                    shifted = logits - float(np.max(logits))
                    probabilities = np.exp(np.clip(shifted, -700.0, 0.0))
                    probabilities /= max(
                        float(np.sum(probabilities)), np.finfo(float).tiny
                    )
                    true_focus_loss = 1.0 - float(probabilities[0])
                    neighbor_advantage = float(
                        np.max(logits[1:]) - logits[0]
                    )
                    sidelobe_ratio = float(np.exp(np.clip(
                        neighbor_advantage, -60.0, 60.0
                    )))
                    bounded_sidelobe = sidelobe_ratio / (1.0 + sidelobe_ratio)
                    target_losses.append(
                        0.70 * true_focus_loss + 0.30 * bounded_sidelobe
                    )
                target_losses = np.asarray(target_losses, dtype=float)
                scenario_scores.append(float(
                    0.80 * np.sum(
                        reference_optimizer.target_weights * target_losses
                    )
                    + 0.20 * _weighted_quantile(
                        target_losses, 0.95, reference_optimizer.target_weights
                    )
                ))
            scenario_scores = np.asarray(scenario_scores, dtype=float)
            posterior = self._posterior_weight_risk(scenario_scores)
        result = {
            'scenario_migration_quality_losses': scenario_scores,
            'expected_migration_quality_loss': posterior['expected'],
            'cvar_migration_quality_loss': posterior['cvar'],
            'posterior_p95_expected_migration_quality_loss': posterior[
                'posterior_expected_p95'
            ],
            'migration_quality_risk': posterior['risk'],
            'migration_velocity_samples_used': int(
                len(self.empirical_velocity_samples)
                if uses_empirical else len(scenario_scores)
            ),
            'migration_bayesian_bootstrap_draws': int(
                len(scenario_scores) if uses_empirical else 0
            ),
            'migration_uses_uncompressed_empirical_samples': bool(
                uses_empirical
            ),
        }
        _lru_put(
            self._migration_quality_cache, canonical, result,
            self._migration_cache_limit,
        )
        return result

    def receiver_certainty_space_risk(self, sensor_indices):
        """Penalize low expectation-minus-variance certainty layouts."""
        indices = np.asarray(sensor_indices, dtype=int)
        values = self.receiver_certainty_scores[indices]
        mean_certainty = float(np.mean(values))
        lower_tail_certainty = float(np.quantile(values, 0.10))
        layout_certainty = float(np.clip(
            0.75 * mean_certainty + 0.25 * lower_tail_certainty,
            0.0, 1.0,
        ))
        return {
            'mean_receiver_certainty': mean_certainty,
            'lower_tail_receiver_certainty': lower_tail_certainty,
            'layout_receiver_certainty': layout_certainty,
            'receiver_certainty_space_risk': 1.0 - layout_certainty,
        }

    def calculate_energy(self, sensor_indices):
        self.energy_evaluations += 1
        losses, mac_values = self.scenario_losses(sensor_indices)
        loss_risk = self._posterior_weight_risk(losses)
        performance_risk = loss_risk['risk']
        regrets = self.scenario_regrets(sensor_indices, losses=losses)
        regret_components = self._posterior_weight_risk(regrets)
        regret_risk = regret_components['risk']
        adaptation_risk = (
            (1.0 - self.regret_weight) * performance_risk
            + self.regret_weight * regret_risk
        )
        confidence_components = self._confidence_geometry_risk(sensor_indices)
        bias_components = self.scenario_velocity_bias_scores(sensor_indices)
        accuracy_and_bias_risk = (
            (1.0 - self.model_bias_weight) * adaptation_risk
            + self.model_bias_weight * bias_components['velocity_bias_risk']
        )
        combined_confidence_risk = (
            (1.0 - self.model_uncertainty_confidence_weight)
            * confidence_components['confidence_geometry_risk']
            + self.model_uncertainty_confidence_weight
            * bias_components['model_aware_confidence_risk']
        )
        uncertainty_adaptation_risk = (
            (1.0 - self.confidence_geometry_weight) * accuracy_and_bias_risk
            + self.confidence_geometry_weight
            * combined_confidence_risk
        )
        joint_fisher = self.joint_location_velocity_fisher_scores(sensor_indices)
        migration_quality = self.migration_quality_scores(sensor_indices)
        former_weight = (
            1.0 - self.joint_fisher_weight - self.migration_quality_weight
        )
        physics_augmented_risk = (
            former_weight * uncertainty_adaptation_risk
            + self.joint_fisher_weight
            * joint_fisher['joint_position_velocity_fisher_risk']
            + self.migration_quality_weight
            * migration_quality['migration_quality_risk']
        )
        certainty_components = self.receiver_certainty_space_risk(
            sensor_indices
        )
        certainty_augmented_risk = (
            (1.0 - self.receiver_certainty_weight) * physics_augmented_risk
            + self.receiver_certainty_weight
            * certainty_components['receiver_certainty_space_risk']
        )
        replacement_fractions = self.layout_replacement_fractions(sensor_indices)
        layout_components = self._posterior_weight_risk(
            replacement_fractions, tail_weight=self.layout_tail_weight
        )
        layout_risk = layout_components['risk']
        robust_loss = (
            (1.0 - self.layout_stability_weight) * certainty_augmented_risk
            + self.layout_stability_weight * layout_risk
        )
        return float(robust_loss), float(np.max(mac_values))

    def energy_components(self, sensor_indices):
        losses, mac_values = self.scenario_losses(sensor_indices)
        loss_risk = self._posterior_weight_risk(losses)
        expected_loss = loss_risk['expected']
        tail_loss = loss_risk['cvar']
        performance_risk = loss_risk['risk']
        regrets = self.scenario_regrets(sensor_indices, losses=losses)
        regret_components = self._posterior_weight_risk(regrets)
        expected_regret = regret_components['expected']
        tail_regret = regret_components['cvar']
        regret_risk = regret_components['risk']
        adaptation_risk = float(
            (1.0 - self.regret_weight) * performance_risk
            + self.regret_weight * regret_risk
        )
        confidence_components = self._confidence_geometry_risk(sensor_indices)
        bias_components = self.scenario_velocity_bias_scores(sensor_indices)
        accuracy_and_bias_risk = float(
            (1.0 - self.model_bias_weight) * adaptation_risk
            + self.model_bias_weight * bias_components['velocity_bias_risk']
        )
        combined_confidence_risk = float(
            (1.0 - self.model_uncertainty_confidence_weight)
            * confidence_components['confidence_geometry_risk']
            + self.model_uncertainty_confidence_weight
            * bias_components['model_aware_confidence_risk']
        )
        uncertainty_adaptation_risk = float(
            (1.0 - self.confidence_geometry_weight) * accuracy_and_bias_risk
            + self.confidence_geometry_weight
            * combined_confidence_risk
        )
        joint_fisher = self.joint_location_velocity_fisher_scores(sensor_indices)
        migration_quality = self.migration_quality_scores(sensor_indices)
        former_weight = float(
            1.0 - self.joint_fisher_weight - self.migration_quality_weight
        )
        physics_augmented_risk = float(
            former_weight * uncertainty_adaptation_risk
            + self.joint_fisher_weight
            * joint_fisher['joint_position_velocity_fisher_risk']
            + self.migration_quality_weight
            * migration_quality['migration_quality_risk']
        )
        certainty_components = self.receiver_certainty_space_risk(
            sensor_indices
        )
        certainty_augmented_risk = float(
            (1.0 - self.receiver_certainty_weight) * physics_augmented_risk
            + self.receiver_certainty_weight
            * certainty_components['receiver_certainty_space_risk']
        )
        replacement_fractions = self.layout_replacement_fractions(sensor_indices)
        layout_components = self._posterior_weight_risk(
            replacement_fractions, tail_weight=self.layout_tail_weight
        )
        expected_replacement = layout_components['expected']
        tail_replacement = layout_components['cvar']
        layout_risk = layout_components['risk']
        return {
            'scenario_losses': losses.copy(),
            'scenario_mac_values': mac_values.copy(),
            'expected_loss': expected_loss,
            'cvar_loss': tail_loss,
            'posterior_p95_expected_loss': loss_risk['posterior_expected_p95'],
            'performance_risk': performance_risk,
            'scenario_regrets': regrets.copy(),
            'expected_regret': expected_regret,
            'cvar_regret': tail_regret,
            'posterior_p95_expected_regret': regret_components[
                'posterior_expected_p95'
            ],
            'regret_risk': regret_risk,
            'adaptation_risk': adaptation_risk,
            **confidence_components,
            **bias_components,
            'accuracy_and_velocity_bias_risk': accuracy_and_bias_risk,
            'combined_picking_and_model_confidence_risk': combined_confidence_risk,
            'uncertainty_adaptation_risk': uncertainty_adaptation_risk,
            **joint_fisher,
            **migration_quality,
            'physics_augmented_risk': physics_augmented_risk,
            **certainty_components,
            'certainty_augmented_physics_risk': certainty_augmented_risk,
            'scenario_replacement_fractions': replacement_fractions.copy(),
            'expected_replacement_fraction': expected_replacement,
            'cvar_replacement_fraction': tail_replacement,
            'posterior_p95_expected_replacement_fraction': layout_components[
                'posterior_expected_p95'
            ],
            'layout_stability_risk': layout_risk,
            'robust_loss': float(
                (1.0 - self.layout_stability_weight)
                * certainty_augmented_risk
                + self.layout_stability_weight * layout_risk
            ),
        }

    # Retain the original search and elbow algorithms without duplicating them.
    run_mcmc = BayesianOptimizer.run_mcmc
    elbow_method = BayesianOptimizer.elbow_method


def _bayesian_velocity_probability_posterior(cases, config):
    """Return Bayesian-bootstrap draws for the unknown velocity distribution.

    Velocity fields are samples from a hierarchical epistemic prior, not a list
    of equally certain deterministic alternatives.  A Dirichlet posterior over
    their probability masses represents finite-ensemble uncertainty.  Its mean
    weights drive Bayesian model averaging, while individual draws propagate
    uncertainty in the model distribution itself into upper credible risk and
    confidence intervals.  No synthetic observation is treated as real data.
    """
    number_of_cases = len(cases)
    if number_of_cases < 1:
        raise ValueError('The Bayesian velocity ensemble cannot be empty.')
    supplied = np.asarray(config.get('velocity_ensemble_weights', ()), dtype=float)
    if supplied.size:
        if supplied.shape != (number_of_cases,):
            raise ValueError(
                'FUTURE_VELOCITY_WEIGHTS must contain one value per generated '
                'velocity field, including the reference member.'
            )
        if np.any(supplied < 0.0) or float(np.sum(supplied)) <= 0.0:
            raise ValueError('FUTURE_VELOCITY_WEIGHTS contains invalid values.')
        prior = supplied / float(np.sum(supplied))
        prior_rule = 'user supplied'
    else:
        reference_indices = [
            index for index, case in enumerate(cases)
            if case['kind'] == 'reference'
        ]
        uncertain_indices = [
            index for index, case in enumerate(cases)
            if case['kind'] != 'reference'
        ]
        reference_mass = float(config.get(
            'velocity_bayesian_reference_prior_mass', 0.05
        ))
        if not 0.0 <= reference_mass < 1.0:
            raise ValueError('FUTURE_BAYESIAN_REFERENCE_PRIOR_MASS must lie in [0, 1).')
        prior = np.zeros(number_of_cases, dtype=float)
        if uncertain_indices:
            if reference_indices:
                prior[reference_indices] = reference_mass / len(reference_indices)
            else:
                reference_mass = 0.0
            # Equal mass is assigned to each uncertainty scale and then divided
            # among that scale's realizations. This prevents a level with more
            # Monte Carlo samples from receiving more prior probability.
            groups = {}
            for index in uncertain_indices:
                case = cases[index]
                group_key = (
                    case['kind'],
                    round(float(case.get('requested_target_rms_fraction',
                                         case.get('magnitude', 0.0))), 8),
                )
                groups.setdefault(group_key, []).append(index)
            group_mass = (1.0 - reference_mass) / len(groups)
            for indices in groups.values():
                prior[indices] = group_mass / len(indices)
        else:
            prior[:] = 1.0 / number_of_cases
        prior /= float(np.sum(prior))
        prior_rule = 'equal mass per uncertainty scale with explicit reference mass'

    draws_count = int(config.get('velocity_bayesian_bootstrap_draws', 256))
    concentration = float(config.get(
        'velocity_bayesian_dirichlet_concentration', 64.0
    ))
    if draws_count < 2:
        raise ValueError('FUTURE_BAYESIAN_BOOTSTRAP_DRAWS must be at least two.')
    if concentration <= 0.0:
        raise ValueError('FUTURE_BAYESIAN_DIRICHLET_CONCENTRATION must be positive.')
    active = np.flatnonzero(prior > 0.0)
    rng = np.random.default_rng(int(config['seed']) + 17117)
    active_draws = rng.dirichlet(concentration * prior[active], size=draws_count)
    draws = np.zeros((draws_count, number_of_cases), dtype=np.float64)
    draws[:, active] = active_draws
    lower = np.quantile(draws, 0.025, axis=0)
    upper = np.quantile(draws, 0.975, axis=0)
    for index, case in enumerate(cases):
        case['prior_probability'] = float(prior[index])
        case['probability'] = float(prior[index])
        case['probability_posterior_mean'] = float(np.mean(draws[:, index]))
        case['probability_posterior_p025'] = float(lower[index])
        case['probability_posterior_p975'] = float(upper[index])
    summary = {
        'method': 'hierarchical prior plus Dirichlet Bayesian bootstrap',
        'prior_rule': prior_rule,
        'draw_count': draws_count,
        'dirichlet_concentration': concentration,
        'reference_prior_mass': float(np.sum([
            prior[index] for index, case in enumerate(cases)
            if case['kind'] == 'reference'
        ])),
        'effective_number_of_models': float(1.0 / np.sum(prior ** 2)),
    }
    return draws, summary


def build_velocity_model_ensemble(reference_phys, config, targets=None):
    """Build a bounded geostatistical ensemble in log-slowness space.

    The ensemble represents unknown *true* media around one available reference
    model. It is not formed by multiplying velocity by an arbitrary residual.
    Each realization combines multiscale correlated slowness structure, an
    uncertain vertical trend, reference-interface sensitivity, and a coherent
    target-zone anomaly. A smooth localization taper makes target uncertainty
    largest while retaining a smaller background error. The nonlinear mapping

        s_m(x) = s_ref(x) exp(delta_log_s,m(x)),  v_m(x) = 1 / s_m(x)

    preserves positive velocity and propagates uncertainty through traveltimes.
    Localization and migration still use the reference model; the ensemble
    members generate possible true arrivals used to quantify model-error bias.
    """
    reference_velocity = np.asarray(reference_phys.V, dtype=np.float32)
    if np.any(~np.isfinite(reference_velocity)) or np.any(reference_velocity <= 0.0):
        raise ValueError('Reference velocity must be finite and strictly positive.')
    reference_log_slowness = np.log(1.0 / reference_velocity)
    cases = [{
        'name': 'reference_residual_0%',
        'kind': 'reference',
        'magnitude': 0.0,
        'velocity': reference_velocity.copy(),
        'fractional_residual': np.zeros_like(
            reference_velocity, dtype=np.float32
        ),
        'uncertainty_parameterization': 'reference log slowness',
        'random_perturbation_sampling': 'none',
    }]
    if config.get('velocity_include_systematic_cases', False):
        for fraction in config['velocity_ensemble_levels']:
            if np.isclose(float(fraction), 0.0):
                continue
            fraction = float(fraction)
            if not -1.0 < fraction:
                raise ValueError('Systematic velocity fractions must exceed -100%.')
            log_slowness_shift = -np.log1p(fraction)
            velocity = np.exp(-(reference_log_slowness + log_slowness_shift))
            residual = velocity / reference_velocity - 1.0
            cases.append({
                'name': f'systematic_{fraction:+.0%}',
                'kind': 'systematic',
                'magnitude': float(abs(fraction)),
                'velocity': np.asarray(velocity, dtype=np.float32),
                'fractional_residual': np.asarray(
                    residual, dtype=np.float32
                ),
                'uncertainty_parameterization': 'uniform log-slowness shift',
                'random_perturbation_sampling': 'systematic log-slowness shift',
            })
    rng = np.random.default_rng(config['seed'] + 17001)
    realization_count = int(config.get('velocity_residual_realizations', 6))
    if realization_count < 1:
        raise ValueError('FUTURE_VELOCITY_RESIDUAL_REALIZATIONS must be positive.')
    correlation_fraction = float(config.get(
        'velocity_residual_correlation_fraction', 0.08
    ))
    if correlation_fraction <= 0.0:
        raise ValueError('Velocity uncertainty correlation fraction must be positive.')
    clip_fraction = float(config.get('velocity_residual_clip_fraction', 0.30))
    if not 0.0 < clip_fraction < 1.0:
        raise ValueError('Velocity uncertainty clipping fraction must lie in (0, 1).')
    target_localized = bool(config.get(
        'velocity_residual_target_localized', targets is not None
    ))
    background_fraction = float(config.get(
        'velocity_residual_background_fraction', 0.08
    ))
    localization_taper = np.ones_like(reference_velocity, dtype=np.float32)
    if target_localized:
        if targets is None:
            raise ValueError(
                'Target-localized velocity residuals require design targets.'
            )
        localization_taper = _target_localization_taper(
            reference_velocity.shape,
            targets,
            config.get('velocity_residual_target_radius_fraction', 0.12),
            background_fraction,
        )
    target_zone_mask = localization_taper >= (
        background_fraction + 0.50 * (1.0 - background_fraction)
        if target_localized else 0.5
    )
    if not np.any(target_zone_mask):
        target_zone_mask = np.ones_like(reference_velocity, dtype=bool)
    background_mask = localization_taper <= (
        background_fraction + 0.10 * (1.0 - background_fraction)
        if target_localized else 1.0
    )

    model_shape = np.asarray(reference_velocity.shape, dtype=float)
    grids = np.meshgrid(
        *[
            np.linspace(-1.0, 1.0, size, dtype=np.float32)
            for size in reference_velocity.shape
        ],
        indexing='ij',
    )
    depth_trend = grids[-1] - float(np.mean(grids[-1]))
    interface_sensitivity = np.gradient(reference_log_slowness, axis=-1)
    interface_sensitivity -= float(np.mean(interface_sensitivity))
    interface_scale = float(np.std(interface_sensitivity))
    if interface_scale > np.finfo(float).tiny:
        interface_sensitivity /= interface_scale

    def standardized(field):
        field = np.asarray(field, dtype=np.float32)
        field = field - float(np.mean(field[target_zone_mask]))
        scale = float(np.std(field[target_zone_mask]))
        if scale <= np.finfo(float).tiny:
            return np.zeros_like(field, dtype=np.float32)
        return np.asarray(field / scale, dtype=np.float32)

    def target_anomaly_field():
        if targets is None:
            return np.zeros_like(reference_velocity, dtype=np.float32)
        result = np.zeros_like(reference_velocity, dtype=np.float32)
        for target in np.asarray(targets, dtype=float):
            radius = np.maximum(
                rng.uniform(0.55, 1.45, size=reference_velocity.ndim)
                * float(config.get('velocity_residual_target_radius_fraction', 0.12))
                * np.maximum(model_shape - 1.0, 1.0),
                1.0,
            )
            distance = np.zeros_like(reference_velocity, dtype=np.float32)
            for dimension, coordinate in enumerate(target):
                grid_index = (grids[dimension] + 1.0) * 0.5 * (
                    reference_velocity.shape[dimension] - 1
                )
                distance += ((grid_index - coordinate) / radius[dimension]) ** 2
            result += rng.normal() * np.exp(-0.5 * distance)
        return standardized(result)

    lower_log_slowness = -np.log1p(clip_fraction)
    upper_log_slowness = -np.log1p(-clip_fraction)
    for rms_fraction in config['velocity_ensemble_spatial_rms']:
        for realization in range(1, realization_count + 1):
            requested_rms = float(rms_fraction)
            sigma_medium = tuple(
                max(0.75, size * correlation_fraction)
                for size in reference_velocity.shape
            )
            sigma_long = tuple(2.5 * value for value in sigma_medium)
            medium = standardized(gaussian_filter(
                rng.normal(size=reference_velocity.shape).astype(np.float32),
                sigma=sigma_medium, mode='reflect',
            ))
            long_scale = standardized(gaussian_filter(
                rng.normal(size=reference_velocity.shape).astype(np.float32),
                sigma=sigma_long, mode='reflect',
            ))
            lateral_sigma = tuple(
                sigma_long[dimension] if dimension < reference_velocity.ndim - 1
                else max(0.75, 0.25 * sigma_medium[dimension])
                for dimension in range(reference_velocity.ndim)
            )
            interface_warp = standardized(
                gaussian_filter(
                    rng.normal(size=reference_velocity.shape).astype(np.float32),
                    sigma=lateral_sigma, mode='reflect',
                ) * interface_sensitivity
            )
            trend = standardized(rng.normal() * depth_trend)
            target_component = target_anomaly_field()
            mixture_weights = rng.dirichlet(np.asarray([2.0, 1.5, 1.5, 2.5]))
            latent = (
                mixture_weights[0] * medium
                + mixture_weights[1] * long_scale
                + mixture_weights[2] * (0.65 * interface_warp + 0.35 * trend)
                + mixture_weights[3] * target_component
            )
            # Bound rare standardized tails before localization; otherwise one
            # extreme background draw can overwhelm the small taper value and
            # make the nominally weak background uncertainty comparable with the
            # target-zone uncertainty.
            latent = np.clip(standardized(latent), -3.0, 3.0)
            latent *= localization_taper

            # Calibrate in the physically relevant velocity-error domain while
            # retaining the nonlinear log-slowness parameterization.
            # Start close to the requested physical scale before applying hard
            # bounds. Clipping an order-one latent field first would saturate the
            # target and background together and destroy the localization taper.
            log_slowness_error = requested_rms * latent
            for _ in range(10):
                log_slowness_error = np.clip(
                    log_slowness_error, lower_log_slowness, upper_log_slowness
                )
                trial_velocity = np.exp(
                    -(reference_log_slowness + log_slowness_error)
                )
                trial_residual = trial_velocity / reference_velocity - 1.0
                realized = float(np.sqrt(np.mean(
                    trial_residual[target_zone_mask] ** 2
                )))
                if requested_rms <= 0.0:
                    log_slowness_error.fill(0.0)
                    break
                if realized > np.finfo(float).tiny:
                    log_slowness_error *= requested_rms / realized
            log_slowness_error = np.clip(
                log_slowness_error, lower_log_slowness, upper_log_slowness
            )
            perturbed_slowness = np.exp(
                reference_log_slowness + log_slowness_error
            )
            velocity = 1.0 / perturbed_slowness
            residual = velocity / reference_velocity - 1.0
            sampling = (
                'multiscale geostatistical log-slowness field with interface '
                'warping, vertical trend, and coherent target anomaly'
            )
            cases.append({
                'name': f'geostatistical_slowness_{rms_fraction:.0%}_{realization:02d}',
                'kind': 'geostatistical_slowness',
                'magnitude': float(np.sqrt(np.mean(residual**2))),
                'requested_target_rms_fraction': requested_rms,
                'velocity': np.asarray(velocity, dtype=np.float32),
                'fractional_residual': np.asarray(residual, dtype=np.float32),
                'random_perturbation_sampling': sampling,
                'uncertainty_parameterization': 'bounded additive log slowness',
                'latent_mixture_weights': [
                    float(value) for value in mixture_weights
                ],
                'correlation_sigma_cells': [
                    float(value) for value in sigma_medium
                ],
            })
    if not cases:
        raise ValueError('The future velocity ensemble cannot be empty.')
    for case in cases:
        case['fractional_residual'] = np.asarray(
            case['fractional_residual'], dtype=np.float32
        )
        residual = np.asarray(case['fractional_residual'], dtype=float)
        case['residual_mean_fraction'] = float(np.mean(residual))
        case['residual_rms_fraction'] = float(np.sqrt(np.mean(residual**2)))
        case['residual_max_abs_fraction'] = float(np.max(np.abs(residual)))
        case['velocity_min_m_per_s'] = float(np.min(case['velocity']))
        case['velocity_mean_m_per_s'] = float(np.mean(case['velocity']))
        case['velocity_max_m_per_s'] = float(np.max(case['velocity']))
        if target_localized:
            case['target_zone_residual_rms_fraction'] = float(np.sqrt(
                np.mean(residual[target_zone_mask] ** 2)
            ))
            case['background_residual_rms_fraction'] = float(np.sqrt(
                np.mean(residual[background_mask] ** 2)
            )) if np.any(background_mask) else np.nan
        else:
            case['target_zone_residual_rms_fraction'] = (
                case['residual_rms_fraction']
            )
            case['background_residual_rms_fraction'] = (
                case['residual_rms_fraction']
            )
        case['target_localized_residual'] = bool(
            target_localized and case['kind'] == 'geostatistical_slowness'
        )
        case.setdefault(
            'random_perturbation_sampling',
            'none' if case['kind'] == 'reference' else 'systematic log-slowness shift',
        )
        case.setdefault('uncertainty_parameterization', 'bounded log slowness')
        case['physics'] = _clone_with_velocity(reference_phys, case['velocity'])
        # Store only one velocity array per member. The case points directly to
        # the float32 physics array; the residual remains float32 for plotting.
        case['velocity'] = case['physics'].V
    probability_draws, probability_summary = (
        _bayesian_velocity_probability_posterior(cases, config)
    )
    cases[0]['_bayesian_probability_draws'] = probability_draws
    cases[0]['_bayesian_probability_summary'] = probability_summary
    return cases


def _compress_velocity_ensemble_quadrature(cases, maximum_models):
    """Compress many velocity fields to weighted medoids before exact FMM.

    The full ensemble determines the Dirichlet posterior and cluster masses.
    A deterministic posterior-weighted farthest-point rule then chooses fields
    in a downsampled residual-feature space. This is a discrete Bayesian
    quadrature approximation: discarded fields transfer all probability-draw
    mass to their nearest medoid instead of disappearing from uncertainty.
    """
    maximum_models = int(maximum_models)
    if maximum_models < 1:
        raise ValueError('The velocity quadrature requires a positive size.')
    number_of_cases = len(cases)
    if number_of_cases <= maximum_models:
        return list(cases), {
            'enabled': False,
            'original_model_count': number_of_cases,
            'quadrature_model_count': number_of_cases,
            'assignment': list(range(number_of_cases)),
        }
    reference_index = next(
        index for index, case in enumerate(cases)
        if case['kind'] == 'reference'
    )
    cell_count = int(np.asarray(cases[0]['fractional_residual']).size)
    sample_count = min(2048, cell_count)
    sample_indices = np.linspace(
        0, cell_count - 1, sample_count, dtype=int
    )
    features = []
    for case in cases:
        residual = np.asarray(
            case['fractional_residual'], dtype=np.float32
        ).ravel()[sample_indices]
        features.append(np.concatenate([
            residual.astype(np.float64, copy=False),
            np.asarray([
                case['target_zone_residual_rms_fraction'],
                case['background_residual_rms_fraction'],
                case['residual_mean_fraction'],
                case['residual_max_abs_fraction'],
            ], dtype=float),
        ]))
    features = np.asarray(features, dtype=float)
    center = features[reference_index]
    scale = np.std(features, axis=0)
    scale = np.where(scale > 1.0e-8, scale, 1.0)
    features = (features - center[None, :]) / scale[None, :]
    probabilities = np.asarray(
        [case['probability'] for case in cases], dtype=float
    )
    probabilities /= float(np.sum(probabilities))
    selected = [int(reference_index)]
    minimum_distance = np.sum(
        (features - features[reference_index][None, :]) ** 2, axis=1
    )
    target_count = min(maximum_models, number_of_cases)
    while len(selected) < target_count:
        score = probabilities * np.maximum(minimum_distance, 0.0)
        score[np.asarray(selected, dtype=int)] = -np.inf
        next_index = int(np.argmax(score))
        if not np.isfinite(score[next_index]) or score[next_index] <= 0.0:
            remaining = [
                index for index in range(number_of_cases)
                if index not in selected
            ]
            next_index = max(
                remaining, key=lambda index: probabilities[index]
            )
        selected.append(next_index)
        distance = np.sum(
            (features - features[next_index][None, :]) ** 2, axis=1
        )
        minimum_distance = np.minimum(minimum_distance, distance)
    medoid_features = features[np.asarray(selected, dtype=int)]
    distances = np.sum(
        (features[:, None, :] - medoid_features[None, :, :]) ** 2,
        axis=2,
    )
    assignment_slots = np.argmin(distances, axis=1)
    original_draws = np.asarray(
        cases[reference_index]['_bayesian_probability_draws'], dtype=float
    )
    compressed_draws = np.zeros(
        (original_draws.shape[0], len(selected)), dtype=np.float32
    )
    compressed_cases = []
    cluster_rows = []
    for slot, medoid_index in enumerate(selected):
        members = np.flatnonzero(assignment_slots == slot)
        mass = float(np.sum(probabilities[members]))
        compressed_draws[:, slot] = np.sum(
            original_draws[:, members], axis=1, dtype=np.float64
        ).astype(np.float32)
        medoid = cases[int(medoid_index)]
        medoid['probability'] = mass
        medoid['quadrature_member_count'] = int(members.size)
        medoid['quadrature_member_names'] = [
            cases[int(index)]['name'] for index in members
        ]
        medoid['quadrature_original_indices'] = [
            int(index) for index in members
        ]
        compressed_cases.append(medoid)
        cluster_rows.append({
            'quadrature_slot': int(slot),
            'medoid_original_index': int(medoid_index),
            'medoid_name': medoid['name'],
            'cluster_probability': mass,
            'cluster_member_count': int(members.size),
        })
    row_sums = np.sum(compressed_draws, axis=1, keepdims=True)
    compressed_draws /= np.maximum(
        row_sums, np.finfo(np.float32).tiny
    )
    for slot, case in enumerate(compressed_cases):
        slot_draws = np.asarray(compressed_draws[:, slot], dtype=float)
        case['probability_posterior_mean'] = float(np.mean(slot_draws))
        case['probability_posterior_p025'] = float(
            np.quantile(slot_draws, 0.025)
        )
        case['probability_posterior_p975'] = float(
            np.quantile(slot_draws, 0.975)
        )
        member_indices = case['quadrature_original_indices']
        case['prior_probability'] = float(np.sum([
            cases[index].get('prior_probability', probabilities[index])
            for index in member_indices
        ]))
    original_summary = dict(
        cases[reference_index]['_bayesian_probability_summary']
    )
    compressed_cases[0]['_bayesian_probability_draws'] = compressed_draws
    compressed_cases[0]['_bayesian_probability_summary'] = {
        **original_summary,
        'quadrature_compression': {
            'original_model_count': number_of_cases,
            'quadrature_model_count': len(compressed_cases),
            'probability_mass_preserved': float(np.sum([
                case['probability'] for case in compressed_cases
            ])),
            'clusters': cluster_rows,
        },
    }
    summary = {
        'enabled': True,
        'method': (
            'posterior-weighted farthest-point medoids in downsampled '
            'fractional-velocity-residual space'
        ),
        'original_model_count': number_of_cases,
        'quadrature_model_count': len(compressed_cases),
        'selected_original_indices': [int(value) for value in selected],
        'assignment': [int(value) for value in assignment_slots],
        'clusters': cluster_rows,
        'original_model_statistics': [
            {
                'original_index': int(index),
                'name': case['name'],
                'kind': case['kind'],
                'probability': float(probabilities[index]),
                'residual_rms_fraction': float(
                    case['residual_rms_fraction']
                ),
                'target_zone_residual_rms_fraction': float(
                    case['target_zone_residual_rms_fraction']
                ),
                'background_residual_rms_fraction': float(
                    case['background_residual_rms_fraction']
                ),
                'assigned_quadrature_slot': int(assignment_slots[index]),
            }
            for index, case in enumerate(cases)
        ],
    }
    del features, medoid_features, distances, original_draws
    gc.collect()
    return compressed_cases, summary


def _future_mcmc_kwargs(config):
    return {
        'iter': config['velocity_ensemble_mcmc_iterations'],
        'greedy_iter': config['velocity_ensemble_greedy_iterations'],
        'backtrack_iter': config['velocity_ensemble_backtrack_iterations'],
    }


def _scaled_future_mcmc_kwargs(config, fraction):
    """Return a smaller, but nonzero, search budget for reference layouts."""
    fraction = float(fraction)
    if fraction <= 0.0:
        raise ValueError(
            'FUTURE_VELOCITY_REFERENCE_SEARCH_FRACTION must be positive.'
        )
    full = _future_mcmc_kwargs(config)
    return {
        key: max(1, int(round(value * fraction)))
        for key, value in full.items()
    }


def _chord_elbow_index(sensor_counts, costs):
    """Return the same maximum-distance elbow used by BayesianOptimizer."""
    sensor_counts = np.asarray(sensor_counts, dtype=float)
    costs = np.asarray(costs, dtype=float)
    if sensor_counts.size != costs.size or sensor_counts.size == 0:
        raise ValueError('sensor_counts and costs must have equal nonzero size.')
    if sensor_counts.size < 3:
        return int(np.argmin(costs))
    first = np.array([sensor_counts[0], costs[0]], dtype=float)
    last = np.array([sensor_counts[-1], costs[-1]], dtype=float)
    line = last - first
    line_norm = max(float(np.linalg.norm(line)), np.finfo(float).tiny)
    distances = []
    for count, cost in zip(sensor_counts, costs):
        offset = first - np.array([count, cost], dtype=float)
        distances.append(abs(line[0] * offset[1] - line[1] * offset[0]) /
                         line_norm)
    if np.ptp(distances) <= np.finfo(float).eps:
        return int(np.argmin(costs))
    return int(np.argmax(distances))


def _pairwise_layout_replacement_statistics(layouts):
    """Summarize array turnover among equal-size scenario-optimal layouts."""
    layouts = [frozenset(int(index) for index in layout) for layout in layouts]
    if not layouts:
        return {'mean_fraction': 0.0, 'maximum_fraction': 0.0}
    layout_size = len(layouts[0])
    if layout_size == 0 or any(len(layout) != layout_size for layout in layouts):
        raise ValueError('Pairwise layout comparison requires equal nonzero sizes.')
    fractions = [
        1.0 - len(layouts[first].intersection(layouts[second])) / layout_size
        for first in range(len(layouts))
        for second in range(first + 1, len(layouts))
    ]
    if not fractions:
        fractions = [0.0]
    return {
        'mean_fraction': float(np.mean(fractions)),
        'maximum_fraction': float(np.max(fractions)),
    }


class _TrueVelocityTargetKernel:
    """Lightweight exact target-to-receiver traveltimes for one true model.

    A conventional scenario optimizer solves one FMM problem per candidate
    receiver. Large ensembles would therefore scale as models times candidates.
    Reciprocity permits one solve per target instead. Reference gradients,
    covariance, and illumination remain fixed because the inverse problem uses
    only the reference velocity; the true model contributes only exact arrival
    times sampled at every feasible receiver.
    """

    def __init__(self, physics, candidates, targets, reference_optimizer):
        self.phys = physics
        self.candidates = list(candidates)
        targets = [tuple(target) for target in targets]
        # Formerly every full-grid field was appended to target_fields before
        # sampling. Marmousi therefore retained N_target full grids at once.
        # The compact matrix below retains only receiver samples and releases
        # each full field immediately.
        sampled_times = np.empty(
            (len(targets), len(self.candidates)), dtype=np.float32
        )
        candidate_coordinates = tuple(
            np.asarray(self.candidates, dtype=int).T
        )
        for target_index, target in enumerate(targets):
            field = _plain_numpy_array(
                physics.compute_traveltime_field(tuple(target)),
                dtype=np.float32,
                name='Bayesian true-model target traveltime',
                expected_ndim=physics.dims,
            )
            sampled_times[target_index] = field[candidate_coordinates]
            del field
        self.kernel_db = {}
        for candidate_index, candidate in enumerate(self.candidates):
            reference_kernel = reference_optimizer.kernel_db[candidate_index]
            self.kernel_db[candidate_index] = {
                'times': sampled_times[:, candidate_index],
                'grads': reference_kernel['grads'],
                'illum': reference_kernel['illum'],
            }
        self.sampled_target_times = sampled_times


class _CompactBayesianTargetKernel:
    """Compact true-arrival kernel generated from latent posterior parameters."""

    def __init__(self, candidates, target_times, reference_optimizer):
        self.candidates = list(candidates)
        target_times = np.asarray(target_times, dtype=np.float32)
        if target_times.shape != (
                len(self.candidates), len(reference_optimizer.targets)):
            raise ValueError('Compact Bayesian target-time matrix is invalid.')
        self.kernel_db = {}
        for candidate_index in range(len(self.candidates)):
            reference_kernel = reference_optimizer.kernel_db[candidate_index]
            self.kernel_db[candidate_index] = {
                'times': target_times[candidate_index],
                'grads': reference_kernel['grads'],
                'illum': reference_kernel['illum'],
            }


def _build_localized_log_slowness_basis(reference_phys, targets, config):
    """Build target-dominant smooth perturbation modes without a field ensemble.

    ``delta log(s)(x)=sum_k B_k(x) theta_k`` is only a finite spatial
    representation; no probability distribution is imposed on ``theta``.
    Random sign fields are smoothed and orthogonalized to give coherent but
    diverse spatial patterns. Their pointwise scale is largest at the targets
    and decreases smoothly to a smaller nonzero background value.
    """
    mode_count = int(config.get('analytic_velocity_mode_count', 4))
    if mode_count < 1:
        raise ValueError('ANALYTIC_VELOCITY_MODE_COUNT must be positive.')
    target_std = float(config.get(
        'analytic_velocity_target_std_fraction', 0.08
    ))
    background_std = float(config.get(
        'analytic_velocity_background_std_fraction', 0.01
    ))
    if not 0.0 <= background_std < target_std < 0.5:
        raise ValueError(
            'Analytic background/target velocity standard deviations are invalid.'
        )
    taper = _target_localization_taper(
        reference_phys.shape,
        targets,
        config.get('velocity_residual_target_radius_fraction', 0.12),
        0.0,
    ).astype(np.float32)
    coordinates = np.meshgrid(*[
        np.linspace(-1.0, 1.0, size, dtype=np.float32)
        for size in reference_phys.shape
    ], indexing='ij')
    raw_modes = [np.ones(reference_phys.shape, dtype=np.float32)]
    raw_modes.extend(np.asarray(axis, dtype=np.float32) for axis in coordinates)
    rng = np.random.default_rng(int(config['seed']) + 36821)
    random_mode_index = 0
    while len(raw_modes) < mode_count:
        # Rademacher sign patterns are a randomized construction mechanism,
        # not an assumed probability law for the unknown velocity. Smoothing
        # produces geological-scale coherent changes instead of pixel noise.
        signs = rng.choice(
            np.asarray([-1.0, 1.0], dtype=np.float32),
            size=reference_phys.shape,
        )
        scale_fraction = 0.055 + 0.025 * (random_mode_index % 4)
        sigma = tuple(max(1.0, scale_fraction * size)
                      for size in reference_phys.shape)
        smooth = gaussian_filter(signs, sigma=sigma, mode='reflect')
        smooth -= np.mean(smooth)
        maximum = max(float(np.max(np.abs(smooth))), np.finfo(float).tiny)
        raw_modes.append(np.asarray(smooth / maximum, dtype=np.float32))
        random_mode_index += 1
        del signs, smooth
    raw = np.stack(raw_modes[:mode_count], axis=0).astype(np.float32)
    target_weight = np.maximum(taper, 1.0e-3)
    # Weighted Gram-Schmidt makes modes represent distinct spatial patterns.
    orthogonal = []
    for raw_mode in raw:
        vector = np.asarray(raw_mode, dtype=np.float32).copy()
        for former in orthogonal:
            numerator = float(np.sum(target_weight * vector * former))
            denominator = max(
                float(np.sum(target_weight * former * former)),
                np.finfo(float).tiny,
            )
            vector -= np.float32(numerator / denominator) * former
        norm_value = np.sqrt(max(
            float(np.sum(target_weight * vector * vector)),
            np.finfo(float).tiny,
        ))
        orthogonal.append(vector / np.float32(norm_value))
    modes = np.stack(orthogonal, axis=0)
    point_norm = np.sqrt(np.sum(modes * modes, axis=0))
    point_norm = np.maximum(point_norm, np.finfo(np.float32).tiny)
    desired_std = (
        background_std + (target_std - background_std) * taper
    ).astype(np.float32)
    basis = modes / point_norm[None, ...] * desired_std[None, ...]
    realized_std = np.sqrt(np.sum(basis * basis, axis=0)).astype(np.float32)
    return basis.astype(np.float32), realized_std, taper


def _sample_traveltimes_at_candidates(physics, sources, candidates, label):
    """Stream full FMM fields and retain only source-by-candidate samples."""
    sources = [tuple(source) for source in sources]
    candidates = [tuple(candidate) for candidate in candidates]
    coordinates = tuple(np.asarray(candidates, dtype=int).T)
    result = np.empty((len(sources), len(candidates)), dtype=np.float32)
    for source_index, source in enumerate(sources):
        field = _plain_numpy_array(
            physics.compute_traveltime_field(source),
            dtype=np.float32,
            name=label,
            expected_ndim=physics.dims,
        )
        result[source_index] = field[coordinates]
        del field
    return result


def _distribution_free_latent_perturbation_samples(config, mode_count):
    """Generate a large empirical perturbation bank without a parametric law.

    Randomized stratification covers every coefficient range. Several bounded
    nonlinear amplitude mechanisms and sparse/dense patterns are interleaved,
    then empirically centered and whitened. Therefore the samples describe an
    admissible uncertainty set; they are not declared Gaussian, uniform,
    Laplace, or any other probability family.
    """
    sample_count = int(config.get(
        'analytic_velocity_posterior_samples', 4096
    ))
    if sample_count < max(32, 4 * mode_count):
        raise ValueError(
            'DISTRIBUTION_FREE_VELOCITY_SAMPLES must be at least '
            'max(32, 4 * mode_count).'
        )
    latent_clip = float(config.get('analytic_velocity_latent_clip', 3.0))
    if latent_clip <= 0.0:
        raise ValueError('ANALYTIC_VELOCITY_LATENT_CLIP must be positive.')
    rng = np.random.default_rng(int(config['seed']) + 37001)
    stratified = np.empty((sample_count, mode_count), dtype=np.float64)
    for mode_index in range(mode_count):
        order = rng.permutation(sample_count)
        stratified[:, mode_index] = (
            order + rng.random(sample_count)
        ) / float(sample_count)
    raw = 2.0 * stratified - 1.0
    sample_ids = np.arange(sample_count)
    square_mask = sample_ids % 4 == 1
    root_mask = sample_ids % 4 == 2
    sparse_mask = sample_ids % 4 == 3
    raw[square_mask] = (
        np.sign(raw[square_mask]) * np.abs(raw[square_mask]) ** 2
    )
    raw[root_mask] = (
        np.sign(raw[root_mask]) * np.sqrt(np.abs(raw[root_mask]))
    )
    if np.any(sparse_mask):
        sparse_rows = raw[sparse_mask]
        dominant = rng.integers(0, mode_count, size=len(sparse_rows))
        sparse_rows *= 0.20
        sparse_rows[np.arange(len(sparse_rows)), dominant] *= 5.0
        raw[sparse_mask] = sparse_rows
    raw *= (0.35 + 0.65 * rng.random((sample_count, 1)))
    raw -= np.mean(raw, axis=0, keepdims=True)
    covariance = raw.T @ raw / float(max(sample_count - 1, 1))
    eigenvalues, eigenvectors = np.linalg.eigh(covariance)
    tolerance = max(float(np.max(eigenvalues)) * 1.0e-10, 1.0e-12)
    inverse_root = eigenvectors @ np.diag(
        1.0 / np.sqrt(np.maximum(eigenvalues, tolerance))
    ) @ eigenvectors.T
    samples = raw @ inverse_root
    samples = np.clip(samples, -latent_clip, latent_clip)
    samples -= np.mean(samples, axis=0, keepdims=True)
    empirical_std = np.std(samples, axis=0, ddof=1)
    samples /= np.maximum(empirical_std, np.finfo(float).tiny)[None, :]
    return np.asarray(samples, dtype=np.float32)


def _bayesian_bootstrap_sample_weights(sample_count, draw_count, seed):
    """Return Rubin Bayesian-bootstrap weights for an empirical sample bank."""
    sample_count = int(sample_count)
    draw_count = int(draw_count)
    if sample_count < 2 or draw_count < 16:
        raise ValueError(
            'Bayesian bootstrap requires at least 2 samples and 16 draws.'
        )
    rng = np.random.default_rng(int(seed) + 37073)
    weights = rng.exponential(
        scale=1.0, size=(draw_count, sample_count)
    ).astype(np.float32)
    weights /= np.sum(weights, axis=1, keepdims=True)
    return weights


def _posterior_latent_design_nodes(samples, maximum_nodes,
                                   bootstrap_sample_weights):
    """Cluster posterior samples to compact positive-weight design nodes."""
    samples = np.asarray(samples, dtype=float)
    maximum_nodes = int(maximum_nodes)
    if maximum_nodes < 3:
        raise ValueError('ANALYTIC_VELOCITY_DESIGN_NODES must be at least 3.')
    maximum_nodes = min(maximum_nodes, samples.shape[0] + 1)
    nodes = [np.zeros(samples.shape[1], dtype=float)]
    minimum_distance = np.sum(samples * samples, axis=1)
    while len(nodes) < maximum_nodes:
        next_index = int(np.argmax(minimum_distance))
        nodes.append(samples[next_index].copy())
        distance = np.sum(
            (samples - samples[next_index][None, :]) ** 2, axis=1
        )
        minimum_distance = np.minimum(minimum_distance, distance)
    nodes = np.asarray(nodes, dtype=float)
    for _ in range(12):
        distances = np.sum(
            (samples[:, None, :] - nodes[None, :, :]) ** 2, axis=2
        )
        assignments = np.argmin(distances, axis=1)
        updated = nodes.copy()
        updated[0] = 0.0
        for node_index in range(1, len(nodes)):
            members = samples[assignments == node_index]
            if members.size:
                updated[node_index] = np.mean(members, axis=0)
        if np.max(np.abs(updated - nodes)) < 1.0e-6:
            nodes = updated
            break
        nodes = updated
    distances = np.sum(
        (samples[:, None, :] - nodes[None, :, :]) ** 2, axis=2
    )
    assignments = np.argmin(distances, axis=1)
    counts = np.bincount(assignments, minlength=len(nodes)).astype(float)
    weights = counts / np.sum(counts)
    bootstrap_sample_weights = np.asarray(
        bootstrap_sample_weights, dtype=np.float32
    )
    if bootstrap_sample_weights.ndim != 2 or (
            bootstrap_sample_weights.shape[1] != len(samples)):
        raise ValueError('Bayesian-bootstrap weights do not match samples.')
    probability_draws = np.empty(
        (bootstrap_sample_weights.shape[0], len(nodes)), dtype=np.float32
    )
    for node_index in range(len(nodes)):
        probability_draws[:, node_index] = np.sum(
            bootstrap_sample_weights[:, assignments == node_index], axis=1
        )
    probability_draws /= np.sum(
        probability_draws, axis=1, keepdims=True
    )
    weights = np.mean(probability_draws, axis=0, dtype=np.float64)
    weights /= np.sum(weights)
    return nodes.astype(np.float32), weights, probability_draws, assignments


def _prepare_analytic_bayesian_velocity_model(
        reference_phys, candidates, targets, true_sources, noise_model, config,
        model_bias_weight=0.70):
    """Propagate a distribution-free empirical velocity uncertainty set."""
    reference_optimizer = BayesianOptimizer(
        reference_phys, candidates, targets, noise_model=noise_model
    )
    common_candidates = list(reference_optimizer.candidates)
    if len(common_candidates) < reference_phys.dims + 2:
        raise ValueError(
            'Too few feasible sites for distribution-free Bayesian design.'
        )
    basis, prior_std_fraction, target_taper = (
        _build_localized_log_slowness_basis(reference_phys, targets, config)
    )
    mode_count = basis.shape[0]
    combined_sources = [tuple(value) for value in targets] + [
        tuple(value) for value in true_sources
    ]
    reference_samples = _sample_traveltimes_at_candidates(
        reference_phys, combined_sources, common_candidates,
        'analytic reference source-to-candidate traveltime',
    )
    time_jacobian = np.empty(
        (len(combined_sources), len(common_candidates), mode_count),
        dtype=np.float32,
    )
    step = float(config.get('analytic_velocity_finite_difference_step', 0.50))
    if not 0.0 < step <= 1.0:
        raise ValueError('ANALYTIC_VELOCITY_FD_STEP must lie in (0, 1].')
    reference_log_slowness = np.log(
        1.0 / np.asarray(reference_phys.V, dtype=np.float32)
    )
    solve_count_before = int(reference_phys.traveltime_solve_count)
    for mode_index in range(mode_count):
        perturbation = np.clip(
            step * basis[mode_index], -0.35, 0.35
        )
        plus_velocity = np.exp(
            -(reference_log_slowness + perturbation)
        ).astype(np.float32)
        minus_velocity = np.exp(
            -(reference_log_slowness - perturbation)
        ).astype(np.float32)
        plus_physics = _clone_with_velocity(reference_phys, plus_velocity)
        minus_physics = _clone_with_velocity(reference_phys, minus_velocity)
        plus_times = _sample_traveltimes_at_candidates(
            plus_physics, combined_sources, common_candidates,
            f'analytic velocity-mode {mode_index + 1} positive probe',
        )
        minus_times = _sample_traveltimes_at_candidates(
            minus_physics, combined_sources, common_candidates,
            f'analytic velocity-mode {mode_index + 1} negative probe',
        )
        time_jacobian[:, :, mode_index] = (
            plus_times - minus_times
        ) / np.float32(2.0 * step)
        del (
            plus_times, minus_times, plus_physics, minus_physics,
            plus_velocity, minus_velocity, perturbation,
        )
        gc.collect()
    all_empirical_samples = _distribution_free_latent_perturbation_samples(
        config, mode_count
    )
    validation_fraction = float(config.get(
        'distribution_free_validation_fraction', 0.20
    ))
    validation_maximum = int(config.get(
        'distribution_free_validation_max_samples', 128
    ))
    if not 0.0 < validation_fraction < 0.5 or validation_maximum < 16:
        raise ValueError(
            'Distribution-free validation fraction must lie in (0, 0.5) and '
            'the maximum validation sample count must be at least 16.'
        )
    validation_count = min(
        validation_maximum,
        max(16, int(round(validation_fraction * len(all_empirical_samples)))),
    )
    if len(all_empirical_samples) - validation_count < max(32, 4 * mode_count):
        raise ValueError('Too few design perturbations remain after holdout splitting.')
    split_rng = np.random.default_rng(int(config['seed']) + 37057)
    permutation = split_rng.permutation(len(all_empirical_samples))
    validation_indices = permutation[:validation_count]
    design_indices = permutation[validation_count:]
    posterior_samples = np.asarray(
        all_empirical_samples[design_indices], dtype=np.float32
    )
    validation_samples = np.asarray(
        all_empirical_samples[validation_indices], dtype=np.float32
    )
    del all_empirical_samples
    bootstrap_sample_weights = _bayesian_bootstrap_sample_weights(
        len(posterior_samples),
        config.get('distribution_free_bayesian_bootstrap_draws', 256),
        config['seed'],
    )
    nodes, probabilities, probability_draws, assignments = (
        _posterior_latent_design_nodes(
            posterior_samples,
            config.get('analytic_velocity_design_nodes', 17),
            bootstrap_sample_weights,
        )
    )
    target_count = len(targets)
    reference_target_times = reference_samples[:target_count].T
    reference_source_times = reference_samples[target_count:]
    target_time_jacobian = np.transpose(
        time_jacobian[:target_count], (1, 0, 2)
    )
    source_time_jacobian = time_jacobian[target_count:]
    scenario_optimizers = []
    cases = []
    for node_index, (node, probability) in enumerate(zip(nodes, probabilities)):
        target_times = reference_target_times + np.einsum(
            'ctk,k->ct', target_time_jacobian, node, optimize=True
        )
        true_kernel = _CompactBayesianTargetKernel(
            common_candidates, target_times, reference_optimizer
        )
        scenario_optimizer = FixedReferenceVelocityScenarioOptimizer(
            reference_optimizer, true_kernel, model_bias_weight
        )
        scenario_optimizers.append(scenario_optimizer)
        delta_log_slowness = np.einsum(
            'k,k...->...', node, basis, optimize=True
        )
        fractional_residual = (
            np.exp(-delta_log_slowness) - 1.0
        ).astype(np.float32)
        visualization_velocity = np.asarray(
            np.asarray(reference_phys.V, dtype=np.float32)
            * (1.0 + fractional_residual), dtype=np.float32
        )
        source_times = reference_source_times + np.einsum(
            'sck,k->sc', source_time_jacobian, node, optimize=True
        )
        case = {
            'name': (
                'reference_latent_mean' if node_index == 0
                else f'bayesian_velocity_node_{node_index:02d}'
            ),
            'kind': 'reference' if node_index == 0 else 'bayesian_latent_node',
            'magnitude': float(np.sqrt(np.mean(
                np.asarray(fractional_residual, dtype=np.float32) ** 2
            ))),
            'probability': float(probability),
            'prior_probability': float(probability),
            'latent_velocity_parameters': [float(value) for value in node],
            # All cases reference one covariance basis. Full velocity/residual
            # volumes are reconstructed one at a time only for plotting/audits.
            '_shared_log_slowness_basis': basis,
            'physics': reference_phys,
            'uncertainty_parameterization': (
                'distribution-free empirical low-rank target-localized log slowness'
            ),
            'random_perturbation_sampling': (
                'randomized stratified empirical perturbations; compact node only'
            ),
            '_true_source_candidate_times': np.asarray(
                source_times, dtype=np.float32
            ),
            '_true_source_candidate_key': tuple(
                tuple(value) for value in common_candidates
            ),
        }
        residual_float = np.asarray(fractional_residual, dtype=np.float32)
        target_mask = target_taper >= 0.5
        background_mask = target_taper <= 0.1
        case.update({
            'residual_mean_fraction': float(np.mean(residual_float)),
            'residual_rms_fraction': float(np.sqrt(np.mean(residual_float**2))),
            'residual_max_abs_fraction': float(np.max(np.abs(residual_float))),
            'target_zone_residual_rms_fraction': float(np.sqrt(np.mean(
                residual_float[target_mask] ** 2
            ))),
            'background_residual_rms_fraction': float(np.sqrt(np.mean(
                residual_float[background_mask] ** 2
            ))) if np.any(background_mask) else 0.0,
            'target_localized_residual': bool(node_index != 0),
            'velocity_min_m_per_s': float(np.min(visualization_velocity)),
            'velocity_mean_m_per_s': float(np.mean(visualization_velocity)),
            'velocity_max_m_per_s': float(np.max(visualization_velocity)),
        })
        cases.append(case)
        del delta_log_slowness, fractional_residual, residual_float
        del visualization_velocity, source_times, target_times, true_kernel
    for node_index, case in enumerate(cases):
        node_draws = np.asarray(probability_draws[:, node_index], dtype=float)
        case['probability_posterior_mean'] = float(np.mean(node_draws))
        case['probability_posterior_p025'] = float(np.quantile(node_draws, 0.025))
        case['probability_posterior_p975'] = float(np.quantile(node_draws, 0.975))
    cases[0]['_bayesian_probability_draws'] = probability_draws
    cases[0]['_bayesian_probability_summary'] = {
        'method': (
            'distribution-free empirical velocity perturbations; Rubin '
            'Bayesian bootstrap propagates probability uncertainty and compact '
            'positive-weight nodes evaluate the nonlinear design objective'
        ),
        'latent_mode_count': int(mode_count),
        'posterior_sample_count': int(len(posterior_samples)),
        'independent_empirical_holdout_sample_count': int(
            len(validation_samples)
        ),
        'total_empirical_perturbation_count': int(
            len(posterior_samples) + len(validation_samples)
        ),
        'compact_design_node_count': int(len(nodes)),
        'large_velocity_ensemble_stored': False,
        'assumed_parametric_velocity_distribution': None,
        'bayesian_bootstrap_draw_count': int(len(bootstrap_sample_weights)),
    }
    state = {
        'basis': basis,
        'prior_std_fraction': prior_std_fraction,
        'target_taper': target_taper,
        'posterior_samples': posterior_samples,
        'empirical_holdout_samples': validation_samples,
        'empirical_design_sample_indices': np.asarray(
            design_indices, dtype=np.int32
        ),
        'empirical_holdout_sample_indices': np.asarray(
            validation_indices, dtype=np.int32
        ),
        'bayesian_bootstrap_sample_weights': bootstrap_sample_weights,
        'nodes': nodes,
        'node_assignments': assignments,
        'probabilities': np.asarray(probabilities, dtype=float),
        'probability_draws': probability_draws,
        'target_time_jacobian': target_time_jacobian,
        'source_time_jacobian': source_time_jacobian,
        'reference_target_times': reference_target_times,
        'reference_source_times': reference_source_times,
        'streamed_sensitivity_probe_count': int(2 * mode_count),
        'streamed_probe_fmm_solves': int(
            2 * mode_count * len(combined_sources)
        ),
        'reference_fmm_solves_during_sensitivity': int(
            reference_phys.traveltime_solve_count - solve_count_before
        ),
    }
    return scenario_optimizers, common_candidates, cases, state


def _save_analytic_bayesian_velocity_state(
        reference_phys, targets, state, output_dir):
    """Persist the empirical Bayesian uncertainty state and spatial scale."""
    os.makedirs(output_dir, exist_ok=True)
    array_path = os.path.join(
        output_dir, 'distribution_free_bayesian_velocity_state.mat'
    )
    savemat(array_path, {
        'log_slowness_covariance_modes': np.asarray(
            state['basis'], dtype=np.float32
        ),
        'pointwise_empirical_scale_fraction': np.asarray(
            state['prior_std_fraction'], dtype=np.float32
        ),
        'target_localization_taper': np.asarray(
            state['target_taper'], dtype=np.float32
        ),
        'empirical_perturbation_coefficients': np.asarray(
            state['posterior_samples'], dtype=np.float32
        ),
        'independent_holdout_perturbation_coefficients': np.asarray(
            state['empirical_holdout_samples'], dtype=np.float32
        ),
        'bayesian_bootstrap_sample_weights': np.asarray(
            state['bayesian_bootstrap_sample_weights'], dtype=np.float32
        ),
        'compact_latent_nodes': np.asarray(state['nodes'], dtype=np.float32),
        'compact_node_probabilities': np.asarray(
            state['probabilities'], dtype=np.float64
        ),
        'target_traveltime_jacobian_seconds': np.asarray(
            state['target_time_jacobian'], dtype=np.float32
        ),
        'source_traveltime_jacobian_seconds': np.asarray(
            state['source_time_jacobian'], dtype=np.float32
        ),
        'reference_velocity_m_per_s': np.asarray(
            reference_phys.V, dtype=np.float32
        ),
    }, do_compression=True)
    node_rows = []
    assignments = np.asarray(state['node_assignments'], dtype=int)
    for node_index, (node, probability) in enumerate(zip(
            state['nodes'], state['probabilities'])):
        row = {
            'node_index': int(node_index),
            'posterior_probability': float(probability),
            'assigned_parameter_draw_count': int(np.count_nonzero(
                assignments == node_index
            )),
            'is_reference_mean': int(node_index == 0),
        }
        row.update({
            f'latent_parameter_{mode_index + 1}': float(value)
            for mode_index, value in enumerate(node)
        })
        node_rows.append(row)
    node_table = os.path.join(
        output_dir, 'distribution_free_bayesian_compact_nodes.csv'
    )
    _write_csv(node_table, node_rows)

    velocity = np.asarray(reference_phys.V, dtype=float)
    prior_std = np.asarray(state['prior_std_fraction'], dtype=float)
    taper = np.asarray(state['target_taper'], dtype=float)
    targets = np.asarray(targets, dtype=float)
    if reference_phys.dims == 2:
        velocity_view = velocity.T
        uncertainty_view = (100.0 * prior_std).T
        taper_view = taper.T
        extent = [
            0.0, (reference_phys.shape[0] - 1) * reference_phys.spacing[0],
            (reference_phys.shape[1] - 1) * reference_phys.spacing[1], 0.0,
        ]
        target_x = targets[:, 0] * reference_phys.spacing[0]
        target_z = targets[:, 1] * reference_phys.spacing[1]
        slice_note = ''
    else:
        middle = int(reference_phys.shape[1] // 2)
        velocity_view = velocity[:, middle, :].T
        uncertainty_view = (100.0 * prior_std[:, middle, :]).T
        taper_view = taper[:, middle, :].T
        extent = [
            0.0, (reference_phys.shape[0] - 1) * reference_phys.spacing[0],
            (reference_phys.shape[2] - 1) * reference_phys.spacing[2], 0.0,
        ]
        target_x = targets[:, 0] * reference_phys.spacing[0]
        target_z = targets[:, 2] * reference_phys.spacing[2]
        slice_note = f' (central y slice {middle})'
    figure, axes = plt.subplots(
        1, 3, figsize=(16.5, 5.2), constrained_layout=True
    )
    panels = (
        (velocity_view, 'Reference velocity (m/s)',
         '(a) Fixed inverse/migration model'),
        (uncertainty_view, 'Empirical perturbation scale (%)',
         '(b) Distribution-free velocity uncertainty'),
        (taper_view, 'Target localization taper',
         '(c) Target-dominant perturbation support'),
    )
    for axis, (values, color_label, title) in zip(axes, panels):
        artist = axis.imshow(
            values, cmap='rainbow', origin='upper', extent=extent,
            aspect='auto', interpolation='nearest',
        )
        axis.scatter(
            target_x, target_z, marker='*', s=80, c='white',
            edgecolors='black', linewidths=0.7, zorder=3,
        )
        axis.set_xlabel('X (m)')
        axis.set_ylabel('Depth (m)')
        axis.set_title(title)
        figure.colorbar(artist, ax=axis, pad=0.02).set_label(color_label)
        _apply_complete_layout_padding(
            axis, reference_phys, np.column_stack((target_x, target_z))
        )
    figure.suptitle(
        'Distribution-free empirical Bayesian velocity uncertainty'
        + slice_note, fontsize=14
    )
    figure_path = os.path.join(
        output_dir, 'Figure_Distribution_Free_Bayesian_Velocity_Uncertainty.png'
    )
    figure.savefig(figure_path, dpi=300, bbox_inches='tight', pad_inches=0.15)
    plt.close(figure)
    return {
        'matlab_state': array_path,
        'compact_node_table': node_table,
        'prior_figure': figure_path,
    }


def _prepare_velocity_ensemble_optimizers(cases, candidates, targets,
                                           noise_model,
                                           model_bias_weight=0.70):
    """Prepare scalable fixed-reference inversions for a large true ensemble."""
    reference_index = next(
        (index for index, case in enumerate(cases) if case['kind'] == 'reference'),
        None,
    )
    if reference_index is None:
        raise ValueError('The velocity ensemble requires one reference member.')
    reference_optimizer = BayesianOptimizer(
        cases[reference_index]['physics'], candidates, targets,
        noise_model=noise_model,
    )
    common_candidates = list(reference_optimizer.candidates)
    minimum_sites = reference_optimizer.phys.dims + 2
    if len(common_candidates) < minimum_sites:
        raise ValueError('Too few feasible receiver sites in the reference model.')
    true_kernels = []
    for index, case in enumerate(cases):
        if index == reference_index:
            true_kernels.append(reference_optimizer)
        else:
            true_kernels.append(_TrueVelocityTargetKernel(
                case['physics'], common_candidates, targets, reference_optimizer
            ))
    scenario_optimizers = [
        FixedReferenceVelocityScenarioOptimizer(
            reference_optimizer, true_kernel, model_bias_weight
        )
        for true_kernel in true_kernels
    ]
    return scenario_optimizers, common_candidates


def _bayesian_receiver_certainty_space(
        scenario_optimizers, probabilities, probability_draws, config):
    """Infer the maximum-certainty feasible receiver distribution.

    For candidate c and target t, all possible true models provide the
    differential residual e_mct=T_mct-T_ref,ct after removing its candidate-
    common component (unknown origin time). For each posterior probability draw
    q, its second moment enters the denominator of reference-gradient location
    information and a Gaussian migration-coherence term. Their geometric mean
    is evaluated for every site; a lower credible bound defines the spatial
    certainty support.
    """
    if not scenario_optimizers:
        raise ValueError('Receiver certainty requires velocity scenarios.')
    reference_optimizer = scenario_optimizers[0]
    number_models = len(scenario_optimizers)
    number_candidates = len(reference_optimizer.candidates)
    number_targets = len(reference_optimizer.targets)
    true_times = np.empty(
        (number_models, number_candidates, number_targets), dtype=np.float32
    )
    for model_index, optimizer in enumerate(scenario_optimizers):
        database = getattr(optimizer, 'true_kernel_db', optimizer.kernel_db)
        for candidate_index in range(number_candidates):
            true_times[model_index, candidate_index] = np.asarray(
                database[candidate_index]['times'], dtype=np.float32
            )
    reference_times = true_times[0]
    errors = true_times - reference_times[None, :, :]
    # Project out the candidate-common time component separately for every
    # model and target, matching the differential-time inverse problem.
    errors -= np.mean(errors, axis=1, keepdims=True)
    gradients = np.stack([
        np.asarray(
            reference_optimizer.kernel_db[index]['grads'], dtype=np.float32
        )
        for index in range(number_candidates)
    ], axis=0)
    gradient_energy = np.sum(gradients * gradients, axis=2)
    target_weights = np.asarray(
        reference_optimizer.target_weights, dtype=np.float64
    )
    probabilities = np.asarray(probabilities, dtype=float)
    probabilities /= float(np.sum(probabilities))
    draws = np.asarray(probability_draws, dtype=float)
    if draws.ndim != 2 or draws.shape[1] != number_models:
        raise ValueError('Certainty posterior draws do not match velocity models.')
    draws = np.vstack([probabilities[None, :], draws])
    migration_scale = float(config.get(
        'receiver_certainty_migration_time_scale_s', 0.008
    ))
    if migration_scale <= 0.0:
        raise ValueError('Receiver certainty migration time scale must be positive.')
    picking_variance = max(
        float(reference_optimizer.picking_noise_std) ** 2,
        np.finfo(float).tiny,
    )
    certainty_draws = np.empty(
        (draws.shape[0], number_candidates), dtype=np.float32
    )
    information_draws = np.empty_like(certainty_draws)
    coherence_draws = np.empty_like(certainty_draws)
    squared_errors = np.asarray(errors * errors, dtype=np.float32)
    for draw_index, draw in enumerate(draws):
        draw = np.asarray(draw, dtype=float)
        draw /= max(float(np.sum(draw)), np.finfo(float).tiny)
        second_moment = np.einsum(
            'm,mct->ct', draw, squared_errors, optimize=True
        )
        raw_information = np.sum(
            target_weights[None, :]
            * gradient_energy
            / (picking_variance + second_moment),
            axis=1,
        )
        information_scale = max(
            float(np.quantile(raw_information, 0.95)),
            np.finfo(float).tiny,
        )
        information = np.clip(raw_information / information_scale, 0.0, 1.0)
        coherence = np.sum(
            target_weights[None, :]
            * np.exp(-0.5 * second_moment / migration_scale**2),
            axis=1,
        )
        certainty = np.sqrt(
            np.clip(information, 0.0, 1.0)
            * np.clip(coherence, 0.0, 1.0)
        )
        information_draws[draw_index] = information
        coherence_draws[draw_index] = coherence
        certainty_draws[draw_index] = certainty
    posterior_mean = np.mean(certainty_draws, axis=0)
    posterior_p05 = np.quantile(certainty_draws, 0.05, axis=0)
    posterior_p95 = np.quantile(certainty_draws, 0.95, axis=0)
    tail_weight = float(config.get(
        'receiver_certainty_lower_tail_weight', 0.70
    ))
    if not 0.0 <= tail_weight <= 1.0:
        raise ValueError('Receiver certainty tail weight must lie in [0, 1].')
    score = np.clip(
        (1.0 - tail_weight) * posterior_mean
        + tail_weight * posterior_p05,
        0.0, 1.0,
    )
    quantile = float(config.get('receiver_certainty_space_quantile', 0.55))
    if not 0.0 <= quantile < 1.0:
        raise ValueError('Receiver certainty quantile must lie in [0, 1).')
    threshold = float(np.quantile(score, quantile))
    eligible = np.flatnonzero(score >= threshold)
    minimum_count = min(
        number_candidates,
        max(
            reference_optimizer.phys.dims + 2,
            int(config.get('velocity_ensemble_max_k', 14))
            + int(config.get('receiver_certainty_minimum_margin', 8)),
        ),
    )
    if eligible.size < minimum_count:
        eligible = np.argsort(-score)[:minimum_count]
        threshold = float(np.min(score[eligible]))
    eligible = np.sort(np.asarray(eligible, dtype=int))
    eligible_set = set(int(value) for value in eligible)
    rows = []
    for candidate_index, candidate in enumerate(reference_optimizer.candidates):
        rows.append({
            'candidate_index_before_certainty_filter': int(candidate_index),
            'grid_coordinates': [int(value) for value in candidate],
            'posterior_mean_location_migration_certainty': float(
                posterior_mean[candidate_index]
            ),
            'posterior_p05_location_migration_certainty': float(
                posterior_p05[candidate_index]
            ),
            'posterior_p95_location_migration_certainty': float(
                posterior_p95[candidate_index]
            ),
            'posterior_mean_location_information': float(np.mean(
                information_draws[:, candidate_index]
            )),
            'posterior_mean_migration_coherence': float(np.mean(
                coherence_draws[:, candidate_index]
            )),
            'certainty_objective_score': float(score[candidate_index]),
            'certainty_threshold': threshold,
            'inside_maximum_certainty_space': int(
                candidate_index in eligible_set
            ),
        })
    result = {
        'scores': score.astype(np.float32),
        'posterior_mean': posterior_mean.astype(np.float32),
        'posterior_p05': posterior_p05.astype(np.float32),
        'posterior_p95': posterior_p95.astype(np.float32),
        'eligible_indices': eligible,
        'threshold': threshold,
        'rows': rows,
        'formula': (
            'C_c(q)=sqrt(normalized sum_t w_t ||grad T_ref||^2/'
            '(sigma_pick^2+E_q[e_mct^2]) * sum_t w_t exp(-E_q[e_mct^2]/'
            '(2 tau_mig^2))); score=(1-w_tail)E_q[C]+w_tail Q0.05_q[C]'
        ),
    }
    del true_times, errors, gradients, squared_errors
    return result


def _analytic_posterior_receiver_certainty_space(
        reference_optimizer, target_time_jacobian, posterior_samples, config,
        bootstrap_sample_weights=None):
    """Infer deployment certainty by empirical Bayesian expectation/variance."""
    target_time_jacobian = np.asarray(target_time_jacobian, dtype=np.float32)
    posterior_samples = np.asarray(posterior_samples, dtype=np.float32)
    candidate_count, target_count, mode_count = target_time_jacobian.shape
    if posterior_samples.ndim != 2 or posterior_samples.shape[1] != mode_count:
        raise ValueError('Analytic posterior samples and Jacobian do not match.')
    gradients = np.stack([
        np.asarray(reference_optimizer.kernel_db[index]['grads'], dtype=np.float32)
        for index in range(candidate_count)
    ], axis=0)
    gradient_energy = np.sum(gradients * gradients, axis=2)
    target_weights = np.asarray(reference_optimizer.target_weights, dtype=float)
    migration_scale = float(config.get(
        'receiver_certainty_migration_time_scale_s', 0.008
    ))
    picking_variance = max(
        float(reference_optimizer.picking_noise_std) ** 2,
        np.finfo(float).tiny,
    )
    certainty_samples = np.empty(
        (len(posterior_samples), candidate_count), dtype=np.float32
    )
    information_samples = np.empty_like(certainty_samples)
    coherence_samples = np.empty_like(certainty_samples)
    time_sum = np.zeros((candidate_count, target_count), dtype=np.float64)
    time_square_sum = np.zeros_like(time_sum)
    batch_size = int(config.get(
        'distribution_free_certainty_batch_size', 128
    ))
    if batch_size < 1:
        raise ValueError('DISTRIBUTION_FREE_CERTAINTY_BATCH_SIZE must be positive.')
    for start in range(0, len(posterior_samples), batch_size):
        stop = min(start + batch_size, len(posterior_samples))
        parameters = posterior_samples[start:stop]
        errors = np.einsum(
            'ctk,bk->bct', target_time_jacobian, parameters, optimize=True
        )
        errors -= np.mean(errors, axis=1, keepdims=True)
        time_sum += np.sum(errors, axis=0, dtype=np.float64)
        time_square_sum += np.sum(errors * errors, axis=0, dtype=np.float64)
        second_moment = errors * errors
        raw_information = np.sum(
            target_weights[None, None, :] * gradient_energy[None, :, :]
            / (picking_variance + second_moment), axis=2
        )
        scale = np.maximum(
            np.quantile(raw_information, 0.95, axis=1),
            np.finfo(float).tiny,
        )
        information = np.clip(
            raw_information / scale[:, None], 0.0, 1.0
        )
        coherence = np.sum(
            target_weights[None, None, :]
            * np.exp(-0.5 * second_moment / migration_scale**2), axis=2
        )
        certainty_samples[start:stop] = np.sqrt(
            information * np.clip(coherence, 0.0, 1.0)
        )
        information_samples[start:stop] = information
        coherence_samples[start:stop] = coherence
        del errors, second_moment, raw_information, information, coherence
    if bootstrap_sample_weights is None:
        bootstrap_sample_weights = _bayesian_bootstrap_sample_weights(
            len(posterior_samples),
            config.get('distribution_free_bayesian_bootstrap_draws', 256),
            config['seed'],
        )
    bootstrap_sample_weights = np.asarray(
        bootstrap_sample_weights, dtype=np.float32
    )
    if bootstrap_sample_weights.ndim != 2 or (
            bootstrap_sample_weights.shape[1] != len(posterior_samples)):
        raise ValueError(
            'Bayesian-bootstrap weights do not match empirical perturbations.'
        )
    bootstrap_mean = bootstrap_sample_weights @ certainty_samples
    bootstrap_second = bootstrap_sample_weights @ (
        certainty_samples * certainty_samples
    )
    bootstrap_variance = np.maximum(
        bootstrap_second - bootstrap_mean * bootstrap_mean, 0.0
    )
    variance_weight = float(config.get(
        'distribution_free_certainty_variance_weight', 1.0
    ))
    if variance_weight < 0.0:
        raise ValueError(
            'DISTRIBUTION_FREE_CERTAINTY_VARIANCE_WEIGHT cannot be negative.'
        )
    utility_draws = np.clip(
        bootstrap_mean - variance_weight * np.sqrt(bootstrap_variance),
        0.0, 1.0,
    )
    expected_certainty = np.mean(bootstrap_mean, axis=0)
    expected_variance = np.mean(bootstrap_variance, axis=0)
    p05_score = np.quantile(bootstrap_mean, 0.05, axis=0)
    p95_score = np.quantile(bootstrap_mean, 0.95, axis=0)
    expected_utility = np.mean(utility_draws, axis=0)
    p05_utility = np.quantile(utility_draws, 0.05, axis=0)
    tail_weight = float(config.get(
        'receiver_certainty_lower_tail_weight', 0.70
    ))
    score = np.clip(
        (1.0 - tail_weight) * expected_utility + tail_weight * p05_utility,
        0.0, 1.0,
    )
    quantile = float(config.get('receiver_certainty_space_quantile', 0.55))
    threshold = float(np.quantile(score, quantile))
    eligible = np.flatnonzero(score >= threshold)
    minimum_count = min(
        candidate_count,
        max(
            reference_optimizer.phys.dims + 2,
            int(config.get('velocity_ensemble_max_k', 14))
            + int(config.get('receiver_certainty_minimum_margin', 8)),
        ),
    )
    if eligible.size < minimum_count:
        eligible = np.argsort(-score)[:minimum_count]
        threshold = float(np.min(score[eligible]))
    eligible = np.sort(eligible.astype(int))
    eligible_set = set(int(value) for value in eligible)
    time_mean = time_sum / float(len(posterior_samples))
    time_standard_deviation = np.sqrt(np.maximum(
        time_square_sum / float(len(posterior_samples)) - time_mean * time_mean,
        0.0,
    ))
    rows = []
    for candidate_index, candidate in enumerate(reference_optimizer.candidates):
        rows.append({
            'candidate_index_before_certainty_filter': int(candidate_index),
            'grid_coordinates': [int(value) for value in candidate],
            'posterior_mean_location_migration_certainty': float(
                expected_certainty[candidate_index]
            ),
            'posterior_p05_location_migration_certainty': float(
                p05_score[candidate_index]
            ),
            'posterior_p95_location_migration_certainty': float(
                p95_score[candidate_index]
            ),
            'posterior_mean_location_information': float(np.mean(
                information_samples[:, candidate_index]
            )),
            'posterior_mean_migration_coherence': float(np.mean(
                coherence_samples[:, candidate_index]
            )),
            'posterior_mean_certainty_variance': float(
                expected_variance[candidate_index]
            ),
            'posterior_mean_certainty_standard_deviation': float(np.sqrt(
                expected_variance[candidate_index]
            )),
            'expectation_minus_std_utility': float(
                expected_utility[candidate_index]
            ),
            'weighted_velocity_induced_time_std_s': float(np.sum(
                target_weights * time_standard_deviation[candidate_index]
            )),
            'certainty_objective_score': float(score[candidate_index]),
            'certainty_threshold': threshold,
            'inside_maximum_certainty_space': int(
                candidate_index in eligible_set
            ),
        })
    return {
        'scores': score.astype(np.float32),
        'posterior_mean': expected_certainty.astype(np.float32),
        'posterior_p05': p05_score.astype(np.float32),
        'posterior_p95': p95_score.astype(np.float32),
        'posterior_variance': expected_variance.astype(np.float32),
        'expectation_minus_std_utility': expected_utility.astype(np.float32),
        'eligible_indices': eligible,
        'threshold': threshold,
        'rows': rows,
        'formula': (
            'theta belongs to an empirical distribution-free perturbation bank; '
            'e_ct(theta)=G_ct theta; C_c=sqrt(normalized I_location,c * '
            'Q_migration,c); for Bayesian-bootstrap draw q, '
            'U_c(q)=E_q[C_c]-gamma*sqrt(Var_q[C_c]); '
            'score=(1-w)E_q[U_c]+w*Q0.05_q[U_c]'
        ),
        'posterior_sample_count': int(len(posterior_samples)),
        'bayesian_bootstrap_draw_count': int(
            len(bootstrap_sample_weights)
        ),
        'assumed_parametric_velocity_distribution': None,
    }


def _restrict_scenario_optimizers_to_certainty_space(
        scenario_optimizers, eligible_indices):
    """Reindex reference/true compact kernels to the certainty support."""
    eligible_indices = np.asarray(eligible_indices, dtype=int)
    if eligible_indices.size < scenario_optimizers[0].phys.dims + 2:
        raise ValueError('The certainty space contains too few receiver sites.')
    old_candidates = list(scenario_optimizers[0].candidates)
    new_candidates = [
        old_candidates[int(index)] for index in eligible_indices
    ]
    for optimizer in scenario_optimizers:
        old_kernel = optimizer.kernel_db
        old_true_kernel = optimizer.true_kernel_db
        optimizer.kernel_db = {
            new_index: old_kernel[int(old_index)]
            for new_index, old_index in enumerate(eligible_indices)
        }
        optimizer.true_kernel_db = {
            new_index: old_true_kernel[int(old_index)]
            for new_index, old_index in enumerate(eligible_indices)
        }
        optimizer.candidates = list(new_candidates)
        optimizer.illumination_reference = max(
            max(float(item['illum']) for item in optimizer.kernel_db.values()),
            np.finfo(float).tiny,
        )
        optimizer._dd_whitener_cache.clear()
        optimizer._layout_precision_cache.clear()
        optimizer._velocity_bias_cache.clear()
    return new_candidates


def _restrict_analytic_case_arrivals(
        cases, eligible_indices, new_candidates):
    """Restrict compact posterior source arrivals without any new FMM solve."""
    eligible_indices = np.asarray(eligible_indices, dtype=int)
    candidate_key = tuple(tuple(value) for value in new_candidates)
    for case in cases:
        arrivals = np.asarray(
            case['_true_source_candidate_times'], dtype=np.float32
        )
        case['_true_source_candidate_times'] = arrivals[:, eligible_indices]
        case['_true_source_candidate_key'] = candidate_key


def plot_receiver_certainty_space(physics, original_candidates,
                                  certainty_result, output_dir):
    """Plot the posterior certainty field and retained deployment support."""
    candidate_positions = (
        np.asarray(original_candidates, dtype=float)
        * np.asarray(physics.spacing, dtype=float)
    )
    scores = np.asarray(certainty_result['scores'], dtype=float)
    expectation = np.asarray(certainty_result['posterior_mean'], dtype=float)
    standard_deviation = np.sqrt(np.maximum(
        np.asarray(certainty_result['posterior_variance'], dtype=float), 0.0
    ))
    eligible = np.asarray(certainty_result['eligible_indices'], dtype=int)
    path = os.path.join(
        output_dir,
        'Figure_Distribution_Free_Bayesian_Receiver_Certainty_Space.png'
    )
    if physics.dims == 2:
        extent = [
            0.0, (physics.shape[0] - 1) * physics.spacing[0],
            (physics.shape[1] - 1) * physics.spacing[1], 0.0,
        ]
        figure, axes = plt.subplots(
            1, 3, figsize=(17.5, 5.8), sharex=True, sharey=True,
            constrained_layout=True,
        )
        panel_values = (
            (expectation, 0.0, 1.0, '(a) Posterior expected certainty',
             'Bayesian-bootstrap expectation'),
            (standard_deviation, 0.0, max(
                float(np.max(standard_deviation)), 1.0e-8
             ), '(b) Posterior certainty variability',
             'Bayesian-bootstrap standard deviation'),
            (scores, 0.0, 1.0, '(c) Maximum-certainty deployment space',
             'Expectation-minus-variance score'),
        )
        for panel_index, (axis, panel) in enumerate(zip(axes, panel_values)):
            values, vmin, vmax, title, color_label = panel
            axis.imshow(
                np.asarray(physics.V, dtype=float).T, cmap='rainbow',
                origin='upper', extent=extent, aspect='auto', alpha=0.28,
            )
            artist = axis.scatter(
                candidate_positions[:, 0], candidate_positions[:, 1],
                c=values, cmap='viridis', vmin=vmin, vmax=vmax,
                s=42, edgecolor='black', linewidth=0.25, zorder=3,
            )
            if panel_index == 2:
                axis.scatter(
                    candidate_positions[eligible, 0],
                    candidate_positions[eligible, 1],
                    facecolors='none', edgecolors='#D00000', linewidth=1.15,
                    s=115, label='Retained deployment support', zorder=4,
                )
                axis.legend(loc='best', fontsize=8)
            axis.set_xlabel('X (m)')
            axis.set_ylabel('Depth (m)')
            axis.set_title(title)
            figure.colorbar(artist, ax=axis, pad=0.02).set_label(color_label)
            _apply_complete_layout_padding(
                axis, physics, candidate_positions
            )
        figure.suptitle(
            'Distribution-free Bayesian receiver certainty on the reference '
            'velocity background', fontsize=14,
        )
    else:
        figure = plt.figure(figsize=(10.0, 7.5), constrained_layout=True)
        axis = figure.add_subplot(111, projection='3d')
        artist = axis.scatter(
            candidate_positions[:, 0], candidate_positions[:, 1],
            candidate_positions[:, 2], c=scores, cmap='viridis',
            vmin=0.0, vmax=1.0, s=35,
        )
        axis.scatter(
            candidate_positions[eligible, 0],
            candidate_positions[eligible, 1],
            candidate_positions[eligible, 2], facecolors='none',
            edgecolors='#D00000', s=100,
            label='Maximum-certainty support',
        )
        axis.set_xlabel('X (m)')
        axis.set_ylabel('Y (m)')
        axis.set_zlabel('Depth (m)')
        _apply_complete_layout_padding_3d(
            axis, physics, candidate_positions
        )
        axis.legend(loc='best')
        figure.colorbar(artist, ax=axis, pad=0.08).set_label(
            'Expectation–variance receiver certainty'
        )
    figure.savefig(path, dpi=300, bbox_inches='tight', pad_inches=0.15)
    plt.close(figure)
    return path


def plot_fixed_core_movable_receiver_layout(
        physics, candidates, targets, selected_indices, selection_evidence,
        output_dir):
    """Export the stable core and limited movable receiver shell."""
    selected_indices = [int(value) for value in selected_indices]
    core_indices = set(int(value) for value in selection_evidence.get(
        'selected_fixed_core_indices', []
    ))
    selected_set = set(selected_indices)
    core_indices &= selected_set
    movable_indices = selected_set - core_indices
    rows = []
    for index in selected_indices:
        grid = tuple(int(value) for value in candidates[index])
        physical = np.asarray(grid, dtype=float) * np.asarray(
            physics.spacing, dtype=float
        )
        row = {
            'candidate_index': index,
            'receiver_role': 'fixed_core' if index in core_indices else 'movable',
            'grid_coordinates': list(grid),
        }
        row.update({
            f'physical_coordinate_{dimension + 1}_m': float(value)
            for dimension, value in enumerate(physical)
        })
        rows.append(row)
    table_path = os.path.join(
        output_dir, 'fixed_core_and_movable_receiver_layout.csv'
    )
    _write_csv(table_path, rows)
    candidate_positions = np.asarray(candidates, dtype=float) * np.asarray(
        physics.spacing, dtype=float
    )
    target_positions = np.asarray(targets, dtype=float) * np.asarray(
        physics.spacing, dtype=float
    )
    core_positions = candidate_positions[sorted(core_indices)] if core_indices else (
        np.empty((0, physics.dims), dtype=float)
    )
    movable_positions = candidate_positions[sorted(movable_indices)] if movable_indices else (
        np.empty((0, physics.dims), dtype=float)
    )
    figure_path = os.path.join(
        output_dir, 'Figure_Fixed_Core_And_Limited_Movable_Receivers.png'
    )
    if physics.dims == 2:
        extent = [
            0.0, (physics.shape[0] - 1) * physics.spacing[0],
            (physics.shape[1] - 1) * physics.spacing[1], 0.0,
        ]
        figure, axis = plt.subplots(
            figsize=(11.5, 6.8), constrained_layout=True
        )
        velocity_artist = axis.imshow(
            np.asarray(physics.V, dtype=float).T, cmap='rainbow',
            origin='upper', extent=extent, aspect='auto', alpha=0.70,
        )
        axis.scatter(
            candidate_positions[:, 0], candidate_positions[:, 1],
            s=18, facecolors='none', edgecolors='0.45', alpha=0.45,
            label='Eligible certainty-space sites',
        )
        if len(core_positions):
            axis.scatter(
                core_positions[:, 0], core_positions[:, 1], s=95,
                marker='o', c='#0077B6', edgecolors='white', linewidths=0.9,
                label='Fixed posterior-stable core', zorder=4,
            )
        if len(movable_positions):
            axis.scatter(
                movable_positions[:, 0], movable_positions[:, 1], s=120,
                marker='v', c='#D00000', edgecolors='white', linewidths=0.9,
                label='Limited movable shell', zorder=5,
            )
        axis.scatter(
            target_positions[:, 0], target_positions[:, 1], s=105,
            marker='*', c='#FFD60A', edgecolors='black', linewidths=0.7,
            label='Target region', zorder=6,
        )
        axis.set_xlabel('X (m)')
        axis.set_ylabel('Depth (m)')
        axis.set_title(
            f'Fixed core ({len(core_positions)}) and movable receivers '
            f'({len(movable_positions)})'
        )
        axis.legend(loc='best', fontsize=9)
        figure.colorbar(velocity_artist, ax=axis, pad=0.02).set_label(
            'Reference velocity (m/s)'
        )
        _apply_complete_layout_padding(
            axis, physics,
            np.vstack((candidate_positions, target_positions)),
        )
    else:
        figure = plt.figure(figsize=(10.0, 7.5), constrained_layout=True)
        axis = figure.add_subplot(111, projection='3d')
        axis.scatter(*candidate_positions.T, s=12, c='0.6', alpha=0.35)
        if len(core_positions):
            axis.scatter(*core_positions.T, s=75, c='#0077B6', marker='o',
                         label='Fixed posterior-stable core')
        if len(movable_positions):
            axis.scatter(*movable_positions.T, s=95, c='#D00000', marker='v',
                         label='Limited movable shell')
        axis.scatter(*target_positions.T, s=95, c='#FFD60A', marker='*',
                     edgecolors='black', label='Target region')
        axis.set_xlabel('X (m)')
        axis.set_ylabel('Y (m)')
        axis.set_zlabel('Depth (m)')
        _apply_complete_layout_padding_3d(
            axis, physics,
            np.vstack((candidate_positions, target_positions)),
        )
        axis.legend(loc='best')
    figure.savefig(figure_path, dpi=300, bbox_inches='tight', pad_inches=0.15)
    plt.close(figure)
    return {
        'table': table_path,
        'figure': figure_path,
        'fixed_core_receiver_count': len(core_positions),
        'movable_receiver_count': len(movable_positions),
    }


def _select_bayesian_velocity_representatives(scenario_optimizers,
                                                probabilities,
                                                maximum_representatives,
                                                reference_index):
    """Weighted farthest-point medoids in true-minus-reference time space."""
    number_of_models = len(scenario_optimizers)
    maximum_representatives = int(maximum_representatives)
    if maximum_representatives < 1:
        raise ValueError('FUTURE_BAYESIAN_REPRESENTATIVE_MODELS must be positive.')
    number_to_select = min(maximum_representatives, number_of_models)
    features = []
    for optimizer in scenario_optimizers:
        features.append(np.concatenate([
            np.asarray(optimizer.true_kernel_db[index]['times'], dtype=float)
            - np.asarray(optimizer.kernel_db[index]['times'], dtype=float)
            for index in range(len(optimizer.candidates))
        ]))
    features = np.asarray(features, dtype=float)
    scale = np.std(features, axis=0)
    scale = np.where(scale > np.finfo(float).eps, scale, 1.0)
    features = (features - features[int(reference_index)][None, :]) / scale[None, :]
    probabilities = np.asarray(probabilities, dtype=float)
    probabilities /= float(np.sum(probabilities))
    selected = [int(reference_index)]
    minimum_distance = np.sum(
        (features - features[int(reference_index)][None, :]) ** 2, axis=1
    )
    while len(selected) < number_to_select:
        score = probabilities * np.maximum(minimum_distance, 0.0)
        score[np.asarray(selected, dtype=int)] = -np.inf
        next_index = int(np.argmax(score))
        if not np.isfinite(score[next_index]) or score[next_index] <= 0.0:
            remaining = [index for index in range(number_of_models)
                         if index not in selected]
            next_index = max(remaining, key=lambda index: probabilities[index])
        selected.append(next_index)
        distance = np.sum(
            (features - features[next_index][None, :]) ** 2, axis=1
        )
        minimum_distance = np.minimum(minimum_distance, distance)
    representative_features = features[np.asarray(selected, dtype=int)]
    distances = np.sum(
        (features[:, None, :] - representative_features[None, :, :]) ** 2,
        axis=2,
    )
    assignment_slots = np.argmin(distances, axis=1)
    assignments = np.asarray(
        [selected[int(slot)] for slot in assignment_slots], dtype=int
    )
    representative_weights = {
        int(index): float(np.sum(probabilities[assignments == index]))
        for index in selected
    }
    return selected, assignments, representative_weights


def _design_uncertainty_across_velocity_ensemble(reference_phys, cases,
                                                  sensors, targets,
                                                  noise_std,
                                                  confidence_level,
                                                  design_name,
                                                  probability_draws=None,
                                                  scenario_optimizers=None,
                                                  common_candidates=None):
    """Evaluate picking plus propagated velocity-model uncertainty.

    Possible true media generate noiseless arrivals, but every inversion uses
    the reference locator. Across-model position-bias covariance is added to the
    reference picking-noise covariance by the law of total covariance.
    """
    target_positions = _source_positions_in_metres(reference_phys, targets)
    locator = SourceLocator(reference_phys, sensors)
    sensor_coordinates = tuple(np.asarray(sensors, dtype=int).T)
    compact_layout_indices = None
    if scenario_optimizers is not None:
        if common_candidates is None:
            raise ValueError(
                'Compact uncertainty evaluation requires common candidates.'
            )
        lookup = {
            tuple(candidate): index
            for index, candidate in enumerate(common_candidates)
        }
        compact_layout_indices = [lookup[tuple(sensor)] for sensor in sensors]
        if len(scenario_optimizers) != len(cases):
            raise ValueError(
                'Compact uncertainty kernels do not match velocity cases.'
            )
    scenario_biases = []
    for scenario_index, case in enumerate(cases):
        case_biases = []
        for target_index, (target, position) in enumerate(zip(
                targets, target_positions)):
            if compact_layout_indices is None:
                field = _plain_numpy_array(
                    case['physics'].compute_traveltime_field(tuple(target)),
                    dtype=np.float64,
                    name='uncertainty true traveltime field',
                )
                observed = np.asarray(field[sensor_coordinates], dtype=float)
                del field
            else:
                database = scenario_optimizers[
                    scenario_index
                ].true_kernel_db
                observed = np.asarray([
                    database[index]['times'][target_index]
                    for index in compact_layout_indices
                ], dtype=float)
            try:
                estimate, _, _ = locator._solve_dd(observed, locator.splines)
                bias = np.asarray(estimate, dtype=float) - position
            except Exception:
                bias = np.full(reference_phys.dims, np.nan)
            case_biases.append(bias)
        scenario_biases.append(case_biases)
    scenario_biases = np.asarray(scenario_biases, dtype=float)
    probabilities = np.asarray(
        [max(float(case['probability']), 0.0) for case in cases], dtype=float
    )
    probabilities /= max(float(np.sum(probabilities)), np.finfo(float).tiny)
    finite_biases = np.where(np.isfinite(scenario_biases), scenario_biases, 0.0)
    mean_bias = np.einsum('s,std->td', probabilities, finite_biases)
    centered = finite_biases - mean_bias[None, :, :]
    between_model_covariances = np.einsum(
        's,std,ste->tde', probabilities, centered, centered
    )
    if probability_draws is None:
        probability_draws = probabilities[None, :]
    probability_draws = np.asarray(probability_draws, dtype=float)
    probability_draws /= np.sum(probability_draws, axis=1, keepdims=True)
    posterior_means = np.einsum(
        'bs,std->btd', probability_draws, finite_biases
    )
    posterior_mean_offsets = posterior_means - np.mean(
        posterior_means, axis=0, keepdims=True
    )
    posterior_weight_covariances = np.einsum(
        'btd,bte->tde', posterior_mean_offsets, posterior_mean_offsets
    ) / float(max(probability_draws.shape[0], 1))
    model_covariances = (
        between_model_covariances + posterior_weight_covariances
    )
    rows = []
    for scenario_index, case in enumerate(cases):
        for target_index, position in enumerate(target_positions, 1):
            metric = design_stage_confidence_metrics(
                locator,
                position,
                noise_std,
                confidence_level=confidence_level,
            )
            picking_covariance = np.asarray(metric['covariance'], dtype=float)
            covariance = (
                picking_covariance + model_covariances[target_index - 1]
            )
            covariance = 0.5 * (covariance + covariance.T)
            identifiable = bool(
                metric['rank'] == locator.dims
                and np.all(np.isfinite(covariance))
            )
            if identifiable:
                covariance_trace = float(np.trace(covariance))
                eigenvalues = np.maximum(np.linalg.eigvalsh(covariance), 0.0)
                joint_axes = np.sqrt(
                    chi2.ppf(confidence_level, locator.dims) * eigenvalues
                )
                standard_deviation = np.sqrt(np.maximum(np.diag(covariance), 0.0))
                marginal_half_width = float(norm.ppf(
                    0.5 + confidence_level / 2.0
                )) * standard_deviation
                rms_radius = float(np.sqrt(
                    chi2.ppf(confidence_level, locator.dims)
                    * covariance_trace / locator.dims
                ))
                maximum_axis = float(np.max(joint_axes))
                region_measure = float(
                    (np.pi if locator.dims == 2 else 4.0 * np.pi / 3.0)
                    * np.prod(joint_axes)
                )
            else:
                covariance_trace = np.inf
                rms_radius = np.inf
                maximum_axis = np.inf
                standard_deviation = np.full(locator.dims, np.inf)
                marginal_half_width = np.full(locator.dims, np.inf)
                region_measure = np.inf
            scenario_bias = scenario_biases[scenario_index, target_index - 1]
            row = {
                'scenario': case['name'],
                'scenario_kind': case['kind'],
                'scenario_probability': case['probability'],
                'residual_rms_percent': 100.0 * case['residual_rms_fraction'],
                'residual_max_abs_percent': (
                    100.0 * case['residual_max_abs_fraction']
                ),
                'velocity_mean_m_per_s': case['velocity_mean_m_per_s'],
                'design': design_name,
                'target': target_index,
                'identifiable': int(identifiable),
                'fisher_rank': metric['rank'],
                'normal_matrix_condition_number': (
                    metric['normal_matrix_condition_number']
                ),
                'covariance_trace_m2': covariance_trace,
                'picking_covariance_trace_m2': float(np.trace(picking_covariance)),
                'velocity_model_covariance_trace_m2': float(np.trace(
                    model_covariances[target_index - 1]
                )),
                'between_velocity_model_covariance_trace_m2': float(np.trace(
                    between_model_covariances[target_index - 1]
                )),
                'posterior_weight_covariance_trace_m2': float(np.trace(
                    posterior_weight_covariances[target_index - 1]
                )),
                'scenario_velocity_bias_m': float(np.linalg.norm(scenario_bias)),
                'rms_95_radius_m': rms_radius,
                'maximum_95_semi_axis_m': maximum_axis,
                'mean_marginal_95_half_width_m': float(np.mean(marginal_half_width)),
                'maximum_marginal_95_half_width_m': float(np.max(marginal_half_width)),
                'confidence_region_measure_m2_or_m3': region_measure,
            }
            for dimension, value in enumerate(standard_deviation):
                row[f'standard_deviation_coordinate_{dimension + 1}_m'] = float(
                    value
                )
            for dimension, value in enumerate(marginal_half_width):
                row[f'marginal_95_half_width_coordinate_{dimension + 1}_m'] = (
                    float(value)
                )
            for first_dimension in range(locator.dims):
                for second_dimension in range(locator.dims):
                    row[
                        f'covariance_{first_dimension + 1}_{second_dimension + 1}_m2'
                    ] = float(covariance[first_dimension, second_dimension])
            rows.append(row)
    del locator, scenario_biases, finite_biases, model_covariances
    del between_model_covariances, posterior_weight_covariances, posterior_means
    return rows


def _summarize_velocity_uncertainty_rows(rows):
    """Aggregate target-level uncertainty into one row per model and design."""
    grouped = {}
    for row in rows:
        grouped.setdefault((row['scenario'], row['design']), []).append(row)
    summary = []
    for (scenario, design), group in grouped.items():
        identifiable = np.asarray(
            [row['identifiable'] for row in group], dtype=float
        )
        axes = np.asarray(
            [row['maximum_95_semi_axis_m'] for row in group], dtype=float
        )
        radii = np.asarray(
            [row['rms_95_radius_m'] for row in group], dtype=float
        )
        traces = np.asarray(
            [row['covariance_trace_m2'] for row in group], dtype=float
        )
        conditions = np.asarray([
            row['normal_matrix_condition_number'] for row in group
        ], dtype=float)
        mean_half_widths = np.asarray([
            row['mean_marginal_95_half_width_m'] for row in group
        ], dtype=float)
        maximum_half_widths = np.asarray([
            row['maximum_marginal_95_half_width_m'] for row in group
        ], dtype=float)
        regions = np.asarray([
            row['confidence_region_measure_m2_or_m3'] for row in group
        ], dtype=float)

        def finite_statistic(values, statistic):
            finite = values[np.isfinite(values)]
            return float(statistic(finite)) if finite.size else np.inf

        summary.append({
            'scenario': scenario,
            'scenario_kind': group[0]['scenario_kind'],
            'scenario_probability': group[0]['scenario_probability'],
            'residual_rms_percent': group[0]['residual_rms_percent'],
            'residual_max_abs_percent': group[0]['residual_max_abs_percent'],
            'velocity_mean_m_per_s': group[0]['velocity_mean_m_per_s'],
            'design': design,
            'target_count': len(group),
            'identifiable_fraction': float(np.mean(identifiable)),
            'mean_maximum_95_semi_axis_m': finite_statistic(axes, np.mean),
            'p95_maximum_95_semi_axis_m': finite_statistic(
                axes, lambda values: np.quantile(values, 0.95)
            ),
            'mean_rms_95_radius_m': finite_statistic(radii, np.mean),
            'p95_rms_95_radius_m': finite_statistic(
                radii, lambda values: np.quantile(values, 0.95)
            ),
            'mean_covariance_trace_m2': finite_statistic(traces, np.mean),
            'mean_marginal_95_half_width_m': finite_statistic(
                mean_half_widths, np.mean
            ),
            'p95_mean_marginal_95_half_width_m': finite_statistic(
                mean_half_widths, lambda values: np.quantile(values, 0.95)
            ),
            'p95_maximum_marginal_95_half_width_m': finite_statistic(
                maximum_half_widths,
                lambda values: np.quantile(values, 0.95),
            ),
            'mean_confidence_region_measure_m2_or_m3': finite_statistic(
                regions, np.mean
            ),
            'p95_confidence_region_measure_m2_or_m3': finite_statistic(
                regions, lambda values: np.quantile(values, 0.95)
            ),
            'maximum_condition_number': finite_statistic(conditions, np.max),
        })
    return summary


def _precompute_true_source_candidate_arrivals(
        cases, common_candidates, true_sources):
    """Compute each true-model/source FMM once and share it across designs."""
    candidate_coordinates = tuple(
        np.asarray(common_candidates, dtype=int).T
    )
    candidate_key = tuple(tuple(value) for value in common_candidates)
    for case in cases:
        arrivals = np.empty(
            (len(true_sources), len(common_candidates)), dtype=np.float32
        )
        for source_index, source in enumerate(true_sources):
            field = _plain_numpy_array(
                case['physics'].compute_traveltime_field(tuple(source)),
                dtype=np.float32,
                name='shared true-source candidate arrivals',
                expected_ndim=case['physics'].dims,
            )
            arrivals[source_index] = field[candidate_coordinates]
            del field
        case['_true_source_candidate_times'] = arrivals
        case['_true_source_candidate_key'] = candidate_key
    gc.collect()


def _cached_true_arrivals_for_sensors(case, sensors, true_sources):
    """Return source-by-sensor arrivals from the shared compact signature."""
    candidate_key = case.get('_true_source_candidate_key')
    arrivals = case.get('_true_source_candidate_times')
    if candidate_key is None or arrivals is None:
        return None
    lookup = {
        tuple(candidate): index
        for index, candidate in enumerate(candidate_key)
    }
    try:
        indices = [lookup[tuple(sensor)] for sensor in sensors]
    except KeyError:
        return None
    result = np.asarray(arrivals[:, indices], dtype=float)
    if result.shape != (len(true_sources), len(sensors)):
        raise RuntimeError('A cached true-arrival signature has invalid shape.')
    return result


def _evaluate_design_across_velocity_ensemble(reference_phys, cases, sensors,
                                               true_sources, noise_model,
                                               realizations, seed,
                                               design_name):
    """Propagate unknown true velocity through one fixed reference locator.

    Each ensemble member generates possible true arrivals. The locator always
    uses ``reference_phys`` because the true velocity is unavailable. Identical
    noise seeds are reused across cases, isolating velocity-model uncertainty.
    """
    true_positions = _source_positions_in_metres(reference_phys, true_sources)
    sensor_coordinates = tuple(np.asarray(sensors, dtype=int).T)
    rows = []
    trials = []
    locator = SourceLocator(reference_phys, sensors)
    for case in cases:
        errors = []
        successes = []
        cached_arrivals = _cached_true_arrivals_for_sensors(
            case, sensors, true_sources
        )
        if cached_arrivals is None:
            true_arrivals = [
                np.asarray(
                    case['physics'].compute_traveltime_field(source)[
                        sensor_coordinates
                    ],
                    dtype=float,
                )
                for source in true_sources
            ]
        else:
            true_arrivals = [
                cached_arrivals[index]
                for index in range(len(true_sources))
            ]
        for source_index, (source, truth) in enumerate(
                zip(true_sources, true_positions)):
            clean = true_arrivals[source_index]
            for realization in range(int(realizations)):
                trial_seed = int(
                    seed + source_index * 10007 + realization * 101
                )
                rng = np.random.default_rng(trial_seed)
                observed = clean + noise_model.sample(
                    reference_phys, sensors, rng
                )
                try:
                    located = locate_source_noise_aware(
                        locator, observed, noise_model
                    )
                    estimate = located['estimate']
                    error = float(np.linalg.norm(estimate - truth))
                    success = bool(located['success'] and np.isfinite(error))
                except Exception as exc:
                    estimate = np.full(reference_phys.dims, np.nan)
                    error = np.nan
                    success = False
                    located = {
                        'cost': np.nan, 'nfev': 0,
                        'optimality': np.nan, 'exception': str(exc),
                    }
                successes.append(success)
                if success:
                    errors.append(error)
                trial = {
                    'scenario': case['name'],
                    'scenario_probability': case['probability'],
                    'design': design_name,
                    'source': source_index + 1,
                    'realization': realization + 1,
                    'seed': trial_seed,
                    'success': int(success),
                    'location_error_m': error,
                    'solver_cost': located['cost'],
                    'solver_nfev': located['nfev'],
                    'solver_optimality': located['optimality'],
                }
                for dimension, value in enumerate(truth):
                    trial[f'true_coordinate_{dimension + 1}_m'] = float(value)
                    trial[f'estimated_coordinate_{dimension + 1}_m'] = float(
                        estimate[dimension]
                    )
                trial['exception'] = located.get('exception', '')
                trials.append(trial)
        errors = np.asarray(errors, dtype=float)
        rows.append({
            'scenario': case['name'],
            'scenario_kind': case['kind'],
            'scenario_magnitude_percent': 100.0 * case['magnitude'],
            'scenario_probability': case['probability'],
            'prior_probability': case.get(
                'prior_probability', case['probability']
            ),
            'probability_posterior_mean': case.get(
                'probability_posterior_mean', case['probability']
            ),
            'probability_posterior_p025': case.get(
                'probability_posterior_p025', case['probability']
            ),
            'probability_posterior_p975': case.get(
                'probability_posterior_p975', case['probability']
            ),
            'design': design_name,
            'number_of_geophones': len(sensors),
            'mean_error_m': float(np.mean(errors)) if errors.size else np.nan,
            'median_error_m': float(np.median(errors)) if errors.size else np.nan,
            'p95_error_m': float(np.quantile(errors, 0.95)) if errors.size else np.nan,
            'maximum_error_m': float(np.max(errors)) if errors.size else np.nan,
            'failure_rate': float(1.0 - np.mean(successes)),
        })
        del true_arrivals, errors, successes
    del locator
    return rows, trials


def _statistical_mean_receiver_layout(common_candidates, scenario_layouts,
                                      probabilities, physics):
    """Align scenario layouts and project their weighted mean to valid sites.

    Receiver labels have no physical meaning, so the Hungarian algorithm first
    matches every scenario-optimal layout to the reference-scenario layout in
    physical coordinates. The probability-weighted slot means are then assigned
    jointly to distinct feasible receiver sites. Joint projection prevents two
    averaged slots from collapsing onto the same candidate.
    """
    layouts = [np.asarray(layout, dtype=int).ravel() for layout in scenario_layouts]
    if not layouts:
        raise ValueError('Scenario receiver layouts cannot be empty.')
    receiver_count = layouts[0].size
    if receiver_count < 1 or any(layout.size != receiver_count for layout in layouts):
        raise ValueError('All scenario receiver layouts must have equal nonzero size.')
    weights = np.asarray(probabilities, dtype=float).ravel()
    if weights.shape != (len(layouts),) or np.any(weights < 0.0):
        raise ValueError('Scenario probabilities do not match receiver layouts.')
    if float(np.sum(weights)) <= 0.0:
        raise ValueError('Scenario probabilities must have positive total weight.')
    weights = weights / float(np.sum(weights))

    candidate_coordinates = (
        np.asarray(common_candidates, dtype=float)
        * np.asarray(physics.spacing, dtype=float)
    )
    anchor_indices = layouts[0]
    anchor_coordinates = candidate_coordinates[anchor_indices]
    aligned_coordinates = []
    alignment_records = []
    for scenario_index, layout in enumerate(layouts):
        scenario_coordinates = candidate_coordinates[layout]
        squared_distance = np.sum(
            (anchor_coordinates[:, None, :] - scenario_coordinates[None, :, :]) ** 2,
            axis=2,
        )
        anchor_slots, scenario_slots = opt.linear_sum_assignment(squared_distance)
        aligned = np.empty_like(anchor_coordinates)
        aligned_indices = np.empty(receiver_count, dtype=int)
        aligned[anchor_slots] = scenario_coordinates[scenario_slots]
        aligned_indices[anchor_slots] = layout[scenario_slots]
        aligned_coordinates.append(aligned)
        alignment_records.append({
            'scenario_index': int(scenario_index),
            'probability': float(weights[scenario_index]),
            'aligned_candidate_indices': [int(value) for value in aligned_indices],
        })
    aligned_coordinates = np.stack(aligned_coordinates, axis=0)
    mean_coordinates = np.einsum('s,skd->kd', weights, aligned_coordinates)

    projection_cost = np.sum(
        (mean_coordinates[:, None, :] - candidate_coordinates[None, :, :]) ** 2,
        axis=2,
    )
    mean_slots, selected_sites = opt.linear_sum_assignment(projection_cost)
    if mean_slots.size != receiver_count:
        raise RuntimeError('Could not project every mean receiver position.')
    selected_by_slot = np.empty(receiver_count, dtype=int)
    selected_by_slot[mean_slots] = selected_sites
    slot_records = []
    for slot, selected_index in enumerate(selected_by_slot):
        slot_records.append({
            'receiver_slot': int(slot + 1),
            'mean_physical_coordinates_m': [
                float(value) for value in mean_coordinates[slot]
            ],
            'projected_candidate_index': int(selected_index),
            'projected_grid_coordinates': [
                int(value) for value in common_candidates[int(selected_index)]
            ],
            'projected_physical_coordinates_m': [
                float(value) for value in candidate_coordinates[int(selected_index)]
            ],
            'projection_distance_m': float(np.sqrt(
                projection_cost[slot, int(selected_index)]
            )),
        })
    return np.sort(selected_by_slot), slot_records, alignment_records


def _changed_velocity_layout_movement_statistics(layout, scenario_layouts,
                                                 cases, probabilities):
    """Measure replacements relative to changed-velocity scenario optima."""
    selected = set(int(value) for value in np.asarray(layout, dtype=int).ravel())
    if not selected:
        raise ValueError('The robust-count candidate layout cannot be empty.')
    changed = [
        index for index, case in enumerate(cases)
        if case['kind'] != 'reference'
    ]
    if not changed:
        changed = list(range(len(cases)))
    weights = np.asarray([probabilities[index] for index in changed], dtype=float)
    if float(np.sum(weights)) <= 0.0:
        weights[:] = 1.0
    weights /= float(np.sum(weights))
    moved_counts = np.asarray([
        len(selected - set(
            int(value) for value in np.asarray(scenario_layouts[index], dtype=int)
        ))
        for index in changed
    ], dtype=float)
    return {
        'expected_changed_velocity_moved_receiver_count': float(
            np.dot(weights, moved_counts)
        ),
        'p95_changed_velocity_moved_receiver_count': float(
            _weighted_quantile(moved_counts, 0.95, weights)
        ),
        'worst_changed_velocity_moved_receiver_count': float(
            np.max(moved_counts)
        ),
        'expected_changed_velocity_moved_receiver_fraction': float(
            np.dot(weights, moved_counts) / len(selected)
        ),
    }


def _select_independent_robust_receiver_count(
        counts, mean_layouts_by_count, scenario_layouts_by_count,
        localization_rows, confidence_metrics_by_count, cases, probabilities,
        error_tolerance):
    """Select robust count from accuracy, model-aware confidence, and relocation.

    The localization criterion is primary: a candidate must lie within
    ``error_tolerance`` of the best joint mean/P95/model-aware-95%-axis score.
    Within that near-best set, the expected and worst numbers of receivers
    requiring replacement are minimized. Candidates improving both errors over
    the nominal comparator are preferred whenever at least one exists.
    """
    error_tolerance = float(error_tolerance)
    if error_tolerance < 0.0:
        raise ValueError('FUTURE_ROBUST_COUNT_ERROR_TOLERANCE cannot be negative.')
    row_by_layout = {
        tuple(sorted(int(value) for value in row['sensor_indices'])): row
        for row in localization_rows
    }
    nominal_rows = [
        row for row in localization_rows
        if row.get('layout_role') == 'nominal comparator'
    ]
    if not nominal_rows:
        raise ValueError('Robust-count localization validation lacks a nominal row.')
    nominal = nominal_rows[0]
    records = []
    for count in counts:
        layout = np.asarray(mean_layouts_by_count[int(count)], dtype=int)
        key = tuple(sorted(int(value) for value in layout))
        row = row_by_layout.get(key)
        if row is None:
            raise RuntimeError(
                f'Missing localization validation for robust count {count}.'
            )
        movement = _changed_velocity_layout_movement_statistics(
            layout, scenario_layouts_by_count[int(count)], cases, probabilities
        )
        confidence = confidence_metrics_by_count[int(count)]
        records.append({
            'robust_receiver_count': int(count),
            'weighted_changed_model_mean_error_m': float(
                row['weighted_changed_model_mean_error_m']
            ),
            'worst_changed_model_p95_error_m': float(
                row['worst_changed_model_p95_error_m']
            ),
            'localization_failed': int(row.get('failed', 0)),
            'model_aware_confidence_risk': float(
                confidence['model_aware_confidence_risk']
            ),
            'combined_picking_and_model_confidence_risk': float(
                confidence['combined_picking_and_model_confidence_risk']
            ),
            'mean_model_aware_marginal_95_half_width_m': float(
                confidence['mean_model_aware_marginal_95_half_width_m']
            ),
            'p95_model_aware_maximum_95_axis_m': float(
                confidence['p95_model_aware_maximum_95_axis_m']
            ),
            'model_error_covariance_trace_m2': float(
                confidence['model_error_covariance_trace_m2']
            ),
            'improves_nominal_mean_and_p95': int(
                row['weighted_changed_model_mean_error_m']
                < nominal['weighted_changed_model_mean_error_m']
                and row['worst_changed_model_p95_error_m']
                < nominal['worst_changed_model_p95_error_m']
            ),
            **movement,
        })
    valid = [row for row in records if not row['localization_failed']]
    if not valid:
        raise RuntimeError('Every independent robust-count candidate failed localization.')
    dominant = [row for row in valid if row['improves_nominal_mean_and_p95']]
    accuracy_pool = dominant if dominant else valid
    best_mean = min(row['weighted_changed_model_mean_error_m'] for row in accuracy_pool)
    best_p95 = min(row['worst_changed_model_p95_error_m'] for row in accuracy_pool)
    best_confidence_axis = min(
        row['p95_model_aware_maximum_95_axis_m'] for row in accuracy_pool
    )
    tiny = np.finfo(float).tiny
    for row in records:
        row['joint_changed_velocity_error_score'] = float(max(
            row['weighted_changed_model_mean_error_m'] / max(best_mean, tiny),
            row['worst_changed_model_p95_error_m'] / max(best_p95, tiny),
            row['p95_model_aware_maximum_95_axis_m']
            / max(best_confidence_axis, tiny),
        ))
        row['within_near_minimum_error_set'] = int(False)
        row['selected_independent_robust_count'] = int(False)
    best_joint = min(
        row['joint_changed_velocity_error_score'] for row in accuracy_pool
    )
    near_best = [
        row for row in accuracy_pool
        if row['joint_changed_velocity_error_score']
        <= (1.0 + error_tolerance) * best_joint
    ]
    for row in near_best:
        row['within_near_minimum_error_set'] = int(True)
    selected = min(
        near_best,
        key=lambda row: (
            row['expected_changed_velocity_moved_receiver_count'],
            row['worst_changed_velocity_moved_receiver_count'],
            row['joint_changed_velocity_error_score'],
            row['robust_receiver_count'],
        ),
    )
    selected['selected_independent_robust_count'] = int(True)
    evidence = {
        'selected_robust_receiver_count': int(selected['robust_receiver_count']),
        'error_tolerance_fraction': error_tolerance,
        'preferred_candidates_improving_nominal_mean_and_p95': bool(dominant),
        'selected_weighted_changed_model_mean_error_m': (
            selected['weighted_changed_model_mean_error_m']
        ),
        'selected_worst_changed_model_p95_error_m': (
            selected['worst_changed_model_p95_error_m']
        ),
        'selected_p95_model_aware_maximum_95_axis_m': (
            selected['p95_model_aware_maximum_95_axis_m']
        ),
        'selected_mean_model_aware_marginal_95_half_width_m': (
            selected['mean_model_aware_marginal_95_half_width_m']
        ),
        'selected_expected_moved_receiver_count': (
            selected['expected_changed_velocity_moved_receiver_count']
        ),
        'selected_worst_moved_receiver_count': (
            selected['worst_changed_velocity_moved_receiver_count']
        ),
        'selection_rule': (
            'near-minimum changed-velocity mean/P95 localization error and '
            'model-aware 95% confidence-axis length, then minimum expected and '
            'worst receiver replacement count'
        ),
    }
    return int(selected['robust_receiver_count']), records, evidence


def _plot_independent_robust_count_selection(rows, fixed_k, robust_k, output_dir):
    """Plot the accuracy/relocation evidence used to select robust count."""
    rows = sorted(rows, key=lambda row: row['robust_receiver_count'])
    counts = np.asarray([row['robust_receiver_count'] for row in rows], dtype=int)
    figure, axes = plt.subplots(
        1, 2, figsize=(14.5, 5.6), constrained_layout=True
    )
    axes[0].plot(
        counts,
        [row['weighted_changed_model_mean_error_m'] for row in rows],
        color='#277DA1', marker='o', linewidth=2.0,
        label='Weighted mean error',
    )
    axes[0].plot(
        counts,
        [row['worst_changed_model_p95_error_m'] for row in rows],
        color='#F94144', marker='s', linewidth=2.0,
        label='Worst P95 error',
    )
    axes[0].plot(
        counts,
        [row['p95_model_aware_maximum_95_axis_m'] for row in rows],
        color='#9B5DE5', marker='^', linewidth=2.0,
        label='Model-aware P95 95%-axis',
    )
    if rows and 'hard_mean_error_limit_m' in rows[0]:
        axes[0].axhline(
            float(rows[0]['hard_mean_error_limit_m']), color='#277DA1',
            linestyle=':', linewidth=1.5, label='Hard mean-error limit',
        )
    if rows and 'hard_p95_error_limit_m' in rows[0]:
        axes[0].axhline(
            float(rows[0]['hard_p95_error_limit_m']), color='#F94144',
            linestyle=':', linewidth=1.5, label='Hard P95-error limit',
        )
    axes[0].set_ylabel('Changed-velocity localization error (m)')
    axes[0].set_title('(a) Fixed-reference localization and confidence versus count')
    axes[0].legend(loc='best')
    axes[1].plot(
        counts,
        [row['expected_changed_velocity_moved_receiver_count'] for row in rows],
        color='#43AA8B', marker='o', linewidth=2.0,
        label='Expected replacements',
    )
    axes[1].plot(
        counts,
        [row['worst_changed_velocity_moved_receiver_count'] for row in rows],
        color='#F8961E', marker='s', linewidth=2.0,
        label='Worst replacements',
    )
    axes[1].set_ylabel('Receiver replacement count')
    axes[1].set_title('(b) Layout adaptation versus robust count')
    axes[1].legend(loc='best')
    for axis in axes:
        axis.axvline(
            robust_k, color='black', linewidth=1.8,
            label='Selected robust count',
        )
        if fixed_k != robust_k:
            axis.axvline(
                fixed_k, color='0.45', linewidth=1.5, linestyle='--',
                label='Fixed/uniform/random count',
            )
        axis.set_xlabel('Number of receivers in robust array')
        axis.set_xticks(counts)
        axis.grid(True, linestyle=':', alpha=0.45)
    # Rebuild the second legend after adding the count markers.
    handles, labels = axes[1].get_legend_handles_labels()
    axes[1].legend(handles, labels, loc='best', fontsize=8)
    figure.suptitle(
        'Independent receiver-count selection for velocity-uncertainty design',
        fontsize=14,
    )
    path = os.path.join(
        output_dir, 'Figure_Independent_Robust_Receiver_Count_Selection.png'
    )
    figure.savefig(path, dpi=300, bbox_inches='tight', pad_inches=0.15)
    plt.close(figure)
    return path


def _localization_selection_layouts(initial_indices, nominal_indices,
                                    scenario_sets, probabilities,
                                    receiver_count, maximum_candidates):
    """Build a compact set of equal-count layouts for localization selection."""
    layouts = []
    seen = set()

    def add(indices):
        values = tuple(sorted(int(value) for value in np.asarray(indices).ravel()))
        if len(values) == receiver_count and len(set(values)) == receiver_count:
            if values not in seen and values != tuple(sorted(nominal_indices)):
                seen.add(values)
                layouts.append(np.asarray(values, dtype=int))

    add(initial_indices)
    for indices in scenario_sets:
        add(indices)
    score = {}
    for probability, indices in zip(probabilities, scenario_sets):
        for index in np.asarray(indices, dtype=int):
            score[int(index)] = score.get(int(index), 0.0) + float(probability)
    consensus = sorted(score, key=lambda index: (-score[index], index))[:receiver_count]
    add(consensus)

    # Local one-for-one consensus swaps add inexpensive alternatives around the
    # MCMC solution without repeating the costly global optimization.
    initial = set(int(value) for value in np.asarray(initial_indices, dtype=int))
    removals = sorted(initial, key=lambda index: (score.get(index, 0.0), index))
    additions = sorted(
        (index for index in score if index not in initial),
        key=lambda index: (-score.get(index, 0.0), index),
    )
    for remove_index in removals:
        for add_index in additions:
            candidate = sorted((initial - {remove_index}) | {add_index})
            add(candidate)
            if len(layouts) >= int(maximum_candidates):
                return layouts
    return layouts


def _select_layout_by_reference_data_localization(
        reference_phys, cases, common_candidates, candidate_layouts,
        nominal_indices, true_sources, noise_model, realizations, seed):
    """Evaluate layouts using true-scenario data and the reference locator.

    The true velocity is treated as unknown: every scenario generates arrivals,
    while one reference-model locator is reused for every candidate layout.
    """
    nominal_key = tuple(sorted(int(value) for value in nominal_indices))
    layouts = [np.asarray(nominal_key, dtype=int)] + [
        np.asarray(layout, dtype=int) for layout in candidate_layouts
        if tuple(sorted(int(value) for value in layout)) != nominal_key
    ]
    if len(layouts) == 1:
        return layouts[0], [], {
            'dominates_nominal_mean_and_p95': False,
            'reason': 'no distinct robust localization candidates',
        }
    candidate_coordinates = tuple(np.asarray(common_candidates, dtype=int).T)
    true_positions = _source_positions_in_metres(reference_phys, true_sources)
    noise_draws = []
    for source_number, source in enumerate(true_sources):
        source_noise = []
        for realization in range(int(realizations)):
            rng = np.random.default_rng(
                int(seed + source_number * 10007 + realization * 101)
            )
            source_noise.append(np.asarray(
                noise_model.sample(reference_phys, common_candidates, rng),
                dtype=float,
            ))
        noise_draws.append(source_noise)

    errors = {
        tuple(int(value) for value in layout): {} for layout in layouts
    }
    reference_locator = SourceLocator(reference_phys, common_candidates)
    for case in cases:
        if case['kind'] == 'reference':
            continue
        cached_arrivals = _cached_true_arrivals_for_sensors(
            case, common_candidates, true_sources
        )
        if cached_arrivals is None:
            scenario_arrivals = []
            for source in true_sources:
                field = _plain_numpy_array(
                    case['physics'].compute_traveltime_field(tuple(source)),
                    dtype=np.float64,
                    name='count-selection true traveltime field',
                )
                scenario_arrivals.append(np.asarray(
                    field[candidate_coordinates], dtype=float
                ))
                del field
        else:
            scenario_arrivals = [
                cached_arrivals[index]
                for index in range(len(true_sources))
            ]
        for layout in layouts:
            key = tuple(int(value) for value in layout)
            selected_splines = [
                reference_locator.splines[index] for index in layout
            ]
            case_errors = []
            for source_number, truth in enumerate(true_positions):
                for realization in range(int(realizations)):
                    observed = (
                        scenario_arrivals[source_number]
                        + noise_draws[source_number][realization]
                    )[layout]
                    try:
                        estimate, _, _ = reference_locator._solve_dd(
                            observed, selected_splines
                        )
                        error = float(np.linalg.norm(estimate - truth))
                        if np.isfinite(error):
                            case_errors.append(error)
                    except Exception:
                        continue
            errors[key][case['name']] = np.asarray(case_errors, dtype=float)
        del scenario_arrivals

    rows = []
    changed_cases = [case for case in cases if case['kind'] != 'reference']
    raw_weights = np.asarray(
        [max(float(case.get('probability', 0.0)), 0.0) for case in changed_cases],
        dtype=float,
    )
    if np.sum(raw_weights) <= 0.0:
        raw_weights[:] = 1.0
    weights = raw_weights / np.sum(raw_weights)
    for layout_number, layout in enumerate(layouts):
        key = tuple(int(value) for value in layout)
        means = []
        p95_values = []
        failed = False
        for case in changed_cases:
            values = errors[key].get(case['name'], np.empty(0, dtype=float))
            if values.size:
                means.append(float(np.mean(values)))
                p95_values.append(float(np.quantile(values, 0.95)))
            else:
                means.append(np.inf)
                p95_values.append(np.inf)
                failed = True
        rows.append({
            'layout_number': layout_number,
            'layout_role': 'nominal comparator' if layout_number == 0 else 'robust candidate',
            'sensor_indices': list(key),
            'weighted_changed_model_mean_error_m': float(np.sum(weights * means)),
            'worst_changed_model_p95_error_m': float(np.max(p95_values)),
            'failed': int(failed),
        })

    nominal = rows[0]
    tiny = np.finfo(float).tiny
    for row in rows:
        mean_ratio = row['weighted_changed_model_mean_error_m'] / max(
            nominal['weighted_changed_model_mean_error_m'], tiny
        )
        p95_ratio = row['worst_changed_model_p95_error_m'] / max(
            nominal['worst_changed_model_p95_error_m'], tiny
        )
        row['mean_error_ratio_to_nominal'] = float(mean_ratio)
        row['p95_error_ratio_to_nominal'] = float(p95_ratio)
        row['joint_localization_score'] = float(max(mean_ratio, p95_ratio))
    eligible = [
        row for row in rows[1:]
        if not row['failed']
        and row['weighted_changed_model_mean_error_m']
        < nominal['weighted_changed_model_mean_error_m']
        and row['worst_changed_model_p95_error_m']
        < nominal['worst_changed_model_p95_error_m']
    ]
    pool = eligible if eligible else [row for row in rows[1:] if not row['failed']]
    if not pool:
        evidence = {
            'dominates_nominal_mean_and_p95': False,
            'selected_layout_number': 1,
            'reason': 'all localization-selection candidates failed',
            'validation_realizations_per_source': int(realizations),
        }
        return layouts[1], rows, evidence
    selected = min(
        pool,
        key=lambda row: (
            row['joint_localization_score'],
            row['mean_error_ratio_to_nominal'] + row['p95_error_ratio_to_nominal'],
            row['layout_number'],
        ),
    )
    selected_layout = layouts[int(selected['layout_number'])]
    evidence = {
        'dominates_nominal_mean_and_p95': bool(selected in eligible),
        'selected_layout_number': int(selected['layout_number']),
        'weighted_mean_error_m': selected['weighted_changed_model_mean_error_m'],
        'worst_p95_error_m': selected['worst_changed_model_p95_error_m'],
        'mean_error_ratio_to_nominal': selected['mean_error_ratio_to_nominal'],
        'p95_error_ratio_to_nominal': selected['p95_error_ratio_to_nominal'],
        'validation_realizations_per_source': int(realizations),
    }
    del reference_locator, noise_draws, errors
    gc.collect()
    return selected_layout, rows, evidence


def _hard_constraint_layout_candidates(
        robust_layout, mean_layout, scenario_layouts, probabilities,
        receiver_count, maximum_candidates, fixed_core_fraction=0.70,
        maximum_movable_receivers=4):
    """Build fixed-core plus limited-movable candidate arrays."""
    receiver_count = int(receiver_count)
    maximum_candidates = int(maximum_candidates)
    if maximum_candidates < 3:
        raise ValueError(
            'FUTURE_VELOCITY_LOCALIZATION_SELECTION_CANDIDATES must be at least 3.'
        )
    records = {}
    fixed_core_fraction = float(fixed_core_fraction)
    maximum_movable_receivers = int(maximum_movable_receivers)
    if not 0.0 < fixed_core_fraction <= 1.0:
        raise ValueError('Fixed-core fraction must lie in (0, 1].')
    if maximum_movable_receivers < 0:
        raise ValueError('Maximum movable receiver count cannot be negative.')
    probabilities = np.asarray(probabilities, dtype=float)
    inclusion = {}
    for probability, layout in zip(probabilities, scenario_layouts):
        for index in np.asarray(layout, dtype=int):
            inclusion[int(index)] = inclusion.get(int(index), 0.0) + float(probability)
    requested_movable = int(np.ceil(
        (1.0 - fixed_core_fraction) * receiver_count
    ))
    movable_count = min(
        maximum_movable_receivers,
        max(0, requested_movable),
        max(0, receiver_count - 1),
    )
    core_count = receiver_count - movable_count
    ranked_inclusion = sorted(
        inclusion, key=lambda index: (-inclusion[index], index)
    )
    fixed_core = tuple(sorted(ranked_inclusion[:core_count]))
    fixed_core_set = set(fixed_core)

    def add(indices, role):
        proposed = [
            int(value) for value in np.asarray(indices).ravel()
            if int(value) not in fixed_core_set
        ]
        selected = list(fixed_core)
        selected.extend(proposed[:max(0, receiver_count - len(selected))])
        if len(selected) < receiver_count:
            selected.extend([
                index for index in ranked_inclusion
                if index not in set(selected)
            ][:receiver_count - len(selected)])
        key = tuple(sorted(selected))
        if len(key) != receiver_count or len(set(key)) != receiver_count:
            return
        if key in records:
            roles = records[key]['candidate_role'].split(' + ')
            if role not in roles:
                records[key]['candidate_role'] += f' + {role}'
            return
        if len(records) < maximum_candidates:
            records[key] = {
                'sensor_indices': list(key),
                'receiver_count': receiver_count,
                'candidate_role': role + ' | fixed-core movable-shell',
                'fixed_core_indices': list(fixed_core),
                'fixed_core_receiver_count': int(core_count),
                'maximum_movable_receiver_count': int(movable_count),
                'respects_fixed_core_constraint': 1,
            }

    add(robust_layout, 'direct robust MCMC')
    add(mean_layout, 'aligned posterior mean')
    consensus = sorted(
        inclusion, key=lambda index: (-inclusion[index], index)
    )[:receiver_count]
    add(consensus, 'posterior inclusion consensus')

    # Add the most probable distinct scenario-conditioned layouts before local
    # exchanges. This preserves physically meaningful alternatives without
    # evaluating every near-duplicate member of a large ensemble.
    for rank, scenario_index in enumerate(
            np.argsort(probabilities)[::-1], start=1):
        add(
            scenario_layouts[int(scenario_index)],
            f'scenario-conditioned rank {rank}',
        )
        if len(records) >= maximum_candidates:
            break

    if len(records) < maximum_candidates:
        current = set(int(value) for value in np.asarray(robust_layout, dtype=int))
        removals = sorted(
            current, key=lambda index: (inclusion.get(index, 0.0), index)
        )
        additions = sorted(
            (index for index in inclusion if index not in current),
            key=lambda index: (-inclusion.get(index, 0.0), index),
        )
        for remove_index in removals:
            for add_index in additions:
                add(
                    sorted((current - {remove_index}) | {add_index}),
                    'one-site posterior exchange',
                )
                if len(records) >= maximum_candidates:
                    break
            if len(records) >= maximum_candidates:
                break
    return list(records.values())


def _normalized_candidate_metric(rows, field):
    """Return min-max normalized finite values for a candidate-table field."""
    values = np.asarray([float(row[field]) for row in rows], dtype=float)
    finite = np.isfinite(values)
    if not np.any(finite):
        return np.ones(values.shape, dtype=float)
    minimum = float(np.min(values[finite]))
    maximum = float(np.max(values[finite]))
    if maximum <= minimum + np.finfo(float).eps:
        normalized = np.zeros(values.shape, dtype=float)
    else:
        normalized = (values - minimum) / (maximum - minimum)
    normalized[~finite] = 1.0
    return np.clip(normalized, 0.0, 1.0)


def _validate_layouts_on_empirical_velocity_holdout(
        reference_phys, common_candidates, layout_records, true_sources,
        noise_model, analytic_state, realizations, seed):
    """Nonlinearly locate held-out empirical-velocity arrivals with reference v.

    Holdout coefficient samples never participate in certainty-space filtering,
    compact-node construction, MCMC, or Fisher/migration objective evaluation.
    They perturb forward arrival times through the independently computed
    source-time Jacobian. SourceLocator then performs the full bounded nonlinear
    differential-time inverse using only reference-velocity splines.
    """
    if analytic_state is None:
        return {}
    holdout = np.asarray(
        analytic_state['empirical_holdout_samples'], dtype=np.float32
    )
    source_jacobian = np.asarray(
        analytic_state['source_time_jacobian'], dtype=np.float32
    )
    reference_times = np.asarray(
        analytic_state['reference_source_times'], dtype=np.float32
    )
    if source_jacobian.shape[:2] != reference_times.shape or (
            source_jacobian.shape[2] != holdout.shape[1]):
        raise ValueError('Empirical holdout/source-time sensitivity shapes mismatch.')
    realizations = int(realizations)
    if realizations < 1:
        raise ValueError('Holdout noise realizations must be positive.')
    true_positions = _source_positions_in_metres(reference_phys, true_sources)
    rng = np.random.default_rng(int(seed) + 42017)
    results = {}
    for record in layout_records:
        key = tuple(sorted(int(value) for value in record['sensor_indices']))
        sensors = [common_candidates[index] for index in key]
        locator = SourceLocator(reference_phys, sensors)
        layout_jacobian = source_jacobian[:, np.asarray(key, dtype=int), :]
        layout_reference_times = reference_times[:, np.asarray(key, dtype=int)]
        errors = []
        failed = 0
        for parameters in holdout:
            perturbed_times = layout_reference_times + np.einsum(
                'srk,k->sr', layout_jacobian, parameters, optimize=True
            )
            for source_index, true_position in enumerate(true_positions):
                for _ in range(realizations):
                    observed = np.asarray(
                        perturbed_times[source_index], dtype=float
                    ) + noise_model.sample(reference_phys, sensors, rng)
                    try:
                        estimate, _, _ = locator._solve_dd(
                            observed, locator.splines
                        )
                        error = float(np.linalg.norm(
                            np.asarray(estimate, dtype=float) - true_position
                        ))
                        if np.isfinite(error):
                            errors.append(error)
                        else:
                            failed += 1
                    except Exception:
                        failed += 1
        errors = np.asarray(errors, dtype=float)
        total = len(holdout) * len(true_sources) * realizations
        failure_fraction = float(failed / max(total, 1))
        if errors.size:
            mean_error = float(np.mean(errors))
            p95_error = float(np.quantile(errors, 0.95))
            maximum_error = float(np.max(errors))
        else:
            mean_error = p95_error = maximum_error = np.inf
        results[key] = {
            'empirical_holdout_mean_error_m': mean_error,
            'empirical_holdout_p95_error_m': p95_error,
            'empirical_holdout_maximum_error_m': maximum_error,
            'empirical_holdout_failure_fraction': failure_fraction,
            'empirical_holdout_sample_count': int(len(holdout)),
            'empirical_holdout_noise_realizations': int(realizations),
            'empirical_holdout_trial_count': int(total),
            'empirical_holdout_passed': int(
                errors.size > 0 and failure_fraction <= 0.05
            ),
        }
        del locator, layout_jacobian, layout_reference_times, errors
        gc.collect()
    return results


def _hierarchical_hard_constraint_layout_selection(
        reference_phys, cases, common_candidates, candidate_records,
        nominal_indices, true_sources, noise_model, realizations, seed,
        robust_optimizer, scenario_layouts_by_count,
        scenario_costs_by_count, probabilities, config, analytic_state=None):
    """Select layout by hard localization constraints, then secondary costs.

    Stage 1 uses nonlinear fixed-reference localization of possible-true-model
    arrivals. Both changed-velocity weighted mean error and worst P95 error must
    satisfy their limits. Stage 2 operates only on that feasible set and blends
    receiver replacements, joint location--velocity Fisher risk, and local
    migration-focus risk. Statistical averaging is therefore only one candidate
    and can never overwrite a better direct robust-MCMC layout by construction.
    """
    nominal_key = tuple(sorted(int(value) for value in nominal_indices))
    unique = {}
    for record in candidate_records:
        key = tuple(sorted(int(value) for value in record['sensor_indices']))
        if key in unique:
            if record['candidate_role'] not in unique[key]['candidate_role']:
                unique[key]['candidate_role'] += (
                    f" + {record['candidate_role']}"
                )
        else:
            unique[key] = dict(record, sensor_indices=list(key))
    if nominal_key not in unique:
        unique[nominal_key] = {
            'sensor_indices': list(nominal_key),
            'receiver_count': len(nominal_key),
            'candidate_role': 'nominal fixed-velocity comparator',
            'fixed_core_indices': [],
            'fixed_core_receiver_count': 0,
            'maximum_movable_receiver_count': len(nominal_key),
            'respects_fixed_core_constraint': 0,
        }
    else:
        unique[nominal_key]['candidate_role'] += (
            ' + nominal fixed-velocity comparator'
        )
    ordered = [unique[nominal_key]] + [
        record for key, record in unique.items() if key != nominal_key
    ]
    if len(ordered) < 2:
        raise RuntimeError('Hard-constraint selection requires distinct layouts.')

    _, localization_rows, _ = _select_layout_by_reference_data_localization(
        reference_phys,
        cases,
        common_candidates,
        [record['sensor_indices'] for record in ordered[1:]],
        nominal_indices,
        true_sources,
        noise_model,
        realizations,
        seed,
    )
    localization_lookup = {
        tuple(sorted(int(value) for value in row['sensor_indices'])): row
        for row in localization_rows
    }
    empirical_holdout_lookup = _validate_layouts_on_empirical_velocity_holdout(
        reference_phys,
        common_candidates,
        ordered,
        true_sources,
        noise_model,
        analytic_state,
        config.get('distribution_free_validation_noise_realizations', 1),
        seed,
    )
    candidate_rows = []
    for record in ordered:
        layout = np.asarray(record['sensor_indices'], dtype=int)
        key = tuple(int(value) for value in layout)
        count = int(len(layout))
        if count not in scenario_layouts_by_count:
            raise RuntimeError(f'No scenario layouts are available for count {count}.')
        robust_optimizer.set_scenario_reference_layouts(
            scenario_layouts_by_count[count], scenario_costs_by_count[count]
        )
        components = robust_optimizer.energy_components(layout)
        movement = _changed_velocity_layout_movement_statistics(
            layout, scenario_layouts_by_count[count], cases, probabilities
        )
        validation = localization_lookup.get(key)
        if validation is None:
            raise RuntimeError('A hard-constraint candidate lacks validation results.')
        empirical_validation = empirical_holdout_lookup.get(key)
        if empirical_validation is None:
            empirical_validation = {
                'empirical_holdout_mean_error_m': float(
                    validation['weighted_changed_model_mean_error_m']
                ),
                'empirical_holdout_p95_error_m': float(
                    validation['worst_changed_model_p95_error_m']
                ),
                'empirical_holdout_maximum_error_m': np.nan,
                'empirical_holdout_failure_fraction': float(
                    validation.get('failed', 0)
                ),
                'empirical_holdout_sample_count': 0,
                'empirical_holdout_noise_realizations': 0,
                'empirical_holdout_trial_count': 0,
                'empirical_holdout_passed': int(
                    not validation.get('failed', 0)
                ),
            }
        candidate_rows.append({
            **record,
            'compressed_node_weighted_mean_error_m': float(
                validation['weighted_changed_model_mean_error_m']
            ),
            'compressed_node_worst_p95_error_m': float(
                validation['worst_changed_model_p95_error_m']
            ),
            'weighted_changed_model_mean_error_m': float(
                empirical_validation['empirical_holdout_mean_error_m']
            ),
            'worst_changed_model_p95_error_m': float(
                empirical_validation['empirical_holdout_p95_error_m']
            ),
            'localization_failed': int(
                validation.get('failed', 0)
                or not empirical_validation['empirical_holdout_passed']
            ),
            **empirical_validation,
            **movement,
            'joint_position_velocity_fisher_risk': float(
                components['joint_position_velocity_fisher_risk']
            ),
            'joint_fisher_p95_maximum_95_axis_m': float(
                components['joint_fisher_p95_maximum_95_axis_m']
            ),
            'joint_fisher_mean_information_retention': float(
                components['joint_fisher_mean_information_retention']
            ),
            'migration_quality_risk': float(
                components['migration_quality_risk']
            ),
            'posterior_p95_expected_migration_quality_loss': float(
                components['posterior_p95_expected_migration_quality_loss']
            ),
            'p95_model_aware_maximum_95_axis_m': float(
                components['p95_model_aware_maximum_95_axis_m']
            ),
            'mean_model_aware_marginal_95_half_width_m': float(
                components['mean_model_aware_marginal_95_half_width_m']
            ),
            'model_error_covariance_trace_m2': float(
                components['model_error_covariance_trace_m2']
            ),
            'common_robust_objective': float(components['robust_loss']),
        })

    valid = [row for row in candidate_rows if not row['localization_failed']]
    if not valid:
        raise RuntimeError('Every hard-constraint layout failed localization.')
    nominal = next(
        row for row in candidate_rows
        if tuple(row['sensor_indices']) == nominal_key
    )
    required_improvement = float(config.get(
        'distribution_free_required_improvement_fraction', 0.0
    ))
    if not 0.0 <= required_improvement < 1.0:
        raise ValueError(
            'DISTRIBUTION_FREE_REQUIRED_IMPROVEMENT must lie in [0, 1).'
        )
    improved = [
        row for row in valid
        if tuple(row['sensor_indices']) != nominal_key
        and row['weighted_changed_model_mean_error_m']
        <= (1.0 - required_improvement)
        * nominal['weighted_changed_model_mean_error_m']
        and row['worst_changed_model_p95_error_m']
        <= (1.0 - required_improvement)
        * nominal['worst_changed_model_p95_error_m']
    ]
    no_worse = [
        row for row in valid
        if row['weighted_changed_model_mean_error_m']
        <= nominal['weighted_changed_model_mean_error_m']
        and row['worst_changed_model_p95_error_m']
        <= nominal['worst_changed_model_p95_error_m']
    ]
    if improved:
        no_worse = improved
    if not no_worse:
        no_worse = [nominal]
    minimum_mean = min(
        row['weighted_changed_model_mean_error_m'] for row in no_worse
    )
    minimum_p95 = min(
        row['worst_changed_model_p95_error_m'] for row in no_worse
    )
    tiny = np.finfo(float).tiny
    anchor = min(
        no_worse,
        key=lambda row: (
            max(
                row['weighted_changed_model_mean_error_m'] / max(minimum_mean, tiny),
                row['worst_changed_model_p95_error_m'] / max(minimum_p95, tiny),
            ),
            row['weighted_changed_model_mean_error_m']
            + row['worst_changed_model_p95_error_m'],
        ),
    )
    tolerance = float(config.get('velocity_robust_count_error_tolerance', 0.02))
    if tolerance < 0.0:
        raise ValueError('FUTURE_ROBUST_COUNT_ERROR_TOLERANCE cannot be negative.')
    explicit_mean = float(config.get('velocity_hard_max_mean_error_m', 0.0))
    explicit_p95 = float(config.get('velocity_hard_max_p95_error_m', 0.0))
    if explicit_mean < 0.0 or explicit_p95 < 0.0:
        raise ValueError('Hard localization limits cannot be negative.')
    mean_limit = (
        explicit_mean if explicit_mean > 0.0
        else min(
            nominal['weighted_changed_model_mean_error_m'],
            (1.0 + tolerance)
            * anchor['weighted_changed_model_mean_error_m'],
        )
    )
    p95_limit = (
        explicit_p95 if explicit_p95 > 0.0
        else min(
            nominal['worst_changed_model_p95_error_m'],
            (1.0 + tolerance) * anchor['worst_changed_model_p95_error_m'],
        )
    )
    feasible = []
    for row in candidate_rows:
        row['hard_mean_error_limit_m'] = float(mean_limit)
        row['hard_p95_error_limit_m'] = float(p95_limit)
        row['passes_mean_error_constraint'] = int(
            not row['localization_failed']
            and row['weighted_changed_model_mean_error_m'] <= mean_limit
        )
        row['passes_p95_error_constraint'] = int(
            not row['localization_failed']
            and row['worst_changed_model_p95_error_m'] <= p95_limit
        )
        row['hard_constraints_feasible'] = int(
            row['passes_mean_error_constraint']
            and row['passes_p95_error_constraint']
        )
        row['selected_hierarchical_layout'] = 0
        if row['hard_constraints_feasible']:
            feasible.append(row)
    if not feasible:
        raise RuntimeError(
            'No observation system satisfies both hard localization limits: '
            f'mean <= {mean_limit:.6g} m and P95 <= {p95_limit:.6g} m. '
            'Increase the receiver-count range/candidate budget or relax the '
            'explicit FUTURE_HARD_MAX_* limits.'
        )

    movement_expected = _normalized_candidate_metric(
        feasible, 'expected_changed_velocity_moved_receiver_count'
    )
    movement_worst = _normalized_candidate_metric(
        feasible, 'worst_changed_velocity_moved_receiver_count'
    )
    fisher_normalized = _normalized_candidate_metric(
        feasible, 'joint_position_velocity_fisher_risk'
    )
    migration_normalized = _normalized_candidate_metric(
        feasible, 'migration_quality_risk'
    )
    mean_error_normalized = _normalized_candidate_metric(
        feasible, 'weighted_changed_model_mean_error_m'
    )
    p95_error_normalized = _normalized_candidate_metric(
        feasible, 'worst_changed_model_p95_error_m'
    )
    interval_normalized = _normalized_candidate_metric(
        feasible, 'p95_model_aware_maximum_95_axis_m'
    )
    # Accuracy is lexicographically prior to receiver movement. Mean/P95 errors
    # dominate, while model-aware interval, joint Fisher, and migration focus
    # prevent a superficially low-error but poorly constrained layout.
    accuracy_weights = np.asarray([0.25, 0.30, 0.20, 0.15, 0.10])
    for index, row in enumerate(feasible):
        row['normalized_movement_secondary_cost'] = float(
            0.70 * movement_expected[index] + 0.30 * movement_worst[index]
        )
        row['normalized_joint_fisher_secondary_cost'] = float(
            fisher_normalized[index]
        )
        row['normalized_migration_secondary_cost'] = float(
            migration_normalized[index]
        )
        row['bayesian_accuracy_objective'] = float(
            accuracy_weights[0] * mean_error_normalized[index]
            + accuracy_weights[1] * p95_error_normalized[index]
            + accuracy_weights[2] * interval_normalized[index]
            + accuracy_weights[3] * fisher_normalized[index]
            + accuracy_weights[4] * migration_normalized[index]
        )
    accuracy_values = np.asarray([
        row['bayesian_accuracy_objective'] for row in feasible
    ], dtype=float)
    accuracy_gate_fraction = float(config.get(
        'final_bayesian_accuracy_gate_fraction', 0.05
    ))
    if not 0.0 <= accuracy_gate_fraction <= 1.0:
        raise ValueError(
            'FINAL_BAYESIAN_ACCURACY_GATE_FRACTION must lie in [0, 1].'
        )
    accuracy_minimum = float(np.min(accuracy_values))
    accuracy_range = float(np.max(accuracy_values) - accuracy_minimum)
    accuracy_limit = accuracy_minimum + accuracy_gate_fraction * accuracy_range
    accuracy_gated = []
    for row in feasible:
        row['bayesian_accuracy_gate_limit'] = float(accuracy_limit)
        row['bayesian_accuracy_gate_passed'] = int(
            row['bayesian_accuracy_objective'] <= accuracy_limit + 1.0e-12
        )
        # Movement is evaluated only inside the near-optimal accuracy set.
        row['secondary_feasible_objective'] = (
            row['normalized_movement_secondary_cost']
            if row['bayesian_accuracy_gate_passed'] else np.inf
        )
        if row['bayesian_accuracy_gate_passed']:
            accuracy_gated.append(row)
    for row in candidate_rows:
        if not row['hard_constraints_feasible']:
            row['normalized_movement_secondary_cost'] = np.nan
            row['normalized_joint_fisher_secondary_cost'] = np.nan
            row['normalized_migration_secondary_cost'] = np.nan
            row['bayesian_accuracy_objective'] = np.inf
            row['bayesian_accuracy_gate_limit'] = float(accuracy_limit)
            row['bayesian_accuracy_gate_passed'] = 0
            row['secondary_feasible_objective'] = np.inf
    selected = min(
        accuracy_gated,
        key=lambda row: (
            row['secondary_feasible_objective'],
            row['bayesian_accuracy_objective'],
            row['expected_changed_velocity_moved_receiver_count'],
            row['worst_changed_velocity_moved_receiver_count'],
            row['common_robust_objective'],
            row['receiver_count'],
        ),
    )
    selected['selected_hierarchical_layout'] = 1

    count_rows = []
    for count in sorted({int(row['receiver_count']) for row in candidate_rows}):
        group = [row for row in candidate_rows if int(row['receiver_count']) == count]
        group_feasible = [row for row in group if row['hard_constraints_feasible']]
        group_accuracy_gated = [
            row for row in group_feasible if row['bayesian_accuracy_gate_passed']
        ]
        if group_accuracy_gated:
            best = min(
                group_accuracy_gated,
                key=lambda row: (
                    row['secondary_feasible_objective'],
                    row['bayesian_accuracy_objective'],
                    row['common_robust_objective'],
                ),
            )
        elif group_feasible:
            best = min(
                group_feasible,
                key=lambda row: (
                    row['bayesian_accuracy_objective'],
                    row['common_robust_objective'],
                ),
            )
        else:
            best = min(
                group,
                key=lambda row: max(
                    row['weighted_changed_model_mean_error_m'] / max(mean_limit, tiny),
                    row['worst_changed_model_p95_error_m'] / max(p95_limit, tiny),
                ),
            )
        count_rows.append({
            **best,
            'robust_receiver_count': count,
            'within_near_minimum_error_set': int(bool(group_accuracy_gated)),
            'selected_independent_robust_count': int(
                count == int(selected['receiver_count'])
            ),
        })
    evidence = {
        'selection_method': (
            'hard mean/P95 constraints, followed by a near-optimal Bayesian '
            'accuracy gate using mean/P95/interval/Fisher/migration terms, '
            'followed by receiver movement as the secondary objective'
        ),
        'selected_robust_receiver_count': int(selected['receiver_count']),
        'selected_sensor_indices': list(selected['sensor_indices']),
        'selected_candidate_role': selected['candidate_role'],
        'selected_fixed_core_indices': list(selected.get(
            'fixed_core_indices', []
        )),
        'selected_fixed_core_receiver_count': int(selected.get(
            'fixed_core_receiver_count', 0
        )),
        'selected_maximum_movable_receiver_count': int(selected.get(
            'maximum_movable_receiver_count', len(selected['sensor_indices'])
        )),
        'selected_respects_fixed_core_constraint': bool(selected.get(
            'respects_fixed_core_constraint', 0
        )),
        'selected_is_direct_robust_mcmc': bool(
            'direct robust MCMC' in selected['candidate_role']
        ),
        'selected_is_statistical_mean': bool(
            'aligned posterior mean' in selected['candidate_role']
        ),
        'statistical_mean_is_only_a_candidate': True,
        'hard_mean_error_limit_m': float(mean_limit),
        'hard_p95_error_limit_m': float(p95_limit),
        'limits_are_user_supplied': bool(
            explicit_mean > 0.0 or explicit_p95 > 0.0
        ),
        'validation_realizations_per_source': int(realizations),
        'independent_empirical_holdout_used': bool(analytic_state is not None),
        'independent_empirical_holdout_sample_count': int(selected.get(
            'empirical_holdout_sample_count', 0
        )),
        'required_improvement_fraction': float(required_improvement),
        'any_candidate_improves_nominal_mean_and_p95': bool(improved),
        'selected_improves_nominal_mean_and_p95': bool(
            tuple(selected['sensor_indices']) != nominal_key
            and selected['weighted_changed_model_mean_error_m']
            <= (1.0 - required_improvement)
            * nominal['weighted_changed_model_mean_error_m']
            and selected['worst_changed_model_p95_error_m']
            <= (1.0 - required_improvement)
            * nominal['worst_changed_model_p95_error_m']
        ),
        'feasible_candidate_count': len(feasible),
        'total_candidate_count': len(candidate_rows),
        'selected_weighted_changed_model_mean_error_m': float(
            selected['weighted_changed_model_mean_error_m']
        ),
        'selected_worst_changed_model_p95_error_m': float(
            selected['worst_changed_model_p95_error_m']
        ),
        'selected_expected_moved_receiver_count': float(
            selected['expected_changed_velocity_moved_receiver_count']
        ),
        'selected_joint_position_velocity_fisher_risk': float(
            selected['joint_position_velocity_fisher_risk']
        ),
        'selected_migration_quality_risk': float(
            selected['migration_quality_risk']
        ),
        'bayesian_accuracy_gate_fraction': float(accuracy_gate_fraction),
        'bayesian_accuracy_gate_limit': float(accuracy_limit),
        'bayesian_accuracy_gated_candidate_count': int(len(accuracy_gated)),
        'bayesian_accuracy_weights': {
            'mean_error': float(accuracy_weights[0]),
            'p95_error': float(accuracy_weights[1]),
            'model_aware_interval': float(accuracy_weights[2]),
            'joint_fisher': float(accuracy_weights[3]),
            'migration_quality': float(accuracy_weights[4]),
        },
        'movement_is_secondary_only_after_accuracy_gate': True,
    }
    return (
        np.asarray(selected['sensor_indices'], dtype=int),
        candidate_rows,
        count_rows,
        evidence,
    )


def plot_ensemble_velocity_robust_results(summary_rows, design_records,
                                          count_curve, output_dir):
    scenarios = []
    for row in summary_rows:
        if row['scenario'] not in scenarios:
            scenarios.append(row['scenario'])
    designs = ['Nominal-model design', 'Ensemble-CVaR robust design']
    colors = {
        'Nominal-model design': C_RND,
        'Ensemble-CVaR robust design': C_OPT,
    }
    lookup = {
        (row['scenario'], row['design']): row for row in summary_rows
    }
    x_values = np.arange(len(scenarios), dtype=float)
    bar_width = 0.36
    fig, axes = plt.subplots(1, 3, figsize=(17.0, 5.5))
    for design_index, design in enumerate(designs):
        offset = (design_index - 0.5) * bar_width
        axes[0].bar(
            x_values + offset,
            [lookup[(scenario, design)]['mean_error_m'] for scenario in scenarios],
            width=bar_width, color=colors[design], edgecolor='black',
            label=design,
        )
        axes[1].bar(
            x_values + offset,
            [lookup[(scenario, design)]['p95_error_m'] for scenario in scenarios],
            width=bar_width, color=colors[design], edgecolor='black',
            label=design,
        )
    for axis, ylabel, title in (
            (axes[0], 'Mean location error (m)', '(a) Mean error by velocity model'),
            (axes[1], '95th-percentile error (m)', '(b) Upper-tail error by velocity model')):
        axis.set_xticks(x_values, scenarios, rotation=25, ha='right')
        axis.set_ylabel(ylabel)
        axis.set_title(title)
        axis.grid(axis='y', linestyle='--', alpha=0.45)
    axes[0].legend(loc='best')
    axes[2].plot(
        count_curve['sensor_counts'], count_curve['robust_costs'],
        color=C_OPT, marker='o', linewidth=2.0, label='Robust objective',
    )
    axes[2].plot(
        count_curve['sensor_counts'], count_curve['nominal_costs'],
        color=C_RND, marker='s', linewidth=1.8, label='Nominal objective',
    )
    axes[2].axvline(
        design_records['selected_number_of_geophones'], color='black',
        linestyle='-', linewidth=1.8, label='Independent robust count',
    )
    fixed_count = design_records.get(
        'fixed_baseline_number_of_geophones',
        design_records['selected_number_of_geophones'],
    )
    if fixed_count != design_records['selected_number_of_geophones']:
        axes[2].axvline(
            fixed_count, color='0.45', linestyle='--', linewidth=1.6,
            label='Nominal/uniform/random count',
        )
    unconstrained_k = design_records.get(
        'unconstrained_elbow_number_of_geophones',
        design_records['selected_number_of_geophones'],
    )
    if unconstrained_k != design_records['selected_number_of_geophones']:
        axes[2].axvline(
            unconstrained_k, color='0.4', linestyle=':', linewidth=1.6,
            label='Economy-oriented elbow',
        )
    axes[2].set_xlabel('Number of geophones')
    axes[2].set_ylabel('Dimensionless design loss')
    axes[2].set_title('(c) Independent receiver-count selection')
    axes[2].grid(True, linestyle='--', alpha=0.45)
    replacement_axis = axes[2].twinx()
    replacement_axis.plot(
        count_curve['sensor_counts'],
        100.0 * np.asarray(count_curve['expected_replacement_fractions']),
        color='#6A4C93', marker='^', linewidth=1.5, linestyle='--',
        label='Expected receiver replacement',
    )
    replacement_axis.plot(
        count_curve['sensor_counts'],
        100.0 * np.asarray(count_curve['cvar_replacement_fractions']),
        color='#F4A261', marker='v', linewidth=1.5, linestyle=':',
        label='Tail receiver replacement',
    )
    replacement_axis.set_ylabel('Receiver replacement (%)')
    lines, labels = axes[2].get_legend_handles_labels()
    extra_lines, extra_labels = replacement_axis.get_legend_handles_labels()
    axes[2].legend(lines + extra_lines, labels + extra_labels, loc='best')
    fig.suptitle(
        'Ensemble-velocity robust Bayesian observation-system design',
        fontsize=14,
    )
    fig.tight_layout()
    fig.savefig(
        os.path.join(output_dir, 'Figure_Ensemble_Velocity_Robust_Design.png'),
        bbox_inches='tight', dpi=300,
    )
    plt.close(fig)


def _validated_optimized_receiver_positions(sensors, physics):
    """Convert 2-D or 3-D receiver grid nodes to physical coordinates."""
    dimensions = int(physics.dims)
    if dimensions not in (2, 3):
        raise ValueError(
            'Final observation plotting supports only 2-D or 3-D models.'
        )
    positions = np.asarray(sensors, dtype=float)
    if positions.size == 0:
        raise ValueError('The final optimized receiver array is empty.')
    positions = np.atleast_2d(positions)
    spacing = np.asarray(physics.spacing, dtype=float)
    if positions.shape[1] != dimensions or spacing.shape != (dimensions,):
        raise ValueError(
            f'Final receiver coordinates must have shape (N, {dimensions}); '
            f'got {positions.shape} with spacing shape {spacing.shape}.'
        )
    if not np.isfinite(positions).all() or not np.isfinite(spacing).all():
        raise ValueError('Receiver coordinates and spacing must be finite.')
    if np.any(spacing <= 0.0):
        raise ValueError('Grid spacing must be strictly positive.')
    rounded = np.rint(positions)
    if not np.array_equal(positions, rounded):
        raise ValueError('Receiver grid coordinates must be integers.')
    nodes = rounded.astype(np.int64)
    model_shape = np.asarray(physics.shape, dtype=np.int64)
    if np.any(nodes < 0) or np.any(nodes >= model_shape):
        raise IndexError('A final optimized receiver lies outside the model grid.')
    if len(np.unique(nodes, axis=0)) != len(nodes):
        raise ValueError('The final optimized receiver nodes are not unique.')
    return positions * spacing[None, :]


def _validated_seam3d_receiver_positions(sensors, physics):
    """Backward-compatible 3-D receiver-coordinate validation wrapper."""
    if int(physics.dims) != 3:
        raise ValueError('SEAM3D receiver plotting requires a 3-D model.')
    return _validated_optimized_receiver_positions(sensors, physics)


def _seam3d_slice_indices(physics):
    """Resolve bounded 3-D slice indices, with optional environment overrides."""
    defaults = tuple((int(size) - 1) // 2 for size in physics.shape)
    name_pairs = (
        ('FINAL_3D_SLICE_X_INDEX', 'FINAL_SEAM3D_SLICE_X_INDEX'),
        ('FINAL_3D_SLICE_Y_INDEX', 'FINAL_SEAM3D_SLICE_Y_INDEX'),
        ('FINAL_3D_SLICE_Z_INDEX', 'FINAL_SEAM3D_SLICE_Z_INDEX'),
    )
    indices = []
    for dimension, (names, default) in enumerate(zip(name_pairs, defaults)):
        generic_name, legacy_name = names
        raw_value = os.getenv(
            generic_name, os.getenv(legacy_name, str(default))
        )
        value = int(raw_value)
        if not 0 <= value < int(physics.shape[dimension]):
            raise ValueError(
                f'{generic_name}={value} is outside [0, '
                f'{int(physics.shape[dimension]) - 1}].'
            )
        indices.append(value)
    return tuple(indices)


def _plot_seam3d_orthogonal_velocity_slices(axis, physics):
    """Draw target-independent X-Y, X-Z and Y-Z reference-velocity slices."""
    velocity = np.asarray(physics.V, dtype=float)
    if velocity.ndim != 3 or velocity.shape != tuple(physics.shape):
        raise ValueError(
            '3-D slice plotting requires a velocity array matching '
            'reference_phys.shape.'
        )
    if not np.isfinite(velocity).all():
        raise ValueError('The 3-D reference velocity contains non-finite values.')
    spacing = np.asarray(physics.spacing, dtype=float)
    ix, iy, iz = _seam3d_slice_indices(physics)
    x = np.arange(velocity.shape[0], dtype=float) * spacing[0]
    y = np.arange(velocity.shape[1], dtype=float) * spacing[1]
    z = np.arange(velocity.shape[2], dtype=float) * spacing[2]
    normalizer = plt.Normalize(
        vmin=float(np.min(velocity)), vmax=float(np.max(velocity))
    )
    colour_map = plt.get_cmap('turbo')
    surface_options = dict(
        rstride=1, cstride=1, linewidth=0.0,
        antialiased=False, shade=False, alpha=0.88,
    )

    x_xy, y_xy = np.meshgrid(x, y, indexing='ij')
    axis.plot_surface(
        x_xy, y_xy, np.full_like(x_xy, z[iz]),
        facecolors=colour_map(normalizer(velocity[:, :, iz])),
        **surface_options,
    )
    x_xz, z_xz = np.meshgrid(x, z, indexing='ij')
    axis.plot_surface(
        x_xz, np.full_like(x_xz, y[iy]), z_xz,
        facecolors=colour_map(normalizer(velocity[:, iy, :])),
        **surface_options,
    )
    y_yz, z_yz = np.meshgrid(y, z, indexing='ij')
    axis.plot_surface(
        np.full_like(y_yz, x[ix]), y_yz, z_yz,
        facecolors=colour_map(normalizer(velocity[ix, :, :])),
        **surface_options,
    )

    model_maximum = (
        (np.asarray(physics.shape, dtype=float) - 1.0) * spacing
    )
    padding = np.maximum(2.0 * spacing, 0.04 * model_maximum)
    axis.set_xlim(-padding[0], model_maximum[0] + padding[0])
    axis.set_ylim(-padding[1], model_maximum[1] + padding[1])
    axis.set_zlim(model_maximum[2] + padding[2], -padding[2])
    axis.set_box_aspect(model_maximum + 2.0 * padding)
    axis.view_init(elev=25, azim=132)
    if hasattr(axis, 'set_proj_type'):
        axis.set_proj_type('ortho')
    scalar_mappable = plt.cm.ScalarMappable(norm=normalizer, cmap=colour_map)
    scalar_mappable.set_array(velocity)
    return scalar_mappable, (ix, iy, iz)


def _projected_receiver_offsets(point_count, downward=False):
    """Return bounded point offsets that expose coincident 2-D projections."""
    point_count = int(point_count)
    if point_count <= 1:
        return [(0.0, 0.0)]
    columns = min(5, int(np.ceil(np.sqrt(point_count))))
    rows = int(np.ceil(point_count / columns))
    spacing_points = 8.5
    offsets = []
    for number in range(point_count):
        row, column = divmod(number, columns)
        row_count = min(columns, point_count - row * columns)
        x_offset = (column - 0.5 * (row_count - 1)) * spacing_points
        if downward:
            y_offset = -(row + 0.65) * spacing_points
        else:
            y_offset = (0.5 * (rows - 1) - row) * spacing_points
        offsets.append((float(x_offset), float(y_offset)))
    return offsets


def _plot_optimized_receiver_projection(
        axis, positions, horizontal_dimension, vertical_dimension,
        horizontal_label, vertical_label, spacing, invert_vertical=False):
    """Plot every optimized receiver, fanning only exact projected coincidences."""
    projected = positions[:, [horizontal_dimension, vertical_dimension]]
    groups = OrderedDict()
    for receiver_number, point in enumerate(projected):
        key = tuple(float(value) for value in point)
        groups.setdefault(key, []).append(receiver_number)
    first_marker = True
    maximum_group_size = 1
    for point, receiver_numbers in groups.items():
        maximum_group_size = max(maximum_group_size, len(receiver_numbers))
        offsets = _projected_receiver_offsets(
            len(receiver_numbers),
            downward=(invert_vertical and point[1] == float(np.min(projected[:, 1]))),
        )
        for x_offset, y_offset in offsets:
            display_offset = transforms.ScaledTranslation(
                x_offset / 72.0, y_offset / 72.0,
                axis.figure.dpi_scale_trans,
            )
            axis.scatter(
                [point[0]], [point[1]], s=76, marker='v',
                c=C_OPT, edgecolors='black', linewidths=0.70,
                alpha=0.94, clip_on=False, zorder=5,
                transform=axis.transData + display_offset,
                label=(f'Optimized receivers (N={len(positions)})'
                       if first_marker else None),
            )
            first_marker = False

    horizontal_span = max(
        float(np.ptp(projected[:, 0])), 6.0 * float(spacing[horizontal_dimension])
    )
    vertical_span = max(
        float(np.ptp(projected[:, 1])), 6.0 * float(spacing[vertical_dimension])
    )
    horizontal_padding = max(
        3.0 * float(spacing[horizontal_dimension]), 0.075 * horizontal_span
    )
    vertical_padding = max(
        3.0 * float(spacing[vertical_dimension]), 0.075 * vertical_span
    )
    axis.set_xlim(
        float(np.min(projected[:, 0])) - horizontal_padding,
        float(np.max(projected[:, 0])) + horizontal_padding,
    )
    vertical_limits = (
        float(np.min(projected[:, 1])) - vertical_padding,
        float(np.max(projected[:, 1])) + vertical_padding,
    )
    axis.set_ylim(
        vertical_limits[1], vertical_limits[0]
    ) if invert_vertical else axis.set_ylim(*vertical_limits)
    axis.set_xlabel(horizontal_label)
    axis.set_ylabel(vertical_label)
    axis.grid(True, linestyle='--', linewidth=0.75, alpha=0.38)
    axis.set_axisbelow(True)
    return maximum_group_size


def _validate_final_observation_figure_layout(figure, panel_axes):
    """Fail before export if panel, title, or fixed-label geometry is unsafe."""
    figure.canvas.draw()
    renderer = figure.canvas.get_renderer()
    panel_boxes = [axis.get_window_extent(renderer) for axis in panel_axes]
    title_boxes = [
        axis.title.get_window_extent(renderer)
        for axis in panel_axes if axis.title.get_text().strip()
    ]
    panel_overlap = any(
        left.overlaps(right)
        for number, left in enumerate(panel_boxes)
        for right in panel_boxes[number + 1:]
    )
    title_overlap = any(
        left.overlaps(right)
        for number, left in enumerate(title_boxes)
        for right in title_boxes[number + 1:]
    )
    suptitle_overlap = (
        figure._suptitle is not None
        and any(figure._suptitle.get_window_extent(renderer).overlaps(box)
                for box in title_boxes)
    )

    fixed_artists = list(figure.texts)
    for axis in panel_axes:
        fixed_artists.extend((
            axis.title, axis.xaxis.label, axis.yaxis.label,
        ))
        if hasattr(axis, 'zaxis'):
            fixed_artists.append(axis.zaxis.label)
    unique_artists = []
    observed_ids = set()
    for artist in fixed_artists:
        if (id(artist) in observed_ids or not artist.get_visible()
                or not artist.get_text().strip()):
            continue
        observed_ids.add(id(artist))
        unique_artists.append(artist)
    fixed_boxes = [artist.get_window_extent(renderer) for artist in unique_artists]
    fixed_overlap = any(
        left.overlaps(right)
        for number, left in enumerate(fixed_boxes)
        for right in fixed_boxes[number + 1:]
    )
    width, height = figure.canvas.get_width_height()
    outside_canvas = any(
        box.x0 < 0.0 or box.y0 < 0.0
        or box.x1 > float(width) or box.y1 > float(height)
        for box in fixed_boxes
    )
    if (panel_overlap or title_overlap or suptitle_overlap
            or fixed_overlap or outside_canvas):
        raise RuntimeError(
            'The final observation-system layout overlaps or crosses the '
            'canvas boundary. Increase the figure size, axes padding, or '
            'GridSpec spacing before export.'
        )


def _validate_seam3d_final_figure_layout(figure, panel_axes):
    """Backward-compatible name for final-figure layout validation."""
    return _validate_final_observation_figure_layout(figure, panel_axes)


def _plot_final_2d_optimized_observation_system(
        reference_phys, robust_sensors, output_dir):
    """Create a 2-D velocity panel and optimized-only receiver distribution."""
    if int(reference_phys.dims) != 2:
        raise ValueError('The 2-D final figure requires a 2-D physics model.')
    velocity = np.asarray(reference_phys.V, dtype=float)
    if velocity.ndim != 2 or velocity.shape != tuple(reference_phys.shape):
        raise ValueError(
            'The 2-D velocity array must match reference_phys.shape.'
        )
    if not np.isfinite(velocity).all():
        raise ValueError('The 2-D reference velocity contains non-finite values.')
    receiver_positions = _validated_optimized_receiver_positions(
        robust_sensors, reference_phys
    )
    spacing = np.asarray(reference_phys.spacing, dtype=float)
    model_maximum = (
        (np.asarray(reference_phys.shape, dtype=float) - 1.0) * spacing
    )
    model_padding = np.maximum(2.0 * spacing, 0.04 * model_maximum)
    os.makedirs(output_dir, exist_ok=True)
    figure_path = os.path.join(
        output_dir, 'Figure_Final_Velocity_Robust_Observation_System.png'
    )
    figure = plt.figure(figsize=(15.8, 8.2), dpi=100)
    try:
        grid = figure.add_gridspec(
            2, 3,
            width_ratios=(1.16, 0.045, 1.0),
            height_ratios=(1.0, 0.12),
            left=0.065, right=0.965, bottom=0.060, top=0.855,
            wspace=0.29, hspace=0.18,
        )
        velocity_axis = figure.add_subplot(grid[0, 0])
        colorbar_axis = figure.add_subplot(grid[0, 1])
        receiver_axis = figure.add_subplot(grid[0, 2])
        legend_axis = figure.add_subplot(grid[1, :])
        legend_axis.set_axis_off()

        velocity_artist = velocity_axis.imshow(
            velocity.T,
            cmap='turbo', origin='upper', interpolation='nearest',
            extent=(0.0, model_maximum[0], model_maximum[1], 0.0),
            aspect='auto',
            vmin=float(np.min(velocity)), vmax=float(np.max(velocity)),
        )
        velocity_axis.set_xlim(
            -model_padding[0], model_maximum[0] + model_padding[0]
        )
        velocity_axis.set_ylim(
            model_maximum[1] + model_padding[1], -model_padding[1]
        )
        velocity_axis.set_xlabel('X (m)')
        velocity_axis.set_ylabel('Depth Z (m)')
        velocity_axis.set_title(
            '(a) 2-D reference velocity model', fontsize=12.5, pad=12
        )
        colorbar = figure.colorbar(velocity_artist, cax=colorbar_axis)
        colorbar.set_label('Velocity (m/s)', labelpad=8)
        colorbar_axis.yaxis.set_label_position('left')

        maximum_multiplicity = _plot_optimized_receiver_projection(
            receiver_axis, receiver_positions, 0, 1,
            'X (m)', 'Depth Z (m)', spacing, invert_vertical=True,
        )
        receiver_axis.set_title(
            '(b) Optimized receiver X–depth distribution',
            fontsize=12.5, pad=12,
        )
        handles, labels = receiver_axis.get_legend_handles_labels()
        legend_axis.legend(
            handles, labels, loc='center', ncol=1, frameon=True,
            fontsize=10.5, handletextpad=0.70,
        )
        figure.suptitle(
            'Final optimized 2-D observation system',
            fontsize=15.0, y=0.965,
        )
        figure.text(
            0.50, 0.027,
            'Only the final optimized receiver array is shown. '
            'Coincident locations are fanned in display space only '
            f'(maximum multiplicity: {maximum_multiplicity}).',
            ha='center', va='bottom', fontsize=8.5,
        )
        _validate_final_observation_figure_layout(
            figure, (velocity_axis, colorbar_axis, receiver_axis)
        )
        fixed_bbox_inches = transforms.Bbox.from_bounds(
            0.0, 0.0, *figure.get_size_inches()
        )
        _MATPLOTLIB_FIGURE_SAVEFIG(
            figure, figure_path, dpi=300, facecolor='white',
            bbox_inches=fixed_bbox_inches, pad_inches=0.0,
        )
        return figure_path
    finally:
        plt.close(figure)


def _plot_final_seam3d_optimized_observation_system(
        reference_phys, robust_sensors, output_dir):
    """Create one 3-D velocity-slice panel and two optimized-array projections."""
    receiver_positions = _validated_seam3d_receiver_positions(
        robust_sensors, reference_phys
    )
    spacing = np.asarray(reference_phys.spacing, dtype=float)
    os.makedirs(output_dir, exist_ok=True)
    figure_path = os.path.join(
        output_dir, 'Figure_Final_Velocity_Robust_Observation_System.png'
    )
    figure = plt.figure(figsize=(18.8, 8.4), dpi=100)
    try:
        grid = figure.add_gridspec(
            2, 4,
            width_ratios=(1.34, 0.045, 1.0, 1.0),
            height_ratios=(1.0, 0.12),
            left=0.045, right=0.975, bottom=0.055, top=0.865,
            wspace=0.31, hspace=0.16,
        )
        velocity_axis = figure.add_subplot(grid[0, 0], projection='3d')
        colorbar_axis = figure.add_subplot(grid[0, 1])
        xy_axis = figure.add_subplot(grid[0, 2])
        xz_axis = figure.add_subplot(grid[0, 3])
        legend_axis = figure.add_subplot(grid[1, :])
        legend_axis.set_axis_off()

        velocity_artist, slice_indices = _plot_seam3d_orthogonal_velocity_slices(
            velocity_axis, reference_phys
        )
        velocity_axis.set_xlabel('X (m)', labelpad=8)
        velocity_axis.set_ylabel('Y (m)', labelpad=8)
        velocity_axis.set_zlabel('Depth Z (m)', labelpad=8)
        velocity_axis.set_title(
            '(a) 3-D orthogonal velocity slices', fontsize=12.5, pad=12
        )
        colorbar = figure.colorbar(velocity_artist, cax=colorbar_axis)
        colorbar.set_label('Velocity (m/s)', labelpad=8)
        colorbar_axis.yaxis.set_label_position('left')

        xy_multiplicity = _plot_optimized_receiver_projection(
            xy_axis, receiver_positions, 0, 1,
            'X (m)', 'Y (m)', spacing, invert_vertical=False,
        )
        xy_axis.set_title(
            '(b) Optimized receiver X–Y distribution', fontsize=12.5, pad=12
        )
        xy_axis.set_aspect('equal', adjustable='box')

        xz_multiplicity = _plot_optimized_receiver_projection(
            xz_axis, receiver_positions, 0, 2,
            'X (m)', 'Depth Z (m)', spacing, invert_vertical=True,
        )
        xz_axis.set_title(
            '(c) Optimized receiver X–depth distribution', fontsize=12.5, pad=12
        )

        handles, labels = xy_axis.get_legend_handles_labels()
        legend_axis.legend(
            handles, labels, loc='center', ncol=1, frameon=True,
            fontsize=10.5, handletextpad=0.70,
        )
        ix, iy, iz = slice_indices
        figure.suptitle(
            'Final optimized 3-D observation system',
            fontsize=15.0, y=0.965,
        )
        figure.text(
            0.50, 0.026,
            'Velocity slices: '
            f'X={ix * spacing[0]:.0f} m, '
            f'Y={iy * spacing[1]:.0f} m, '
            f'Z={iz * spacing[2]:.0f} m. '
            'Coincident 2-D projections are fanned in display space only '
            f'(maximum multiplicity: X–Y {xy_multiplicity}, '
            f'X–depth {xz_multiplicity}).',
            ha='center', va='bottom', fontsize=8.5,
        )
        _validate_final_observation_figure_layout(
            figure, (velocity_axis, colorbar_axis, xy_axis, xz_axis)
        )
        # This manual layout has already been bounded and checked. Calling the
        # saved original method avoids the global adaptive wrapper moving titles
        # or projected points immediately before export.  A fixed canvas is used
        # instead of bbox_inches='tight': the latter performs a second full
        # high-resolution render and can derive a huge bounding box from 3-D or
        # display-offset artists, which caused the reported std::bad_alloc.
        fixed_bbox_inches = transforms.Bbox.from_bounds(
            0.0, 0.0, *figure.get_size_inches()
        )
        _MATPLOTLIB_FIGURE_SAVEFIG(
            figure, figure_path, dpi=300, facecolor='white',
            bbox_inches=fixed_bbox_inches, pad_inches=0.0,
        )
        return figure_path
    finally:
        plt.close(figure)


def _selected_optimized_receiver_nodes(reference_physics, selected_designs):
    """Recover and validate the active 2-D or 3-D optimized receiver nodes."""
    dimensions = int(reference_physics.dims)
    if dimensions not in (2, 3):
        raise ValueError(
            'Final observation plotting supports only 2-D or 3-D models.'
        )
    if not isinstance(selected_designs, dict):
        raise TypeError('selected_designs must be a dictionary.')

    candidate_values = np.asarray(
        selected_designs.get('candidate_receiver_indices', []), dtype=float
    )
    if (candidate_values.ndim != 2
            or candidate_values.shape[1] != dimensions):
        raise ValueError(
            'candidate_receiver_indices must have shape '
            f'(N, {dimensions}); '
            f'got {candidate_values.shape}.'
        )
    if len(candidate_values) == 0 or not np.isfinite(candidate_values).all():
        raise ValueError(
            'candidate_receiver_indices must contain finite grid nodes.'
        )
    rounded_candidates = np.rint(candidate_values)
    if not np.array_equal(candidate_values, rounded_candidates):
        raise ValueError('Candidate receiver grid indices must be integers.')
    candidate_nodes = rounded_candidates.astype(np.int64)

    selected_values = np.asarray(
        selected_designs.get('proposed_receiver_candidate_numbers', []),
        dtype=float,
    )
    if selected_values.ndim != 1 or len(selected_values) == 0:
        raise ValueError(
            'proposed_receiver_candidate_numbers must be a non-empty vector.'
        )
    if not np.isfinite(selected_values).all():
        raise ValueError('Selected receiver numbers must be finite.')
    rounded_selected = np.rint(selected_values)
    if not np.array_equal(selected_values, rounded_selected):
        raise ValueError('Selected receiver numbers must be integers.')
    selected_numbers = rounded_selected.astype(np.int64)
    if len(np.unique(selected_numbers)) != len(selected_numbers):
        raise ValueError('The optimized receiver selection has duplicates.')
    if np.any(selected_numbers < 0) or np.any(
            selected_numbers >= len(candidate_nodes)):
        raise IndexError(
            'An optimized receiver number is outside the active candidate pool.'
        )

    optimized_nodes = candidate_nodes[selected_numbers]
    model_shape = np.asarray(reference_physics.shape, dtype=np.int64)
    if np.any(optimized_nodes < 0) or np.any(optimized_nodes >= model_shape):
        raise IndexError(
            'An optimized receiver node lies outside the velocity grid.'
        )
    if len(np.unique(optimized_nodes, axis=0)) != len(optimized_nodes):
        raise ValueError('The optimized receiver nodes are not unique.')
    return [tuple(map(int, node)) for node in optimized_nodes]


def _write_active_final_observation_system(
        reference_physics, selected_designs, output_dir):
    """Write the active optimized-only final figure for a 2-D or 3-D model.

    The robust workflow stores selected receivers as indices into its bounded
    candidate pool.  The resolved nodes therefore match the installed design
    exactly and no inactive legacy optimization needs to be rerun for plotting.
    """
    dimensions = int(reference_physics.dims)
    optimized_nodes = _selected_optimized_receiver_nodes(
        reference_physics, selected_designs
    )

    final_output_dir = os.path.join(
        output_dir,
        'future_marmousi_adaptive_core_bayesian_posterior_design',
    )
    print(
        f'>>> Writing active optimized-only {dimensions}-D observation system: '
        f'{final_output_dir}'
    )
    if dimensions == 2:
        figure_path = _plot_final_2d_optimized_observation_system(
            reference_physics, optimized_nodes, final_output_dir
        )
    elif dimensions == 3:
        figure_path = _plot_final_seam3d_optimized_observation_system(
            reference_physics, optimized_nodes, final_output_dir
        )
    else:
        raise ValueError(
            'Final observation plotting supports only 2-D or 3-D models.'
        )
    if not os.path.isfile(figure_path) or os.path.getsize(figure_path) <= 0:
        raise IOError(
            'The final observation-system figure was not written: '
            f'{figure_path}'
        )
    print(
        f'>>> Final optimized {dimensions}-D observation-system figure: '
        f'{figure_path}'
    )
    return figure_path


def _write_active_seam3d_final_observation_system(
        reference_physics, selected_designs, output_dir):
    """Backward-compatible entry point retained for existing user scripts."""
    if int(reference_physics.dims) != 3:
        return None
    return _write_active_final_observation_system(
        reference_physics, selected_designs, output_dir
    )


def plot_final_velocity_robust_observation_system(reference_phys, candidates,
                                                  targets, cases,
                                                  robust_sensors,
                                                  nominal_sensors,
                                                  localization_rows,
                                                  uncertainty_summary,
                                                  design_records,
                                                  output_dir):
    """Plot the dimension-aware final optimized observation system."""
    if reference_phys.dims == 3:
        return _plot_final_seam3d_optimized_observation_system(
            reference_phys, robust_sensors, output_dir
        )
    if (reference_phys.dims == 2
            and os.getenv('FINAL_OBSERVATION_LEGACY_DIAGNOSTICS', '0') != '1'):
        return _plot_final_2d_optimized_observation_system(
            reference_phys, robust_sensors, output_dir
        )
    if reference_phys.dims != 2:
        raise ValueError('Final observation plotting supports only 2-D or 3-D models.')
    cases = _posterior_plot_cases(cases, maximum_models=16)
    spacing = np.asarray(reference_phys.spacing, dtype=float)
    extent = [
        0.0,
        (reference_phys.shape[0] - 1) * spacing[0],
        (reference_phys.shape[1] - 1) * spacing[1],
        0.0,
    ]
    candidate_positions = np.asarray(candidates, dtype=float) * spacing
    target_positions = np.asarray(targets, dtype=float) * spacing
    robust_positions = np.asarray(robust_sensors, dtype=float) * spacing
    nominal_positions = np.asarray(nominal_sensors, dtype=float) * spacing
    nominal_set = {tuple(sensor) for sensor in nominal_sensors}
    common_positions = np.asarray(
        [sensor for sensor in robust_sensors if tuple(sensor) in nominal_set],
        dtype=float,
    )
    if common_positions.size:
        common_positions *= spacing

    robust_name = 'Ensemble-CVaR robust design'
    robust_location = {
        row['scenario']: row for row in localization_rows
        if row['design'] == robust_name
    }
    nominal_location = {
        row['scenario']: row for row in localization_rows
        if row['design'] == 'Nominal-model design'
    }
    robust_uncertainty = {
        row['scenario']: row for row in uncertainty_summary
        if row['design'] == robust_name
    }
    nominal_uncertainty = {
        row['scenario']: row for row in uncertainty_summary
        if row['design'] == 'Nominal-model design'
    }
    scenario_names = [case['name'] for case in cases]
    x_values = np.arange(len(scenario_names), dtype=float)
    labels = [
        'Reference' if case['kind'] == 'reference'
        else f"R{index:02d}\n{100.0 * case['residual_rms_fraction']:.1f}% RMS"
        for index, case in enumerate(cases)
    ]

    fig, axes = plt.subplots(2, 2, figsize=(15.0, 11.0))
    image = axes[0, 0].imshow(
        np.asarray(reference_phys.V, dtype=float).T,
        cmap='rainbow', origin='upper', extent=extent, aspect='auto'
    )
    axes[0, 0].scatter(
        candidate_positions[:, 0], candidate_positions[:, 1], s=14,
        facecolors='none', edgecolors='white', alpha=0.45,
        label='Feasible sites',
    )
    axes[0, 0].scatter(
        nominal_positions[:, 0], nominal_positions[:, 1], s=70,
        marker='s', facecolors='none', edgecolors=C_RND, linewidths=1.8,
        label='Nominal-model array',
    )
    axes[0, 0].scatter(
        robust_positions[:, 0], robust_positions[:, 1], s=85,
        marker='v', c=C_OPT, edgecolors='black', linewidths=0.7,
        label='Final robust array', zorder=5,
    )
    if common_positions.size:
        axes[0, 0].scatter(
            common_positions[:, 0], common_positions[:, 1], s=25,
            marker='o', c='white', edgecolors='black', linewidths=0.5,
            label='Shared site', zorder=6,
        )
    axes[0, 0].scatter(
        target_positions[:, 0], target_positions[:, 1], s=30,
        marker='o', facecolors=C_SRC, edgecolors='black', linewidths=0.35,
        label='Design targets', zorder=4,
    )
    axes[0, 0].set_xlabel('Horizontal distance (m)')
    axes[0, 0].set_ylabel('Depth (m)')
    axes[0, 0].set_title('(a) Final velocity-robust observation system')
    axes[0, 0].legend(loc='best', fontsize=8)
    colorbar = fig.colorbar(image, ax=axes[0, 0], pad=0.02)
    colorbar.set_label('Reference velocity (m/s)')
    _apply_complete_layout_padding(
        axes[0, 0], reference_phys,
        np.vstack((candidate_positions, target_positions,
                   nominal_positions, robust_positions)),
    )

    residuals = np.asarray([
        100.0 * case['residual_rms_fraction'] for case in cases
    ])
    max_residuals = np.asarray([
        100.0 * case['residual_max_abs_fraction'] for case in cases
    ])
    axes[0, 1].bar(x_values - 0.18, residuals, width=0.36,
                   color='#2A9D8F', label='RMS residual')
    axes[0, 1].bar(x_values + 0.18, max_residuals, width=0.36,
                   color='#E9C46A', label='Maximum absolute residual')
    axes[0, 1].set_xticks(x_values, labels, rotation=30, ha='right')
    axes[0, 1].set_ylabel('Velocity residual (%)')
    axes[0, 1].set_title('(b) Reference-plus-residual velocity ensemble')
    axes[0, 1].grid(axis='y', linestyle='--', alpha=0.4)
    axes[0, 1].legend(loc='best')

    axes[1, 0].plot(
        x_values,
        [robust_location[name]['p95_error_m'] for name in scenario_names],
        color=C_OPT, marker='o', linewidth=2.0, label='Robust array',
    )
    axes[1, 0].plot(
        x_values,
        [nominal_location[name]['p95_error_m'] for name in scenario_names],
        color=C_RND, marker='s', linewidth=1.8, label='Nominal array',
    )
    axes[1, 0].set_xticks(x_values, labels, rotation=30, ha='right')
    axes[1, 0].set_ylabel('95th-percentile location error (m)')
    axes[1, 0].set_title('(c) Localization performance under velocity uncertainty')
    axes[1, 0].grid(True, linestyle='--', alpha=0.4)
    axes[1, 0].legend(loc='best')

    axes[1, 1].plot(
        x_values,
        [robust_uncertainty[name]['p95_maximum_95_semi_axis_m']
         for name in scenario_names],
        color=C_OPT, marker='o', linewidth=2.0, label='Robust array',
    )
    axes[1, 1].plot(
        x_values,
        [nominal_uncertainty[name]['p95_maximum_95_semi_axis_m']
         for name in scenario_names],
        color=C_RND, marker='s', linewidth=1.8, label='Nominal array',
    )
    axes[1, 1].set_xticks(x_values, labels, rotation=30, ha='right')
    axes[1, 1].set_ylabel('P95 of maximum 95% semi-axis (m)')
    axes[1, 1].set_title('(d) FIM localization uncertainty by velocity model')
    axes[1, 1].grid(True, linestyle='--', alpha=0.4)
    axes[1, 1].legend(loc='best')

    figure_path = os.path.join(
        output_dir, 'Figure_Final_Velocity_Robust_Observation_System.png'
    )
    fig.suptitle(
        'Final observation-system layout and velocity-uncertainty evaluation\n'
        f"robust k={design_records['selected_number_of_geophones']}; "
        f"baseline k={design_records.get('fixed_baseline_number_of_geophones', design_records['selected_number_of_geophones'])}; "
        f"expected replacement="
        f"{100.0 * design_records['robust_design_energy']['expected_replacement_fraction']:.1f}%",
        fontsize=14,
    )
    fig.tight_layout(rect=(0.0, 0.0, 1.0, 0.95))
    fig.savefig(figure_path, bbox_inches='tight', dpi=300)
    plt.close(fig)
    return figure_path


def _aggregate_design_metrics(localization_rows, uncertainty_summary, cases):
    """Create deterministic, expected, and worst-case design comparisons."""
    probabilities = {
        case['name']: float(case['probability']) for case in cases
    }
    reference_name = next(
        case['name'] for case in cases if case['kind'] == 'reference'
    )
    designs = []
    for row in localization_rows:
        if row['design'] not in designs:
            designs.append(row['design'])
    result = []
    for design in designs:
        location = {
            row['scenario']: row for row in localization_rows
            if row['design'] == design
        }
        uncertainty = {
            row['scenario']: row for row in uncertainty_summary
            if row['design'] == design
        }

        def weighted(field, source):
            return float(sum(
                probabilities[name] * float(source[name][field])
                for name in probabilities
            ))

        def worst(field, source):
            return float(max(float(source[name][field]) for name in probabilities))

        deterministic_location = location[reference_name]
        deterministic_uncertainty = uncertainty[reference_name]
        result.extend([
            {
                'design': design,
                'evaluation_regime': 'Deterministic reference velocity',
                'mean_location_error_m': deterministic_location['mean_error_m'],
                'p95_location_error_m': deterministic_location['p95_error_m'],
                'maximum_location_error_m': (
                    deterministic_location['maximum_error_m']
                ),
                'failure_rate': deterministic_location['failure_rate'],
                'p95_maximum_95_semi_axis_m': (
                    deterministic_uncertainty['p95_maximum_95_semi_axis_m']
                ),
                'p95_rms_95_radius_m': (
                    deterministic_uncertainty['p95_rms_95_radius_m']
                ),
                'p95_mean_marginal_95_half_width_m': (
                    deterministic_uncertainty[
                        'p95_mean_marginal_95_half_width_m'
                    ]
                ),
                'p95_confidence_region_measure_m2_or_m3': (
                    deterministic_uncertainty[
                        'p95_confidence_region_measure_m2_or_m3'
                    ]
                ),
                'maximum_condition_number': (
                    deterministic_uncertainty['maximum_condition_number']
                ),
                'identifiable_fraction': (
                    deterministic_uncertainty['identifiable_fraction']
                ),
            },
            {
                'design': design,
                'evaluation_regime': 'Probability-weighted velocity ensemble',
                'mean_location_error_m': weighted('mean_error_m', location),
                'p95_location_error_m': weighted('p95_error_m', location),
                'maximum_location_error_m': weighted(
                    'maximum_error_m', location
                ),
                'failure_rate': weighted('failure_rate', location),
                'p95_maximum_95_semi_axis_m': weighted(
                    'p95_maximum_95_semi_axis_m', uncertainty
                ),
                'p95_rms_95_radius_m': weighted(
                    'p95_rms_95_radius_m', uncertainty
                ),
                'p95_mean_marginal_95_half_width_m': weighted(
                    'p95_mean_marginal_95_half_width_m', uncertainty
                ),
                'p95_confidence_region_measure_m2_or_m3': weighted(
                    'p95_confidence_region_measure_m2_or_m3', uncertainty
                ),
                'maximum_condition_number': weighted(
                    'maximum_condition_number', uncertainty
                ),
                'identifiable_fraction': weighted(
                    'identifiable_fraction', uncertainty
                ),
            },
            {
                'design': design,
                'evaluation_regime': 'Worst velocity realization',
                'mean_location_error_m': worst('mean_error_m', location),
                'p95_location_error_m': worst('p95_error_m', location),
                'maximum_location_error_m': worst(
                    'maximum_error_m', location
                ),
                'failure_rate': worst('failure_rate', location),
                'p95_maximum_95_semi_axis_m': worst(
                    'p95_maximum_95_semi_axis_m', uncertainty
                ),
                'p95_rms_95_radius_m': worst(
                    'p95_rms_95_radius_m', uncertainty
                ),
                'p95_mean_marginal_95_half_width_m': worst(
                    'p95_mean_marginal_95_half_width_m', uncertainty
                ),
                'p95_confidence_region_measure_m2_or_m3': worst(
                    'p95_confidence_region_measure_m2_or_m3', uncertainty
                ),
                'maximum_condition_number': worst(
                    'maximum_condition_number', uncertainty
                ),
                'identifiable_fraction': float(min(
                    uncertainty[name]['identifiable_fraction']
                    for name in probabilities
                )),
            },
        ])
    return result


def plot_velocity_residual_models(reference_phys, cases, output_dir):
    """Plot reference velocity and a posterior-stratified residual subset."""
    if reference_phys.dims != 2:
        return None
    cases = _posterior_plot_cases(cases, maximum_models=12)
    columns = 3
    rows = int(np.ceil(len(cases) / columns))
    spacing = np.asarray(reference_phys.spacing, dtype=float)
    extent = [
        0.0, (reference_phys.shape[0] - 1) * spacing[0],
        (reference_phys.shape[1] - 1) * spacing[1], 0.0,
    ]
    fig, axes = plt.subplots(rows, columns, figsize=(15.0, 4.1 * rows))
    axes = np.atleast_1d(axes).ravel()
    residual_cases = [case for case in cases if case['kind'] != 'reference']
    residual_limit = max(
        [case['residual_max_abs_fraction'] for case in residual_cases] or [0.01]
    ) * 100.0
    for index, case in enumerate(cases):
        axis = axes[index]
        if case['kind'] == 'reference':
            velocity = _velocity_case_array(reference_phys, case)
            image = axis.imshow(
                velocity.T, origin='upper', extent=extent,
                aspect='auto', cmap='rainbow'
            )
            colorbar = fig.colorbar(image, ax=axis, pad=0.02)
            colorbar.set_label('Velocity (m/s)')
            axis.set_title('(a) Reference velocity model')
            del velocity
        else:
            residual = _velocity_case_fractional_residual(case)
            image = axis.imshow(
                100.0 * residual.T,
                origin='upper', extent=extent, aspect='auto', cmap='rainbow',
                vmin=-residual_limit, vmax=residual_limit,
            )
            colorbar = fig.colorbar(image, ax=axis, pad=0.02)
            colorbar.set_label('Velocity residual (%)')
            axis.set_title(
                f"({chr(97 + index)}) {case['name']}\n"
                f"RMS={100.0 * case['residual_rms_fraction']:.1f}%, "
                f"max={100.0 * case['residual_max_abs_fraction']:.1f}%"
            )
            del residual
        axis.set_xlabel('Horizontal distance (m)')
        axis.set_ylabel('Depth (m)')
    for axis in axes[len(cases):]:
        axis.axis('off')
    figure_path = os.path.join(
        output_dir, 'Figure_Velocity_Residual_Models.png'
    )
    fig.suptitle(
        'Reference velocity and on-demand views of continuous posterior nodes',
        fontsize=14,
    )
    fig.tight_layout(rect=(0.0, 0.0, 1.0, 0.96))
    fig.savefig(figure_path, dpi=300, bbox_inches='tight')
    plt.close(fig)
    return figure_path


def plot_velocity_scenario_evaluation(localization_rows, uncertainty_summary,
                                      cases, output_dir):
    """Plot error, uncertainty, conditioning, and identifiability by model."""
    cases = _posterior_plot_cases(cases, maximum_models=16)
    designs = ['Nominal-model design', 'Ensemble-CVaR robust design']
    colors = {'Nominal-model design': C_RND,
              'Ensemble-CVaR robust design': C_OPT}
    markers = {'Nominal-model design': 's',
               'Ensemble-CVaR robust design': 'o'}
    scenarios = [case['name'] for case in cases]
    labels = [
        'Reference' if case['kind'] == 'reference'
        else f"R{index:02d}\n{100.0 * case['residual_rms_fraction']:.1f}%"
        for index, case in enumerate(cases)
    ]
    location = {(row['scenario'], row['design']): row
                for row in localization_rows}
    uncertainty = {(row['scenario'], row['design']): row
                   for row in uncertainty_summary}
    x_values = np.arange(len(scenarios), dtype=float)
    fig, axes = plt.subplots(2, 2, figsize=(15.0, 10.0))
    panels = (
        (axes[0, 0], 'mean_error_m', location,
         'Mean location error (m)', '(a) Mean localization error'),
        (axes[0, 1], 'p95_error_m', location,
         '95th-percentile error (m)', '(b) Upper-tail localization error'),
        (axes[1, 0], 'p95_maximum_95_semi_axis_m', uncertainty,
         'P95 maximum 95% semi-axis (m)', '(c) FIM localization uncertainty'),
        (axes[1, 1], 'maximum_condition_number', uncertainty,
         'Maximum FIM condition number', '(d) Geometric conditioning'),
    )
    for axis, field, lookup, ylabel, title in panels:
        for design in designs:
            axis.plot(
                x_values,
                [lookup[(scenario, design)][field] for scenario in scenarios],
                color=colors[design], marker=markers[design], linewidth=2.0,
                label=('Deterministic-velocity design' if design == designs[0]
                       else 'Random-residual robust design'),
            )
        axis.set_xticks(x_values, labels, rotation=30, ha='right')
        axis.set_ylabel(ylabel)
        axis.set_title(title)
        axis.grid(True, linestyle='--', alpha=0.4)
    axes[0, 0].legend(loc='best')
    figure_path = os.path.join(
        output_dir, 'Figure_Velocity_Scenario_Error_Uncertainty_Metrics.png'
    )
    fig.suptitle(
        'Observation-system evaluation for deterministic and uncertain velocity',
        fontsize=14,
    )
    fig.tight_layout(rect=(0.0, 0.0, 1.0, 0.96))
    fig.savefig(figure_path, dpi=300, bbox_inches='tight')
    plt.close(fig)
    return figure_path


def plot_deterministic_vs_uncertain_comparison(reference_phys, candidates,
                                               targets, nominal_sensors,
                                               robust_sensors,
                                               aggregate_rows, output_dir):
    """Compare layouts and metrics from deterministic and uncertain designs."""
    if reference_phys.dims != 2:
        return None
    spacing = np.asarray(reference_phys.spacing, dtype=float)
    extent = [
        0.0, (reference_phys.shape[0] - 1) * spacing[0],
        (reference_phys.shape[1] - 1) * spacing[1], 0.0,
    ]
    candidate_positions = np.asarray(candidates, dtype=float) * spacing
    target_positions = np.asarray(targets, dtype=float) * spacing
    arrays = (
        ('Deterministic reference-velocity design', nominal_sensors, C_RND, 's'),
        ('Random-residual robust design', robust_sensors, C_OPT, 'v'),
    )
    fig, axes = plt.subplots(2, 2, figsize=(15.0, 10.5))
    for axis, (title, sensors, color, marker), panel in zip(
            axes[0], arrays, ('(a)', '(b)')):
        image = axis.imshow(
            np.asarray(reference_phys.V).T, origin='upper', extent=extent,
            aspect='auto', cmap='rainbow'
        )
        positions = np.asarray(sensors, dtype=float) * spacing
        axis.scatter(candidate_positions[:, 0], candidate_positions[:, 1],
                     s=14, facecolors='none', edgecolors='white', alpha=0.45)
        axis.scatter(target_positions[:, 0], target_positions[:, 1], s=28,
                     c=C_SRC, edgecolors='black', linewidths=0.35,
                     label='Targets')
        axis.scatter(positions[:, 0], positions[:, 1], s=90, marker=marker,
                     c=color, edgecolors='black', linewidths=0.7,
                     label='Selected receivers')
        axis.set_xlabel('Horizontal distance (m)')
        axis.set_ylabel('Depth (m)')
        axis.set_title(f'{panel} {title}')
        axis.legend(loc='best')
        colorbar = fig.colorbar(image, ax=axis, pad=0.02)
        colorbar.set_label('Reference velocity (m/s)')
        _apply_complete_layout_padding(
            axis, reference_phys,
            np.vstack((candidate_positions, target_positions, positions)),
        )

    lookup = {(row['design'], row['evaluation_regime']): row
              for row in aggregate_rows}
    plot_designs = ['Nominal-model design', 'Ensemble-CVaR robust design']
    plot_labels = ['Deterministic design', 'Robust design']
    colors = [C_RND, C_OPT]
    regimes = [
        'Deterministic reference velocity',
        'Probability-weighted velocity ensemble',
        'Worst velocity realization',
    ]
    regime_labels = ['Reference', 'Ensemble mean', 'Worst case']
    x_values = np.arange(len(regimes), dtype=float)
    width = 0.36
    for design_index, (design, label, color) in enumerate(
            zip(plot_designs, plot_labels, colors)):
        offset = (design_index - 0.5) * width
        axes[1, 0].bar(
            x_values + offset,
            [lookup[(design, regime)]['p95_location_error_m']
             for regime in regimes],
            width=width, color=color, edgecolor='black', label=label,
        )
        axes[1, 1].bar(
            x_values + offset,
            [lookup[(design, regime)]['p95_maximum_95_semi_axis_m']
             for regime in regimes],
            width=width, color=color, edgecolor='black', label=label,
        )
    for axis, ylabel, title in (
            (axes[1, 0], 'P95 location error (m)',
             '(c) Deterministic and uncertain-velocity error'),
            (axes[1, 1], 'P95 maximum 95% semi-axis (m)',
             '(d) Deterministic and uncertain-velocity uncertainty')):
        axis.set_xticks(x_values, regime_labels)
        axis.set_ylabel(ylabel)
        axis.set_title(title)
        axis.grid(axis='y', linestyle='--', alpha=0.4)
        axis.legend(loc='best')
    figure_path = os.path.join(
        output_dir, 'Figure_Deterministic_vs_Uncertain_Velocity_Comparison.png'
    )
    fig.suptitle(
        'Deterministic reference-velocity design versus random-residual robust design',
        fontsize=14,
    )
    fig.tight_layout(rect=(0.0, 0.0, 1.0, 0.96))
    fig.savefig(figure_path, dpi=300, bbox_inches='tight')
    plt.close(fig)
    return figure_path


def plot_confidence_intervals_and_error_ellipses(reference_phys, cases,
                                                 uncertainty_rows,
                                                 uncertainty_summary,
                                                 output_dir):
    """Plot marginal 95% intervals and representative joint error ellipses."""
    if reference_phys.dims != 2:
        return None
    cases = _posterior_plot_cases(cases, maximum_models=16)
    designs = ['Nominal-model design', 'Ensemble-CVaR robust design']
    labels_by_design = {
        designs[0]: 'Deterministic-velocity design',
        designs[1]: 'Random-residual robust design',
    }
    colors = {designs[0]: C_RND, designs[1]: C_OPT}
    markers = {designs[0]: 's', designs[1]: 'o'}
    scenario_names = [case['name'] for case in cases]
    scenario_labels = [
        'Reference' if case['kind'] == 'reference'
        else f"R{index:02d}\n{100.0 * case['residual_rms_fraction']:.1f}%"
        for index, case in enumerate(cases)
    ]
    summary_lookup = {
        (row['scenario'], row['design']): row for row in uncertainty_summary
    }
    x_values = np.arange(len(scenario_names), dtype=float)
    fig, axes = plt.subplots(2, 2, figsize=(15.0, 10.5))
    for design in designs:
        axes[0, 0].plot(
            x_values,
            [summary_lookup[(scenario, design)][
                'p95_mean_marginal_95_half_width_m'
             ] for scenario in scenario_names],
            color=colors[design], marker=markers[design], linewidth=2.0,
            label=labels_by_design[design],
        )
        axes[0, 1].plot(
            x_values,
            [summary_lookup[(scenario, design)][
                'p95_maximum_95_semi_axis_m'
             ] for scenario in scenario_names],
            color=colors[design], marker=markers[design], linewidth=2.0,
            label=labels_by_design[design],
        )
        axes[1, 0].plot(
            x_values,
            [summary_lookup[(scenario, design)][
                'p95_confidence_region_measure_m2_or_m3'
             ] for scenario in scenario_names],
            color=colors[design], marker=markers[design], linewidth=2.0,
            label=labels_by_design[design],
        )
    for axis, ylabel, title in (
            (axes[0, 0], 'P95 mean marginal 95% half-width (m)',
             '(a) Coordinate confidence intervals'),
            (axes[0, 1], 'P95 maximum 95% semi-axis (m)',
             '(b) Error-ellipse major semi-axis'),
            (axes[1, 0], 'P95 error-ellipse area (m$^2$)',
             '(c) Joint 95% confidence-region area')):
        axis.set_xticks(x_values, scenario_labels, rotation=30, ha='right')
        axis.set_ylabel(ylabel)
        axis.set_title(title)
        axis.grid(True, linestyle='--', alpha=0.4)
    axes[0, 0].legend(loc='best')

    reference_name = next(
        case['name'] for case in cases if case['kind'] == 'reference'
    )
    random_cases = [case for case in cases if case['kind'] != 'reference']
    worst_name = max(
        random_cases,
        key=lambda case: summary_lookup[(
            case['name'], designs[0]
        )]['p95_maximum_95_semi_axis_m'],
    )['name'] if random_cases else reference_name
    target_rows = {}
    for scenario in (reference_name, worst_name):
        scenario_rows = [
            row for row in uncertainty_rows
            if row['scenario'] == scenario
        ]
        target_ids = sorted({row['target'] for row in scenario_rows})
        # Select one common target using the worse of the two arrays, then draw
        # both ellipses for that exact target and velocity realization.
        common_target = max(
            target_ids,
            key=lambda target: max(
                row['maximum_95_semi_axis_m'] for row in scenario_rows
                if row['target'] == target
            ),
        )
        for design in designs:
            target_rows[(scenario, design)] = next(
                row for row in scenario_rows
                if row['target'] == common_target and row['design'] == design
            )
    ellipse_axis = axes[1, 1]
    style = {
        (reference_name, designs[0]): ('--', C_RND),
        (reference_name, designs[1]): ('--', C_OPT),
        (worst_name, designs[0]): ('-', C_RND),
        (worst_name, designs[1]): ('-', C_OPT),
    }
    maximum_extent = 1.0
    for (scenario, design), row in target_rows.items():
        covariance = np.asarray([
            [row['covariance_1_1_m2'], row['covariance_1_2_m2']],
            [row['covariance_2_1_m2'], row['covariance_2_2_m2']],
        ], dtype=float)
        eigenvalues, eigenvectors = np.linalg.eigh(covariance)
        order = np.argsort(eigenvalues)[::-1]
        eigenvalues = np.maximum(eigenvalues[order], 0.0)
        eigenvectors = eigenvectors[:, order]
        semi_axes = np.sqrt(chi2.ppf(0.95, 2) * eigenvalues)
        angle = float(np.degrees(np.arctan2(
            eigenvectors[1, 0], eigenvectors[0, 0]
        )))
        maximum_extent = max(maximum_extent, float(np.max(semi_axes)))
        linestyle, color = style[(scenario, design)]
        ellipse = Ellipse(
            (0.0, 0.0), width=2.0 * semi_axes[0],
            height=2.0 * semi_axes[1], angle=angle,
            fill=False, edgecolor=color, linestyle=linestyle, linewidth=2.0,
            label=(
                f"{'Reference' if scenario == reference_name else 'Worst residual'}; "
                f"{'deterministic' if design == designs[0] else 'robust'}"
            ),
        )
        ellipse_axis.add_patch(ellipse)
    ellipse_axis.axhline(0.0, color='0.6', linewidth=0.8)
    ellipse_axis.axvline(0.0, color='0.6', linewidth=0.8)
    ellipse_axis.set_xlim(-1.15 * maximum_extent, 1.15 * maximum_extent)
    ellipse_axis.set_ylim(-1.15 * maximum_extent, 1.15 * maximum_extent)
    ellipse_axis.set_aspect('equal', adjustable='box')
    ellipse_axis.set_xlabel('Horizontal location error (m)')
    ellipse_axis.set_ylabel('Depth error (m)')
    ellipse_axis.set_title('(d) Representative joint 95% error ellipses')
    ellipse_axis.grid(True, linestyle='--', alpha=0.35)
    ellipse_axis.legend(loc='best', fontsize=8)
    figure_path = os.path.join(
        output_dir, 'Figure_Confidence_Intervals_and_Error_Ellipses.png'
    )
    fig.suptitle(
        'Confidence-interval and error-ellipse performance across velocity models',
        fontsize=14,
    )
    fig.tight_layout(rect=(0.0, 0.0, 1.0, 0.96))
    fig.savefig(figure_path, dpi=300, bbox_inches='tight')
    plt.close(fig)
    return figure_path


def plot_observation_system_relationships(reference_phys, nominal_sensors,
                                          robust_sensors, records,
                                          aggregate_rows, output_dir):
    """Visualize distinctions and shared properties of the two designs."""
    nominal_set = {tuple(sensor) for sensor in nominal_sensors}
    robust_set = {tuple(sensor) for sensor in robust_sensors}
    intersection = nominal_set & robust_set
    union = nominal_set | robust_set
    jaccard = len(intersection) / len(union) if union else 1.0
    overlap_fraction = len(intersection) / max(len(robust_set), 1)
    lookup = {(row['design'], row['evaluation_regime']): row
              for row in aggregate_rows}
    designs = ['Nominal-model design', 'Ensemble-CVaR robust design']
    labels = ['Deterministic design', 'Robust design']
    colors = [C_RND, C_OPT]
    regimes = ['Deterministic reference velocity',
               'Probability-weighted velocity ensemble',
               'Worst velocity realization']
    fig, axes = plt.subplots(1, 3, figsize=(16.5, 5.4))
    axes[0].bar(
        ['Shared sites', 'Only deterministic', 'Only robust'],
        [len(intersection), len(nominal_set - robust_set),
         len(robust_set - nominal_set)],
        color=['#2A9D8F', C_RND, C_OPT], edgecolor='black',
    )
    axes[0].set_ylabel('Number of receiver sites')
    axes[0].set_title(
        '(a) Layout relationship\n'
        f'Jaccard={jaccard:.2f}, robust overlap={overlap_fraction:.1%}'
    )
    axes[0].grid(axis='y', linestyle='--', alpha=0.4)

    x_values = np.arange(len(regimes), dtype=float)
    for design, label, color in zip(designs, labels, colors):
        axes[1].plot(
            x_values,
            [lookup[(design, regime)]['p95_location_error_m']
             for regime in regimes],
            color=color, marker='o', linewidth=2.0, label=label,
        )
        axes[2].plot(
            x_values,
            [lookup[(design, regime)]['p95_maximum_95_semi_axis_m']
             for regime in regimes],
            color=color, marker='o', linewidth=2.0, label=label,
        )
    regime_labels = ['Reference', 'Ensemble mean', 'Worst case']
    for axis, ylabel, title in (
            (axes[1], 'P95 location error (m)',
             '(b) Accuracy: same estimator and targets'),
            (axes[2], 'P95 maximum 95% semi-axis (m)',
             '(c) Uncertainty: same FIM definition')):
        axis.set_xticks(x_values, regime_labels)
        axis.set_ylabel(ylabel)
        axis.set_title(title)
        axis.grid(True, linestyle='--', alpha=0.4)
        axis.legend(loc='best')
    figure_path = os.path.join(
        output_dir, 'Figure_Observation_System_Differences_and_Relationships.png'
    )
    fig.suptitle(
        'Differences and relationships between deterministic and robust arrays',
        fontsize=14,
    )
    fig.tight_layout(rect=(0.0, 0.0, 1.0, 0.94))
    fig.savefig(figure_path, dpi=300, bbox_inches='tight')
    plt.close(fig)
    return figure_path, {
        'shared_receiver_count': len(intersection),
        'deterministic_only_receiver_count': len(nominal_set - robust_set),
        'robust_only_receiver_count': len(robust_set - nominal_set),
        'jaccard_similarity': float(jaccard),
        'robust_overlap_fraction': float(overlap_fraction),
    }


def _four_design_plot_style():
    """Centralize publication labels and styles for the four-array comparison."""
    return {
        'Nominal-model design': {
            'label': 'Deterministic optimization', 'color': C_RND, 'marker': 's'
        },
        'Ensemble-CVaR robust design': {
            'label': 'Ensemble robust optimization', 'color': C_OPT, 'marker': 'v'
        },
        'Uniform maximin design': {
            'label': 'Uniform maximin', 'color': C_UNI, 'marker': '^'
        },
        'Random design': {
            'label': 'Random (fixed seed)', 'color': '#7B2CBF', 'marker': 'X'
        },
    }


def plot_four_observation_system_layouts(reference_phys, candidates, targets,
                                         design_sensors, output_dir):
    """Plot equal-size deterministic, robust, uniform, and random arrays."""
    if reference_phys.dims != 2:
        return None
    styles = _four_design_plot_style()
    spacing = np.asarray(reference_phys.spacing, dtype=float)
    extent = [
        0.0, (reference_phys.shape[0] - 1) * spacing[0],
        (reference_phys.shape[1] - 1) * spacing[1], 0.0,
    ]
    candidate_positions = np.asarray(candidates, dtype=float) * spacing
    target_positions = np.asarray(targets, dtype=float) * spacing
    fig, axes = plt.subplots(2, 2, figsize=(15.0, 10.5), sharex=True, sharey=True)
    panels = ('(a)', '(b)', '(c)', '(d)')
    image = None
    for panel, axis, design in zip(panels, axes.ravel(), styles):
        style = styles[design]
        positions = np.asarray(design_sensors[design], dtype=float) * spacing
        image = axis.imshow(
            np.asarray(reference_phys.V, dtype=float).T, origin='upper',
            extent=extent, aspect='auto', cmap='rainbow'
        )
        axis.scatter(
            candidate_positions[:, 0], candidate_positions[:, 1], s=13,
            facecolors='none', edgecolors='white', alpha=0.40,
            label='Feasible sites'
        )
        axis.scatter(
            target_positions[:, 0], target_positions[:, 1], s=26,
            c=C_SRC, edgecolors='black', linewidths=0.35,
            label='Design targets', zorder=4
        )
        axis.scatter(
            positions[:, 0], positions[:, 1], s=92,
            marker=style['marker'], c=style['color'], edgecolors='black',
            linewidths=0.75, label='Selected receivers', zorder=5
        )
        for receiver_index, position in enumerate(positions, start=1):
            axis.annotate(
                str(receiver_index), position, xytext=(4, 9),
                textcoords='offset points', color='white', fontsize=7,
                fontweight='bold', zorder=6, clip_on=False,
            )
        axis.set_xlabel('Horizontal distance (m)')
        axis.set_ylabel('Depth (m)')
        axis.set_title(f"{panel} {style['label']} (k={len(positions)})")
        axis.legend(loc='best', fontsize=8)
        _apply_complete_layout_padding(
            axis, reference_phys,
            np.vstack((candidate_positions, target_positions, positions)),
        )
    colorbar_axis = fig.add_axes((0.915, 0.14, 0.018, 0.72))
    colorbar = fig.colorbar(image, cax=colorbar_axis)
    colorbar.set_label('Reference velocity (m/s)')
    figure_path = os.path.join(
        output_dir, 'Figure_Four_Observation_System_Layouts.png'
    )
    fig.suptitle(
        'Equal-receiver-count observation-system layouts on the common feasible set',
        fontsize=14,
    )
    fig.subplots_adjust(left=0.07, right=0.885, bottom=0.07, top=0.92,
                        wspace=0.18, hspace=0.22)
    fig.savefig(figure_path, dpi=300, bbox_inches='tight')
    plt.close(fig)
    return figure_path


def plot_four_design_velocity_scenario_metrics(localization_rows,
                                               uncertainty_summary,
                                               cases, output_dir):
    """Compare error and FIM uncertainty for all four arrays in every model."""
    cases = _posterior_plot_cases(cases, maximum_models=16)
    styles = _four_design_plot_style()
    scenarios = [case['name'] for case in cases]
    scenario_labels = [
        'Reference' if case['kind'] == 'reference'
        else f"R{index:02d}\n{100.0 * case['residual_rms_fraction']:.1f}% RMS"
        for index, case in enumerate(cases)
    ]
    location = {(row['scenario'], row['design']): row
                for row in localization_rows}
    uncertainty = {(row['scenario'], row['design']): row
                   for row in uncertainty_summary}
    x_values = np.arange(len(scenarios), dtype=float)
    fig, axes = plt.subplots(2, 2, figsize=(15.5, 10.2), sharex=True)
    panels = (
        (axes[0, 0], 'mean_error_m', location,
         'Mean location error (m)', '(a) Mean localization error'),
        (axes[0, 1], 'p95_error_m', location,
         '95th-percentile location error (m)', '(b) Upper-tail localization error'),
        (axes[1, 0], 'p95_mean_marginal_95_half_width_m', uncertainty,
         'P95 mean marginal 95% half-width (m)', '(c) Coordinate uncertainty'),
        (axes[1, 1], 'p95_maximum_95_semi_axis_m', uncertainty,
         'P95 maximum 95% semi-axis (m)', '(d) Joint error-ellipse uncertainty'),
    )
    for axis, field, lookup, ylabel, title in panels:
        for design, style in styles.items():
            axis.plot(
                x_values,
                [lookup[(scenario, design)][field] for scenario in scenarios],
                color=style['color'], marker=style['marker'], linewidth=1.9,
                markersize=6, label=style['label']
            )
        axis.set_xticks(x_values, scenario_labels, rotation=28, ha='right')
        axis.set_ylabel(ylabel)
        axis.set_title(title)
        axis.grid(True, linestyle='--', alpha=0.40)
    axes[0, 0].legend(loc='best', fontsize=8)
    figure_path = os.path.join(
        output_dir, 'Figure_Four_Designs_By_Velocity_Model.png'
    )
    fig.suptitle(
        'Matched-noise comparison across the reference and random-residual velocities',
        fontsize=14,
    )
    fig.tight_layout(rect=(0.0, 0.0, 1.0, 0.96))
    fig.savefig(figure_path, dpi=300, bbox_inches='tight')
    plt.close(fig)
    return figure_path


