def _draw_covariance_ellipse(axis, row, color, linestyle, label):
    """Add a 95% covariance ellipse and return its maximum semi-axis."""
    covariance = np.asarray([
        [row['covariance_1_1_m2'], row['covariance_1_2_m2']],
        [row['covariance_2_1_m2'], row['covariance_2_2_m2']],
    ], dtype=float)
    eigenvalues, eigenvectors = np.linalg.eigh(covariance)
    order = np.argsort(eigenvalues)[::-1]
    eigenvalues = np.maximum(eigenvalues[order], 0.0)
    eigenvectors = eigenvectors[:, order]
    semi_axes = np.sqrt(chi2.ppf(0.95, 2) * eigenvalues)
    angle = float(np.degrees(np.arctan2(
        eigenvectors[1, 0], eigenvectors[0, 0]
    )))
    axis.add_patch(Ellipse(
        (0.0, 0.0), width=2.0 * semi_axes[0], height=2.0 * semi_axes[1],
        angle=angle, fill=False, edgecolor=color, linestyle=linestyle,
        linewidth=2.2, label=label,
    ))
    return float(np.max(semi_axes))


def plot_matched_confidence_intervals_and_ellipses(reference_phys, cases,
                                                   uncertainty_rows,
                                                   uncertainty_summary,
                                                   output_dir):
    """Give both designs the same CI panels and side-by-side error ellipses."""
    if reference_phys.dims != 2:
        return None
    cases = _posterior_plot_cases(cases, maximum_models=16)
    designs = ['Nominal-model design', 'Ensemble-CVaR robust design']
    labels_by_design = {
        designs[0]: 'Deterministic optimization',
        designs[1]: 'Velocity-ensemble robust optimization',
    }
    colors = {designs[0]: C_RND, designs[1]: C_OPT}
    markers = {designs[0]: 's', designs[1]: 'v'}
    scenarios = [case['name'] for case in cases]
    scenario_labels = [
        'Reference' if case['kind'] == 'reference'
        else f"R{index:02d}\n{100.0 * case['residual_rms_fraction']:.1f}% RMS"
        for index, case in enumerate(cases)
    ]
    summary = {(row['scenario'], row['design']): row
               for row in uncertainty_summary}
    fig, axes = plt.subplots(2, 2, figsize=(15.0, 10.2))
    x_values = np.arange(len(scenarios), dtype=float)
    for design in designs:
        axes[0, 0].plot(
            x_values,
            [summary[(scenario, design)]['p95_mean_marginal_95_half_width_m']
             for scenario in scenarios],
            color=colors[design], marker=markers[design], linewidth=2.0,
            label=labels_by_design[design],
        )
        axes[0, 1].plot(
            x_values,
            [summary[(scenario, design)]['p95_maximum_95_semi_axis_m']
             for scenario in scenarios],
            color=colors[design], marker=markers[design], linewidth=2.0,
            label=labels_by_design[design],
        )
    for axis, ylabel, title in (
            (axes[0, 0], 'P95 mean marginal 95% half-width (m)',
             '(a) Marginal coordinate confidence intervals'),
            (axes[0, 1], 'P95 maximum 95% semi-axis (m)',
             '(b) Joint confidence-ellipse major semi-axis')):
        axis.set_xticks(x_values, scenario_labels, rotation=28, ha='right')
        axis.set_ylabel(ylabel)
        axis.set_title(title)
        axis.grid(True, linestyle='--', alpha=0.40)
        axis.legend(loc='best', fontsize=8)

    reference_name = next(
        case['name'] for case in cases if case['kind'] == 'reference'
    )
    random_names = [case['name'] for case in cases if case['kind'] != 'reference']
    worst_name = max(
        random_names,
        key=lambda name: max(
            summary[(name, design)]['p95_maximum_95_semi_axis_m']
            for design in designs
        ),
    ) if random_names else reference_name
    for axis, scenario, panel_title in (
            (axes[1, 0], reference_name, '(c) Reference-velocity 95% ellipses'),
            (axes[1, 1], worst_name, '(d) Worst-residual 95% ellipses')):
        scenario_rows = [
            row for row in uncertainty_rows if row['scenario'] == scenario
        ]
        target_ids = sorted({row['target'] for row in scenario_rows})
        common_target = max(
            target_ids,
            key=lambda target: max(
                row['maximum_95_semi_axis_m'] for row in scenario_rows
                if row['target'] == target
            ),
        )
        maximum_extent = 1.0
        for design in designs:
            row = next(
                candidate for candidate in scenario_rows
                if candidate['target'] == common_target
                and candidate['design'] == design
            )
            maximum_extent = max(
                maximum_extent,
                _draw_covariance_ellipse(
                    axis, row, colors[design], '-', labels_by_design[design]
                ),
            )
        axis.axhline(0.0, color='0.6', linewidth=0.8)
        axis.axvline(0.0, color='0.6', linewidth=0.8)
        axis.set_xlim(-1.15 * maximum_extent, 1.15 * maximum_extent)
        axis.set_ylim(-1.15 * maximum_extent, 1.15 * maximum_extent)
        axis.set_aspect('equal', adjustable='box')
        axis.set_xlabel('Horizontal location error (m)')
        axis.set_ylabel('Depth error (m)')
        axis.set_title(f'{panel_title}; common target {common_target}')
        axis.grid(True, linestyle='--', alpha=0.35)
        axis.legend(loc='best', fontsize=8)
    figure_path = os.path.join(
        output_dir,
        'Figure_Deterministic_Robust_Confidence_Intervals_Error_Ellipses.png',
    )
    fig.suptitle(
        'Matched confidence intervals and localization-error ellipses',
        fontsize=14,
    )
    fig.tight_layout(rect=(0.0, 0.0, 1.0, 0.95))
    fig.savefig(figure_path, dpi=300, bbox_inches='tight')
    plt.close(fig)
    return figure_path


def plot_four_design_convergence_and_objective(nominal_history, robust_history,
                                               design_components, output_dir):
    """Compare optimizer histories and common-objective values for four arrays.

    Uniform and random arrays have no iterative optimization history. Their
    robust-loss values are therefore plotted as horizontal construction
    baselines over the recorded search length. This distinction is explicit in
    the legend and prevents a one-step construction from being misrepresented
    as a convergent stochastic optimizer.
    """
    styles = _four_design_plot_style()
    nominal_curve = _running_best_objective(nominal_history)
    robust_curve = _running_best_objective(robust_history)
    history_length = max(nominal_curve.size, robust_curve.size, 2)
    history_x = np.arange(1, history_length + 1)
    uniform_value = float(
        design_components['Uniform maximin design']['robust_loss']
    )
    random_value = float(design_components['Random design']['robust_loss'])
    fig, axes = plt.subplots(1, 2, figsize=(15.5, 5.8))
    axes[0].plot(
        np.arange(1, nominal_curve.size + 1), nominal_curve,
        color=styles['Nominal-model design']['color'], linewidth=2.0,
        label='Deterministic optimizer: native-objective history'
    )
    axes[0].plot(
        np.arange(1, robust_curve.size + 1), robust_curve,
        color=styles['Ensemble-CVaR robust design']['color'], linewidth=2.0,
        label='Robust optimizer: native-objective history'
    )
    axes[0].plot(
        history_x, np.full(history_length, uniform_value),
        color=styles['Uniform maximin design']['color'], linestyle='--',
        linewidth=1.8, label='Uniform construction: final common-objective baseline'
    )
    axes[0].plot(
        history_x, np.full(history_length, random_value),
        color=styles['Random design']['color'], linestyle=':',
        linewidth=2.0, label='Random construction: final common-objective baseline'
    )
    axes[0].set_xlabel('Recorded search-history index')
    axes[0].set_ylabel('Dimensionless objective')
    axes[0].set_title('(a) Search convergence and noniterative baselines')
    axes[0].grid(True, linestyle='--', alpha=0.40)
    axes[0].legend(loc='best', fontsize=7)
    axes[0].text(
        0.02, 0.03,
        'Native deterministic and robust objectives differ during search;\n'
        'final bars use the same ensemble objective for all four arrays.',
        transform=axes[0].transAxes, fontsize=7, va='bottom',
        bbox={'facecolor': 'white', 'edgecolor': '0.7', 'alpha': 0.85},
    )

    component_fields = (
        ('performance_risk', 'Accuracy'),
        ('velocity_bias_risk', 'Velocity bias'),
        ('combined_picking_and_model_confidence_risk', 'Model-aware confidence'),
        ('layout_stability_risk', 'Layout change'),
        ('robust_loss', 'Total'),
    )
    x_values = np.arange(len(component_fields), dtype=float)
    width = 0.19
    for design_index, (design, style) in enumerate(styles.items()):
        axes[1].bar(
            x_values + (design_index - 1.5) * width,
            [float(design_components[design][field])
             for field, _ in component_fields],
            width=width, color=style['color'], edgecolor='black', linewidth=0.5,
            label=style['label'],
        )
    axes[1].set_xticks(
        x_values, [label for _, label in component_fields],
        rotation=25, ha='right'
    )
    axes[1].set_ylabel('Common ensemble-risk component')
    axes[1].set_title('(b) Final arrays under one ensemble objective')
    axes[1].grid(axis='y', linestyle='--', alpha=0.40)
    axes[1].legend(loc='best', fontsize=7)
    figure_path = os.path.join(
        output_dir, 'Figure_Four_Designs_Convergence_and_Objective.png'
    )
    fig.suptitle(
        'Optimization behavior and final objective comparison of four arrays',
        fontsize=14,
    )
    fig.tight_layout(rect=(0.0, 0.0, 1.0, 0.95))
    fig.savefig(figure_path, dpi=300, bbox_inches='tight')
    plt.close(fig)
    return figure_path


