def _apply_complete_layout_padding(axis, physics, physical_points=None,
                                   padding_fraction=0.055,
                                   minimum_padding_cells=5.0):
    """Expose every 2-D receiver marker, including markers on model boundaries.

    The image still occupies the physical model extent.  Only the axes are
    enlarged, so the added area appears as blank space and no velocity or image
    sample is extrapolated.  Scatter collections are also made non-clipping to
    protect large publication markers and their white/black edges.
    """
    x_model_max = (physics.shape[0] - 1) * physics.spacing[0]
    depth_model_max = (physics.shape[-1] - 1) * physics.spacing[-1]
    x_values = [0.0, float(x_model_max)]
    depth_values = [0.0, float(depth_model_max)]
    if physical_points is not None:
        points = np.asarray(physical_points, dtype=float)
        if points.size:
            points = np.atleast_2d(points)
            x_values.extend(points[:, 0].tolist())
            depth_values.extend(points[:, -1].tolist())
    x_min, x_max = float(np.min(x_values)), float(np.max(x_values))
    depth_min = float(np.min(depth_values))
    depth_max = float(np.max(depth_values))
    x_span = max(x_max - x_min, float(physics.spacing[0]))
    depth_span = max(depth_max - depth_min, float(physics.spacing[-1]))
    x_padding = max(
        minimum_padding_cells * float(physics.spacing[0]),
        float(padding_fraction) * x_span,
    )
    depth_padding = max(
        minimum_padding_cells * float(physics.spacing[-1]),
        float(padding_fraction) * depth_span,
    )
    axis.set_xlim(x_min - x_padding, x_max + x_padding)
    axis.set_ylim(depth_max + depth_padding, depth_min - depth_padding)
    for collection in axis.collections:
        collection.set_clip_on(False)


def _apply_complete_layout_padding_3d(axis, physics, physical_points=None,
                                      padding_fraction=0.055,
                                      minimum_padding_cells=5.0):
    """Add blank X/Y/Z margins around a 3-D receiver geometry."""
    model_max = (
        (np.asarray(physics.shape, dtype=float) - 1.0)
        * np.asarray(physics.spacing, dtype=float)
    )
    lower = np.zeros(3, dtype=float)
    upper = np.asarray(model_max, dtype=float)
    if physical_points is not None:
        points = np.asarray(physical_points, dtype=float)
        if points.size:
            points = np.atleast_2d(points)
            lower = np.minimum(lower, np.min(points[:, :3], axis=0))
            upper = np.maximum(upper, np.max(points[:, :3], axis=0))
    span = np.maximum(upper - lower, np.asarray(physics.spacing, dtype=float))
    padding = np.maximum(
        minimum_padding_cells * np.asarray(physics.spacing, dtype=float),
        float(padding_fraction) * span,
    )
    axis.set_xlim(lower[0] - padding[0], upper[0] + padding[0])
    axis.set_ylim(lower[1] - padding[1], upper[1] + padding[1])
    axis.set_zlim(upper[2] + padding[2], lower[2] - padding[2])
    axis.set_box_aspect(span + 2.0 * padding)
    for collection in axis.collections:
        collection.set_clip_on(False)






















def plot_computational_cost(output_dir, records):
    """Compare offline design time, online location time, and amortization."""
    design_rows = [row for row in records
                   if row.get('stage') == 'observation-system design']
    location_rows = [row for row in records
                     if row.get('stage') == 'double-difference localization']
    if not design_rows and not location_rows:
        return

    fig, axes = plt.subplots(1, 3, figsize=(15.5, 5.0))
    color_lookup = {
        'Bayesian multi-objective MCMC + elbow': C_OPT,
        'Random selection': C_RND,
        'Uniform selection': C_UNI,
        'Optimized array': C_OPT,
        'Random array': C_RND,
        'Uniform array': C_UNI,
    }

    design_labels = [row['method'].replace(' selection', '').replace(
        'Bayesian multi-objective MCMC + elbow', 'Proposed') for row in design_rows]
    design_times = [max(float(row.get('wall_seconds', 0.0)), 1.0e-9)
                    for row in design_rows]
    axes[0].bar(design_labels, design_times,
                color=[color_lookup.get(row['method'], '0.5') for row in design_rows],
                edgecolor='black')
    axes[0].set_yscale('log')
    axes[0].set_ylabel('Wall time (s, logarithmic scale)')
    axes[0].set_title('(a) Offline array design')
    axes[0].tick_params(axis='x', rotation=20)
    axes[0].grid(axis='y', linestyle='--', alpha=0.45)

    location_labels = [row['method'].replace(' array', '') for row in location_rows]
    location_times = [max(float(row.get('wall_seconds', 0.0)) /
                          max(int(row.get('number_of_sources', 1)), 1), 1.0e-9)
                      for row in location_rows]
    axes[1].bar(location_labels, location_times,
                color=[color_lookup.get(row['method'], '0.5') for row in location_rows],
                edgecolor='black')
    axes[1].set_yscale('log')
    axes[1].set_ylabel('Wall time per source (s, logarithmic scale)')
    axes[1].set_title('(b) Online DD localization')
    axes[1].tick_params(axis='x', rotation=20)
    axes[1].grid(axis='y', linestyle='--', alpha=0.45)

    event_counts = np.asarray([1, 3, 10, 30, 100, 300, 1000], dtype=float)
    for row in design_rows:
        design_time = max(float(row.get('wall_seconds', 0.0)), 1.0e-9)
        label = row['method'].replace(' selection', '').replace(
            'Bayesian multi-objective MCMC + elbow', 'Proposed')
        axes[2].loglog(event_counts, design_time / event_counts,
                       marker='o', linewidth=2.0,
                       color=color_lookup.get(row['method'], '0.5'), label=label)
    axes[2].set_xlabel('Number of located events')
    axes[2].set_ylabel('Amortized design overhead (s/event)')
    axes[2].set_title('(c) One-time design cost amortization')
    axes[2].grid(True, which='both', linestyle='--', alpha=0.4)
    axes[2].legend(loc='best')

    fig.suptitle('Computational-cost comparison with conventional layouts',
                 fontsize=13)
    fig.tight_layout()
    fig.savefig(os.path.join(output_dir,
                             'Figure_Computational_Cost_Comparison.png'),
                bbox_inches='tight', dpi=300)
    plt.close(fig)


def write_computational_cost(output_dir, records):
    _write_csv(os.path.join(output_dir, 'computational_cost.csv'), records)
    with open(os.path.join(output_dir, 'computational_cost.json'),
              'w', encoding='utf-8') as stream:
        json.dump(records, stream, indent=2)
    plot_computational_cost(output_dir, records)


def replot_rtm_from_checkpoint(output_dir):
    """Regenerate every RTM figure without rerunning design or wave propagation."""
    requested_manifest = os.getenv('RTM_CHECKPOINT_MANIFEST', '').strip()
    if requested_manifest:
        manifest_path = os.path.abspath(requested_manifest)
        candidates = [manifest_path]
    else:
        candidates = glob.glob(
            os.path.join(os.path.abspath(output_dir), '**',
                         'rtm_checkpoint_manifest.json'),
            recursive=True,
        )
        candidates.sort(key=os.path.getmtime, reverse=True)
    if not candidates or not os.path.isfile(candidates[0]):
        raise FileNotFoundError(
            'No RTM checkpoint manifest was found. Run once with '
            'RTM_RESUME=1 and RTM_SAVE_TEXT=1 before using RTM_REPLOT_ONLY=1.'
        )
    manifest_path = candidates[0]
    with open(manifest_path, 'r', encoding='utf-8') as stream:
        manifest = json.load(stream)
    checkpoint_dir = os.path.dirname(manifest_path)
    shape = tuple(int(value) for value in manifest['model_shape'])
    spacing = tuple(float(value) for value in manifest['model_spacing_m'])
    is_3d = bool(manifest['is_3d'])
    reference_velocity = _load_rtm_checkpoint(
        os.path.join(checkpoint_dir, 'reference_velocity_model'), shape
    )
    perturbed_velocity = _load_rtm_checkpoint(
        os.path.join(checkpoint_dir, 'perturbed_migration_velocity_model'), shape
    )
    # Version-2 manifests used this legacy filename.  Retain read support so
    # existing checkpoints remain re-plottable after this reference-data-only
    # revision.
    if perturbed_velocity is None:
        perturbed_velocity = _load_rtm_checkpoint(
            os.path.join(checkpoint_dir, 'changed_velocity_model'), shape
        )
    if reference_velocity is None or perturbed_velocity is None:
        raise RuntimeError('Velocity-model checkpoints are incomplete or corrupt.')
    reference_physics = PhysicsEngine(shape, spacing, is_3d=is_3d)
    perturbed_physics = PhysicsEngine(shape, spacing, is_3d=is_3d)
    reference_physics.V = reference_velocity
    perturbed_physics.V = perturbed_velocity
    source_indices = [
        tuple(int(value) for value in source)
        for source in manifest['source_indices']
    ]
    design_sensors = {
        name: [tuple(int(value) for value in sensor) for sensor in sensors]
        for name, sensors in manifest['design_sensor_indices'].items()
    }
    experiments = []
    for record in manifest['experiments']:
        experiment = dict(record)
        experiment['data_physics'] = (
            reference_physics if record['data_case'] == 'reference'
            else perturbed_physics
        )
        experiment['migration_physics'] = (
            reference_physics if record['migration_case'] == 'reference'
            else perturbed_physics
        )
        experiments.append(experiment)
    images = {
        experiment['key']: {name: [] for name in design_sensors}
        for experiment in experiments
    }
    missing = []
    for experiment in experiments:
        for source_number, _ in enumerate(source_indices, start=1):
            for design_name in design_sensors:
                image_base = _rtm_image_checkpoint_base(
                    checkpoint_dir, experiment['key'], design_name, source_number
                )
                image = _load_rtm_checkpoint(image_base, shape)
                if image is None:
                    missing.append(image_base)
                else:
                    images[experiment['key']][design_name].append(image)
    if missing:
        preview = '\n'.join(f'  - {path}' for path in missing[:8])
        raise RuntimeError(
            f'{len(missing)} RTM image checkpoints are missing. Run the normal '
            f'workflow with RTM_RESUME=1 to compute only those images.\n{preview}'
        )

    focus_radius_cells = float(manifest['focus_radius_cells'])
    detail_rows = []
    for experiment in experiments:
        for design_name, sensors in design_sensors.items():
            for source_number, source_index in enumerate(source_indices, start=1):
                image = images[experiment['key']][design_name][source_number - 1]
                metrics = _rtm_image_metrics(
                    image, source_index, spacing, focus_radius_cells
                )
                metrics['reference_image_correlation'] = _rtm_image_correlation(
                    images['reference_matched'][design_name][source_number - 1],
                    image,
                )
                detail_rows.append({
                    'experiment': experiment['key'],
                    'design': design_name,
                    'number_of_receivers': len(sensors),
                    'source_number': source_number,
                    'source_index': list(source_index),
                    'data_velocity_case': experiment['data_case'],
                    'migration_velocity_case': experiment['migration_case'],
                    'velocity_mismatch': int(
                        experiment['data_case'] != experiment['migration_case']
                    ),
                    **metrics,
                })
    summary_rows = []
    for experiment in experiments:
        for design_name, sensors in design_sensors.items():
            rows = [
                row for row in detail_rows
                if row['experiment'] == experiment['key']
                and row['design'] == design_name
            ]
            summary_rows.append({
                'experiment': experiment['key'],
                'design': design_name,
                'number_of_receivers': len(sensors),
                'number_of_sources': len(rows),
                'mean_peak_location_error_m': float(np.mean([
                    row['peak_location_error_m'] for row in rows
                ])),
                'mean_focus_energy_fraction': float(np.mean([
                    row['focus_energy_fraction'] for row in rows
                ])),
                'mean_source_to_sidelobe_db': float(np.mean([
                    row['source_to_sidelobe_db'] for row in rows
                ])),
                'mean_normalized_image_entropy': float(np.mean([
                    row['normalized_image_entropy'] for row in rows
                ])),
                'mean_reference_image_correlation': float(np.mean([
                    row['reference_image_correlation'] for row in rows
                ])),
            })
    rtm_dir = manifest.get(
        'rtm_output_directory', os.path.dirname(os.path.dirname(checkpoint_dir))
    )
    legacy_dir = manifest.get('legacy_output_directory', output_dir)
    os.makedirs(rtm_dir, exist_ok=True)
    os.makedirs(legacy_dir, exist_ok=True)
    _write_csv(os.path.join(rtm_dir, 'rtm_four_design_source_metrics.csv'), detail_rows)
    _write_csv(os.path.join(rtm_dir, 'rtm_four_design_summary_metrics.csv'), summary_rows)
    figures = {}
    for experiment in experiments:
        figures[experiment['key']] = _plot_rtm_four_array_experiment(
            experiment, images, detail_rows, design_sensors, source_indices,
            rtm_dir,
        )
    geometry_figure = _plot_rtm_four_array_geometry_3d(
        reference_physics, design_sensors, source_indices, rtm_dir
    )
    legacy_figures = _plot_legacy_reference_rtm_figures(
        images['reference_matched'], reference_physics, source_indices,
        legacy_dir,
    )
    metric_figure = _plot_rtm_metric_comparison(
        summary_rows, [experiment['key'] for experiment in experiments], rtm_dir
    )
    replot_inventory = {
        'mode': 'RTM_REPLOT_ONLY',
        'checkpoint_manifest': os.path.abspath(manifest_path),
        'experiment_figures': figures,
        'three_dimensional_acquisition_geometry_figure': geometry_figure,
        'legacy_reference_velocity_rtm_figures': legacy_figures,
        'metric_comparison_figure': metric_figure,
        'summary_metrics': summary_rows,
    }
    inventory_path = os.path.join(rtm_dir, 'rtm_replot_inventory.json')
    _atomic_write_json(inventory_path, replot_inventory)
    print(f'>>> RTM figures regenerated from checkpoint: {manifest_path}')
    return replot_inventory


# =============================================================================
# Path-correlated model discrepancy, joint receiver/calibration-source design,
# calibrated uncertainty, and leakage-free twin validation
# =============================================================================

import math
from dataclasses import dataclass
from scipy.special import logsumexp


@dataclass
class RobustArrivalSplit:
    """One independent velocity-realization split represented by FMM arrivals."""

    name: str
    arrivals_s: np.ndarray
    inventory: list
    last_fractional_velocity_residual: np.ndarray


def robust_closed_loop_config(analysis_config, physics, candidate_count):
    """Read bounded, reproducible controls for the replacement workflow.

    Production and smoke-test sizes are intentionally separate.  All four
    velocity splits use independent seeds and are generated before any design
    selection.  The final test split is never inspected by the optimizer or by
    the interval calibrator.
    """
    smoke = os.getenv('ROBUST_TWIN_TEST_MODE', '0') == '1'
    compute_profile = os.getenv(
        'ROBUST_COMPUTE_PROFILE', 'quick'
    ).strip().lower()
    if smoke:
        compute_profile = 'smoke'
    valid_profiles = {'smoke', 'quick', 'balanced', 'production'}
    if compute_profile not in valid_profiles:
        raise ValueError(
            'ROBUST_COMPUTE_PROFILE must be smoke, quick, balanced, or '
            f'production; received {compute_profile!r}.'
        )
    default_receiver_count = min(
        max(4, physics.dims + 2),
        int(os.getenv('POSTERIOR_STREAM_RECEIVER_COUNT', '10')),
        int(candidate_count),
    )
    default_receiver_count = 40
    # Production defaults deliberately use many independent velocity models.
    # Training learns the empirical path-error mean and full receiver covariance;
    # the disjoint interval split calibrates confidence regions.  Smoke-test sizes
    # stay small so the implementation can be checked quickly.  Environment
    # variables below can override every count without editing this file.
    profile_counts = {
        'smoke': {'train': 4, 'interval': 3, 'validation': 2, 'test': 3},
        'quick': {'train': 32, 'interval': 16, 'validation': 12, 'test': 8},
        'balanced': {
        #    'train': 256, 'interval': 128, 'validation': 64, 'test': 32,
            'train': 500, 'interval': 500,
            'validation': 500, 'test': 100,
        },
        # Exact legacy defaults for publication/final-production reproduction.
        'production': {
            'train': 500, 'interval': 500,
            'validation': 500, 'test': 100,
        },
    }
    default_counts = profile_counts[compute_profile]
    profile_event_counts = {
        'smoke': {'training': 6, 'interval': 6, 'validation': 6, 'test': 6},
        'quick': {'training': 12, 'interval': 12, 'validation': 12, 'test': 8},
        'balanced': {
           # 'training': 24, 'interval': 24, 'validation': 24, 'test': 16,
            'training': 70, 'interval': 70, 'validation': 70, 'test': 16,
        },
        'production': {
            'training': 100, 'interval': 100, 'validation': 100, 'test': 50,
        },
    }[compute_profile]
    profile_search = {
        'smoke': (1, 3, 1, 50, 2),
        'quick': (4, 4, 1, 200, 10),
        'balanced': (12, 8, 1, 500, 20),
        'production': (30, 12, 2, 300, 30),
    }[compute_profile]
    cpu_count = max(1, int(os.cpu_count() or 1))
    default_process_workers = min(2 if smoke else 8, max(1, cpu_count - 1))
    default_thread_workers = min(2 if smoke else 4, cpu_count)
    config = {
        'smoke_test': bool(smoke),
        'compute_profile': compute_profile,
        'seed': int(os.getenv(
            'ROBUST_TWIN_SEED', str(int(analysis_config['seed']) + 61001)
        )),
        'receiver_count': int(os.getenv(
            'ROBUST_RECEIVER_COUNT', str(default_receiver_count)
        )),
        'calibration_source_count': int(os.getenv(
            'ROBUST_CALIBRATION_SOURCE_COUNT', '2' if smoke else '3'
        )),
        'maximum_candidate_sites': int(os.getenv(
            'ROBUST_MAXIMUM_CANDIDATE_SITES', '14' if smoke else '48'
        )),
        'maximum_source_nodes': int(os.getenv(
            'ROBUST_MAXIMUM_SOURCE_NODES', '32' if smoke else '144'
        )),
        'train_models': int(os.getenv(
            'ROBUST_TRAIN_MODELS', str(default_counts['train'])
        )),
        'interval_models': int(os.getenv(
            'ROBUST_INTERVAL_MODELS', str(default_counts['interval'])
        )),
        'validation_models': int(os.getenv(
            'ROBUST_VALIDATION_MODELS', str(default_counts['validation'])
        )),
        'test_models': int(os.getenv(
            'ROBUST_TEST_MODELS', str(default_counts['test'])
        )),
        # The velocity realization is the natural process-parallel unit: every
        # task has an independent random seed and returns only its compact arrival
        # bank.  Spawn is the safe default on Windows and remains portable.
        'parallel_workers': int(os.getenv(
            'ROBUST_PARALLEL_WORKERS', str(default_process_workers)
        )),
        'parallel_minimum_models': int(os.getenv(
            'ROBUST_PARALLEL_MINIMUM_MODELS', '2' if smoke else '8'
        )),
        'parallel_chunksize': int(os.getenv(
            'ROBUST_PARALLEL_CHUNKSIZE', '1'
        )),
        'multiprocessing_start_method': os.getenv(
            'ROBUST_MP_START_METHOD', 'spawn'
        ).strip().lower(),
        'parallel_fallback_to_serial': (
            os.getenv('ROBUST_PARALLEL_FALLBACK_TO_SERIAL', '1') != '0'
        ),
        # These bounded thread pools execute only when no velocity-model process
        # pool is active; worker-side arrival banks always force one thread.
        'reference_arrival_workers': int(os.getenv(
            'ROBUST_REFERENCE_ARRIVAL_WORKERS', str(default_thread_workers)
        )),
        'design_parallel_workers': int(os.getenv(
            'ROBUST_DESIGN_PARALLEL_WORKERS', str(default_thread_workers)
        )),
        'simulation_parallel_workers': int(os.getenv(
            'ROBUST_SIMULATION_PARALLEL_WORKERS', str(default_thread_workers)
        )),
        # Position-disjoint event sets.  ROBUST_EVENTS_PER_MODEL remains a legacy
        # common override, while split-specific variables take precedence.
        'training_events_per_model': int(os.getenv(
            'ROBUST_TRAINING_EVENTS_PER_MODEL',
            os.getenv('ROBUST_EVENTS_PER_MODEL', str(
                profile_event_counts['training']
            )),
        )),
        'interval_events_per_model': int(os.getenv(
            'ROBUST_INTERVAL_EVENTS_PER_MODEL',
            os.getenv('ROBUST_EVENTS_PER_MODEL', str(
                profile_event_counts['interval']
            )),
        )),
        'validation_events_per_model': int(os.getenv(
            'ROBUST_VALIDATION_EVENTS_PER_MODEL',
            os.getenv('ROBUST_EVENTS_PER_MODEL', str(
                profile_event_counts['validation']
            )),
        )),
        'test_events_per_model': int(os.getenv(
            'ROBUST_TEST_EVENTS_PER_MODEL',
            os.getenv('ROBUST_EVENTS_PER_MODEL', str(
                profile_event_counts['test']
            )),
        )),
        'event_target_jitter_fraction': float(os.getenv(
            'ROBUST_EVENT_TARGET_JITTER_FRACTION', '0.035'
        )),
        'picking_noise_std_s': float(os.getenv(
            'ROBUST_PICKING_NOISE_STD',
            str(analysis_config['picking_noise_std']),
        )),
        'calibration_repeats': int(os.getenv(
            'ROBUST_CALIBRATION_REPEATS', str(profile_search[4])
        )),
        'velocity_rms_fractions': _parse_float_list(
            'ROBUST_VELOCITY_RMS_FRACTIONS', (0.03, 0.05, 0.08, 0.10)
        ),
        'velocity_correlation_fractions': _parse_float_list(
            'ROBUST_VELOCITY_CORRELATION_FRACTIONS', (0.035, 0.07, 0.12)
        ),
        # An independent perturbation is drawn at every grid point and smoothed
        # before the taper is applied.  The default background amplitude is only
        # six percent of the target-zone amplitude.
        'velocity_target_radius_fraction': float(os.getenv(
            'ROBUST_VELOCITY_TARGET_RADIUS_FRACTION', '0.14'
        )),
        'velocity_background_fraction': float(os.getenv(
            'ROBUST_VELOCITY_BACKGROUND_FRACTION', '0.06'
        )),
        'velocity_clip_fraction': float(os.getenv(
            'ROBUST_VELOCITY_CLIP_FRACTION', '0.30'
        )),
        'test_rms_multiplier': float(os.getenv(
            'ROBUST_TEST_RMS_MULTIPLIER', '1.20'
        )),
        'test_correlation_multiplier': float(os.getenv(
            'ROBUST_TEST_CORRELATION_MULTIPLIER', '1.25'
        )),
        'model_covariance_shrinkage': float(os.getenv(
            'ROBUST_MODEL_COVARIANCE_SHRINKAGE', '0.10'
        )),
        'calibration_kernel_length_fraction': float(os.getenv(
            'ROBUST_CALIBRATION_KERNEL_LENGTH_FRACTION', '0.25'
        )),
        'confidence_levels': (0.68, 0.90, 0.95),
        'cvar_alpha': float(os.getenv('ROBUST_CVAR_ALPHA', '0.90')),
        'objective_mean_weight': float(os.getenv(
            'ROBUST_OBJECTIVE_MEAN_WEIGHT', '0.50'
        )),
        'objective_tail_weight': float(os.getenv(
            'ROBUST_OBJECTIVE_TAIL_WEIGHT', '0.20'
        )),
        'objective_coverage_weight': float(os.getenv(
            'ROBUST_OBJECTIVE_COVERAGE_WEIGHT', '0.20'
        )),
        'objective_sharpness_weight': float(os.getenv(
            'ROBUST_OBJECTIVE_SHARPNESS_WEIGHT', '0.10'
        )),
        'joint_exchange_iterations': int(os.getenv(
            'ROBUST_JOINT_EXCHANGE_ITERATIONS', str(profile_search[0])
        )),
        'joint_exchange_proposals': int(os.getenv(
            'ROBUST_JOINT_EXCHANGE_PROPOSALS', str(profile_search[1])
        )),
        'joint_random_restarts': int(os.getenv(
            'ROBUST_JOINT_RANDOM_RESTARTS', str(profile_search[2])
        )),
        'bootstrap_draws': int(os.getenv(
            'ROBUST_BOOTSTRAP_DRAWS', str(profile_search[3])
        )),
        'checkpoint_velocity_arrivals': (
            os.getenv('ROBUST_CHECKPOINT_VELOCITY_ARRIVALS', '1') != '0'
        ),
        'resume_velocity_arrivals': (
            os.getenv('ROBUST_RESUME_VELOCITY_ARRIVALS', '1') != '0'
        ),
        'marginal_likelihood_event_batch': int(os.getenv(
            'ROBUST_MARGINAL_EVENT_BATCH', '4'
        )),
        'station_failure_cases': int(os.getenv(
            'ROBUST_STATION_FAILURE_CASES', '1' if smoke else '3'
        )),
    }
    if not 0.0 < config['picking_noise_std_s']:
        raise ValueError('ROBUST_PICKING_NOISE_STD must be positive.')
    if not 0.0 <= config['model_covariance_shrinkage'] <= 1.0:
        raise ValueError('ROBUST_MODEL_COVARIANCE_SHRINKAGE must lie in [0, 1].')
    if not 0.0 < config['cvar_alpha'] < 1.0:
        raise ValueError('ROBUST_CVAR_ALPHA must lie in (0, 1).')
    if config['velocity_target_radius_fraction'] <= 0.0:
        raise ValueError(
            'ROBUST_VELOCITY_TARGET_RADIUS_FRACTION must be positive.'
        )
    if not 0.0 <= config['velocity_background_fraction'] < 1.0:
        raise ValueError(
            'ROBUST_VELOCITY_BACKGROUND_FRACTION must lie in [0, 1).'
        )
    event_count_keys = (
        'training_events_per_model', 'interval_events_per_model',
        'validation_events_per_model', 'test_events_per_model',
    )
    if any(config[key] <= 0 for key in event_count_keys):
        raise ValueError('All split-specific event counts must be positive.')
    if config['event_target_jitter_fraction'] <= 0.0:
        raise ValueError('ROBUST_EVENT_TARGET_JITTER_FRACTION must be positive.')
    if any(config[key] <= 0 for key in (
            'parallel_workers', 'parallel_minimum_models',
            'parallel_chunksize', 'reference_arrival_workers',
            'design_parallel_workers', 'simulation_parallel_workers')):
        raise ValueError('All robust parallel worker/chunk controls must be positive.')
    available_start_methods = multiprocessing.get_all_start_methods()
    if config['multiprocessing_start_method'] not in available_start_methods:
        raise ValueError(
            'ROBUST_MP_START_METHOD must be one of '
            f'{available_start_methods}, not '
            f"{config['multiprocessing_start_method']!r}."
        )
    if any(value <= 0 for value in (
            config['receiver_count'], config['calibration_source_count'],
            config['train_models'], config['interval_models'],
            config['validation_models'], config['test_models'],
            config['marginal_likelihood_event_batch'])):
        raise ValueError('Robust design counts must be positive.')
    return config


def _robust_physical_positions(indices, physics):
    return (
        np.asarray(indices, dtype=float)
        * np.asarray(physics.spacing, dtype=float)[None, :]
    )


def _maximin_subset_indices(positions, count, mandatory=()):
    """Deterministic farthest-point subset with optional mandatory indices."""
    positions = np.asarray(positions, dtype=float)
    count = min(int(count), len(positions))
    if count <= 0:
        return np.empty(0, dtype=int)
    selected = []
    for index in mandatory:
        index = int(index)
        if 0 <= index < len(positions) and index not in selected:
            selected.append(index)
        if len(selected) == count:
            return np.asarray(selected, dtype=int)
    scale = np.ptp(positions, axis=0)
    scale = np.where(scale > np.finfo(float).eps, scale, 1.0)
    normalized = (positions - np.min(positions, axis=0)) / scale
    if not selected:
        centre = np.mean(normalized, axis=0)
        selected.append(int(np.argmin(np.sum((normalized - centre) ** 2, axis=1))))
    minimum_distance = np.min(
        np.sum(
            (normalized[:, None, :] - normalized[np.asarray(selected)][None, :, :]) ** 2,
            axis=2,
        ),
        axis=1,
    )
    minimum_distance[np.asarray(selected)] = -np.inf
    while len(selected) < count:
        next_index = int(np.argmax(minimum_distance))
        selected.append(next_index)
        distance = np.sum((normalized - normalized[next_index]) ** 2, axis=1)
        minimum_distance = np.minimum(minimum_distance, distance)
        minimum_distance[np.asarray(selected)] = -np.inf
    return np.asarray(selected, dtype=int)


def _bounded_candidate_pool(candidates, physics, maximum_count):
    candidates = [tuple(int(value) for value in point) for point in candidates]
    if len(candidates) <= int(maximum_count):
        return candidates
    positions = _robust_physical_positions(candidates, physics)
    selected = _maximin_subset_indices(positions, int(maximum_count))
    return [candidates[index] for index in selected]


def _generate_target_near_event_nodes(targets, physics, count, seed,
                                      jitter_fraction, excluded=()):
    """Generate unique integer-grid events around the monitored target body."""
    targets_array = np.asarray(targets, dtype=int)
    if targets_array.ndim != 2 or targets_array.shape[1] != physics.dims:
        raise ValueError('Targets must contain one grid index per model dimension.')
    count = int(count)
    shape = np.asarray(physics.shape, dtype=int)
    sigma = np.maximum(
        1.0, float(jitter_fraction) * np.maximum(shape - 1, 1)
    )
    rng = np.random.default_rng(int(seed))
    forbidden = {tuple(map(int, point)) for point in excluded}
    selected = []
    selected_set = set()
    maximum_attempts = max(2000, 250 * count)
    for _ in range(maximum_attempts):
        anchor = targets_array[int(rng.integers(0, len(targets_array)))]
        proposal = np.rint(anchor + rng.normal(0.0, sigma)).astype(int)
        proposal = np.clip(proposal, 0, shape - 1)
        point = tuple(map(int, proposal))
        if point in forbidden or point in selected_set:
            continue
        selected.append(point)
        selected_set.add(point)
        if len(selected) == count:
            break

    # Deterministic near-target fallback for unusually dense requested splits.
    if len(selected) < count:
        lower = np.maximum(
            0, np.min(targets_array, axis=0) - np.ceil(3.5 * sigma).astype(int)
        )
        upper = np.minimum(
            shape - 1,
            np.max(targets_array, axis=0) + np.ceil(3.5 * sigma).astype(int),
        )
        axes = [np.arange(lo, hi + 1, dtype=int) for lo, hi in zip(lower, upper)]
        mesh = np.meshgrid(*axes, indexing='ij')
        candidates = np.stack([component.ravel() for component in mesh], axis=1)
        normalized_distance = np.min(np.sum(
            ((candidates[:, None, :] - targets_array[None, :, :])
             / sigma[None, None, :]) ** 2,
            axis=2,
        ), axis=1)
        tie_break = rng.uniform(0.0, 1.0e-9, size=len(candidates))
        for candidate_number in np.argsort(normalized_distance + tie_break):
            point = tuple(map(int, candidates[int(candidate_number)]))
            if point in forbidden or point in selected_set:
                continue
            selected.append(point)
            selected_set.add(point)
            if len(selected) == count:
                break
    if len(selected) != count:
        raise ValueError(
            f'Could generate only {len(selected)} of {count} unique target-near '
            'events. Reduce the event counts or jitter exclusion constraints.'
        )
    selected_array = np.asarray(selected, dtype=float)
    spacing = np.asarray(physics.spacing, dtype=float)
    nearest_target_distance = np.min(np.linalg.norm(
        (selected_array[:, None, :] - targets_array[None, :, :])
        * spacing[None, None, :], axis=2,
    ), axis=1)
    diagnostics = {
        'seed': int(seed),
        'event_count': int(count),
        'jitter_sigma_cells': sigma.tolist(),
        'mean_nearest_target_distance_m': float(np.mean(nearest_target_distance)),
        'maximum_nearest_target_distance_m': float(np.max(nearest_target_distance)),
    }
    return selected, diagnostics


def _build_disjoint_target_event_splits(targets, true_sources, physics, config):
    """Create position-disjoint train/calibration/validation/test event sets."""
    specifications = [
        ('training', 'training_events_per_model', 1101),
        ('interval_calibration', 'interval_events_per_model', 1201),
        ('design_validation', 'validation_events_per_model', 1301),
        ('untouched_test', 'test_events_per_model', 1401),
    ]
    excluded = {tuple(map(int, point)) for point in true_sources}
    splits = {}
    diagnostics = {}
    for split_name, count_key, seed_offset in specifications:
        nodes, summary = _generate_target_near_event_nodes(
            targets, physics, int(config[count_key]),
            int(config['seed']) + seed_offset,
            config['event_target_jitter_fraction'], excluded=excluded,
        )
        splits[split_name] = nodes
        diagnostics[split_name] = summary
        excluded.update(nodes)
    sets = {name: set(nodes) for name, nodes in splits.items()}
    pairwise_overlap = {
        f'{left}__{right}': int(len(sets[left] & sets[right]))
        for number, left in enumerate(sets)
        for right in list(sets)[number + 1:]
    }
    if any(pairwise_overlap.values()):
        raise RuntimeError('Generated event splits are not position-disjoint.')
    return splits, {
        'split_diagnostics': diagnostics,
        'pairwise_position_overlap_counts': pairwise_overlap,
        'all_splits_position_disjoint': True,
        'declared_true_sources_excluded_from_generated_events': True,
    }


def _build_robust_source_nodes(targets, true_sources, physics, maximum_count,
                               mandatory_sources=()):
    """Construct a bounded search grid while preserving all split events."""
    shape = np.asarray(physics.shape, dtype=int)
    declared = [
        tuple(map(int, point))
        for point in list(targets) + list(true_sources) + list(mandatory_sources)
    ]
    unique = list(dict.fromkeys(declared))
    if not unique:
        raise ValueError('At least one target/source is required.')
    coordinates = np.asarray(unique, dtype=int)
    lower = np.maximum(0, np.min(coordinates, axis=0) - 3)
    upper = np.minimum(shape - 1, np.max(coordinates, axis=0) + 3)
    per_axis = max(3, int(np.ceil(float(maximum_count) ** (1.0 / physics.dims))))
    axes = [
        np.unique(np.rint(np.linspace(lo, hi, per_axis)).astype(int))
        for lo, hi in zip(lower, upper)
    ]
    mesh = np.meshgrid(*axes, indexing='ij')
    grid = np.stack([component.ravel() for component in mesh], axis=1)
    for point in grid:
        unique.append(tuple(int(value) for value in point))
    unique = list(dict.fromkeys(unique))
    declared_unique = list(dict.fromkeys(
        tuple(map(int, point))
        for point in list(true_sources) + list(mandatory_sources)
    ))
    if len(declared_unique) > int(maximum_count):
        raise ValueError(
            'ROBUST_MAXIMUM_SOURCE_NODES is smaller than the number of mandatory '
            'declared and split-specific event nodes.'
        )
    if len(unique) > int(maximum_count):
        positions = _robust_physical_positions(unique, physics)
        mandatory = [unique.index(point) for point in declared_unique if point in unique]
        selected = _maximin_subset_indices(
            positions, int(maximum_count), mandatory=mandatory
        )
        unique = [unique[index] for index in selected]
    return unique


def _straight_segment_arrival_bank(velocity, spacing, sources, candidates,
                                   samples_per_path=96):
    """Path-specific straight-ray fallback when scikit-fmm is unavailable."""
    velocity = np.asarray(velocity, dtype=float)
    spacing = np.asarray(spacing, dtype=float)
    sources_array = np.asarray(sources, dtype=float)
    candidates_array = np.asarray(candidates, dtype=float)
    bank = np.empty((len(sources), len(candidates)), dtype=float)
    fractions = np.linspace(0.0, 1.0, int(samples_per_path), dtype=float)
    slowness = 1.0 / np.maximum(velocity, np.finfo(float).tiny)
    for source_number, source in enumerate(sources_array):
        for receiver_number, receiver in enumerate(candidates_array):
            path = source[:, None] + (receiver - source)[:, None] * fractions[None, :]
            sampled_slowness = map_coordinates(
                slowness, path, order=1, mode='nearest'
            )
            distance = float(np.linalg.norm((receiver - source) * spacing))
            bank[source_number, receiver_number] = distance * float(
                np.trapezoid(sampled_slowness, fractions)
            )
    return bank


def _robust_arrival_bank(physics, sources, candidates, parallel_workers=1):
    """Return source-by-receiver arrivals using FMM or a path-aware fallback.

    Receiver FMM solves share one read-only velocity volume and are therefore
    thread-parallel without copying the model.  Velocity-model process workers
    call this function with ``parallel_workers=1`` so that process and receiver
    parallelism are never nested.
    """
    if not SKFMM_AVAILABLE:
        return _straight_segment_arrival_bank(
            physics.V, physics.spacing, sources, candidates
        )
    sources = [tuple(map(int, source)) for source in sources]
    candidates = [tuple(map(int, receiver)) for receiver in candidates]
    bank = np.empty((len(sources), len(candidates)), dtype=np.float64)

    def solve_receiver(item):
        receiver_number, receiver = item
        field = physics.compute_traveltime_field(tuple(receiver))
        values = np.asarray(
            [field[tuple(source)] for source in sources], dtype=float
        )
        del field
        return int(receiver_number), values

    worker_count = min(
        max(1, int(parallel_workers)), max(1, len(candidates))
    )
    indexed_candidates = list(enumerate(candidates))
    if worker_count == 1 or len(candidates) < 2:
        results = map(solve_receiver, indexed_candidates)
        execution_mode = 'serial receiver FMM'
    else:
        executor = ThreadPoolExecutor(
            max_workers=worker_count,
            thread_name_prefix='robust-reference-fmm',
        )
        results = executor.map(solve_receiver, indexed_candidates)
        execution_mode = f'{worker_count}-thread receiver FMM'
    try:
        for receiver_number, values in results:
            bank[:, receiver_number] = values
    finally:
        if worker_count > 1 and len(candidates) >= 2:
            executor.shutdown(wait=True)
    physics.last_robust_arrival_execution_mode = execution_mode
    return bank


_ROBUST_VELOCITY_WORKER_STATE = None
_ROBUST_THREADPOOL_LIMITER = None


def _initialize_robust_velocity_worker(reference_velocity, shape, spacing,
                                       is_3d, sources, candidates, targets,
                                       perturbation_config):
    """Initialize one spawn-safe worker without sending a model per task."""
    global _ROBUST_VELOCITY_WORKER_STATE, _ROBUST_THREADPOOL_LIMITER
    # Each process performs independent FMM work.  Restricting BLAS/OpenMP inside
    # it prevents N processes from each creating a full machine-sized thread team.
    os.environ['OMP_NUM_THREADS'] = '1'
    os.environ['OPENBLAS_NUM_THREADS'] = '1'
    os.environ['MKL_NUM_THREADS'] = '1'
    try:
        from threadpoolctl import threadpool_limits
        _ROBUST_THREADPOOL_LIMITER = threadpool_limits(limits=1)
    except Exception:
        _ROBUST_THREADPOOL_LIMITER = None
    reusable_physics = PhysicsEngine(
        tuple(map(int, shape)), tuple(map(float, spacing)),
        is_3d=bool(is_3d), velocity_file=None,
    )
    _ROBUST_VELOCITY_WORKER_STATE = {
        'reference_velocity': np.asarray(reference_velocity, dtype=np.float32),
        'shape': tuple(map(int, shape)),
        'spacing': tuple(map(float, spacing)),
        'is_3d': bool(is_3d),
        'sources': [tuple(map(int, value)) for value in sources],
        'candidates': [tuple(map(int, value)) for value in candidates],
        'targets': [tuple(map(int, value)) for value in targets],
        'config': dict(perturbation_config),
        'physics_engine': reusable_physics,
    }


def _compute_robust_velocity_realization(state, task):
    """Generate and forward-model one deterministic velocity realization."""
    (model_number, model_seed, split_seed, requested_rms,
     correlation_fraction, split_name, retain_residual) = task
    started = time.perf_counter()
    rng = np.random.default_rng(int(model_seed))
    config = state['config']
    velocity, residual, diagnostics = (
        _target_localized_random_smoothed_velocity_perturbation(
            state['reference_velocity'], state['targets'], requested_rms, rng,
            correlation_fraction=correlation_fraction,
            target_radius_fraction=config['velocity_target_radius_fraction'],
            background_fraction=config['velocity_background_fraction'],
            clip_fraction=config['velocity_clip_fraction'],
        )
    )
    model_physics = state.get('physics_engine')
    if model_physics is None:
        model_physics = PhysicsEngine(
            state['shape'], state['spacing'], is_3d=state['is_3d'],
            velocity_file=None,
        )
        state['physics_engine'] = model_physics
    model_physics.V = np.asarray(velocity, dtype=np.float32)
    arrival_bank = _robust_arrival_bank(
        model_physics, state['sources'], state['candidates'],
        parallel_workers=1,
    ).astype(np.float32)
    inventory_row = {
        'split': str(split_name),
        'model_number': int(model_number),
        'split_seed': int(split_seed),
        'model_seed': int(model_seed),
        'requested_rms_fraction': float(requested_rms),
        'realized_rms_fraction': float(np.sqrt(np.mean(residual ** 2))),
        'realized_target_rms_fraction': diagnostics[
            'realized_target_rms_fraction'
        ],
        'realized_background_rms_fraction': diagnostics[
            'realized_background_rms_fraction'
        ],
        'background_to_target_rms_ratio': float(
            diagnostics['realized_background_rms_fraction']
            / max(
                diagnostics['realized_target_rms_fraction'],
                np.finfo(float).tiny,
            )
        ),
        'correlation_fraction_of_grid': float(correlation_fraction),
        'generation_method': diagnostics['generation_method'],
        'smoothing_sigma_cells': diagnostics['smoothing_sigma_cells'],
        'pointwise_random_draw_count': diagnostics[
            'pointwise_random_draw_count'
        ],
        'target_cell_count': diagnostics['target_cell_count'],
        'background_cell_count': diagnostics['background_cell_count'],
        'velocity_min_m_per_s': float(np.min(velocity)),
        'velocity_mean_m_per_s': float(np.mean(velocity)),
        'velocity_max_m_per_s': float(np.max(velocity)),
        'forward_model_wall_seconds': float(time.perf_counter() - started),
    }
    retained = (
        np.asarray(residual, dtype=np.float32)
        if bool(retain_residual) else None
    )
    return int(model_number), arrival_bank, inventory_row, retained


def _robust_velocity_model_worker(task):
    """Process-pool entry point using the read-only initializer state."""
    if _ROBUST_VELOCITY_WORKER_STATE is None:
        raise RuntimeError('Robust velocity worker was not initialized.')
    return _compute_robust_velocity_realization(
        _ROBUST_VELOCITY_WORKER_STATE, task
    )


def _sha256_contiguous_array(array, block_bytes=8 * 1024 * 1024):
    """Hash an ndarray without materializing a second full-size byte string."""
    contiguous = np.ascontiguousarray(array)
    byte_view = memoryview(contiguous).cast('B')
    digest = hashlib.sha256()
    for start in range(0, len(byte_view), int(block_bytes)):
        digest.update(byte_view[start:start + int(block_bytes)])
    return digest.hexdigest()


def _read_checkpoint_inventory(path, count):
    """Read append-only rows; a later duplicate safely supersedes an older row."""
    rows = [None] * int(count)
    if not os.path.exists(path):
        return rows
    with open(path, 'r', encoding='utf-8') as stream:
        for line in stream:
            try:
                row = json.loads(line)
                index = int(row['model_number'])
                if 0 <= index < len(rows):
                    rows[index] = row
            except (ValueError, TypeError, KeyError, json.JSONDecodeError):
                # A final partial line can be left by a forced process stop.
                continue
    return rows


def _stream_independent_velocity_arrivals(reference_physics, sources,
                                          candidates, targets, count, seed,
                                          config, split_name,
                                          rms_multiplier=1.0,
                                          correlation_multiplier=1.0,
                                          process_executor=None,
                                          checkpoint_dir=None):
    """Generate and forward-model one independent velocity split in parallel.

    A process initializer transfers the reference volume and immutable geometry
    once per worker.  Individual tasks contain only a model number, deterministic
    child seed, and two perturbation scalars; workers return compact arrival banks.
    This avoids repeatedly serializing the full velocity model.  The serial path
    uses the same child seeds and computation, so results do not depend on worker
    count or completion order.
    """
    split_started = time.perf_counter()
    count = int(count)
    reference_velocity = np.asarray(reference_physics.V, dtype=np.float32)
    last_residual = np.zeros_like(reference_velocity, dtype=np.float32)
    rms_values = list(config['velocity_rms_fractions'])
    correlation_values = list(config['velocity_correlation_fractions'])
    child_sequences = np.random.SeedSequence(int(seed)).spawn(count)
    tasks = []
    for model_number, child_sequence in enumerate(child_sequences):
        requested_rms = float(
            rms_values[model_number % len(rms_values)] * rms_multiplier
        )
        correlation_fraction = float(
            correlation_values[(2 * model_number + 1) % len(correlation_values)]
            * correlation_multiplier
        )
        model_seed = int(child_sequence.generate_state(
            1, dtype=np.uint64
        )[0])
        tasks.append(
            (
                int(model_number), model_seed, int(seed), requested_rms,
                correlation_fraction, str(split_name),
                bool(model_number == count - 1),
            )
        )

    arrival_shape = (count, len(sources), len(candidates))
    checkpoint_enabled = bool(
        checkpoint_dir
        and config.get('checkpoint_velocity_arrivals', True)
    )
    inventory = [None] * count
    completed = np.zeros(count, dtype=bool)
    checkpoint_inventory_stream = None
    checkpoint_paths = None
    if checkpoint_enabled:
        os.makedirs(checkpoint_dir, exist_ok=True)
        token = _safe_file_token(split_name)
        checkpoint_paths = {
            'metadata': os.path.join(checkpoint_dir, f'{token}.metadata.json'),
            'arrivals': os.path.join(checkpoint_dir, f'{token}.arrivals.npy'),
            'progress': os.path.join(checkpoint_dir, f'{token}.progress.npy'),
            'inventory': os.path.join(checkpoint_dir, f'{token}.inventory.jsonl'),
            'last_residual': os.path.join(
                checkpoint_dir, f'{token}.last_residual.npy'
            ),
        }
        cached_hash = getattr(
            reference_physics, '_robust_reference_velocity_sha256', None
        )
        if cached_hash is None:
            cached_hash = _sha256_contiguous_array(reference_velocity)
            reference_physics._robust_reference_velocity_sha256 = cached_hash
        fingerprint_payload = {
            'kernel_version': 2,
            'split_name': str(split_name),
            'count': count,
            'seed': int(seed),
            'shape': list(map(int, reference_physics.shape)),
            'spacing': list(map(float, reference_physics.spacing)),
            'reference_velocity_sha256': cached_hash,
            'sources': [list(map(int, value)) for value in sources],
            'candidates': [list(map(int, value)) for value in candidates],
            'targets': [list(map(int, value)) for value in targets],
            'rms_values': list(map(float, rms_values)),
            'correlation_values': list(map(float, correlation_values)),
            'rms_multiplier': float(rms_multiplier),
            'correlation_multiplier': float(correlation_multiplier),
            'velocity_target_radius_fraction': float(
                config['velocity_target_radius_fraction']
            ),
            'velocity_background_fraction': float(
                config['velocity_background_fraction']
            ),
            'velocity_clip_fraction': float(config['velocity_clip_fraction']),
            'skfmm_available': bool(SKFMM_AVAILABLE),
        }
        fingerprint = hashlib.sha256(json.dumps(
            fingerprint_payload, sort_keys=True, separators=(',', ':')
        ).encode('utf-8')).hexdigest()
        valid_checkpoint = False
        if config.get('resume_velocity_arrivals', True):
            try:
                with open(
                        checkpoint_paths['metadata'], 'r',
                        encoding='utf-8') as stream:
                    prior_metadata = json.load(stream)
                valid_checkpoint = (
                    prior_metadata.get('fingerprint') == fingerprint
                    and os.path.exists(checkpoint_paths['arrivals'])
                    and os.path.exists(checkpoint_paths['progress'])
                )
            except (OSError, ValueError, json.JSONDecodeError):
                valid_checkpoint = False
        if valid_checkpoint:
            try:
                arrivals = np.load(
                    checkpoint_paths['arrivals'], mmap_mode='r+'
                )
                progress_map = np.load(
                    checkpoint_paths['progress'], mmap_mode='r+'
                )
                valid_checkpoint = (
                    arrivals.shape == arrival_shape
                    and arrivals.dtype == np.dtype(np.float32)
                    and progress_map.shape == (count,)
                )
            except (OSError, ValueError):
                valid_checkpoint = False
        if not valid_checkpoint:
            arrivals = np.lib.format.open_memmap(
                checkpoint_paths['arrivals'], mode='w+', dtype=np.float32,
                shape=arrival_shape,
            )
            progress_map = np.lib.format.open_memmap(
                checkpoint_paths['progress'], mode='w+', dtype=np.bool_,
                shape=(count,),
            )
            progress_map[:] = False
            progress_map.flush()
            with open(
                    checkpoint_paths['inventory'], 'w',
                    encoding='utf-8'):
                pass
            _atomic_write_json(checkpoint_paths['metadata'], {
                'fingerprint': fingerprint,
                'fingerprint_inputs': fingerprint_payload,
                'arrival_shape': list(arrival_shape),
                'dtype': 'float32',
            })
        else:
            inventory = _read_checkpoint_inventory(
                checkpoint_paths['inventory'], count
            )
            completed = np.asarray(progress_map, dtype=bool).copy()
            completed &= np.asarray([
                row is not None for row in inventory
            ], dtype=bool)
            if completed[-1] and not os.path.exists(
                    checkpoint_paths['last_residual']):
                completed[-1] = False
            progress_map[:] = completed
            progress_map.flush()
            if os.path.exists(checkpoint_paths['last_residual']):
                last_residual = np.asarray(np.load(
                    checkpoint_paths['last_residual'], allow_pickle=False
                ), dtype=np.float32)
        completed_count = int(np.sum(completed))
        if completed_count:
            print(
                f'        {split_name}: resuming {completed_count}/{count} '
                'checkpointed velocity models.'
            )
        tasks = [task for task in tasks if not completed[int(task[0])]]
        checkpoint_inventory_stream = open(
            checkpoint_paths['inventory'], 'a', encoding='utf-8', buffering=1
        )
    else:
        arrivals = np.empty(arrival_shape, dtype=np.float32)
        progress_map = None

    perturbation_config = {
        key: config[key] for key in (
            'velocity_target_radius_fraction',
            'velocity_background_fraction',
            'velocity_clip_fraction',
        )
    }
    state = {
        'reference_velocity': reference_velocity,
        'shape': tuple(reference_physics.shape),
        'spacing': tuple(reference_physics.spacing),
        'is_3d': bool(reference_physics.is_3d),
        'sources': [tuple(map(int, value)) for value in sources],
        'candidates': [tuple(map(int, value)) for value in candidates],
        'targets': [tuple(map(int, value)) for value in targets],
        'config': perturbation_config,
        'physics_engine': PhysicsEngine(
            tuple(reference_physics.shape), tuple(reference_physics.spacing),
            is_3d=bool(reference_physics.is_3d), velocity_file=None,
        ),
    }
    pending_count = len(tasks)
    worker_count = min(
        int(config['parallel_workers']), max(1, pending_count)
    )
    use_process_pool = bool(
        worker_count > 1
        and pending_count >= int(config['parallel_minimum_models'])
    )
    execution_mode = 'serial velocity realizations'
    completed_in_parallel = False

    def store_result(result):
        nonlocal last_residual
        model_number, arrival_bank, row, retained_residual = result
        model_number = int(model_number)
        arrivals[model_number] = arrival_bank
        row['execution_mode'] = execution_mode
        row['configured_process_workers'] = int(config['parallel_workers'])
        row['effective_process_workers'] = (
            int(worker_count)
            if use_process_pool and 'fallback' not in execution_mode else 1
        )
        inventory[model_number] = row
        if retained_residual is not None:
            last_residual = np.asarray(retained_residual, dtype=np.float32)
            if checkpoint_paths is not None:
                _atomic_save_npy(
                    checkpoint_paths['last_residual'], last_residual
                )
        if checkpoint_paths is not None:
            # Durability order matters: arrival data and diagnostics reach disk
            # before the completion bit makes this model eligible for resume.
            arrivals.flush()
            checkpoint_inventory_stream.write(
                json.dumps(row, separators=(',', ':')) + '\n'
            )
            checkpoint_inventory_stream.flush()
            progress_map[model_number] = True
            progress_map.flush()

    def consume_results(results):
        # Stream results directly into the preallocated bank.  Converting the
        # executor iterator to a list temporarily duplicated an entire split.
        for result in results:
            store_result(result)

    if pending_count == 0:
        execution_mode = 'checkpoint resume (no FMM solves)'
        completed_in_parallel = True
    elif use_process_pool:
        execution_mode = f'{worker_count}-process velocity realizations'
        if process_executor is not None:
            try:
                consume_results(process_executor.map(
                    _robust_velocity_model_worker, tasks,
                    chunksize=int(config['parallel_chunksize']),
                ))
                completed_in_parallel = True
            except Exception as error:
                if not bool(config['parallel_fallback_to_serial']):
                    raise
                warnings.warn(
                    f'Shared parallel velocity pool failed for {split_name!r}; '
                    f'retrying serially with identical child seeds. Original '
                    f'error: {error}', RuntimeWarning,
                )
                execution_mode = 'serial fallback after shared-pool failure'
        else:
            context = multiprocessing.get_context(
                config['multiprocessing_start_method']
            )
            previous_worker_flag = os.environ.get('ROBUST_FMM_PROCESS_WORKER')
            os.environ['ROBUST_FMM_PROCESS_WORKER'] = '1'
            try:
                with ProcessPoolExecutor(
                        max_workers=worker_count,
                        mp_context=context,
                        initializer=_initialize_robust_velocity_worker,
                        initargs=(
                            reference_velocity, reference_physics.shape,
                            reference_physics.spacing, reference_physics.is_3d,
                            sources, candidates, targets, perturbation_config,
                        )) as executor:
                    consume_results(executor.map(
                        _robust_velocity_model_worker, tasks,
                        chunksize=int(config['parallel_chunksize']),
                    ))
                    completed_in_parallel = True
            except Exception as error:
                if not bool(config['parallel_fallback_to_serial']):
                    raise
                warnings.warn(
                    f'Parallel velocity split {split_name!r} failed; retrying '
                    f'serially with identical child seeds. Original error: {error}',
                    RuntimeWarning,
                )
                execution_mode = 'serial fallback after process-pool failure'
            finally:
                if previous_worker_flag is None:
                    os.environ.pop('ROBUST_FMM_PROCESS_WORKER', None)
                else:
                    os.environ['ROBUST_FMM_PROCESS_WORKER'] = previous_worker_flag
    if not completed_in_parallel:
        # On a partial parallel failure recompute all deterministic tasks so the
        # returned split is complete and has one consistent execution mode.
        for model_number in range(count):
            if not completed[model_number]:
                inventory[model_number] = None
        for task in tasks:
            store_result(_compute_robust_velocity_realization(state, task))
    if checkpoint_inventory_stream is not None:
        checkpoint_inventory_stream.close()
    if hasattr(arrivals, 'flush'):
        arrivals.flush()
    split_wall_seconds = float(time.perf_counter() - split_started)
    for row in inventory:
        if row is None:
            raise RuntimeError(
                f'Incomplete velocity checkpoint for split {split_name!r}.'
            )
        row.setdefault('split_wall_seconds', split_wall_seconds)
    print(
        f'        {split_name}: {execution_mode}; '
        f'{count} models completed in {split_wall_seconds:.2f} s.'
    )
    gc.collect()
    return RobustArrivalSplit(
        split_name, arrivals, inventory, last_residual
    )


def _calibration_interpolation_weights(source_positions, calibration_indices,
                                       length_scale):
    source_positions = np.asarray(source_positions, dtype=float)
    calibration_indices = np.asarray(calibration_indices, dtype=int)
    calibration_positions = source_positions[calibration_indices]
    distances = np.linalg.norm(
        source_positions[:, None, :] - calibration_positions[None, :, :],
        axis=2,
    )
    length_scale = max(float(length_scale), np.finfo(float).eps)
    weights = np.exp(-0.5 * (distances / length_scale) ** 2)
    weights /= np.maximum(np.sum(weights, axis=1, keepdims=True),
                          np.finfo(float).tiny)
    for calibration_number, source_index in enumerate(calibration_indices):
        weights[source_index] = 0.0
        weights[source_index, calibration_number] = 1.0
    return weights


def _nearest_positive_definite(matrix, floor):
    matrix = 0.5 * (np.asarray(matrix, dtype=float) + np.asarray(matrix, dtype=float).T)
    values, vectors = np.linalg.eigh(matrix)
    values = np.maximum(values, float(floor))
    return (vectors * values) @ vectors.T


def _nearest_positive_definite_batch(matrices, floor):
    """Vectorized equivalent of ``_nearest_positive_definite`` for Q matrices."""
    matrices = np.asarray(matrices, dtype=float)
    symmetric = 0.5 * (matrices + np.swapaxes(matrices, -1, -2))
    values, vectors = np.linalg.eigh(symmetric)
    values = np.maximum(values, float(floor))
    return np.einsum(
        '...ik,...k,...jk->...ij', vectors, values, vectors, optimize=True
    )


def _profiled_precision_matrices(covariances):
    """Precompute origin-time-profiled precision matrices.

    For residual r and covariance C, the profiled score is r.T @ P @ r,
    where P removes the constant receiver-time shift.  Computing P once per
    source avoids a pseudoinverse and determinant inside every event search.
    """
    covariances = np.asarray(covariances, dtype=float)
    single_matrix = covariances.ndim == 2
    if single_matrix:
        covariances = covariances[None, :, :]
    precision = np.linalg.pinv(covariances, rcond=1.0e-10)
    ones = np.ones(covariances.shape[-1], dtype=float)
    precision_ones = np.einsum('qrs,s->qr', precision, ones, optimize=True)
    denominator = np.einsum(
        'r,qr->q', ones, precision_ones, optimize=True
    )
    denominator = np.maximum(denominator, np.finfo(float).tiny)
    profiled = precision - np.einsum(
        'qr,qs,q->qrs', precision_ones, precision_ones,
        1.0 / denominator, optimize=True,
    )
    profiled = 0.5 * (profiled + np.swapaxes(profiled, -1, -2))
    return profiled[0] if single_matrix else profiled


def _source_cell_covariance(source_positions):
    """Return the fixed unresolved within-grid-cell covariance once."""
    positions = np.asarray(source_positions, dtype=float)
    unique_steps = []
    for dimension in range(positions.shape[1]):
        values = np.unique(np.sort(positions[:, dimension]))
        differences = np.diff(values)
        differences = differences[differences > np.finfo(float).eps]
        unique_steps.append(
            float(np.min(differences)) if differences.size else 1.0
        )
    return np.diag((np.asarray(unique_steps) / np.sqrt(12.0)) ** 2)


def _build_path_correlated_discrepancy_state(
        reference_arrivals, training_arrivals, source_positions,
        receiver_indices, calibration_indices, config,
        training_event_indices=None):
    """Learn empirical bias and full path-correlated model-error covariance.

    Calibration residuals are interpolated in source space independently for
    every receiver.  What remains is a model-by-source-by-receiver residual
    cube.  Its non-diagonal receiver covariance is retained, so shared or
    overlapping propagation paths are not misrepresented as independent noise.
    """
    receiver_indices = np.asarray(receiver_indices, dtype=int)
    calibration_indices = np.asarray(calibration_indices, dtype=int)
    if receiver_indices.size < 2:
        raise ValueError('At least two receivers are required.')
    if calibration_indices.size < 1:
        raise ValueError('At least one calibration source is required.')
    positions = np.asarray(source_positions, dtype=float)
    domain_diagonal = max(
        float(np.linalg.norm(np.ptp(positions, axis=0))),
        float(np.max(np.asarray(config.get('physical_spacing', (1.0,))))),
    )
    kernel_length = (
        config['calibration_kernel_length_fraction'] * domain_diagonal
    )
    calibration_weights = _calibration_interpolation_weights(
        positions, calibration_indices, kernel_length
    )
    reference_selected = np.asarray(
        reference_arrivals[:, receiver_indices], dtype=float
    )
    training_selected = np.asarray(
        training_arrivals[:, :, receiver_indices], dtype=float
    )
    model_discrepancy = training_selected - reference_selected[None, :, :]
    interpolated = np.einsum(
        'qc,mcr->mqr', calibration_weights,
        model_discrepancy[:, calibration_indices, :], optimize=True,
    )
    corrected = model_discrepancy - interpolated
    source_count = corrected.shape[1]
    if training_event_indices is None:
        learning_indices = np.arange(source_count, dtype=int)
    else:
        learning_indices = np.unique(np.asarray(
            training_event_indices, dtype=int
        ))
    if learning_indices.size < 1:
        raise ValueError('At least one training event is required.')
    if np.any(learning_indices < 0) or np.any(learning_indices >= source_count):
        raise ValueError('Training-event indices are outside the source grid.')
    # Only the declared training-event positions estimate the spatial discrepancy
    # statistics.  Smooth convex interpolation supplies states at held-out source
    # nodes without using their validation/test residual samples.
    learning_weights = _calibration_interpolation_weights(
        positions, learning_indices, kernel_length
    )
    learning_corrected = corrected[:, learning_indices, :]
    learning_mean = np.mean(learning_corrected, axis=0)
    learning_anomalies = learning_corrected - learning_mean[None, :, :]
    empirical_mean = np.einsum(
        'qk,kr->qr', learning_weights, learning_mean, optimize=True
    )
    model_count, learning_count, receiver_count = learning_anomalies.shape
    shrinkage = float(config['model_covariance_shrinkage'])
    picking_variance = float(config['picking_noise_std_s']) ** 2
    calibration_variance = picking_variance / max(
        1, int(config['calibration_repeats'])
    )
    if model_count > 1:
        learning_covariances = np.einsum(
            'mkr,mks->krs', learning_anomalies, learning_anomalies,
            optimize=True,
        ) / float(model_count - 1)
    else:
        learning_covariances = np.zeros(
            (learning_count, receiver_count, receiver_count), dtype=float
        )
    diagonal_indices = np.arange(receiver_count)
    empirical_diagonal = np.diagonal(
        learning_covariances, axis1=1, axis2=2
    ).copy()
    learning_covariances *= 1.0 - shrinkage
    learning_covariances[:, diagonal_indices, diagonal_indices] = (
        empirical_diagonal
    )
    learning_covariances = _nearest_positive_definite_batch(
        learning_covariances, picking_variance * 1.0e-6
    )
    path_covariances = np.einsum(
        'qk,krs->qrs', learning_weights, learning_covariances, optimize=True
    )
    path_covariances = _nearest_positive_definite_batch(
        path_covariances, picking_variance * 1.0e-6
    )
    calibration_noise_factor = np.sum(
        calibration_weights ** 2, axis=1
    )
    total_covariances = path_covariances.copy()
    total_covariances[:, diagonal_indices, diagonal_indices] += (
        picking_variance
        + calibration_noise_factor[:, None] * calibration_variance
    )
    total_covariances = _nearest_positive_definite_batch(
        total_covariances, picking_variance * 1.0e-6
    )
    standard_deviations = np.sqrt(np.maximum(
        np.diagonal(path_covariances, axis1=1, axis2=2),
        np.finfo(float).tiny,
    ))
    correlations = path_covariances / (
        standard_deviations[:, :, None] * standard_deviations[:, None, :]
    )
    off_diagonal_mask = ~np.eye(receiver_count, dtype=bool)
    if np.any(off_diagonal_mask):
        correlation_summaries = np.mean(
            np.abs(correlations[:, off_diagonal_mask]), axis=1
        )
    else:
        correlation_summaries = np.zeros(source_count, dtype=float)
    return {
        'receiver_indices': receiver_indices,
        'calibration_indices': calibration_indices,
        'interpolation_weights': calibration_weights,
        'training_event_indices': learning_indices,
        'training_event_interpolation_weights': learning_weights,
        'empirical_residual_mean_s': empirical_mean,
        'path_covariances_s2': path_covariances,
        'total_covariances_s2': total_covariances,
        'mean_absolute_off_diagonal_correlation': float(
            np.mean(correlation_summaries)
        ),
        'kernel_length_m': float(kernel_length),
    }


def _profile_origin_time_score(residual, covariance):
    covariance = np.asarray(covariance, dtype=float)
    residual = np.asarray(residual, dtype=float)
    precision = np.linalg.pinv(covariance, rcond=1.0e-10)
    ones = np.ones(residual.size, dtype=float)
    denominator = max(float(ones @ precision @ ones), np.finfo(float).tiny)
    origin_time = float(ones @ precision @ residual) / denominator
    centred = residual - origin_time
    score = float(centred @ precision @ centred)
    sign, logdet = np.linalg.slogdet(covariance)
    if sign <= 0:
        logdet = float(np.log(np.maximum(
            np.linalg.det(_nearest_positive_definite(covariance, 1.0e-16)),
            np.finfo(float).tiny,
        )))
    return score, origin_time, float(logdet)


def _posterior_location_result(log_weights, source_positions, point_mode='mean',
                               cell_covariance=None):
    log_weights = np.asarray(log_weights, dtype=float)
    finite = np.isfinite(log_weights)
    if not np.any(finite):
        weights = np.full(log_weights.size, 1.0 / log_weights.size)
    else:
        shifted = log_weights - float(np.max(log_weights[finite]))
        weights = np.exp(np.where(finite, shifted, -np.inf))
        weights /= max(float(np.sum(weights)), np.finfo(float).tiny)
    positions = np.asarray(source_positions, dtype=float)
    posterior_mean = np.sum(weights[:, None] * positions, axis=0)
    map_index = int(np.argmax(weights))
    estimate = positions[map_index].copy() if point_mode == 'map' else posterior_mean
    centred = positions - posterior_mean
    covariance = np.einsum(
        'q,qi,qj->ij', weights, centred, centred, optimize=True
    )
    # A finite grid represents each node as a cell, not an exact point.  The
    # term is invariant across events and is cached in every method context.
    if cell_covariance is None:
        cell_covariance = _source_cell_covariance(positions)
    covariance += np.asarray(cell_covariance, dtype=float)
    covariance = _nearest_positive_definite(covariance, 1.0e-8)
    return {
        'estimate_m': estimate,
        'posterior_mean_m': posterior_mean,
        'covariance_m2': covariance,
        'map_source_index': map_index,
        'posterior_weights': weights,
    }


def _iid_reference_log_weights(observed_times, predictions, sigma, point_mode):
    residual = np.asarray(observed_times, dtype=float)[None, :] - np.asarray(
        predictions, dtype=float
    )
    residual -= np.mean(residual, axis=1, keepdims=True)
    scores = np.einsum('qr,qr->q', residual, residual, optimize=True) / max(
        float(sigma) ** 2, np.finfo(float).tiny
    )
    return -0.5 * scores, point_mode


def _prepare_fast_locator_state(context):
    """Attach immutable arrays reused by every localization call."""
    source_positions = np.asarray(context['source_positions'], dtype=float)
    context['cell_covariance_m2'] = _source_cell_covariance(source_positions)
    method_key = context['key']
    if method_key == 'velocity_marginalized':
        training = np.asarray(context.pop('training_selected'), dtype=float)
        training -= np.mean(
            training, axis=2, keepdims=True, dtype=float
        )
        context['training_centered_s'] = np.ascontiguousarray(training)
        context['training_centered_norm2_s2'] = np.einsum(
            'mqr,mqr->mq', training, training, optimize=True
        )
    elif method_key == 'double_difference':
        nearest = np.asarray(context['nearest_calibration_number'], dtype=int)
        calibration_indices = np.asarray(
            context['calibration_indices'], dtype=int
        )
        reference = np.asarray(context['reference_selected'], dtype=float)
        context['double_difference_reference_s'] = (
            reference - reference[calibration_indices[nearest]]
        )
    elif method_key in {'proposed', 'proposed_diagonal'}:
        state = context['discrepancy_state']
        context['profiled_precision_matrices'] = _profiled_precision_matrices(
            state['total_covariances_s2']
        )
        context['fast_state_covariance_identity'] = id(
            state['total_covariances_s2']
        )
    return context


def _prepare_method_context(method_key, method_label, receiver_indices,
                            calibration_indices, reference_arrivals,
                            training_arrivals, source_positions, config,
                            training_event_indices=None):
    receiver_indices = np.asarray(receiver_indices, dtype=int)
    calibration_indices = np.asarray(calibration_indices, dtype=int)
    context = {
        'key': method_key,
        'label': method_label,
        'receiver_indices': receiver_indices,
        'calibration_indices': calibration_indices,
        'reference_selected': np.asarray(
            reference_arrivals[:, receiver_indices], dtype=float
        ),
        'source_positions': np.asarray(source_positions, dtype=float),
        'sigma': float(config['picking_noise_std_s']),
    }
    if method_key == 'velocity_marginalized':
        # Preserve float32 storage here; conversion to float64 happens only in
        # the batched score kernel instead of duplicating the large bank for all
        # six method contexts.
        context['training_selected'] = np.asarray(
            training_arrivals[:, :, receiver_indices]
        )
    if method_key == 'proposed':
        context['discrepancy_state'] = _build_path_correlated_discrepancy_state(
            reference_arrivals, training_arrivals, source_positions,
            receiver_indices, calibration_indices, config,
            training_event_indices=training_event_indices,
        )
    if method_key == 'double_difference':
        calibration_positions = np.asarray(source_positions)[calibration_indices]
        distances = np.linalg.norm(
            np.asarray(source_positions)[:, None, :]
            - calibration_positions[None, :, :], axis=2,
        )
        context['nearest_calibration_number'] = np.argmin(distances, axis=1)
    return _prepare_fast_locator_state(context)


def _velocity_marginalized_log_weights_batch(context, observations,
                                               event_batch_size=4):
    """Evaluate exact marginalized likelihoods with bounded GEMM batches.

    Expanding ``observation - training`` created an M x Q x R float64 array for
    every event.  The identity ||y-x||² = ||x||² + ||y||² - 2 x.y computes the
    same scores from one matrix product and a small M x Q norm table.
    """
    observations = np.atleast_2d(np.asarray(observations, dtype=float))
    training = context['training_centered_s']
    model_count, source_count, receiver_count = training.shape
    if observations.shape[1] != receiver_count:
        raise ValueError('Marginalized observations have the wrong receiver count.')
    flat_training = training.reshape(model_count * source_count, receiver_count)
    flat_norms = context['training_centered_norm2_s2'].reshape(-1)
    output = np.empty((len(observations), source_count), dtype=float)
    batch_size = max(1, int(event_batch_size))
    inverse_variance_scale = -0.5 / max(
        float(context['sigma']) ** 2, np.finfo(float).tiny
    )
    for begin in range(0, len(observations), batch_size):
        end = min(len(observations), begin + batch_size)
        centred = observations[begin:end].copy()
        centred -= np.mean(centred, axis=1, keepdims=True)
        observation_norms = np.einsum(
            'er,er->e', centred, centred, optimize=True
        )
        scores = flat_training @ centred.T
        scores *= -2.0
        scores += flat_norms[:, None]
        scores += observation_norms[None, :]
        np.maximum(scores, 0.0, out=scores)
        scores *= inverse_variance_scale
        log_likelihood = scores.reshape(
            model_count, source_count, end - begin
        )
        output[begin:end] = (
            logsumexp(log_likelihood, axis=0).T - np.log(model_count)
        )
    return output


def _locate_velocity_marginalized_batch(context, observations,
                                         event_batch_size=4):
    log_weights = _velocity_marginalized_log_weights_batch(
        context, observations, event_batch_size=event_batch_size
    )
    results = []
    for weights in log_weights:
        result = _posterior_location_result(
            weights, context['source_positions'], point_mode='mean',
            cell_covariance=context.get('cell_covariance_m2'),
        )
        result['log_evidence_proxy'] = float(logsumexp(weights))
        results.append(result)
    return results


def _locate_with_method_context(context, observed_times,
                                calibration_observations):
    method_key = context['key']
    observed_times = np.asarray(observed_times, dtype=float)
    source_positions = context['source_positions']
    reference = context['reference_selected']
    sigma = context['sigma']
    if method_key == 'reference_ls_iid':
        log_weights, point_mode = _iid_reference_log_weights(
            observed_times, reference, sigma, 'map'
        )
    elif method_key in {'reference_probabilistic', 'd_opt_reference'}:
        log_weights, point_mode = _iid_reference_log_weights(
            observed_times, reference, sigma, 'mean'
        )
    elif method_key == 'velocity_marginalized':
        log_weights = _velocity_marginalized_log_weights_batch(
            context, observed_times[None, :], event_batch_size=1
        )[0]
        point_mode = 'mean'
    elif method_key == 'double_difference':
        nearest = context['nearest_calibration_number']
        observed_difference = (
            observed_times[None, :]
            - np.asarray(calibration_observations, dtype=float)[nearest]
        )
        residual = (
            observed_difference - context['double_difference_reference_s']
        )
        residual -= np.mean(residual, axis=1, keepdims=True)
        scores = np.einsum(
            'qr,qr->q', residual, residual, optimize=True
        ) / max(2.0 * sigma ** 2, np.finfo(float).tiny)
        log_weights = -0.5 * scores
        point_mode = 'mean'
    elif method_key in {'proposed', 'proposed_diagonal'}:
        state = context['discrepancy_state']
        calibration_residuals = (
            np.asarray(calibration_observations, dtype=float)
            - reference[state['calibration_indices']]
        )
        empirical_bias = (
            state['interpolation_weights'] @ calibration_residuals
            + state['empirical_residual_mean_s']
        )
        predictions = reference + empirical_bias
        if context.get('fast_state_covariance_identity') != id(
                state['total_covariances_s2']):
            # Supports copied/modified contexts such as the diagonal-covariance
            # evidence ablation while keeping ordinary calls lock-free.
            _prepare_fast_locator_state(context)
        residual = observed_times[None, :] - predictions
        scores = np.einsum(
            'qr,qrs,qs->q', residual,
            context['profiled_precision_matrices'], residual, optimize=True,
        )
        log_weights = -0.5 * scores
        point_mode = 'mean'
    else:
        raise ValueError(f'Unknown robust comparison method: {method_key}')
    result = _posterior_location_result(
        log_weights, source_positions, point_mode=point_mode,
        cell_covariance=context.get('cell_covariance_m2'),
    )
    result['log_evidence_proxy'] = float(logsumexp(log_weights))
    return result


def _truth_indices_for_experiment(source_nodes, true_sources, physics,
                                  maximum_count):
    positions = _robust_physical_positions(source_nodes, physics)
    selected = []
    for source in true_sources:
        source_position = np.asarray(source, dtype=float) * np.asarray(
            physics.spacing, dtype=float
        )
        selected.append(int(np.argmin(np.linalg.norm(
            positions - source_position[None, :], axis=1
        ))))
    remaining_count = max(0, int(maximum_count) - len(set(selected)))
    if remaining_count:
        supplemental = _maximin_subset_indices(
            positions, min(len(positions), remaining_count + len(set(selected))),
            mandatory=tuple(dict.fromkeys(selected)),
        )
        selected.extend(int(value) for value in supplemental)
    return np.asarray(list(dict.fromkeys(selected))[:int(maximum_count)], dtype=int)


def _simulate_method_split(context, split, reference_arrivals, truth_indices,
                           config, random_seed, parallel_workers=None):
    """Run paired model/event blocks with deterministic thread parallelism.

    A child seed is assigned to each velocity model, making the common full-array
    noise exactly reproducible for every method and independent of thread count.
    Calls made inside the parallel design search explicitly request one worker to
    prevent nested thread pools.
    """
    receiver_indices = context['receiver_indices']
    calibration_indices = context['calibration_indices']
    source_positions = context['source_positions']
    sigma = float(config['picking_noise_std_s'])
    calibration_sigma = sigma / np.sqrt(max(1, int(config['calibration_repeats'])))
    model_count = int(split.arrivals_s.shape[0])
    child_sequences = np.random.SeedSequence(int(random_seed)).spawn(model_count)
    model_seeds = [
        int(sequence.generate_state(1, dtype=np.uint64)[0])
        for sequence in child_sequences
    ]

    def simulate_model(model_index):
        rng = np.random.default_rng(model_seeds[int(model_index)])
        model_rows = []
        model_arrivals = np.asarray(split.arrivals_s[model_index], dtype=float)
        # These full-candidate draws are identical for every compared layout;
        # each method merely selects its own columns.
        calibration_noise_full = rng.normal(
            0.0, calibration_sigma,
            size=(len(calibration_indices), model_arrivals.shape[1]),
        )
        calibration_observations = (
            model_arrivals[calibration_indices][:, receiver_indices]
            + calibration_noise_full[:, receiver_indices]
        )
        event_payloads = []
        for event_number, truth_index in enumerate(truth_indices):
            event_noise_full = rng.normal(
                0.0, sigma, size=model_arrivals.shape[1]
            )
            observed = (
                model_arrivals[int(truth_index), receiver_indices]
                + event_noise_full[receiver_indices]
            )
            event_payloads.append((
                int(event_number), int(truth_index), observed
            ))
        if context['key'] == 'velocity_marginalized':
            event_results = _locate_velocity_marginalized_batch(
                context,
                np.asarray([payload[2] for payload in event_payloads]),
                event_batch_size=config.get(
                    'marginal_likelihood_event_batch', 4
                ),
            )
        else:
            event_results = [
                _locate_with_method_context(
                    context, payload[2], calibration_observations
                )
                for payload in event_payloads
            ]
        for (event_number, truth_index, _), result in zip(
                event_payloads, event_results):
            truth = source_positions[int(truth_index)]
            error_vector = np.asarray(result['estimate_m']) - truth
            covariance = _nearest_positive_definite(
                result['covariance_m2'], 1.0e-8
            )
            precision = np.linalg.pinv(covariance, rcond=1.0e-10)
            mahalanobis_squared = float(error_vector @ precision @ error_vector)
            sign, logdet = np.linalg.slogdet(covariance)
            if sign <= 0:
                logdet = float(np.log(np.finfo(float).tiny))
            negative_log_score = 0.5 * (
                source_positions.shape[1] * np.log(2.0 * np.pi)
                + logdet + mahalanobis_squared
            )
            horizontal_error = (
                float(abs(error_vector[0]))
                if physics_dimension_from_positions(source_positions) == 2
                else float(np.linalg.norm(error_vector[:-1]))
            )
            model_rows.append({
                'method_key': context['key'],
                'method': context['label'],
                'split': split.name,
                'velocity_model_index': int(model_index),
                'event_number': int(event_number),
                'truth_source_index': int(truth_index),
                'truth_m': truth.tolist(),
                'estimate_m': np.asarray(result['estimate_m']).tolist(),
                'error_vector_m': error_vector.tolist(),
                'error_3d_m': float(np.linalg.norm(error_vector)),
                'horizontal_error_m': horizontal_error,
                'depth_error_m': float(abs(error_vector[-1])),
                'mahalanobis_squared': mahalanobis_squared,
                'covariance_m2': covariance.tolist(),
                'negative_log_score': float(negative_log_score),
                'receiver_count': int(len(receiver_indices)),
                'calibration_source_count': int(len(calibration_indices)),
                'scenario_id': f'{split.name}_m{model_index:04d}_e{event_number:03d}',
            })
        return model_rows

    requested_workers = (
        int(config.get('simulation_parallel_workers', 1))
        if parallel_workers is None else int(parallel_workers)
    )
    worker_count = min(max(1, requested_workers), max(1, model_count))
    if worker_count == 1 or model_count < 2:
        grouped_rows = map(simulate_model, range(model_count))
        execution_mode = 'serial model/event evaluation'
    else:
        executor = ThreadPoolExecutor(
            max_workers=worker_count,
            thread_name_prefix='robust-event-evaluation',
        )
        grouped_rows = executor.map(simulate_model, range(model_count))
        execution_mode = f'{worker_count}-thread model/event evaluation'
    rows = []
    try:
        for model_rows in grouped_rows:
            for row in model_rows:
                row['evaluation_execution_mode'] = execution_mode
            rows.extend(model_rows)
    finally:
        if worker_count > 1 and model_count >= 2:
            executor.shutdown(wait=True)
    return rows


def physics_dimension_from_positions(source_positions):
    return int(np.asarray(source_positions).shape[1])


def _finite_sample_interval_thresholds(rows, confidence_levels, dimensions):
    values = np.sort(np.asarray(
        [row['mahalanobis_squared'] for row in rows], dtype=float
    ))
    if values.size == 0:
        raise ValueError('Interval calibration requires non-empty rows.')
    thresholds = {}
    for confidence in confidence_levels:
        # Split-conformal finite-sample order statistic ceil((n+1) alpha).
        order = min(values.size, max(1, int(np.ceil(
            (values.size + 1) * float(confidence)
        ))))
        threshold = float(values[order - 1])
        thresholds[str(confidence)] = max(threshold, 1.0e-8)
    return {
        'dimensions': int(dimensions),
        'sample_count': int(values.size),
        'formal_chi_squared': {
            str(level): float(chi2.ppf(level, dimensions))
            for level in confidence_levels
        },
        'empirical_calibrated': thresholds,
    }


def _ellipsoid_volume(covariance, threshold):
    covariance = _nearest_positive_definite(covariance, 1.0e-8)
    dimensions = covariance.shape[0]
    determinant = max(float(np.linalg.det(covariance)), np.finfo(float).tiny)
    unit_ball = math.pi ** (dimensions / 2.0) / math.gamma(dimensions / 2.0 + 1.0)
    return float(
        unit_ball * float(threshold) ** (dimensions / 2.0)
        * np.sqrt(determinant)
    )


def _upper_tail_mean(values, alpha):
    values = np.sort(np.asarray(values, dtype=float))
    if values.size == 0:
        return np.nan
    start = min(values.size - 1, int(np.floor(float(alpha) * values.size)))
    return float(np.mean(values[start:]))


def _aggregate_method_rows(rows, interval_calibration, config,
                           prior_volume, acquisition_cost):
    errors = np.asarray([row['error_3d_m'] for row in rows], dtype=float)
    horizontal = np.asarray([row['horizontal_error_m'] for row in rows], dtype=float)
    depth = np.asarray([row['depth_error_m'] for row in rows], dtype=float)
    mahalanobis = np.asarray(
        [row['mahalanobis_squared'] for row in rows], dtype=float
    )
    formal_coverages = {}
    calibrated_coverages = {}
    calibrated_volumes = {}
    formal_volumes = {}
    for confidence in config['confidence_levels']:
        key = str(confidence)
        formal_threshold = interval_calibration['formal_chi_squared'][key]
        calibrated_threshold = interval_calibration['empirical_calibrated'][key]
        formal_coverages[key] = float(np.mean(mahalanobis <= formal_threshold))
        calibrated_coverages[key] = float(
            np.mean(mahalanobis <= calibrated_threshold)
        )
        formal_volumes[key] = float(np.mean([
            _ellipsoid_volume(np.asarray(row['covariance_m2']), formal_threshold)
            for row in rows
        ]))
        calibrated_volumes[key] = float(np.mean([
            _ellipsoid_volume(
                np.asarray(row['covariance_m2']), calibrated_threshold
            ) for row in rows
        ]))
    volume_95 = calibrated_volumes[str(0.95)]
    information_gain = float(np.log(max(
        float(prior_volume) / max(volume_95, np.finfo(float).tiny),
        np.finfo(float).tiny,
    )))
    return {
        'method_key': rows[0]['method_key'],
        'method': rows[0]['method'],
        'sample_count': int(len(rows)),
        'mean_error_m': float(np.mean(errors)),
        'rmse_m': float(np.sqrt(np.mean(errors ** 2))),
        'median_error_m': float(np.median(errors)),
        'p95_error_m': float(np.quantile(errors, 0.95)),
        'cvar_error_m': _upper_tail_mean(errors, config['cvar_alpha']),
        'mean_horizontal_error_m': float(np.mean(horizontal)),
        'mean_depth_error_m': float(np.mean(depth)),
        'mean_negative_log_score': float(np.mean([
            row['negative_log_score'] for row in rows
        ])),
        'formal_coverage_68': formal_coverages[str(0.68)],
        'formal_coverage_90': formal_coverages[str(0.90)],
        'formal_coverage_95': formal_coverages[str(0.95)],
        'calibrated_coverage_68': calibrated_coverages[str(0.68)],
        'calibrated_coverage_90': calibrated_coverages[str(0.90)],
        'calibrated_coverage_95': calibrated_coverages[str(0.95)],
        'formal_interval_volume_95': formal_volumes[str(0.95)],
        'calibrated_interval_volume_95': volume_95,
        'information_gain_per_cost': information_gain / max(
            float(acquisition_cost), np.finfo(float).tiny
        ),
        'receiver_count': int(rows[0]['receiver_count']),
        'calibration_source_count': int(rows[0]['calibration_source_count']),
    }


def _proposed_design_objective(receiver_indices, calibration_indices,
                               reference_arrivals, training_split,
                               interval_split, validation_split,
                               source_positions, training_event_indices,
                               interval_event_indices,
                               validation_event_indices, config,
                               cache=None):
    key = (
        tuple(sorted(map(int, receiver_indices))),
        tuple(sorted(map(int, calibration_indices))),
    )
    if cache is not None and key in cache:
        return cache[key]
    context = _prepare_method_context(
        'proposed', 'Proposed correlated calibrated robust design',
        key[0], key[1], reference_arrivals,
        training_split.arrivals_s, source_positions, config,
        training_event_indices=training_event_indices,
    )
    calibration_rows = _simulate_method_split(
        context, interval_split, reference_arrivals, interval_event_indices,
        config, config['seed'] + 71001, parallel_workers=1,
    )
    interval_thresholds = _finite_sample_interval_thresholds(
        calibration_rows, config['confidence_levels'], source_positions.shape[1]
    )
    validation_rows = _simulate_method_split(
        context, validation_split, reference_arrivals, validation_event_indices,
        config, config['seed'] + 72001, parallel_workers=1,
    )
    domain_diagonal = max(
        float(np.linalg.norm(np.ptp(source_positions, axis=0))), 1.0
    )
    errors = np.asarray(
        [row['error_3d_m'] for row in validation_rows], dtype=float
    )
    coverage_penalty = 0.0
    volume_terms = []
    cell_volume = float(np.prod(np.asarray(config['physical_spacing'], dtype=float)))
    for confidence in config['confidence_levels']:
        threshold = interval_thresholds['empirical_calibrated'][str(confidence)]
        coverage = float(np.mean([
            row['mahalanobis_squared'] <= threshold for row in validation_rows
        ]))
        coverage_penalty += abs(coverage - float(confidence))
        if np.isclose(confidence, 0.95):
            volume_terms = [
                _ellipsoid_volume(np.asarray(row['covariance_m2']), threshold)
                for row in validation_rows
            ]
    coverage_penalty /= len(config['confidence_levels'])
    mean_term = float(np.mean(errors)) / domain_diagonal
    tail_term = _upper_tail_mean(errors, config['cvar_alpha']) / domain_diagonal
    sharpness_term = float(np.mean(np.log1p(
        np.asarray(volume_terms) / max(cell_volume, np.finfo(float).tiny)
    ))) / 10.0
    score = (
        config['objective_mean_weight'] * mean_term
        + config['objective_tail_weight'] * tail_term
        + config['objective_coverage_weight'] * coverage_penalty
        + config['objective_sharpness_weight'] * sharpness_term
    )
    result = {
        'score': float(score),
        'mean_error_m': float(np.mean(errors)),
        'cvar_error_m': _upper_tail_mean(errors, config['cvar_alpha']),
        'coverage_penalty': float(coverage_penalty),
        'mean_log_sharpness': float(sharpness_term),
        'interval_thresholds': interval_thresholds,
        'path_off_diagonal_correlation': context['discrepancy_state'][
            'mean_absolute_off_diagonal_correlation'
        ],
    }
    if cache is not None:
        cache[key] = result
    return result


def _local_arrival_jacobians(reference_arrivals, source_positions):
    """Estimate source-coordinate travel-time Jacobians by local regression."""
    arrivals = np.asarray(reference_arrivals, dtype=float)
    positions = np.asarray(source_positions, dtype=float)
    source_count, receiver_count = arrivals.shape
    dimensions = positions.shape[1]
    neighbour_count = min(source_count, max(dimensions + 2, 2 * dimensions + 1))
    jacobians = np.empty((source_count, receiver_count, dimensions), dtype=float)
    for source_index in range(source_count):
        distances = np.linalg.norm(
            positions - positions[source_index][None, :], axis=1
        )
        neighbours = np.argsort(distances)[:neighbour_count]
        offsets = positions[neighbours] - positions[source_index][None, :]
        design = np.column_stack([np.ones(len(neighbours)), offsets])
        coefficients = np.linalg.pinv(design, rcond=1.0e-10) @ arrivals[neighbours]
        jacobians[source_index] = coefficients[1:].T
    return jacobians


def _reference_d_optimal_layout(reference_arrivals, source_positions,
                                receiver_count, picking_sigma):
    """Greedy D-optimal baseline using only the reference velocity model."""
    jacobians = _local_arrival_jacobians(
        reference_arrivals, source_positions
    )
    candidate_count = reference_arrivals.shape[1]
    dimensions = source_positions.shape[1]

    def score(indices):
        indices = np.asarray(indices, dtype=int)
        if indices.size == 0:
            return -np.inf
        total = 0.0
        for source_jacobian in jacobians:
            gradients = source_jacobian[indices]
            projector = np.eye(len(indices)) - np.ones(
                (len(indices), len(indices)), dtype=float
            ) / max(1, len(indices))
            information = (
                gradients.T @ projector @ gradients
                / max(float(picking_sigma) ** 2, np.finfo(float).tiny)
            )
            information += np.eye(dimensions) * 1.0e-10
            sign, logdet = np.linalg.slogdet(information)
            total += float(logdet if sign > 0 else -1.0e6)
        return total / len(jacobians)

    selected = []
    while len(selected) < int(receiver_count):
        best_index = None
        best_score = -np.inf
        for candidate_index in range(candidate_count):
            if candidate_index in selected:
                continue
            candidate_score = score(selected + [candidate_index])
            if candidate_score > best_score:
                best_index = candidate_index
                best_score = candidate_score
        selected.append(int(best_index))
    return np.asarray(selected, dtype=int), float(score(selected))


def _joint_receiver_calibration_design(
        reference_arrivals, training_split, interval_split, validation_split,
        source_positions, candidate_positions, training_event_indices,
        interval_event_indices, validation_event_indices,
        calibration_candidate_indices, config):
    """Thread-parallel coordinate exchange in both design spaces.

    Trial layouts within one exchange step are independent and share read-only
    arrival arrays.  A bounded thread pool avoids copying the large training bank;
    event-level threading inside every trial is disabled by the objective.
    """
    receiver_count = min(config['receiver_count'], reference_arrivals.shape[1])
    calibration_candidate_indices = np.unique(np.asarray(
        calibration_candidate_indices, dtype=int
    ))
    if calibration_candidate_indices.size < 1:
        raise ValueError('The calibration-source candidate set is empty.')
    calibration_count = min(
        config['calibration_source_count'], len(calibration_candidate_indices)
    )
    d_opt_receivers, _ = _reference_d_optimal_layout(
        reference_arrivals, source_positions, receiver_count,
        config['picking_noise_std_s'],
    )
    maximin_local = _maximin_subset_indices(
        np.asarray(source_positions)[calibration_candidate_indices],
        calibration_count,
    )
    maximin_calibration = calibration_candidate_indices[maximin_local]
    rng = np.random.default_rng(config['seed'] + 73001)
    starts = [(d_opt_receivers, maximin_calibration, 'D-opt/maximin start')]
    for restart in range(config['joint_random_restarts']):
        receivers = np.sort(rng.choice(
            reference_arrivals.shape[1], receiver_count, replace=False
        ))
        calibrations = np.sort(rng.choice(
            calibration_candidate_indices, calibration_count, replace=False
        ))
        starts.append((receivers, calibrations, f'random restart {restart + 1}'))
    cache = {}
    history = []
    best_global = None
    proposal_limit = max(1, int(config['joint_exchange_proposals']))
    design_worker_count = max(1, int(config.get('design_parallel_workers', 1)))
    design_executor = (
        ThreadPoolExecutor(
            max_workers=design_worker_count,
            thread_name_prefix='robust-design-objective',
        )
        if design_worker_count > 1 else None
    )

    def evaluate_pair(pair):
        trial_receivers, trial_calibrations = pair
        return _proposed_design_objective(
            trial_receivers, trial_calibrations, reference_arrivals,
            training_split, interval_split, validation_split,
            source_positions, training_event_indices,
            interval_event_indices, validation_event_indices,
            config, cache,
        )

    def evaluate_pairs(pairs):
        if not pairs:
            return []
        pair_keys = [(
            tuple(sorted(map(int, pair[0]))),
            tuple(sorted(map(int, pair[1]))),
        ) for pair in pairs]
        unique_missing = {}
        resolved = {}
        for pair, key in zip(pairs, pair_keys):
            if key in cache:
                resolved[key] = cache[key]
            elif key not in unique_missing:
                unique_missing[key] = pair
        missing_pairs = list(unique_missing.values())
        missing_keys = list(unique_missing)
        if design_executor is None:
            missing_results = [evaluate_pair(pair) for pair in missing_pairs]
        else:
            missing_results = list(design_executor.map(
                evaluate_pair, missing_pairs
            ))
        resolved.update(zip(missing_keys, missing_results))
        return [resolved[key] for key in pair_keys]

    for start_receivers, start_calibrations, start_label in starts:
        receivers = np.asarray(start_receivers, dtype=int).copy()
        calibrations = np.asarray(start_calibrations, dtype=int).copy()
        current = evaluate_pair((receivers, calibrations))
        history.append({
            'restart': start_label, 'iteration': 0, 'move': 'initial',
            'score': current['score'],
            'receiver_indices': receivers.tolist(),
            'calibration_indices': calibrations.tolist(),
        })
        for iteration in range(1, config['joint_exchange_iterations'] + 1):
            improved = False
            unselected_receivers = np.setdiff1d(
                np.arange(reference_arrivals.shape[1]), receivers
            )
            if len(unselected_receivers) > proposal_limit:
                trial_pool = rng.choice(
                    unselected_receivers, proposal_limit, replace=False
                )
            else:
                trial_pool = unselected_receivers
            receiver_trial_arrays = []
            replace_positions = np.arange(len(receivers))
            if len(replace_positions) > min(len(replace_positions), proposal_limit):
                replace_positions = rng.choice(
                    replace_positions, proposal_limit, replace=False
                )
            for replace_position in replace_positions:
                for new_receiver in trial_pool:
                    trial = receivers.copy()
                    trial[int(replace_position)] = int(new_receiver)
                    trial = np.unique(trial)
                    if len(trial) != receiver_count:
                        continue
                    receiver_trial_arrays.append(trial)
            receiver_evaluations = evaluate_pairs([
                (trial, calibrations) for trial in receiver_trial_arrays
            ])
            receiver_trials = [
                (evaluation['score'], trial, evaluation)
                for trial, evaluation in zip(
                    receiver_trial_arrays, receiver_evaluations
                )
            ]
            if receiver_trials:
                trial_score, trial_receivers, trial_evaluation = min(
                    receiver_trials, key=lambda item: item[0]
                )
                if trial_score < current['score'] - 1.0e-12:
                    receivers = np.asarray(trial_receivers, dtype=int)
                    current = trial_evaluation
                    improved = True
                    history.append({
                        'restart': start_label, 'iteration': iteration,
                        'move': 'receiver exchange', 'score': current['score'],
                        'receiver_indices': receivers.tolist(),
                        'calibration_indices': calibrations.tolist(),
                    })
            unselected_calibrations = np.setdiff1d(
                calibration_candidate_indices, calibrations
            )
            if len(unselected_calibrations) > proposal_limit:
                calibration_pool = rng.choice(
                    unselected_calibrations, proposal_limit, replace=False
                )
            else:
                calibration_pool = unselected_calibrations
            calibration_trial_arrays = []
            calibration_positions = np.arange(len(calibrations))
            for replace_position in calibration_positions:
                for new_calibration in calibration_pool:
                    trial = calibrations.copy()
                    trial[int(replace_position)] = int(new_calibration)
                    trial = np.unique(trial)
                    if len(trial) != calibration_count:
                        continue
                    calibration_trial_arrays.append(trial)
            calibration_evaluations = evaluate_pairs([
                (receivers, trial) for trial in calibration_trial_arrays
            ])
            calibration_trials = [
                (evaluation['score'], trial, evaluation)
                for trial, evaluation in zip(
                    calibration_trial_arrays, calibration_evaluations
                )
            ]
            if calibration_trials:
                trial_score, trial_calibrations, trial_evaluation = min(
                    calibration_trials, key=lambda item: item[0]
                )
                if trial_score < current['score'] - 1.0e-12:
                    calibrations = np.asarray(trial_calibrations, dtype=int)
                    current = trial_evaluation
                    improved = True
                    history.append({
                        'restart': start_label, 'iteration': iteration,
                        'move': 'calibration-source exchange',
                        'score': current['score'],
                        'receiver_indices': receivers.tolist(),
                        'calibration_indices': calibrations.tolist(),
                    })
            if not improved:
                history.append({
                    'restart': start_label, 'iteration': iteration,
                    'move': 'converged', 'score': current['score'],
                    'receiver_indices': receivers.tolist(),
                    'calibration_indices': calibrations.tolist(),
                })
                break
        candidate = {
            'receiver_indices': np.asarray(receivers, dtype=int),
            'calibration_indices': np.asarray(calibrations, dtype=int),
            'evaluation': current,
        }
        if best_global is None or current['score'] < best_global['evaluation']['score']:
            best_global = candidate
    if design_executor is not None:
        design_executor.shutdown(wait=True)
    best_global['history'] = history
    best_global['evaluated_design_count'] = int(len(cache))
    best_global['parallel_execution'] = {
        'mode': (
            f'{design_worker_count}-thread coordinate-exchange trials'
            if design_worker_count > 1 else 'serial coordinate-exchange trials'
        ),
        'workers': int(design_worker_count),
        'nested_event_workers_per_trial': 1,
    }
    return best_global


def _paired_block_bootstrap(event_rows, proposed_key, draws, seed):
    proposed = {
        row['scenario_id']: row for row in event_rows
        if row['method_key'] == proposed_key
    }
    method_keys = sorted({row['method_key'] for row in event_rows})
    rng = np.random.default_rng(int(seed))
    output = []
    for method_key in method_keys:
        if method_key == proposed_key:
            continue
        baseline = {
            row['scenario_id']: row for row in event_rows
            if row['method_key'] == method_key
        }
        common_ids = sorted(set(proposed) & set(baseline))
        if not common_ids:
            continue
        block_to_ids = {}
        for scenario_id in common_ids:
            block = scenario_id.rsplit('_e', 1)[0]
            block_to_ids.setdefault(block, []).append(scenario_id)
        blocks = sorted(block_to_ids)
        differences = np.asarray([
            np.mean([
                proposed[scenario_id]['error_3d_m']
                - baseline[scenario_id]['error_3d_m']
                for scenario_id in block_to_ids[block]
            ]) for block in blocks
        ], dtype=float)
        bootstrap = np.empty(int(draws), dtype=float)
        for draw in range(int(draws)):
            sampled = rng.choice(len(blocks), len(blocks), replace=True)
            bootstrap[draw] = float(np.mean(differences[sampled]))
        output.append({
            'baseline_method_key': method_key,
            'baseline_method': baseline[common_ids[0]]['method'],
            'paired_block_count': int(len(blocks)),
            'mean_error_difference_proposed_minus_baseline_m': float(
                np.mean(differences)
            ),
            'ci95_lower_m': float(np.quantile(bootstrap, 0.025)),
            'ci95_upper_m': float(np.quantile(bootstrap, 0.975)),
            'probability_proposed_has_lower_mean_error': float(
                np.mean(bootstrap < 0.0)
            ),
        })
    return output


def _station_failure_audit(method_specifications, reference_arrivals,
                           training_split, test_split, source_positions,
                           training_event_indices, test_event_indices, config):
    rows = []
    for specification in method_specifications:
        receiver_indices = np.asarray(
            specification['receiver_indices'], dtype=int
        )
        if receiver_indices.size <= source_positions.shape[1] + 1:
            continue
        failure_positions = _maximin_subset_indices(
            np.arange(receiver_indices.size, dtype=float)[:, None],
            min(config['station_failure_cases'], receiver_indices.size),
        )
        failure_metrics = []
        for failure_position in failure_positions:
            reduced = np.delete(receiver_indices, int(failure_position))
            context = _prepare_method_context(
                specification['key'], specification['label'], reduced,
                specification['calibration_indices'], reference_arrivals,
                training_split.arrivals_s, source_positions, config,
                training_event_indices=training_event_indices,
            )
            failed_rows = _simulate_method_split(
                context, test_split, reference_arrivals, test_event_indices,
                config, config['seed'] + 78001,
            )
            errors = np.asarray(
                [row['error_3d_m'] for row in failed_rows], dtype=float
            )
            failure_metrics.append({
                'failed_global_receiver_index': int(
                    receiver_indices[int(failure_position)]
                ),
                'mean_error_m': float(np.mean(errors)),
                'p95_error_m': float(np.quantile(errors, 0.95)),
            })
        rows.append({
            'method_key': specification['key'],
            'method': specification['label'],
            'audited_failure_count': int(len(failure_metrics)),
            'worst_station_failure_mean_error_m': float(max(
                item['mean_error_m'] for item in failure_metrics
            )),
            'worst_station_failure_p95_error_m': float(max(
                item['p95_error_m'] for item in failure_metrics
            )),
            'failure_details': failure_metrics,
        })
    return rows


def _csv_safe_rows(rows):
    safe = []
    for row in rows:
        converted = {}
        for key, value in row.items():
            if isinstance(value, (list, tuple, dict, np.ndarray)):
                converted[key] = json.dumps(
                    np.asarray(value).tolist() if isinstance(value, np.ndarray)
                    else value,
                    ensure_ascii=False,
                )
            elif isinstance(value, (np.integer, np.floating)):
                converted[key] = value.item()
            else:
                converted[key] = value
        safe.append(converted)
    return safe


def _plot_path_correlated_covariance(state, output_dir):
    source_index = int(len(state['path_covariances_s2']) // 2)
    covariance = state['path_covariances_s2'][source_index]
    standard_deviations = np.sqrt(np.maximum(
        np.diag(covariance), np.finfo(float).tiny
    ))
    correlation = covariance / (
        standard_deviations[:, None] * standard_deviations[None, :]
    )
    fig, axes = plt.subplots(1, 2, figsize=(10.5, 4.4), constrained_layout=True)
    image = axes[0].imshow(covariance * 1.0e6, cmap='magma', aspect='equal')
    fig.colorbar(image, ax=axes[0], label=r'Covariance ($10^{-6}$ s$^2$)')
    axes[0].set_title('Path-induced travel-time covariance')
    corr_image = axes[1].imshow(
        correlation, cmap='coolwarm', vmin=-1.0, vmax=1.0, aspect='equal'
    )
    fig.colorbar(corr_image, ax=axes[1], label='Correlation')
    axes[1].set_title('Non-diagonal path correlation')
    for axis in axes:
        axis.set_xlabel('Receiver number')
        axis.set_ylabel('Receiver number')
    fig.suptitle(
        'BETTER ERROR MODEL: full path covariance retains measured '
        'cross-receiver dependence; IID discards it', fontsize=13
    )
    fig.savefig(os.path.join(
        output_dir, 'path_correlated_traveltime_covariance.png'
    ), dpi=300)
    plt.close(fig)
    return source_index, covariance, correlation


def _plot_joint_design(physics, candidates, source_nodes, proposed_receivers,
                       calibration_indices, d_opt_receivers,
                       uniform_receivers, output_dir):
    candidate_positions = _robust_physical_positions(candidates, physics)
    source_positions = _robust_physical_positions(source_nodes, physics)
    fig = plt.figure(figsize=(12.0, 4.2), constrained_layout=True)
    layouts = [
        ('Reference D-optimal', d_opt_receivers, '#457B9D'),
        ('Uniform maximin', uniform_receivers, '#2A9D8F'),
        ('Joint robust design', proposed_receivers, '#E63946'),
    ]
    for panel, (title, receivers, colour) in enumerate(layouts, start=1):
        if physics.dims == 3:
            axis = fig.add_subplot(1, 3, panel, projection='3d')
            axis.scatter(*candidate_positions.T, s=12, c='0.75', alpha=0.6)
            axis.scatter(
                *candidate_positions[np.asarray(receivers, dtype=int)].T,
                s=55, c=colour, marker='v', edgecolor='k', label='Receivers'
            )
            axis.scatter(
                *source_positions[np.asarray(calibration_indices, dtype=int)].T,
                s=90, c='#FFCA3A', marker='*', edgecolor='k',
                label='Calibration sources'
            )
            axis.set_zlabel('Depth (m)')
            axis.invert_zaxis()
        else:
            axis = fig.add_subplot(1, 3, panel)
            axis.scatter(
                candidate_positions[:, 0], candidate_positions[:, -1],
                s=12, c='0.75', alpha=0.6
            )
            axis.scatter(
                candidate_positions[np.asarray(receivers), 0],
                candidate_positions[np.asarray(receivers), -1],
                s=55, c=colour, marker='v', edgecolor='k', label='Receivers'
            )
            axis.scatter(
                source_positions[np.asarray(calibration_indices), 0],
                source_positions[np.asarray(calibration_indices), -1],
                s=90, c='#FFCA3A', marker='*', edgecolor='k',
                label='Calibration sources'
            )
            axis.set_ylabel('Depth (m)')
            axis.invert_yaxis()
        axis.set_title(title)
        axis.set_xlabel('X (m)')
        axis.grid(True, ls=':', alpha=0.45)
        if panel == 3:
            axis.legend(loc='best', fontsize=8)
    fig.suptitle(
        'BETTER FOR THE JOINT ROBUST OBJECTIVE: selected joint receiver + '
        'calibration-source design', fontsize=13
    )
    fig.savefig(os.path.join(
        output_dir, 'joint_receiver_calibration_source_design.png'
    ), dpi=300)
    plt.close(fig)


def _plot_method_comparison(summary_rows, config, output_dir):
    labels = [row['method'] for row in summary_rows]
    short = [
        'LS-IID', 'Reference\nposterior', 'Velocity\nBMA',
        'Double\ndifference', 'Reference\nD-opt', 'Proposed',
    ][:len(labels)]
    colours = ['#8D99AE', '#577590', '#43AA8B', '#F9C74F', '#F9844A', '#7B2CBF']
    fig, axes = plt.subplots(2, 2, figsize=(12.0, 8.0), constrained_layout=True)
    x = np.arange(len(summary_rows))
    axes[0, 0].bar(x, [row['mean_error_m'] for row in summary_rows], color=colours)
    axes[0, 0].plot(
        x, [row['cvar_error_m'] for row in summary_rows], 'ko--',
        label=f"CVaR$_{{{config['cvar_alpha']:.2f}}}$"
    )
    axes[0, 0].set_ylabel('Location error (m)')
    axes[0, 0].set_title('Mean and tail localization error')
    axes[0, 0].legend()
    width = 0.22
    for offset, level in zip((-width, 0.0, width), (0.68, 0.90, 0.95)):
        axes[0, 1].bar(
            x + offset,
            [row[f'calibrated_coverage_{int(level * 100)}'] for row in summary_rows],
            width=width, label=f'{int(level * 100)}% interval'
        )
        axes[0, 1].axhline(level, color='k', lw=0.7, ls=':')
    axes[0, 1].set_ylim(0.0, 1.05)
    axes[0, 1].set_ylabel('Empirical coverage')
    axes[0, 1].set_title('Held-out calibrated coverage')
    axes[0, 1].legend(fontsize=8)
    axes[1, 0].bar(
        x, [row['calibrated_interval_volume_95'] for row in summary_rows],
        color=colours
    )
    axes[1, 0].set_yscale('log')
    axes[1, 0].set_ylabel('95% ellipse/ellipsoid volume')
    axes[1, 0].set_title('Sharpness after empirical calibration')
    axes[1, 1].bar(
        x, [row['mean_negative_log_score'] for row in summary_rows],
        color=colours
    )
    axes[1, 1].set_ylabel('Mean negative log score')
    axes[1, 1].set_title('Probabilistic accuracy')
    for axis in axes.ravel():
        axis.set_xticks(x)
        axis.set_xticklabels(short, rotation=18, ha='right')
        axis.grid(True, axis='y', ls=':', alpha=0.4)
    mean_winner = min(summary_rows, key=lambda row: row['mean_error_m'])
    fig.suptitle(
        f"BETTER HELD-OUT MEAN LOCATION ERROR: {mean_winner['method']} = "
        f"{mean_winner['mean_error_m']:.3f} m", fontsize=14
    )
    fig.savefig(os.path.join(
        output_dir, 'strict_twin_method_comparison.png'
    ), dpi=300)
    plt.close(fig)


def _plot_coverage_calibration(summary_rows, output_dir):
    levels = np.asarray([0.68, 0.90, 0.95])
    fig, axis = plt.subplots(figsize=(6.4, 5.4), constrained_layout=True)
    axis.plot([0.6, 1.0], [0.6, 1.0], 'k--', lw=1.2, label='Perfect calibration')
    for row in summary_rows:
        coverage = [
            row[f'calibrated_coverage_{int(level * 100)}'] for level in levels
        ]
        axis.plot(levels, coverage, marker='o', lw=1.5, label=row['method'])
    axis.set_xlim(0.65, 0.98)
    axis.set_ylim(0.55, 1.02)
    axis.set_xlabel('Nominal probability')
    axis.set_ylabel('Held-out empirical coverage')
    winner = min(
        summary_rows,
        key=lambda row: sum(
            abs(row[f'calibrated_coverage_{int(level * 100)}'] - level)
            for level in levels
        ),
    )
    axis.set_title(
        f"BETTER MULTI-LEVEL CALIBRATION: {winner['method']} "
        '(smallest total nominal gap)', fontsize=11
    )
    axis.grid(True, ls=':', alpha=0.5)
    axis.legend(fontsize=7, loc='best')
    fig.savefig(os.path.join(
        output_dir, 'heldout_interval_calibration.png'
    ), dpi=300)
    plt.close(fig)


def run_path_correlated_joint_design_validation(
        reference_physics, candidates, targets, true_sources,
        output_dir, analysis_config, config_overrides=None):
    """Run the complete robust reference-velocity design/validation workflow.

    Scientific separation of information is enforced as follows:

    * training velocities and training-event positions estimate empirical residual
      means and path covariance;
    * interval velocities and a disjoint event set determine finite-sample
      coverage thresholds;
    * validation velocities and newly generated target-near events select
      receivers and calibration sources jointly;
    * test velocities (with shifted RMS/correlation statistics) and a second new,
      disjoint target-near event set remain untouched until final comparison.

    All inverse solutions use reference-model travel times, except for the
    explicitly named velocity-marginalization comparator.  The proposed method
    adds only calibration-shot residual interpolation and the covariance learned
    around the reference model; it never sees the held-out true velocity field.
    """
    workflow_start = time.perf_counter()
    robust_output_dir = os.path.join(
        output_dir, 'path_correlated_joint_design_validation'
    )
    os.makedirs(robust_output_dir, exist_ok=True)
    config = robust_closed_loop_config(
        analysis_config, reference_physics, len(candidates)
    )
    if config_overrides:
        overrides = dict(config_overrides)
        config.update(overrides)
        # Backward compatibility for the fixed advantage case and user scripts.
        if 'events_per_model' in overrides:
            for key in (
                    'training_events_per_model', 'interval_events_per_model',
                    'validation_events_per_model', 'test_events_per_model'):
                if key not in overrides:
                    config[key] = int(overrides['events_per_model'])
    event_count_keys = (
        'training_events_per_model', 'interval_events_per_model',
        'validation_events_per_model', 'test_events_per_model',
    )
    if any(int(config[key]) <= 0 for key in event_count_keys):
        raise ValueError('All effective split-specific event counts must be positive.')
    if float(config['event_target_jitter_fraction']) <= 0.0:
        raise ValueError('The effective target-event jitter fraction must be positive.')
    candidate_pool = _bounded_candidate_pool(
        candidates, reference_physics, config['maximum_candidate_sites']
    )
    config['receiver_count'] = min(
        config['receiver_count'], len(candidate_pool)
    )
    event_node_splits, event_generation_diagnostics = (
        _build_disjoint_target_event_splits(
            targets, true_sources, reference_physics, config
        )
    )
    mandatory_event_nodes = [
        node for split_nodes in event_node_splits.values()
        for node in split_nodes
    ]
    required_source_nodes = len(set(
        [tuple(map(int, point)) for point in true_sources]
        + mandatory_event_nodes
    ))
    config['requested_maximum_source_nodes'] = int(
        config['maximum_source_nodes']
    )
    config['maximum_source_nodes'] = max(
        int(config['maximum_source_nodes']), required_source_nodes
    )
    source_nodes = _build_robust_source_nodes(
        targets, true_sources, reference_physics,
        config['maximum_source_nodes'],
        mandatory_sources=mandatory_event_nodes,
    )
    config['calibration_source_count'] = min(
        config['calibration_source_count'], len(source_nodes)
    )
    config['physical_spacing'] = [
        float(value) for value in reference_physics.spacing
    ]
    source_positions = _robust_physical_positions(
        source_nodes, reference_physics
    )
    candidate_positions = _robust_physical_positions(
        candidate_pool, reference_physics
    )
    source_number = {node: index for index, node in enumerate(source_nodes)}
    event_indices_by_split = {
        name: np.asarray([source_number[node] for node in nodes], dtype=int)
        for name, nodes in event_node_splits.items()
    }
    calibration_candidate_indices = np.unique(np.concatenate([
        event_indices_by_split['training'],
        event_indices_by_split['interval_calibration'],
    ])).astype(int)
    heldout_indices = set(event_indices_by_split['design_validation']) | set(
        event_indices_by_split['untouched_test']
    )
    if heldout_indices & set(calibration_candidate_indices):
        raise RuntimeError(
            'Held-out validation/test events entered the calibration candidate set.'
        )
    event_inventory = {
        'event_nodes_by_split': {
            name: [list(node) for node in nodes]
            for name, nodes in event_node_splits.items()
        },
        'source_node_indices_by_split': {
            name: indices.tolist()
            for name, indices in event_indices_by_split.items()
        },
        'events_per_velocity_realization': {
            name: int(len(indices))
            for name, indices in event_indices_by_split.items()
        },
        'calibration_candidate_source_node_indices': (
            calibration_candidate_indices.tolist()
        ),
        'validation_and_test_excluded_from_calibration_candidates': True,
        **event_generation_diagnostics,
    }
    _atomic_write_json(
        os.path.join(robust_output_dir, 'disjoint_event_split_inventory.json'),
        event_inventory,
    )
    _atomic_write_json(
        os.path.join(robust_output_dir, 'robust_run_configuration.json'),
        config,
    )
    hotspot_timings = {}
    print(
        '\n>>> Path-correlated robust design: '
        f'{len(candidate_pool)} candidate receivers, '
        f'{len(source_nodes)} source-search nodes, '
        f"{config['receiver_count']} deployed receivers and "
        f"{config['calibration_source_count']} calibration sources."
    )
    print(
        f"    Compute profile: {config['compute_profile']}; "
        'set ROBUST_COMPUTE_PROFILE=production to reproduce the former '
        '2000/1000/500/48 model defaults exactly.'
    )
    print(
        '    Events per velocity realization: '
        f"training={len(event_indices_by_split['training'])}, "
        f"interval={len(event_indices_by_split['interval_calibration'])}, "
        f"validation={len(event_indices_by_split['design_validation'])}, "
        f"test={len(event_indices_by_split['untouched_test'])}; "
        'all four position sets are disjoint.'
    )
    print(
        '    Parallel configuration: '
        f"velocity={config['parallel_workers']} processes "
        f"({config['multiprocessing_start_method']}), "
        f"reference FMM={config['reference_arrival_workers']} threads, "
        f"design={config['design_parallel_workers']} threads, "
        f"event evaluation={config['simulation_parallel_workers']} threads."
    )

    reference_arrival_started = time.perf_counter()
    reference_arrivals = _robust_arrival_bank(
        reference_physics, source_nodes, candidate_pool,
        parallel_workers=config['reference_arrival_workers'],
    )
    hotspot_timings['reference_arrival_bank_seconds'] = float(
        time.perf_counter() - reference_arrival_started
    )
    _atomic_save_npy(
        os.path.join(robust_output_dir, 'reference_arrival_bank_seconds.npy'),
        np.asarray(reference_arrivals, dtype=np.float32),
    )
    base_seed = int(config['seed'])
    split_specifications = [
        ('training', config['train_models'], base_seed + 101, 1.0, 1.0),
        ('interval_calibration', config['interval_models'], base_seed + 211, 1.0, 1.0),
        ('design_validation', config['validation_models'], base_seed + 307, 1.0, 1.0),
        (
            'untouched_test', config['test_models'], base_seed + 401,
            config['test_rms_multiplier'],
            config['test_correlation_multiplier'],
        ),
    ]
    splits = {}
    shared_velocity_executor = None
    previous_worker_flag = os.environ.get('ROBUST_FMM_PROCESS_WORKER')
    use_shared_velocity_pool = bool(
        int(config['parallel_workers']) > 1
        and max(specification[1] for specification in split_specifications)
        >= int(config['parallel_minimum_models'])
    )
    if use_shared_velocity_pool:
        perturbation_config = {
            key: config[key] for key in (
                'velocity_target_radius_fraction',
                'velocity_background_fraction',
                'velocity_clip_fraction',
            )
        }
        os.environ['ROBUST_FMM_PROCESS_WORKER'] = '1'
        shared_velocity_executor = ProcessPoolExecutor(
            max_workers=int(config['parallel_workers']),
            mp_context=multiprocessing.get_context(
                config['multiprocessing_start_method']
            ),
            initializer=_initialize_robust_velocity_worker,
            initargs=(
                np.asarray(reference_physics.V, dtype=np.float32),
                reference_physics.shape, reference_physics.spacing,
                reference_physics.is_3d, source_nodes, candidate_pool,
                targets, perturbation_config,
            ),
        )
    try:
        for (name, count, seed, rms_multiplier,
             correlation_multiplier) in split_specifications:
            print(
                f'    Generating independent {name} velocity split '
                f'({count} models)...'
            )
            splits[name] = _stream_independent_velocity_arrivals(
                reference_physics, source_nodes, candidate_pool, targets, count,
                seed, config, name, rms_multiplier=rms_multiplier,
                correlation_multiplier=correlation_multiplier,
                process_executor=shared_velocity_executor,
                checkpoint_dir=os.path.join(
                    robust_output_dir, 'velocity_arrival_checkpoints'
                ),
            )
            hotspot_timings[f'{name}_velocity_forward_seconds'] = float(
                splits[name].inventory[0]['split_wall_seconds']
            )
    finally:
        if shared_velocity_executor is not None:
            shared_velocity_executor.shutdown(wait=True)
        if previous_worker_flag is None:
            os.environ.pop('ROBUST_FMM_PROCESS_WORKER', None)
        else:
            os.environ['ROBUST_FMM_PROCESS_WORKER'] = previous_worker_flag
    inventory = {
        name: split.inventory for name, split in splits.items()
    }
    _atomic_write_json(
        os.path.join(robust_output_dir, 'velocity_split_inventory.json'),
        inventory,
    )
    _atomic_save_npy(
        os.path.join(robust_output_dir, 'untouched_test_arrival_bank_seconds.npy'),
        splits['untouched_test'].arrivals_s,
    )
    _atomic_save_npy(
        os.path.join(robust_output_dir, 'last_test_velocity_residual_fraction.npy'),
        splits['untouched_test'].last_fractional_velocity_residual,
    )

    d_opt_receivers, d_opt_score = _reference_d_optimal_layout(
        reference_arrivals, source_positions, config['receiver_count'],
        config['picking_noise_std_s'],
    )
    uniform_receivers = _maximin_subset_indices(
        candidate_positions, config['receiver_count']
    )
    random_rng = np.random.default_rng(base_seed + 503)
    random_receivers = np.sort(random_rng.choice(
        len(candidate_pool), config['receiver_count'], replace=False
    ))
    baseline_calibration_local = _maximin_subset_indices(
        source_positions[calibration_candidate_indices],
        config['calibration_source_count'],
    )
    baseline_calibrations = calibration_candidate_indices[
        baseline_calibration_local
    ]

    joint_design_started = time.perf_counter()
    joint_design = _joint_receiver_calibration_design(
        reference_arrivals,
        splits['training'],
        splits['interval_calibration'],
        splits['design_validation'],
        source_positions,
        candidate_positions,
        event_indices_by_split['training'],
        event_indices_by_split['interval_calibration'],
        event_indices_by_split['design_validation'],
        calibration_candidate_indices,
        config,
    )
    hotspot_timings['joint_design_seconds'] = float(
        time.perf_counter() - joint_design_started
    )
    proposed_receivers = joint_design['receiver_indices']
    proposed_calibrations = joint_design['calibration_indices']
    _write_csv(
        os.path.join(robust_output_dir, 'joint_design_optimization_history.csv'),
        _csv_safe_rows(joint_design['history']),
    )

    method_specifications = [
        {
            'key': 'reference_ls_iid',
            'label': 'Reference LS, IID errors',
            'receiver_indices': uniform_receivers,
            'calibration_indices': baseline_calibrations,
        },
        {
            'key': 'reference_probabilistic',
            'label': 'Reference nonlinear grid posterior',
            'receiver_indices': uniform_receivers,
            'calibration_indices': baseline_calibrations,
        },
        {
            'key': 'velocity_marginalized',
            'label': 'Velocity-ensemble marginalized posterior',
            'receiver_indices': uniform_receivers,
            'calibration_indices': baseline_calibrations,
        },
        {
            'key': 'double_difference',
            'label': 'Master-event double difference',
            'receiver_indices': uniform_receivers,
            'calibration_indices': baseline_calibrations,
        },
        {
            'key': 'd_opt_reference',
            'label': 'Reference Fisher D-optimal design',
            'receiver_indices': d_opt_receivers,
            'calibration_indices': baseline_calibrations,
        },
        {
            'key': 'proposed',
            'label': 'Proposed correlated calibrated robust design',
            'receiver_indices': proposed_receivers,
            'calibration_indices': proposed_calibrations,
        },
    ]

    all_test_rows = []
    summary_rows = []
    interval_calibrations = {}
    contexts = {}
    prior_extent = np.maximum(
        np.ptp(source_positions, axis=0),
        np.asarray(reference_physics.spacing, dtype=float),
    )
    prior_volume = float(np.prod(prior_extent))
    method_evaluation_started = time.perf_counter()
    for specification in method_specifications:
        print(f"    Evaluating: {specification['label']}")
        context = _prepare_method_context(
            specification['key'], specification['label'],
            specification['receiver_indices'],
            specification['calibration_indices'],
            reference_arrivals, splits['training'].arrivals_s,
            source_positions, config,
            training_event_indices=event_indices_by_split['training'],
        )
        contexts[specification['key']] = context
        calibration_rows = _simulate_method_split(
            context, splits['interval_calibration'], reference_arrivals,
            event_indices_by_split['interval_calibration'],
            config, base_seed + 811,
        )
        thresholds = _finite_sample_interval_thresholds(
            calibration_rows, config['confidence_levels'], reference_physics.dims
        )
        interval_calibrations[specification['key']] = thresholds
        test_rows = _simulate_method_split(
            context, splits['untouched_test'], reference_arrivals,
            event_indices_by_split['untouched_test'],
            config, base_seed + 907,
        )
        all_test_rows.extend(test_rows)
        calibration_cost = (
            len(specification['calibration_indices'])
            if specification['key'] in {'double_difference', 'proposed'}
            else 0
        )
        summary_rows.append(_aggregate_method_rows(
            test_rows, thresholds, config, prior_volume,
            len(specification['receiver_indices']) + calibration_cost,
        ))
    hotspot_timings['six_method_evaluation_seconds'] = float(
        time.perf_counter() - method_evaluation_started
    )

    station_failure_started = time.perf_counter()
    station_failure_rows = _station_failure_audit(
        method_specifications, reference_arrivals, splits['training'],
        splits['untouched_test'], source_positions,
        event_indices_by_split['training'],
        event_indices_by_split['untouched_test'], config,
    )
    hotspot_timings['station_failure_audit_seconds'] = float(
        time.perf_counter() - station_failure_started
    )
    failure_by_method = {
        row['method_key']: row for row in station_failure_rows
    }
    for row in summary_rows:
        failure = failure_by_method.get(row['method_key'])
        row['worst_station_failure_mean_error_m'] = (
            failure['worst_station_failure_mean_error_m'] if failure else np.nan
        )
        row['worst_station_failure_p95_error_m'] = (
            failure['worst_station_failure_p95_error_m'] if failure else np.nan
        )

    bootstrap_rows = _paired_block_bootstrap(
        all_test_rows, 'proposed', config['bootstrap_draws'], base_seed + 1009
    )
    proposed_state = contexts['proposed']['discrepancy_state']
    representative_source, path_covariance, path_correlation = (
        _plot_path_correlated_covariance(proposed_state, robust_output_dir)
    )
    _atomic_save_npy(
        os.path.join(robust_output_dir, 'representative_path_covariance_s2.npy'),
        path_covariance,
    )
    _atomic_save_npy(
        os.path.join(robust_output_dir, 'representative_path_correlation.npy'),
        path_correlation,
    )
    _plot_joint_design(
        reference_physics, candidate_pool, source_nodes,
        proposed_receivers, proposed_calibrations,
        d_opt_receivers, uniform_receivers, robust_output_dir,
    )
    _plot_method_comparison(summary_rows, config, robust_output_dir)
    _plot_coverage_calibration(summary_rows, robust_output_dir)

    _write_csv(
        os.path.join(robust_output_dir, 'strict_twin_method_comparison.csv'),
        _csv_safe_rows(summary_rows),
    )
    _write_csv(
        os.path.join(robust_output_dir, 'strict_twin_event_level_results.csv'),
        _csv_safe_rows(all_test_rows),
    )
    _write_csv(
        os.path.join(robust_output_dir, 'paired_block_bootstrap.csv'),
        _csv_safe_rows(bootstrap_rows),
    )
    _write_csv(
        os.path.join(robust_output_dir, 'station_failure_audit.csv'),
        _csv_safe_rows(station_failure_rows),
    )
    _atomic_write_json(
        os.path.join(robust_output_dir, 'interval_calibration_thresholds.json'),
        interval_calibrations,
    )
    designs = {
        'selected_number_of_receivers': int(len(proposed_receivers)),
        'selected_number_of_calibration_sources': int(len(proposed_calibrations)),
        'candidate_receiver_indices': [list(point) for point in candidate_pool],
        'source_search_indices': [list(point) for point in source_nodes],
        # Backward-compatible key now refers to the untouched final-test events.
        'truth_source_node_indices': event_indices_by_split[
            'untouched_test'
        ].tolist(),
        'event_source_node_indices_by_split': {
            name: indices.tolist()
            for name, indices in event_indices_by_split.items()
        },
        'calibration_candidate_source_node_indices': (
            calibration_candidate_indices.tolist()
        ),
        'uniform_receiver_candidate_numbers': uniform_receivers.tolist(),
        'random_receiver_candidate_numbers': random_receivers.tolist(),
        'reference_d_opt_receiver_candidate_numbers': d_opt_receivers.tolist(),
        'proposed_receiver_candidate_numbers': proposed_receivers.tolist(),
        'baseline_calibration_source_numbers': baseline_calibrations.tolist(),
        'proposed_calibration_source_numbers': proposed_calibrations.tolist(),
        'reference_d_opt_logdet_score': float(d_opt_score),
        'joint_design_objective': joint_design['evaluation'],
        'joint_design_evaluated_count': joint_design['evaluated_design_count'],
        'joint_design_parallel_execution': joint_design['parallel_execution'],
    }
    final_observation_system_figure = (
        _write_active_final_observation_system(
            reference_physics, designs, output_dir
        )
    )
    designs['final_observation_system_figure'] = (
        final_observation_system_figure
    )
    _atomic_write_json(
        os.path.join(robust_output_dir, 'selected_observation_systems.json'),
        designs,
    )
    elapsed = float(time.perf_counter() - workflow_start)
    parallel_profile = {
        'hotspot_analysis': {
            'dominant': (
                'independent velocity realization generation plus receiver FMM '
                'arrival-bank construction'
            ),
            'secondary': (
                'joint receiver/calibration coordinate-exchange objective trials'
            ),
            'tertiary': (
                'method-specific interval/test model-event localization blocks'
            ),
        },
        'configured_cpu_count': int(os.cpu_count() or 1),
        'velocity_process_workers': int(config['parallel_workers']),
        'velocity_process_minimum_models': int(
            config['parallel_minimum_models']
        ),
        'multiprocessing_start_method': config[
            'multiprocessing_start_method'
        ],
        'reference_arrival_thread_workers': int(
            config['reference_arrival_workers']
        ),
        'design_objective_thread_workers': int(
            config['design_parallel_workers']
        ),
        'event_simulation_thread_workers': int(
            config['simulation_parallel_workers']
        ),
        'nested_parallelism_disabled': True,
        'deterministic_child_seed_per_velocity_model': True,
        'timings_seconds': hotspot_timings,
        'total_workflow_seconds': elapsed,
    }
    _atomic_write_json(
        os.path.join(robust_output_dir, 'parallel_execution_profile.json'),
        parallel_profile,
    )
    records = {
        'method_summary': summary_rows,
        'paired_block_bootstrap': bootstrap_rows,
        'station_failure_audit': station_failure_rows,
        'selected_designs': designs,
        'final_observation_system_figure': final_observation_system_figure,
        'interval_calibration': interval_calibrations,
        'path_error_diagnostics': {
            'representative_source_node_number': int(representative_source),
            'mean_absolute_off_diagonal_correlation': proposed_state[
                'mean_absolute_off_diagonal_correlation'
            ],
            'calibration_kernel_length_m': proposed_state['kernel_length_m'],
            'training_event_count_per_velocity_model': int(
                len(event_indices_by_split['training'])
            ),
            'heldout_validation_event_count_per_velocity_model': int(
                len(event_indices_by_split['design_validation'])
            ),
            'heldout_test_event_count_per_velocity_model': int(
                len(event_indices_by_split['untouched_test'])
            ),
        },
        'velocity_split_counts': {
            name: len(split.inventory) for name, split in splits.items()
        },
        'event_counts_per_velocity_realization': {
            name: int(len(indices))
            for name, indices in event_indices_by_split.items()
        },
        'event_split_diagnostics': event_generation_diagnostics,
        'validation_and_test_events_are_new_target_near_positions': True,
        'event_position_splits_are_disjoint': True,
        'untouched_test_is_out_of_distribution': True,
        'test_rms_multiplier': config['test_rms_multiplier'],
        'test_correlation_multiplier': config['test_correlation_multiplier'],
        'wall_seconds': elapsed,
        'parallel_execution_profile': parallel_profile,
    }
    _atomic_write_json(
        os.path.join(robust_output_dir, 'robust_validation_summary.json'),
        records,
    )
    print(
        f">>> Robust closed-loop validation complete in {elapsed:.1f} s. "
        f"Results: {robust_output_dir}"
    )
    returned_records = dict(records)
    returned_records['event_level_results'] = all_test_rows
    returned_records['output_directory'] = robust_output_dir
    returned_records['effective_configuration'] = dict(config)
    # Kept in memory (not serialized) so that the localization/migration
    # evidence case can use the exact same leakage-free velocity splits,
    # receiver layouts, calibration shots and path-error state.  This avoids
    # regenerating or silently changing any observation used by the paired
    # comparison.
    returned_records['_migration_context'] = {
        'reference_arrivals': np.asarray(reference_arrivals, dtype=float),
        'training_arrivals': np.asarray(
            splits['training'].arrivals_s, dtype=float
        ),
        'interval_arrivals': np.asarray(
            splits['interval_calibration'].arrivals_s, dtype=float
        ),
        'test_arrivals': np.asarray(
            splits['untouched_test'].arrivals_s, dtype=float
        ),
        'source_nodes': [tuple(map(int, node)) for node in source_nodes],
        'source_positions': np.asarray(source_positions, dtype=float),
        'candidate_pool': [tuple(map(int, node)) for node in candidate_pool],
        'candidate_positions': np.asarray(candidate_positions, dtype=float),
        # Backward-compatible alias used by migration is the final-test set.
        'truth_indices': np.asarray(
            event_indices_by_split['untouched_test'], dtype=int
        ),
        'training_truth_indices': np.asarray(
            event_indices_by_split['training'], dtype=int
        ),
        'interval_truth_indices': np.asarray(
            event_indices_by_split['interval_calibration'], dtype=int
        ),
        'validation_truth_indices': np.asarray(
            event_indices_by_split['design_validation'], dtype=int
        ),
        'test_truth_indices': np.asarray(
            event_indices_by_split['untouched_test'], dtype=int
        ),
        'proposed_context': contexts['proposed'],
        'method_contexts': contexts,
    }
    return returned_records


