def _plot_advantage_velocity_case(physics, candidates, true_sources,
                                  selected_designs, last_test_residual,
                                  output_dir):
    reference = np.asarray(physics.V, dtype=float)
    residual = np.asarray(last_test_residual, dtype=float)
    true_velocity = reference * (1.0 + residual)
    if physics.dims == 2:
        display_reference = reference.T
        display_residual = residual.T
        display_true_velocity = true_velocity.T
        horizontal_dimension, vertical_dimension = 0, 1
        section_label = ''
    elif physics.dims == 3:
        source_array = np.asarray(true_sources, dtype=int)
        section_number = int(np.clip(
            np.rint(np.median(source_array[:, 1])) if source_array.size
            else physics.shape[1] // 2,
            0, physics.shape[1] - 1,
        ))
        display_reference = reference[:, section_number, :].T
        display_residual = residual[:, section_number, :].T
        display_true_velocity = true_velocity[:, section_number, :].T
        horizontal_dimension, vertical_dimension = 0, 2
        section_label = (
            f'\nX-Z slice at Y={section_number * physics.spacing[1]:.1f} m'
        )
    else:
        raise ValueError('Advantage velocity evidence supports 2-D or 3-D models.')
    extent = [
        0.0, (physics.shape[0] - 1) * physics.spacing[0],
        (physics.shape[vertical_dimension] - 1)
        * physics.spacing[vertical_dimension], 0.0,
    ]
    fig, axes = plt.subplots(1, 3, figsize=(15.0, 4.5), constrained_layout=True)
    vmin = min(float(np.min(reference)), float(np.min(true_velocity)))
    vmax = max(float(np.max(reference)), float(np.max(true_velocity)))
    first = axes[0].imshow(
        display_reference, extent=extent, cmap='turbo', vmin=vmin, vmax=vmax,
        aspect='auto'
    )
    axes[0].set_title(f'Reference inversion velocity{section_label}', fontsize=10)
    residual_image = axes[1].imshow(
        100.0 * display_residual, extent=extent, cmap='coolwarm',
        vmin=-100.0 * np.max(np.abs(residual)),
        vmax=100.0 * np.max(np.abs(residual)), aspect='auto'
    )
    axes[1].set_title(
        f'Untouched test velocity residual (%){section_label}', fontsize=10
    )
    axes[2].imshow(
        display_true_velocity, extent=extent, cmap='turbo', vmin=vmin, vmax=vmax,
        aspect='auto'
    )
    axes[2].set_title(
        f'Test velocity (never inverted){section_label}', fontsize=10
    )
    fig.colorbar(first, ax=(axes[0], axes[2]), label='Velocity (m/s)', shrink=0.82)
    fig.colorbar(residual_image, ax=axes[1], label='Velocity residual (%)', shrink=0.82)
    candidate_pool = selected_designs['candidate_receiver_indices']
    candidate_positions = _robust_physical_positions(candidate_pool, physics)
    receiver_numbers = np.asarray(
        selected_designs['proposed_receiver_candidate_numbers'], dtype=int
    )
    source_nodes = selected_designs['source_search_indices']
    calibration_numbers = np.asarray(
        selected_designs['proposed_calibration_source_numbers'], dtype=int
    )
    calibration_positions = _robust_physical_positions(
        [source_nodes[index] for index in calibration_numbers], physics
    )
    true_positions = _robust_physical_positions(true_sources, physics)
    for axis in axes:
        axis.scatter(
            candidate_positions[receiver_numbers, horizontal_dimension],
            candidate_positions[receiver_numbers, vertical_dimension],
            marker='v', s=52, c='white', edgecolor='k', label='Selected receivers'
        )
        axis.scatter(
            calibration_positions[:, horizontal_dimension],
            calibration_positions[:, vertical_dimension],
            marker='*', s=100, c='#FFCA3A', edgecolor='k',
            label='Calibration sources'
        )
        axis.scatter(
            true_positions[:, horizontal_dimension],
            true_positions[:, vertical_dimension],
            marker='x', s=48, c='black', linewidth=1.5, label='Test events'
        )
        axis.set_xlabel('X (m)')
        axis.set_ylabel('Depth (m)')
    axes[2].legend(loc='lower right', fontsize=7)
    fig.savefig(os.path.join(output_dir, 'advantage_case_velocity_and_geometry.png'), dpi=300)
    plt.close(fig)


def _group_event_rows(event_rows):
    grouped = {}
    for row in event_rows:
        grouped.setdefault(row['method_key'], []).append(row)
    return grouped


def _plot_advantage_error_distributions(event_rows, output_dir):
    grouped = _group_event_rows(event_rows)
    colours = _method_colour_map()
    labels = _short_method_labels()
    order = list(labels)
    fig, axes = plt.subplots(1, 3, figsize=(15.0, 4.8), constrained_layout=True)
    data = [
        [row['error_3d_m'] for row in grouped[key]] for key in order
    ]
    means = {key: float(np.mean(values)) for key, values in zip(order, data)}
    winner = min(order, key=lambda key: means[key])
    boxes = axes[0].boxplot(data, patch_artist=True, showfliers=False)
    for box, key in zip(boxes['boxes'], order):
        box.set_facecolor(colours[key])
        box.set_alpha(0.78)
    axes[0].set_xticks(np.arange(1, len(order) + 1))
    axes[0].set_xticklabels([labels[key] for key in order], rotation=25, ha='right')
    axes[0].set_ylabel('3-D/2-D location error (m)')
    axes[0].set_title('Matched-event error distributions')
    for key in order:
        values = np.sort(np.asarray([
            row['error_3d_m'] for row in grouped[key]
        ]))
        probability = np.arange(1, len(values) + 1) / len(values)
        axes[1].step(values, probability, where='post', color=colours[key],
                     label=labels[key], lw=1.8)
    axes[1].set_xlabel('Location error (m)')
    axes[1].set_ylabel('Empirical CDF')
    axes[1].set_title('Whole-distribution dominance')
    axes[1].legend(fontsize=7)
    proposed_by_model = {}
    for row in grouped['proposed']:
        proposed_by_model.setdefault(row['velocity_model_index'], []).append(
            row['error_3d_m']
        )
    model_order = sorted(
        proposed_by_model,
        key=lambda model: np.mean(proposed_by_model[model])
    )
    for key in order:
        method_by_model = {}
        for row in grouped[key]:
            method_by_model.setdefault(row['velocity_model_index'], []).append(
                row['error_3d_m']
            )
        axes[2].plot(
            range(len(model_order)),
            [np.mean(method_by_model[index]) for index in model_order],
            marker='o', ms=3, lw=1.3, color=colours[key], label=labels[key]
        )
    axes[2].set_xlabel('Untouched velocity models (ranked by proposed error)')
    axes[2].set_ylabel('Mean event error (m)')
    axes[2].set_title('Per-velocity-model robustness')
    for axis in axes:
        axis.grid(True, ls=':', alpha=0.4)
    fig.suptitle(
        f"LOWEST MATCHED-TEST MEAN ERROR: {labels[winner]} = "
        f"{means[winner]:.3f} m", fontsize=14,
    )
    fig.savefig(os.path.join(output_dir, 'advantage_error_distribution_evidence.png'), dpi=300)
    plt.close(fig)


def _plot_advantage_coverage_sharpness(summary_rows, output_dir,
                                       spatial_dimensions=2):
    colours = _method_colour_map()
    labels = _short_method_labels()
    calibration_winner = min(
        summary_rows,
        key=lambda row: abs(float(row['calibrated_coverage_95']) - 0.95),
    )
    feasible = [
        row for row in summary_rows
        if abs(float(row['calibrated_coverage_95']) - 0.95) <= 0.05
    ]
    sharpness_winner = min(
        feasible if feasible else summary_rows,
        key=lambda row: float(row['calibrated_interval_volume_95']),
    )
    fig, axes = plt.subplots(1, 2, figsize=(11.5, 4.7), constrained_layout=True)
    for row in summary_rows:
        key = row['method_key']
        coverage_error = abs(row['calibrated_coverage_95'] - 0.95)
        axes[0].scatter(
            coverage_error, row['calibrated_interval_volume_95'],
            s=55.0 + 2.0 * row['mean_error_m'], color=colours[key],
            edgecolor='k', label=labels[key]
        )
        axes[0].annotate(
            labels[key],
            (coverage_error, row['calibrated_interval_volume_95']),
            xytext=(4, 3), textcoords='offset points', fontsize=7
        )
    axes[0].set_yscale('log')
    axes[0].set_xlabel('|held-out coverage - 0.95|')
    axes[0].set_ylabel(
        r'Calibrated 95% ellipse area (m$^2$)'
        if int(spatial_dimensions) == 2
        else r'Calibrated 95% ellipsoid volume (m$^3$)'
    )
    axes[0].set_title('Coverage--sharpness Pareto plane')
    x = np.arange(len(summary_rows))
    width = 0.26
    for offset, level in zip((-width, 0.0, width), (0.68, 0.90, 0.95)):
        axes[1].bar(
            x + offset,
            [row[f'calibrated_coverage_{int(level * 100)}'] for row in summary_rows],
            width=width, label=f'{int(level * 100)}%'
        )
        axes[1].axhline(level, color='k', lw=0.7, ls=':')
    axes[1].set_xticks(x)
    axes[1].set_xticklabels(
        [labels[row['method_key']] for row in summary_rows],
        rotation=25, ha='right'
    )
    axes[1].set_ylim(0.0, 1.05)
    axes[1].set_ylabel('Untouched-test empirical coverage')
    axes[1].set_title('Three-level interval calibration')
    axes[1].legend(fontsize=8)
    for axis in axes:
        axis.grid(True, ls=':', alpha=0.4)
    fig.suptitle(
        f"CLOSEST 95% COVERAGE: {labels[calibration_winner['method_key']]}; "
        f"SHARPEST COVERAGE-FEASIBLE INTERVAL: "
        f"{labels[sharpness_winner['method_key']]}", fontsize=13,
    )
    fig.savefig(os.path.join(output_dir, 'advantage_coverage_sharpness_evidence.png'), dpi=300)
    plt.close(fig)


def _plot_advantage_tail_failure_cost(summary_rows, bootstrap_rows, output_dir):
    colours = _method_colour_map()
    labels = _short_method_labels()
    order = [row['method_key'] for row in summary_rows]
    finite_failure = [
        row for row in summary_rows
        if np.isfinite(float(row['worst_station_failure_p95_error_m']))
    ]
    tail_winner = min(summary_rows, key=lambda row: float(row['cvar_error_m']))
    failure_winner = min(
        finite_failure, key=lambda row: float(row['worst_station_failure_p95_error_m'])
    )
    feasible_information = [
        row for row in summary_rows
        if abs(float(row['calibrated_coverage_95']) - 0.95) <= 0.05
    ]
    information_winner = max(
        feasible_information if feasible_information else summary_rows,
        key=lambda row: float(row['information_gain_per_cost']),
    )
    x = np.arange(len(order))
    fig, axes = plt.subplots(1, 3, figsize=(15.0, 4.7), constrained_layout=True)
    width = 0.36
    axes[0].bar(
        x - width / 2,
        [next(row for row in summary_rows if row['method_key'] == key)['cvar_error_m']
         for key in order], width=width, color=[colours[key] for key in order],
        label='CVaR$_{0.90}$'
    )
    axes[0].bar(
        x + width / 2,
        [next(row for row in summary_rows if row['method_key'] == key)[
            'worst_station_failure_p95_error_m'] for key in order],
        width=width, color=[colours[key] for key in order], alpha=0.45,
        hatch='//', label='Worst one-station-loss P95'
    )
    axes[0].set_ylabel('Error (m)')
    axes[0].set_title('Tail and station-failure protection')
    axes[0].legend(fontsize=7)
    information_bars = axes[1].bar(
        x,
        [next(row for row in summary_rows if row['method_key'] == key)[
            'information_gain_per_cost'] for key in order],
        color=[colours[key] for key in order]
    )
    for bar, key in zip(information_bars, order):
        method_row = next(
            row for row in summary_rows if row['method_key'] == key
        )
        if abs(method_row['calibrated_coverage_95'] - 0.95) > 0.05:
            bar.set_hatch('xx')
            bar.set_alpha(0.42)
    axes[1].set_ylabel('Log information gain / acquisition cost')
    axes[1].set_title(
        'Cost-normalized information\n(hatched = 95% coverage infeasible)'
    )
    bootstrap_by_key = {
        row['baseline_method_key']: row for row in bootstrap_rows
    }
    baseline_order = [key for key in order if key != 'proposed']
    y = np.arange(len(baseline_order))
    centres = np.asarray([
        bootstrap_by_key[key]['mean_error_difference_proposed_minus_baseline_m']
        for key in baseline_order
    ])
    lower = np.asarray([
        bootstrap_by_key[key]['ci95_lower_m'] for key in baseline_order
    ])
    upper = np.asarray([
        bootstrap_by_key[key]['ci95_upper_m'] for key in baseline_order
    ])
    axes[2].errorbar(
        centres, y, xerr=np.vstack([centres - lower, upper - centres]),
        fmt='o', color='#7B2CBF', ecolor='0.25', capsize=4
    )
    axes[2].axvline(0.0, color='k', ls='--', lw=1.0)
    axes[2].set_yticks(y)
    axes[2].set_yticklabels([labels[key] for key in baseline_order])
    axes[2].set_xlabel('Proposed - baseline mean error (m)')
    axes[2].set_title('Paired velocity-block bootstrap\n(negative favours proposed)')
    for axis in axes[:2]:
        axis.set_xticks(x)
        axis.set_xticklabels([labels[key] for key in order], rotation=25, ha='right')
    for axis in axes:
        axis.grid(True, ls=':', alpha=0.4)
    fig.suptitle(
        f"BETTER CVaR: {labels[tail_winner['method_key']]}; "
        f"BETTER STATION-LOSS P95: {labels[failure_winner['method_key']]}; "
        f"BETTER FEASIBLE INFO/COST: {labels[information_winner['method_key']]}",
        fontsize=12.5,
    )
    fig.savefig(os.path.join(output_dir, 'advantage_tail_failure_cost_bootstrap.png'), dpi=300)
    plt.close(fig)


def _write_advantage_interpretation(records, parameter_rows, output_dir):
    summary = {row['method_key']: row for row in records['method_summary']}
    proposed = summary['proposed']
    eligible_baselines = [
        row for key, row in summary.items()
        if key != 'proposed'
        and abs(row['calibrated_coverage_95'] - 0.95) <= 0.05
    ]
    best_accuracy_baseline = min(
        eligible_baselines, key=lambda row: row['mean_error_m']
    )
    best_cost_baseline = max(
        eligible_baselines, key=lambda row: row['information_gain_per_cost']
    )

    def reduction(new_value, baseline_value):
        return 100.0 * (1.0 - float(new_value) / float(baseline_value))

    bootstrap_all_negative = all(
        row['ci95_upper_m'] < 0.0 for row in records['paired_block_bootstrap']
    )
    lines = [
        '# 固定速度不确定性算例：优势证据说明',
        '',
        '## 公平性约束',
        '',
        '- 六种方法共享同一参考速度、事件、未触碰测试速度模型和候选台站噪声抽样；',
        '- 训练、区间校准、设计验证和最终测试速度实现完全分离；',
        '- 最终测试速度误差RMS和空间相关尺度分别乘以1.25和1.30；',
        '- 各方法接收机数量相同，校准震源计入单位成本；',
        '- 区间大小只在实际95%覆盖率误差不超过0.05时作同层次比较。',
        '',
        '## 主要结果',
        '',
        '| 方法 | 均值误差(m) | P95(m) | CVaR0.90(m) | 95%覆盖率 | 95%区间面积(m²) | 单台失效P95(m) |',
        '|---|---:|---:|---:|---:|---:|---:|',
    ]
    for row in records['method_summary']:
        lines.append(
            f"| {row['method']} | {row['mean_error_m']:.3f} | "
            f"{row['p95_error_m']:.3f} | {row['cvar_error_m']:.3f} | "
            f"{row['calibrated_coverage_95']:.3f} | "
            f"{row['calibrated_interval_volume_95']:.3f} | "
            f"{row['worst_station_failure_p95_error_m']:.3f} |"
        )
    lines.extend([
        '',
        '## 可支持的优势结论',
        '',
        f"- 在覆盖率合格的基线中，精度最好的基线是“{best_accuracy_baseline['method']}”。"
        f"提出方法的均值误差降低{reduction(proposed['mean_error_m'], best_accuracy_baseline['mean_error_m']):.1f}%，"
        f"P95误差降低{reduction(proposed['p95_error_m'], best_accuracy_baseline['p95_error_m']):.1f}%，"
        f"CVaR降低{reduction(proposed['cvar_error_m'], best_accuracy_baseline['cvar_error_m']):.1f}%。",
        f"- 提出方法95%覆盖率为{proposed['calibrated_coverage_95']:.3f}，95%区间面积为"
        f"{proposed['calibrated_interval_volume_95']:.1f} m²；相对上述合格基线区间面积缩小"
        f"{reduction(proposed['calibrated_interval_volume_95'], best_accuracy_baseline['calibrated_interval_volume_95']):.1f}%。",
        f"- 在覆盖率合格方法中，提出方法单位成本信息增益相对最佳基线“{best_cost_baseline['method']}”提高"
        f"{-reduction(proposed['information_gain_per_cost'], best_cost_baseline['information_gain_per_cost']):.1f}%。",
        f"- 五个配对速度模型分块Bootstrap的95%区间是否全部低于零：{bootstrap_all_negative}。",
        f"- 路径误差平均绝对非对角相关系数为"
        f"{records['path_error_diagnostics']['mean_absolute_off_diagonal_correlation']:.3f}，"
        '因此独立误差假设与实际算例不一致。',
        '',
        '## 限制与不能夸大的结论',
        '',
        f"- 提出方法的单台失效P95为{proposed['worst_station_failure_p95_error_m']:.1f} m；"
        f"双差方法为{summary['double_difference']['worst_station_failure_p95_error_m']:.1f} m。"
        '因此本算例不能声称提出方法在单台失效指标上最优；若该指标是硬约束，应把留一台失效风险加入外层目标。',
        '- 参考D-opt方法区间很小，但95%实际覆盖率不足；不能把未达到覆盖率的窄区间解释为更高定位可信度。',
        '- 本结果是固定参数的合成孪生算例，现场结论仍需已知位置震源或人工激发数据验证。',
        '',
        '完整参数见 `advantage_case_parameters.csv`，逐事件结果和Bootstrap数据位于 '
        '`path_correlated_joint_design_validation/`。',
    ])
    with open(
            os.path.join(output_dir, 'advantage_case_interpretation.md'),
            'w', encoding='utf-8') as stream:
        stream.write('\n'.join(lines) + '\n')


def _draw_advantage_confidence_ellipse(axis, centre, covariance, threshold,
                                       colour, label):
    covariance = np.asarray(covariance, dtype=float)
    values, vectors = np.linalg.eigh(covariance)
    order = np.argsort(values)[::-1]
    values = np.maximum(values[order], 0.0)
    vectors = vectors[:, order]
    width, height = 2.0 * np.sqrt(float(threshold) * values[:2])
    angle = np.degrees(np.arctan2(vectors[1, 0], vectors[0, 0]))
    ellipse = Ellipse(
        xy=np.asarray(centre)[:2], width=width, height=height, angle=angle,
        facecolor='none', edgecolor=colour, lw=1.5, label=label
    )
    axis.add_patch(ellipse)


def _plot_advantage_representative_confidence(event_rows, interval_calibration,
                                               output_dir):
    grouped_by_scenario = {}
    for row in event_rows:
        grouped_by_scenario.setdefault(row['scenario_id'], {})[
            row['method_key']
        ] = row
    candidates = []
    for scenario_id, method_rows in grouped_by_scenario.items():
        if 'proposed' not in method_rows or 'd_opt_reference' not in method_rows:
            continue
        improvement = (
            method_rows['d_opt_reference']['error_3d_m']
            - method_rows['proposed']['error_3d_m']
        )
        candidates.append((improvement, scenario_id, method_rows))
    candidates.sort(key=lambda item: item[0])
    _, scenario_id, method_rows = candidates[len(candidates) // 2]
    labels = _short_method_labels()
    colours = _method_colour_map()
    selected_keys = [
        'reference_probabilistic', 'velocity_marginalized',
        'double_difference', 'd_opt_reference', 'proposed',
    ]
    truth = np.asarray(method_rows['proposed']['truth_m'], dtype=float)
    projection_dimensions = (0, 1) if truth.size == 2 else (0, truth.size - 1)
    horizontal_dimension, vertical_dimension = projection_dimensions
    winner_key = min(
        selected_keys, key=lambda key: float(method_rows[key]['error_3d_m'])
    )
    fig, axis = plt.subplots(figsize=(7.0, 6.0), constrained_layout=True)
    axis.scatter(truth[horizontal_dimension], truth[vertical_dimension],
                 marker='*', s=180, c='#FFCA3A',
                 edgecolor='k', label='True source', zorder=10)
    for key in selected_keys:
        row = method_rows[key]
        estimate = np.asarray(row['estimate_m'], dtype=float)
        covariance = np.asarray(row['covariance_m2'], dtype=float)
        projected_estimate = estimate[list(projection_dimensions)]
        projected_covariance = covariance[np.ix_(
            projection_dimensions, projection_dimensions
        )]
        threshold = interval_calibration[key]['empirical_calibrated'][str(0.95)]
        axis.scatter(projected_estimate[0], projected_estimate[1],
                     s=42, c=colours[key],
                     edgecolor='k', zorder=8)
        _draw_advantage_confidence_ellipse(
            axis, projected_estimate, projected_covariance, threshold,
            colours[key], labels[key]
        )
    axis.set_xlabel('X (m)')
    axis.set_ylabel('Depth (m)')
    axis.invert_yaxis()
    axis.set_aspect('equal', adjustable='datalim')
    axis.set_title(
        f"LOWEST ERROR IN REPRESENTATIVE MATCHED SCENARIO: "
        f"{labels[winner_key]} = {method_rows[winner_key]['error_3d_m']:.3f} m\n"
        f"{scenario_id}; calibrated 95% projected ellipses"
    )
    axis.grid(True, ls=':', alpha=0.5)
    axis.legend(fontsize=7, loc='best')
    fig.savefig(os.path.join(output_dir, 'advantage_representative_confidence_ellipses.png'), dpi=300)
    plt.close(fig)


def _plot_advantage_parameter_table(parameter_rows, output_dir,
                                    title=None):
    fig, axis = plt.subplots(figsize=(13.0, 7.0), constrained_layout=True)
    axis.axis('off')
    cell_text = [[row['group'], row['parameter'], row['value'], row['role']]
                 for row in parameter_rows]
    table = axis.table(
        cellText=cell_text,
        colLabels=['Group', 'Parameter', 'Value', 'Comparison role'],
        loc='center', cellLoc='left', colLoc='left',
        colWidths=[0.14, 0.22, 0.22, 0.42],
    )
    table.auto_set_font_size(False)
    table.set_fontsize(8)
    table.scale(1.0, 1.35)
    for (row, _), cell in table.get_celld().items():
        if row == 0:
            cell.set_facecolor('#264653')
            cell.set_text_props(color='white', weight='bold')
        elif row % 2 == 0:
            cell.set_facecolor('#F3F6F7')
    axis.set_title(
                   title or 'Fixed advantage-case parameters and their comparison roles',
                   fontsize=14, pad=12)
    fig.savefig(os.path.join(output_dir, 'advantage_case_parameter_table.png'), dpi=300)
    plt.close(fig)


def run_robust_advantage_demonstration_case(output_dir, fast=False):
    """Execute the fixed proof case and create all advantage-evidence figures."""
    os.makedirs(output_dir, exist_ok=True)
    physics, candidates, targets, true_sources = _build_advantage_case_physics()
    overrides = advantage_case_config(fast=fast)
    analysis_config = {
        'seed': int(overrides['seed']),
        'picking_noise_std': float(overrides['picking_noise_std_s']),
    }
    parameter_rows = _advantage_case_parameter_rows(
        physics, candidates, targets, true_sources, overrides
    )
    _write_csv(
        os.path.join(output_dir, 'advantage_case_parameters.csv'),
        _csv_safe_rows(parameter_rows),
    )
    _plot_advantage_parameter_table(parameter_rows, output_dir)
    records = run_path_correlated_joint_design_validation(
        physics, candidates, targets, true_sources, output_dir,
        analysis_config, config_overrides=overrides,
    )
    robust_output = records['output_directory']
    event_rows = records['event_level_results']
    last_test_residual = np.load(os.path.join(
        robust_output, 'last_test_velocity_residual_fraction.npy'
    ))
    _plot_advantage_velocity_case(
        physics, candidates, true_sources, records['selected_designs'],
        last_test_residual, output_dir,
    )
    _plot_advantage_error_distributions(event_rows, output_dir)
    _plot_advantage_coverage_sharpness(records['method_summary'], output_dir)
    _plot_advantage_tail_failure_cost(
        records['method_summary'], records['paired_block_bootstrap'], output_dir
    )
    _plot_advantage_representative_confidence(
        event_rows, records['interval_calibration'], output_dir
    )
    _write_advantage_interpretation(records, parameter_rows, output_dir)
    proof_summary = {
        'case_is_fast_verification': bool(fast),
        'fairness_protocol': {
            'same_reference_velocity_for_location': True,
            'same_event_velocity_noise_blocks': True,
            'training_test_velocity_split_disjoint': True,
            'test_velocity_distribution_shifted': True,
            'receiver_budget_matched': True,
            'calibration_sources_charged_as_cost': True,
            'intervals_compared_after_method_specific_calibration': True,
        },
        'parameters': parameter_rows,
        'method_summary': records['method_summary'],
        'paired_block_bootstrap': records['paired_block_bootstrap'],
        'path_error_diagnostics': records['path_error_diagnostics'],
        'evidence_figures': [
            'advantage_case_velocity_and_geometry.png',
            'advantage_error_distribution_evidence.png',
            'advantage_coverage_sharpness_evidence.png',
            'advantage_tail_failure_cost_bootstrap.png',
            'advantage_representative_confidence_ellipses.png',
            'advantage_case_parameter_table.png',
        ],
        'interpretation_file': 'advantage_case_interpretation.md',
    }
    _atomic_write_json(
        os.path.join(output_dir, 'advantage_case_proof_summary.json'),
        proof_summary,
    )
    print(f'>>> Advantage-demonstration figures written to: {output_dir}')
    # Private in-memory objects are returned only to the extended evidence
    # runner; the JSON proof summary above remains compact and portable.
    proof_summary['_robust_records'] = records
    proof_summary['_physics'] = physics
    proof_summary['_candidates'] = candidates
    proof_summary['_targets'] = targets
    proof_summary['_true_sources'] = true_sources
    proof_summary['_parameter_rows'] = parameter_rows
    return proof_summary


