def _evidence_labels():
    labels = dict(_short_method_labels())
    labels['proposed_diagonal'] = 'Proposed, diagonal covariance'
    return labels


def _evidence_colours():
    colours = dict(_method_colour_map())
    colours['proposed_diagonal'] = '#B565C0'
    return colours


def _evidence_winner(rows, metric, lower=True, eligibility=None):
    eligible = [
        row for row in rows
        if np.isfinite(float(row.get(metric, np.nan)))
        and (eligibility is None or eligibility(row))
    ]
    if not eligible:
        eligible = [
            row for row in rows
            if np.isfinite(float(row.get(metric, np.nan)))
        ]
    chooser = min if lower else max
    return chooser(eligible, key=lambda row: float(row[metric]))


def _evidence_grid_geometry(physics, source_nodes):
    axes = [
        np.arange(size, dtype=float) * float(spacing)
        for size, spacing in zip(physics.shape, physics.spacing)
    ]
    mesh = np.meshgrid(*axes, indexing='ij')
    full_positions = np.stack([part.ravel() for part in mesh], axis=1)
    source_array = np.asarray(source_nodes, dtype=int)
    margin = 4
    lower = np.maximum(0, np.min(source_array, axis=0) - margin)
    upper = np.minimum(np.asarray(physics.shape) - 1,
                       np.max(source_array, axis=0) + margin)
    index_mesh = np.meshgrid(*[
        np.arange(size, dtype=int) for size in physics.shape
    ], indexing='ij')
    mask = np.ones(physics.shape, dtype=bool)
    for dimension, component in enumerate(index_mesh):
        mask &= component >= lower[dimension]
        mask &= component <= upper[dimension]
    search_flat = np.flatnonzero(mask.ravel())
    return full_positions, search_flat, full_positions[search_flat]


def _evidence_reference_fields(physics, candidate_pool):
    fields = np.empty(
        (int(np.prod(physics.shape)), len(candidate_pool)), dtype=np.float32
    )
    for receiver_number, receiver in enumerate(candidate_pool):
        fields[:, receiver_number] = np.asarray(
            physics.compute_traveltime_field(tuple(receiver)), dtype=np.float32
        ).ravel()
    return fields


def _evidence_gaussian_weights(query_positions, control_positions,
                               length_scale):
    query = np.asarray(query_positions, dtype=float)
    control = np.asarray(control_positions, dtype=float)
    distance = np.linalg.norm(
        query[:, None, :] - control[None, :, :], axis=2
    )
    scale = max(float(length_scale), np.finfo(float).eps)
    weights = np.exp(-0.5 * (distance / scale) ** 2)
    weights /= np.maximum(
        np.sum(weights, axis=1, keepdims=True), np.finfo(float).tiny
    )
    # Preserve exact controls.  Without this constraint, even an evaluated
    # source node is blurred with neighbouring node residuals, which would
    # make the continuous migration inconsistent with the discrete locator.
    exact_query, exact_control = np.where(distance <= 1.0e-10)
    for query_number, control_number in zip(exact_query, exact_control):
        weights[query_number] = 0.0
        weights[query_number, control_number] = 1.0
    return weights


def _evidence_profile_iid_scores(observation, predictions, variance):
    residual = np.asarray(observation, dtype=float) - np.asarray(
        predictions, dtype=float
    )
    residual -= np.mean(residual, axis=-1, keepdims=True)
    return np.sum(residual ** 2, axis=-1) / max(
        float(variance), np.finfo(float).tiny
    )


def _evidence_profile_covariance_scores(observation, predictions,
                                        covariance_numbers,
                                        covariances,
                                        profiled_precisions=None):
    residual = np.asarray(observation, dtype=float)[None, :] - np.asarray(
        predictions, dtype=float
    )
    covariance_numbers = np.asarray(covariance_numbers, dtype=int)
    if profiled_precisions is None:
        selected_covariances = _nearest_positive_definite_batch(
            np.asarray(covariances, dtype=float)[covariance_numbers], 1.0e-14
        )
        profiled_precisions = _profiled_precision_matrices(
            selected_covariances
        )
    else:
        profiled_precisions = np.asarray(
            profiled_precisions, dtype=float
        )[covariance_numbers]
    return np.einsum(
        'qi,qij,qj->q', residual, profiled_precisions, residual,
        optimize=True,
    )


def _evidence_scores_to_probability(scores):
    scores = np.asarray(scores, dtype=float)
    log_probability = -0.5 * (scores - float(np.nanmin(scores)))
    probability = np.exp(np.clip(log_probability, -80.0, 0.0))
    probability /= max(float(np.sum(probability)), np.finfo(float).tiny)
    return probability


def _evidence_migration_metrics(probability_image, truth_index, physics,
                                focus_radius_cells=3):
    probability = np.asarray(probability_image, dtype=float)
    probability = np.maximum(probability, 0.0)
    probability /= max(float(np.sum(probability)), np.finfo(float).tiny)
    peak_index = np.unravel_index(int(np.argmax(probability)), probability.shape)
    spacing = np.asarray(physics.spacing, dtype=float)
    truth = np.asarray(truth_index, dtype=float)
    peak_error = float(np.linalg.norm(
        (np.asarray(peak_index, dtype=float) - truth) * spacing
    ))
    grids = np.ogrid[tuple(slice(0, size) for size in probability.shape)]
    distance_squared = np.zeros(probability.shape, dtype=float)
    for dimension, grid in enumerate(grids):
        distance_squared += ((grid - truth[dimension]) * spacing[dimension]) ** 2
    focus_radius = float(focus_radius_cells) * float(np.min(spacing))
    focus_mask = distance_squared <= focus_radius ** 2
    focus_probability = float(np.sum(probability[focus_mask]))
    outside = probability[~focus_mask]
    sidelobe = float(np.max(outside)) if outside.size else 0.0
    truth_probability = float(probability[tuple(map(int, truth_index))])
    source_to_sidelobe_db = float(10.0 * np.log10(
        max(truth_probability, np.finfo(float).tiny)
        / max(sidelobe, np.finfo(float).tiny)
    ))
    positive = probability[probability > 0.0]
    entropy = -float(np.sum(positive * np.log(positive)))
    normalized_entropy = entropy / max(
        float(np.log(probability.size)), np.finfo(float).tiny
    )
    ordered = np.sort(probability.ravel())[::-1]
    credible_cells = int(np.searchsorted(
        np.cumsum(ordered), 0.95, side='left'
    ) + 1)
    credible_area = float(credible_cells * np.prod(spacing))
    return {
        'peak_error_m': peak_error,
        'focus_probability': focus_probability,
        'source_to_sidelobe_db': source_to_sidelobe_db,
        'normalized_entropy': normalized_entropy,
        'credible_area_95_m2': credible_area,
        'peak_index': [int(value) for value in peak_index],
    }


def _evidence_diagonal_localization_ablation(records, physics):
    migration = records['_migration_context']
    original = migration['proposed_context']
    original_state = original['discrepancy_state']
    diagonal_state = dict(original_state)
    diagonal_state['path_covariances_s2'] = np.asarray([
        np.diag(np.diag(covariance))
        for covariance in original_state['path_covariances_s2']
    ])
    diagonal_state['total_covariances_s2'] = np.asarray([
        np.diag(np.diag(covariance))
        for covariance in original_state['total_covariances_s2']
    ])
    context = dict(original)
    context['key'] = 'proposed_diagonal'
    context['label'] = 'Proposed design, diagonal path covariance'
    context['discrepancy_state'] = diagonal_state
    _prepare_fast_locator_state(context)
    config = records['effective_configuration']
    interval_split = RobustArrivalSplit(
        'interval_calibration', migration['interval_arrivals'], [],
        np.empty(0, dtype=float),
    )
    test_split = RobustArrivalSplit(
        'untouched_test', migration['test_arrivals'], [],
        np.empty(0, dtype=float),
    )
    interval_rows = _simulate_method_split(
        context, interval_split, migration['reference_arrivals'],
        migration['interval_truth_indices'], config,
        int(config['seed']) + 811,
    )
    thresholds = _finite_sample_interval_thresholds(
        interval_rows, config['confidence_levels'], physics.dims
    )
    test_rows = _simulate_method_split(
        context, test_split, migration['reference_arrivals'],
        migration['test_truth_indices'], config, int(config['seed']) + 907,
    )
    prior_extent = np.maximum(
        np.ptp(migration['source_positions'], axis=0),
        np.asarray(physics.spacing, dtype=float),
    )
    summary = _aggregate_method_rows(
        test_rows, thresholds, config, float(np.prod(prior_extent)),
        len(context['receiver_indices']) + len(context['calibration_indices']),
    )
    summary['worst_station_failure_mean_error_m'] = np.nan
    summary['worst_station_failure_p95_error_m'] = np.nan
    return summary, test_rows, thresholds, diagonal_state


def _evidence_migration_method_specs(records):
    designs = records['selected_designs']
    return [
        ('reference_probabilistic', 'Reference posterior migration',
         np.asarray(designs['uniform_receiver_candidate_numbers'], dtype=int)),
        ('velocity_marginalized', 'Velocity BMA migration',
         np.asarray(designs['uniform_receiver_candidate_numbers'], dtype=int)),
        ('double_difference', 'Double-difference migration',
         np.asarray(designs['uniform_receiver_candidate_numbers'], dtype=int)),
        ('d_opt_reference', 'Reference D-opt migration',
         np.asarray(designs['reference_d_opt_receiver_candidate_numbers'], dtype=int)),
        ('proposed_diagonal', 'Proposed design, diagonal covariance',
         np.asarray(designs['proposed_receiver_candidate_numbers'], dtype=int)),
        ('proposed', 'Proposed correlated calibrated migration',
         np.asarray(designs['proposed_receiver_candidate_numbers'], dtype=int)),
    ]


def _run_paired_reference_velocity_migration(
        records, physics, fast=False, maximum_scenarios=None):
    """Evaluate paired unseen blocks and retain only one full image set.

    ``maximum_scenarios`` bounds the extra migration audit when this routine is
    called for every model in ``main``.  The subset spans the ordered Cartesian
    product deterministically.  All methods still receive the same selected
    model/event/noise blocks, while only the independently chosen representative
    scenario keeps six full probability volumes in memory.
    """
    context = records['_migration_context']
    config = records['effective_configuration']
    reference = context['reference_arrivals']
    training = context['training_arrivals']
    test = context['test_arrivals']
    source_nodes = context['source_nodes']
    source_positions = context['source_positions']
    candidate_pool = context['candidate_pool']
    truth_indices = context['truth_indices']
    designs = records['selected_designs']
    proposed_state = context['proposed_context']['discrepancy_state']
    diagonal_covariances = np.asarray([
        np.diag(np.diag(covariance))
        for covariance in proposed_state['total_covariances_s2']
    ])
    proposed_profiled_precisions = _profiled_precision_matrices(
        proposed_state['total_covariances_s2']
    )
    diagonal_profiled_precisions = _profiled_precision_matrices(
        diagonal_covariances
    )

    full_positions, search_flat, search_positions = _evidence_grid_geometry(
        physics, source_nodes
    )
    domain_diagonal = max(
        float(np.linalg.norm(np.ptp(source_positions, axis=0))),
        float(np.min(physics.spacing)),
    )
    migration_distance = np.linalg.norm(
        search_positions[:, None, :] - source_positions[None, :, :], axis=2
    )
    migration_kernel_length = max(0.04 * domain_diagonal,
                                  float(np.min(physics.spacing)))
    migration_kernels = np.exp(
        -0.5 * (migration_distance / migration_kernel_length) ** 2
    )
    # Each source-node point mass maps to a unit-mass physical image kernel.
    # Column normalization avoids the almost-uniform images produced by
    # query-normalized interpolation when the source-node posterior is sparse.
    migration_kernels /= np.maximum(
        np.sum(migration_kernels, axis=0, keepdims=True),
        np.finfo(float).tiny,
    )
    proposed_calibrations = np.asarray(
        designs['proposed_calibration_source_numbers'], dtype=int
    )
    baseline_calibrations = np.asarray(
        designs['baseline_calibration_source_numbers'], dtype=int
    )
    proposed_calibration_weights = np.asarray(
        proposed_state['interpolation_weights'], dtype=float
    )
    proposed_receivers = np.asarray(
        designs['proposed_receiver_candidate_numbers'], dtype=int
    )
    proposed_empirical_mean = np.asarray(
        proposed_state['empirical_residual_mean_s'], dtype=float
    )

    uniform_receivers = np.asarray(
        designs['uniform_receiver_candidate_numbers'], dtype=int
    )
    calibration_positions_dd = source_positions[baseline_calibrations]
    nearest_calibration_dd = np.argmin(
        np.linalg.norm(
            source_positions[:, None, :]
            - calibration_positions_dd[None, :, :], axis=2
        ), axis=1,
    )
    all_pairs = [
        (model_number, event_number, int(truth_index))
        for model_number in range(test.shape[0])
        for event_number, truth_index in enumerate(truth_indices)
    ]
    pairs = list(all_pairs)
    if maximum_scenarios is not None:
        maximum_scenarios = max(1, int(maximum_scenarios))
        if len(pairs) > maximum_scenarios:
            selected_numbers = np.unique(np.rint(np.linspace(
                0, len(pairs) - 1, maximum_scenarios
            )).astype(int))
            pairs = [pairs[int(number)] for number in selected_numbers]

    # The displayed case is fixed before any migration image is evaluated.  It
    # is the selected block nearest the 75th-percentile localization error of
    # the conventional reference posterior; the proposed method is not used.
    eligible_localization_ids = {
        f'untouched_test_m{model_number:04d}_e{event_number:03d}'
        for model_number, event_number, _ in pairs
    }
    conventional_localization = [
        row for row in records['event_level_results']
        if row['method_key'] == 'reference_probabilistic'
        and row['scenario_id'] in eligible_localization_ids
    ]
    if conventional_localization:
        challenge = float(np.quantile([
            row['error_3d_m'] for row in conventional_localization
        ], 0.75))
        representative_localization = min(
            conventional_localization,
            key=lambda row: abs(float(row['error_3d_m']) - challenge),
        )['scenario_id']
        representative = representative_localization.replace(
            'untouched_test_', 'migration_', 1
        )
    else:
        first_model, first_event, _ = pairs[0]
        representative = f'migration_m{first_model:04d}_e{first_event:03d}'
    method_specs = _evidence_migration_method_specs(records)
    rng = np.random.default_rng(int(config['seed']) + 1907)
    sigma = float(config['picking_noise_std_s'])
    calibration_sigma = sigma / np.sqrt(
        max(1, int(config['calibration_repeats']))
    )
    rows = []
    images = {}
    for scenario_number, (model_number, event_number, truth_index) in enumerate(pairs):
        event_noise = rng.normal(0.0, sigma, size=test.shape[2])
        calibration_noise = rng.normal(
            0.0, calibration_sigma,
            size=(test.shape[1], test.shape[2]),
        )
        model_arrivals = np.asarray(test[model_number], dtype=float)
        scenario_id = f'migration_m{model_number:04d}_e{event_number:03d}'
        truth_node = tuple(map(int, source_nodes[truth_index]))
        for method_key, method_label, receiver_indices in method_specs:
            observation = (
                model_arrivals[truth_index, receiver_indices]
                + event_noise[receiver_indices]
            )
            # Travel-time posterior migration is evaluated on the exact common
            # source-prior nodes, then mapped to the physical image grid with
            # a positivity-preserving kernel.  Because every method uses the
            # same nodes and kernel, image differences come only from its
            # travel-time likelihood and observation system.
            predictions = reference[:, receiver_indices]
            if method_key in {'reference_probabilistic', 'd_opt_reference'}:
                scores = _evidence_profile_iid_scores(
                    observation, predictions, sigma ** 2
                )
            elif method_key == 'velocity_marginalized':
                per_model = -0.5 * _evidence_profile_iid_scores(
                    observation,
                    training[:, :, receiver_indices],
                    sigma ** 2,
                )
                scores = -2.0 * (
                    logsumexp(per_model, axis=0)
                    - np.log(training.shape[0])
                )
            elif method_key == 'double_difference':
                scores = np.empty(len(source_nodes), dtype=float)
                for calibration_number in range(len(baseline_calibrations)):
                    chosen = np.flatnonzero(
                        nearest_calibration_dd == calibration_number
                    )
                    master_index = int(
                        baseline_calibrations[calibration_number]
                    )
                    master_observation = (
                        model_arrivals[master_index, receiver_indices]
                        + calibration_noise[master_index, receiver_indices]
                    )
                    difference_observation = observation - master_observation
                    difference_prediction = (
                        predictions[chosen]
                        - reference[master_index, receiver_indices][None, :]
                    )
                    scores[chosen] = _evidence_profile_iid_scores(
                        difference_observation, difference_prediction,
                        2.0 * sigma ** 2,
                    )
            else:
                calibration_observation = (
                    model_arrivals[proposed_calibrations][:, receiver_indices]
                    + calibration_noise[
                        proposed_calibrations[:, None], receiver_indices[None, :]
                    ]
                )
                calibration_residual = (
                    calibration_observation
                    - reference[proposed_calibrations][:, receiver_indices]
                )
                predictions = (
                    predictions
                    + proposed_calibration_weights @ calibration_residual
                    + proposed_empirical_mean[:, :]
                )
                covariances = (
                    proposed_state['total_covariances_s2']
                    if method_key == 'proposed'
                    else diagonal_covariances
                )
                scores = _evidence_profile_covariance_scores(
                    observation, predictions,
                    np.arange(len(source_nodes), dtype=int), covariances,
                    profiled_precisions=(
                        proposed_profiled_precisions
                        if method_key == 'proposed'
                        else diagonal_profiled_precisions
                    ),
                )
            probability_nodes = _evidence_scores_to_probability(scores)
            posterior_mean = np.sum(
                probability_nodes[:, None] * source_positions, axis=0
            )
            centroid_error = float(np.linalg.norm(
                posterior_mean - source_positions[truth_index]
            ))
            probability_search = migration_kernels @ probability_nodes
            probability_search /= max(
                float(np.sum(probability_search)), np.finfo(float).tiny
            )
            probability_image = np.zeros(physics.shape, dtype=np.float32)
            probability_image.ravel()[search_flat] = probability_search
            metrics = _evidence_migration_metrics(
                probability_image, truth_node, physics
            )
            row = {
                'scenario_id': scenario_id,
                'velocity_model_index': int(model_number),
                'event_number': int(event_number),
                'truth_source_index': int(truth_index),
                'truth_grid_index': list(truth_node),
                'method_key': method_key,
                'method': method_label,
                'posterior_centroid_error_m': centroid_error,
                **metrics,
            }
            rows.append(row)
            if scenario_id == representative:
                images[(scenario_id, method_key)] = probability_image
    summaries = []
    for method_key, method_label, _ in method_specs:
        selected = [row for row in rows if row['method_key'] == method_key]
        peak = np.asarray([row['peak_error_m'] for row in selected], dtype=float)
        centroid = np.asarray([
            row['posterior_centroid_error_m'] for row in selected
        ], dtype=float)
        summaries.append({
            'method_key': method_key,
            'method': method_label,
            'scenario_count': int(len(selected)),
            'mean_peak_error_m': float(np.mean(peak)),
            'median_peak_error_m': float(np.median(peak)),
            'p95_peak_error_m': float(np.quantile(peak, 0.95)),
            'cvar_peak_error_m': _upper_tail_mean(
                peak, float(config['cvar_alpha'])
            ),
            'mean_centroid_error_m': float(np.mean(centroid)),
            'p95_centroid_error_m': float(np.quantile(centroid, 0.95)),
            'cvar_centroid_error_m': _upper_tail_mean(
                centroid, float(config['cvar_alpha'])
            ),
            'mean_focus_probability': float(np.mean([
                row['focus_probability'] for row in selected
            ])),
            'mean_source_to_sidelobe_db': float(np.mean([
                row['source_to_sidelobe_db'] for row in selected
            ])),
            'mean_normalized_entropy': float(np.mean([
                row['normalized_entropy'] for row in selected
            ])),
            'mean_credible_area_95_m2': float(np.mean([
                row['credible_area_95_m2'] for row in selected
            ])),
        })
    return rows, summaries, images, representative


def _plot_evidence_localization_accuracy(summary_rows, output_dir):
    labels = _evidence_labels()
    colours = _evidence_colours()
    keys = [row['method_key'] for row in summary_rows]
    x = np.arange(len(keys))
    metrics = [
        ('mean_error_m', 'Mean error (m)'),
        ('rmse_m', 'RMSE (m)'),
        ('p95_error_m', '95th-percentile error (m)'),
        ('cvar_error_m', 'CVaR tail error (m)'),
    ]
    fig, axes = plt.subplots(2, 2, figsize=(13.5, 8.4), constrained_layout=True)
    winners = []
    for axis, (metric, ylabel) in zip(axes.ravel(), metrics):
        winner = _evidence_winner(summary_rows, metric, lower=True)
        winners.append(winner['method_key'])
        values = [float(row[metric]) for row in summary_rows]
        bars = axis.bar(x, values, color=[colours[key] for key in keys])
        bars[keys.index(winner['method_key'])].set_edgecolor('black')
        bars[keys.index(winner['method_key'])].set_linewidth(2.2)
        axis.set_ylabel(ylabel)
        axis.set_title(
            f"BETTER: {labels[winner['method_key']]} = "
            f"{winner[metric]:.3f} m (lower is better)", fontsize=11
        )
        axis.grid(True, axis='y', ls=':', alpha=0.45)
        axis.set_xticks(x)
        axis.set_xticklabels([labels[key] for key in keys], rotation=24, ha='right')
    overall = min(set(winners), key=lambda key: (-winners.count(key), keys.index(key)))
    fig.suptitle(
        f'Localization accuracy winner across most criteria: {labels[overall]}',
        fontsize=16, weight='bold',
    )
    path = os.path.join(output_dir, 'Figure_01_Localization_Accuracy_Winners.png')
    fig.savefig(path, dpi=300)
    plt.close(fig)
    return os.path.basename(path)


def _plot_evidence_coverage_sharpness(summary_rows, output_dir,
                                      spatial_dimensions=2):
    labels = _evidence_labels()
    colours = _evidence_colours()
    keys = [row['method_key'] for row in summary_rows]
    coverage_error = {
        row['method_key']: abs(float(row['calibrated_coverage_95']) - 0.95)
        for row in summary_rows
    }
    calibration_winner = min(keys, key=lambda key: coverage_error[key])
    feasible = [
        row for row in summary_rows
        if abs(float(row['calibrated_coverage_95']) - 0.95) <= 0.04
    ]
    sharpness_winner = _evidence_winner(
        feasible if feasible else summary_rows,
        'calibrated_interval_volume_95', lower=True,
    )
    score_winner = _evidence_winner(
        summary_rows, 'mean_negative_log_score', lower=True
    )
    fig, axes = plt.subplots(1, 3, figsize=(15.2, 4.9), constrained_layout=True)
    x = np.arange(len(keys))
    axes[0].bar(
        x, [row['calibrated_coverage_95'] for row in summary_rows],
        color=[colours[key] for key in keys],
    )
    axes[0].axhline(0.95, color='black', ls='--', label='95% nominal')
    axes[0].fill_between([-0.5, len(keys) - 0.5], 0.91, 0.99,
                         color='#2A9D8F', alpha=0.10)
    axes[0].set_ylim(0.0, 1.05)
    axes[0].set_ylabel('Held-out coverage')
    axes[0].set_title(
        f'BETTER CALIBRATION: {labels[calibration_winner]} '
        f'(absolute gap {coverage_error[calibration_winner]:.3f})', fontsize=10
    )
    axes[1].bar(
        x, [row['calibrated_interval_volume_95'] for row in summary_rows],
        color=[colours[key] for key in keys],
    )
    axes[1].set_yscale('log')
    axes[1].set_ylabel(
        r'Calibrated 95% ellipse area (m$^2$)'
        if int(spatial_dimensions) == 2
        else r'Calibrated 95% ellipsoid volume (m$^3$)'
    )
    axes[1].set_title(
        f"BETTER SHARPNESS AT VALID COVERAGE: "
        f"{labels[sharpness_winner['method_key']]} = "
        f"{sharpness_winner['calibrated_interval_volume_95']:.2f}", fontsize=10
    )
    axes[2].bar(
        x, [row['mean_negative_log_score'] for row in summary_rows],
        color=[colours[key] for key in keys],
    )
    axes[2].set_ylabel('Mean negative log score')
    axes[2].set_title(
        f"BETTER PROBABILISTIC SCORE: {labels[score_winner['method_key']]} = "
        f"{score_winner['mean_negative_log_score']:.2f}", fontsize=10
    )
    for axis in axes:
        axis.set_xticks(x)
        axis.set_xticklabels([labels[key] for key in keys], rotation=27, ha='right')
        axis.grid(True, axis='y', ls=':', alpha=0.4)
    fig.suptitle(
        f"Coverage--sharpness winner: {labels[sharpness_winner['method_key']]} "
        '(interval size is compared only after coverage calibration)', fontsize=15
    )
    path = os.path.join(output_dir, 'Figure_02_Coverage_Sharpness_Winners.png')
    fig.savefig(path, dpi=300)
    plt.close(fig)
    return os.path.basename(path)


def _plot_evidence_covariance_ablation(summary_rows, diagonal_state,
                                       proposed_state, output_dir):
    labels = _evidence_labels()
    full = next(row for row in summary_rows if row['method_key'] == 'proposed')
    diagonal = next(
        row for row in summary_rows if row['method_key'] == 'proposed_diagonal'
    )
    pair = [diagonal, full]
    pair_keys = [row['method_key'] for row in pair]
    covariance = np.asarray(proposed_state['path_covariances_s2'][
        len(proposed_state['path_covariances_s2']) // 2
    ])
    standard = np.sqrt(np.maximum(np.diag(covariance), np.finfo(float).tiny))
    correlation = covariance / (standard[:, None] * standard[None, :])
    figure = plt.figure(figsize=(14.0, 8.1), constrained_layout=True)
    grid = figure.add_gridspec(2, 3)
    axis_full = figure.add_subplot(grid[0, 0])
    image = axis_full.imshow(correlation, cmap='coolwarm', vmin=-1.0, vmax=1.0)
    figure.colorbar(image, ax=axis_full, label='Path correlation')
    axis_full.set_title(
        f"BETTER PHYSICS: full covariance; mean |off-diagonal| = "
        f"{proposed_state['mean_absolute_off_diagonal_correlation']:.3f}",
        fontsize=10,
    )
    axis_diag = figure.add_subplot(grid[0, 1])
    axis_diag.imshow(np.eye(correlation.shape[0]), cmap='coolwarm', vmin=-1.0, vmax=1.0)
    axis_diag.set_title('IID/diagonal loses the observed cross-path dependence', fontsize=10)
    axis_text = figure.add_subplot(grid[0, 2])
    axis_text.axis('off')
    axis_text.text(
        0.02, 0.92,
        'Ablation holds fixed:\n'
        '• receiver layout\n• calibration sources\n• calibration bias field\n'
        '• test velocity/event/noise blocks\n\nOnly off-diagonal covariance is removed.',
        va='top', fontsize=12,
        bbox=dict(boxstyle='round', facecolor='#F5F5F5', edgecolor='0.6'),
    )
    metrics = [
        ('mean_error_m', 'Mean error (m)', True),
        ('p95_error_m', 'P95 error (m)', True),
        ('cvar_error_m', 'CVaR error (m)', True),
    ]
    winners = []
    for column, (metric, ylabel, lower) in enumerate(metrics):
        axis = figure.add_subplot(grid[1, column])
        winner = _evidence_winner(pair, metric, lower=lower)
        winners.append(winner['method_key'])
        axis.bar(
            np.arange(2), [row[metric] for row in pair],
            color=[_evidence_colours()[key] for key in pair_keys],
        )
        axis.set_xticks(np.arange(2))
        axis.set_xticklabels([labels[key] for key in pair_keys], rotation=15, ha='right')
        axis.set_ylabel(ylabel)
        axis.set_title(
            f"BETTER: {labels[winner['method_key']]} = {winner[metric]:.3f}",
            fontsize=10,
        )
        axis.grid(True, axis='y', ls=':', alpha=0.4)
    overall = min(set(winners), key=lambda key: -winners.count(key))
    figure.suptitle(
        f'Path-covariance ablation winner: {labels[overall]} '
        '(only correlation structure differs)', fontsize=15,
    )
    path = os.path.join(output_dir, 'Figure_03_Path_Covariance_Ablation_Winner.png')
    figure.savefig(path, dpi=300)
    plt.close(figure)
    return os.path.basename(path)


def _plot_evidence_migration_images(migration_rows, images,
                                    representative, physics, output_dir):
    labels = _evidence_labels()
    selected_rows = [
        row for row in migration_rows if row['scenario_id'] == representative
    ]
    winner = min(
        selected_rows, key=lambda row: row['posterior_centroid_error_m']
    )
    true_index = tuple(selected_rows[0]['truth_grid_index'])
    if physics.dims == 2:
        velocity_display = np.asarray(physics.V, dtype=float).T
        probability_projection = lambda probability: probability.T
        horizontal_dimension, vertical_dimension = 0, 1
        projection_label = ''
    elif physics.dims == 3:
        section_number = int(true_index[1])
        velocity_display = np.asarray(
            physics.V[:, section_number, :], dtype=float
        ).T
        probability_projection = lambda probability: np.max(
            probability, axis=1
        ).T
        horizontal_dimension, vertical_dimension = 0, 2
        projection_label = (
            '; X-Z probability maximum projection over Y, '
            f'velocity slice Y={section_number * physics.spacing[1]:.1f} m'
        )
    else:
        raise ValueError('Migration evidence supports 2-D or 3-D models.')
    extent = [
        0.0, (physics.shape[0] - 1) * physics.spacing[0],
        (physics.shape[vertical_dimension] - 1)
        * physics.spacing[vertical_dimension], 0.0,
    ]
    figure, axes = plt.subplots(2, 3, figsize=(15.0, 9.0), constrained_layout=True)
    for axis, row in zip(axes.ravel(), selected_rows):
        probability = images[(representative, row['method_key'])]
        axis.imshow(velocity_display, cmap='gray', extent=extent, aspect='auto')
        display = probability_projection(probability)
        display = display / max(float(np.max(display)), np.finfo(float).tiny)
        image = axis.imshow(
            np.ma.masked_less_equal(display, 1.0e-4), cmap='inferno',
            extent=extent, aspect='auto', alpha=0.82, vmin=0.0, vmax=1.0,
        )
        true_xy = np.asarray(true_index) * np.asarray(physics.spacing)
        peak_xy = np.asarray(row['peak_index']) * np.asarray(physics.spacing)
        axis.scatter(true_xy[horizontal_dimension], true_xy[vertical_dimension],
                     marker='*', s=145,
                     c='#00E5FF', edgecolor='black', label='True source')
        axis.scatter(peak_xy[horizontal_dimension], peak_xy[vertical_dimension],
                     marker='x', s=85,
                     c='white', linewidth=2.0, label='Migration peak')
        better = labels[winner['method_key']]
        prefix = 'BEST' if row['method_key'] == winner['method_key'] else f'BETTER: {better}'
        axis.set_title(
            f"{prefix}\n{labels[row['method_key']]}: peak error "
            f"{row['peak_error_m']:.1f} m; centroid "
            f"{row['posterior_centroid_error_m']:.1f} m", fontsize=9.5,
        )
        axis.set_xlabel('X (m)')
        axis.set_ylabel('Depth (m)')
        axis.legend(fontsize=7, loc='lower right')
    figure.colorbar(image, ax=axes.ravel().tolist(), label='Normalized migration probability')
    figure.suptitle(
        f"Representative paired migration winner: {labels[winner['method_key']]} "
        f"on {representative}{projection_label}", fontsize=14,
    )
    path = os.path.join(output_dir, 'Figure_04_Paired_Migration_Images_Winner.png')
    figure.savefig(path, dpi=300)
    plt.close(figure)
    return os.path.basename(path)


