def _joint_evidence_rows(localization_rows, migration_rows):
    migration_by_key = {row['method_key']: row for row in migration_rows}
    migration_alias = {'reference_ls_iid': 'reference_probabilistic'}
    joined = []
    for location in localization_rows:
        migration_key = migration_alias.get(
            location['method_key'], location['method_key']
        )
        migration = migration_by_key.get(migration_key)
        if migration is None:
            continue
        coverage_gap = abs(float(location['calibrated_coverage_95']) - 0.95)
        joined.append({
            'method_key': location['method_key'],
            'method': location['method'],
            'migration_method_key': migration_key,
            'mean_location_error_m': float(location['mean_error_m']),
            'location_p95_error_m': float(location['p95_error_m']),
            'location_cvar_error_m': float(location['cvar_error_m']),
            'coverage_95_absolute_gap': coverage_gap,
            'interval_area_95_m2': float(location['calibrated_interval_volume_95']),
            'mean_migration_centroid_error_m': float(
                migration['mean_centroid_error_m']
            ),
            'migration_p95_centroid_error_m': float(
                migration['p95_centroid_error_m']
            ),
            'migration_cvar_centroid_error_m': float(
                migration['cvar_centroid_error_m']
            ),
            'mean_migration_peak_error_m': float(migration['mean_peak_error_m']),
            'migration_focus_probability': float(migration['mean_focus_probability']),
        })
    lower_metrics = [
        'mean_location_error_m', 'location_p95_error_m',
        'location_cvar_error_m', 'coverage_95_absolute_gap',
        'interval_area_95_m2', 'mean_migration_centroid_error_m',
        'migration_p95_centroid_error_m', 'migration_cvar_centroid_error_m',
    ]
    for metric in lower_metrics:
        values = np.asarray([row[metric] for row in joined], dtype=float)
        low, high = float(np.min(values)), float(np.max(values))
        denominator = max(high - low, np.finfo(float).eps)
        for row in joined:
            row.setdefault('_components', []).append((row[metric] - low) / denominator)
    focus = np.asarray([row['migration_focus_probability'] for row in joined])
    focus_low, focus_high = float(np.min(focus)), float(np.max(focus))
    focus_denominator = max(focus_high - focus_low, np.finfo(float).eps)
    for row in joined:
        row['_components'].append(
            (focus_high - row['migration_focus_probability']) / focus_denominator
        )
        row['joint_normalized_loss'] = float(np.mean(row.pop('_components')))
    return joined


def _plot_evidence_joint_pareto(joint_rows, output_dir):
    labels = _evidence_labels()
    colours = _evidence_colours()
    winner = _evidence_winner(joint_rows, 'joint_normalized_loss', lower=True)
