def _plot_evidence_bootstrap(bootstrap_rows, output_dir):
    labels = _evidence_labels()
    rows = sorted(bootstrap_rows, key=lambda row: row['ci95_upper_m'])
    centres = np.asarray([
        row['mean_error_difference_proposed_minus_baseline_m'] for row in rows
    ])
    lower = np.asarray([row['ci95_lower_m'] for row in rows])
    upper = np.asarray([row['ci95_upper_m'] for row in rows])
    all_significant = bool(np.all(upper < 0.0))
    figure, axis = plt.subplots(figsize=(9.0, 5.4), constrained_layout=True)
    y = np.arange(len(rows))
    axis.errorbar(
        centres, y, xerr=np.vstack((centres - lower, upper - centres)),
        fmt='o', color='#7B2CBF', ecolor='#264653', capsize=4,
    )
    axis.axvline(0.0, color='black', ls='--')
    axis.set_yticks(y)
    axis.set_yticklabels([
        labels.get(row['baseline_method_key'], row['baseline_method'])
        for row in rows
    ])
    axis.set_xlabel('Paired mean-error difference: Proposed − baseline (m)')
    conclusion = (
        'BETTER: Proposed; every 95% block-bootstrap CI is below zero'
        if all_significant else
        'MIXED: at least one 95% CI crosses zero; no universal significance claim'
    )
    axis.set_title(conclusion, fontsize=11)
    axis.grid(True, axis='x', ls=':', alpha=0.4)
    figure.suptitle(
        'Statistical winner: Proposed' if all_significant
        else 'Statistical comparison: mixed evidence', fontsize=15,
    )
    path = os.path.join(output_dir, 'Figure_09_Paired_Bootstrap_Winner.png')
    figure.savefig(path, dpi=300)
    plt.close(figure)
    return os.path.basename(path)


def _write_localization_migration_report(records, localization_rows,
                                         migration_rows, joint_rows,
                                         figures, output_dir, fast,
                                         model_type=None,
                                         spatial_dimensions=2):
    proposed_location = next(
        row for row in localization_rows if row['method_key'] == 'proposed'
    )
    best_baseline_location = min(
        (row for row in localization_rows
         if row['method_key'] not in {'proposed', 'proposed_diagonal'}),
        key=lambda row: row['mean_error_m'],
    )
    proposed_migration = next(
        row for row in migration_rows if row['method_key'] == 'proposed'
    )
    best_baseline_migration = min(
        (row for row in migration_rows
         if row['method_key'] not in {'proposed', 'proposed_diagonal'}),
        key=lambda row: row['mean_centroid_error_m'],
    )
    joint_winner = min(joint_rows, key=lambda row: row['joint_normalized_loss'])
    location_reduction = 100.0 * (
        best_baseline_location['mean_error_m'] - proposed_location['mean_error_m']
    ) / max(best_baseline_location['mean_error_m'], np.finfo(float).tiny)
    migration_reduction = 100.0 * (
        best_baseline_migration['mean_centroid_error_m']
        - proposed_migration['mean_centroid_error_m']
    ) / max(best_baseline_migration['mean_centroid_error_m'], np.finfo(float).tiny)
    migration_measure = '面积' if int(spatial_dimensions) == 2 else '体积'
    model_suffix = f'（{model_type}）' if model_type else ''
    lines = [
        f'# 定位—偏移联合优势算例报告{model_suffix}', '',
        '## 公平性与证据链', '',
        '- 所有观测数据由彼此独立的真实速度实现经 FMM 生成；速度偏差因此成为共享传播路径所诱发的相关走时误差，而非独立加噪。',
        '- 训练、区间校准、观测系统设计验证和最终测试速度模型严格分离。最终定位及偏移比较使用相同事件、速度模型和全候选台站噪声。',
        '- 除明确命名的“速度集合边缘化”基线外，所有逆问题只调用同一个参考速度模型。',
        '- 台站数量一致；校准震源在单位成本信息增益中计入成本。',
        '- “全路径协方差 vs 对角协方差”消融固定台网、校准震源、经验偏差场和随机数，仅移除非对角相关项。', '',
        '## 主要结果', '',
        f"- 定位：Proposed 平均误差 {proposed_location['mean_error_m']:.3f} m；最佳非本方法基线 {best_baseline_location['method']} 为 {best_baseline_location['mean_error_m']:.3f} m，相对变化 {location_reduction:+.1f}%（正值表示本方法降低误差）。",
        f"- 定位尾部：Proposed P95/CVaR 为 {proposed_location['p95_error_m']:.3f}/{proposed_location['cvar_error_m']:.3f} m；95% 实际覆盖率 {proposed_location['calibrated_coverage_95']:.3f}。",
        f"- 偏移：Proposed 平均后验质心误差 {proposed_migration['mean_centroid_error_m']:.3f} m；最佳非本方法基线 {best_baseline_migration['method']} 为 {best_baseline_migration['mean_centroid_error_m']:.3f} m，相对变化 {migration_reduction:+.1f}%。图像峰值误差、聚焦概率、熵和 95% 成像{migration_measure}另行独立报告。",
        f"- 联合等权归一化损失的胜出方法为 {_evidence_labels()[joint_winner['method_key']]}，值为 {joint_winner['joint_normalized_loss']:.3f}。", '',
        '## 如何阅读图件', '',
        '每幅比较图的总标题与子图标题均由当前数值自动计算并明确写出胜出方法；程序不会把“Proposed”硬编码为赢家。指标方向（越小/越大越好）也写在标题或坐标轴中。', '',
        '## 结论边界', '',
        '- 单台站失效和单位成本信息增益分别独立报告；若其他方法胜出，图题会如实显示，不用总体平均掩盖局部弱项。',
        '- 偏移比较是走时后验/差分走时相干偏移，不声称替代完整波形 RTM；它直接检验本研究核心的走时定位—偏移一致性。',
        f"- 当前运行模式：{'快速验证' if fast else '正式完整算例'}。", '',
        '## 图件清单', '',
    ]
    lines.extend(f'- `{name}`' for name in figures)
    report_path = os.path.join(output_dir, 'localization_migration_advantage_report.md')
    with open(report_path, 'w', encoding='utf-8') as stream:
        stream.write('\n'.join(lines) + '\n')
    return os.path.basename(report_path)


def run_localization_migration_advantage_evidence(output_dir, fast=False):
    """Run the complete fixed-model proof case and winner-labelled figures."""
    os.makedirs(output_dir, exist_ok=True)
    evidence_dir = os.path.join(output_dir, 'winner_labelled_evidence_figures')
    os.makedirs(evidence_dir, exist_ok=True)
    physics, candidates, targets, true_sources = _build_advantage_case_physics()
    overrides = advantage_case_config(fast=fast)
    analysis_config = {
        'seed': int(overrides['seed']),
        'picking_noise_std': float(overrides['picking_noise_std_s']),
    }
    parameter_rows = _advantage_case_parameter_rows(
        physics, candidates, targets, true_sources, overrides
    )
    _write_csv(
        os.path.join(output_dir, 'case_parameters.csv'),
        _csv_safe_rows(parameter_rows),
    )
    records = run_path_correlated_joint_design_validation(
        physics, candidates, targets, true_sources, output_dir,
        analysis_config, config_overrides=overrides,
    )
    diagonal_summary, diagonal_events, diagonal_thresholds, diagonal_state = (
        _evidence_diagonal_localization_ablation(records, physics)
    )
    localization_rows = list(records['method_summary']) + [diagonal_summary]
    _write_csv(
        os.path.join(output_dir, 'localization_method_summary_with_ablation.csv'),
        _csv_safe_rows(localization_rows),
    )
    _write_csv(
        os.path.join(output_dir, 'diagonal_covariance_event_results.csv'),
        _csv_safe_rows(diagonal_events),
    )
    _atomic_write_json(
        os.path.join(output_dir, 'diagonal_covariance_interval_thresholds.json'),
        diagonal_thresholds,
    )
    migration_event_rows, migration_summary, images, representative = (
        _run_paired_reference_velocity_migration(records, physics, fast=fast)
    )
    _write_csv(
        os.path.join(output_dir, 'migration_event_level_metrics.csv'),
        _csv_safe_rows(migration_event_rows),
    )
    _write_csv(
        os.path.join(output_dir, 'migration_method_summary.csv'),
        _csv_safe_rows(migration_summary),
    )
    joint_rows = _joint_evidence_rows(localization_rows, migration_summary)
    _write_csv(
        os.path.join(output_dir, 'joint_localization_migration_summary.csv'),
        _csv_safe_rows(joint_rows),
    )
    proposed_state = records['_migration_context'][
        'proposed_context'
    ]['discrepancy_state']
    figures = [
        _plot_evidence_localization_accuracy(localization_rows, evidence_dir),
        _plot_evidence_coverage_sharpness(localization_rows, evidence_dir),
        _plot_evidence_covariance_ablation(
            localization_rows, diagonal_state, proposed_state, evidence_dir
        ),
        _plot_evidence_migration_images(
            migration_event_rows, images, representative, physics, evidence_dir
        ),
        _plot_evidence_migration_metrics(migration_summary, evidence_dir),
        _plot_evidence_migration_tail(
            migration_event_rows, migration_summary, evidence_dir
        ),
        _plot_evidence_joint_pareto(joint_rows, evidence_dir),
        _plot_evidence_failure_cost(localization_rows, evidence_dir),
        _plot_evidence_bootstrap(records['paired_block_bootstrap'], evidence_dir),
    ]
    report_file = _write_localization_migration_report(
        records, localization_rows, migration_summary, joint_rows,
        figures, output_dir, fast,
    )
    winners = {
        'localization_mean_error': _evidence_winner(
            localization_rows, 'mean_error_m', True
        )['method_key'],
        'localization_p95_error': _evidence_winner(
            localization_rows, 'p95_error_m', True
        )['method_key'],
        'localization_cvar_error': _evidence_winner(
            localization_rows, 'cvar_error_m', True
        )['method_key'],
        'coverage_95_calibration': min(
            localization_rows,
            key=lambda row: abs(row['calibrated_coverage_95'] - 0.95),
        )['method_key'],
        'migration_mean_centroid_error': _evidence_winner(
            migration_summary, 'mean_centroid_error_m', True
        )['method_key'],
        'migration_cvar_centroid_error': _evidence_winner(
            migration_summary, 'cvar_centroid_error_m', True
        )['method_key'],
        'joint_normalized_loss': _evidence_winner(
            joint_rows, 'joint_normalized_loss', True
        )['method_key'],
    }
    manifest = {
        'fast_verification': bool(fast),
        'all_comparison_figure_titles_name_the_data_driven_winner': True,
        'winner_selection_is_not_hard_coded': True,
        'representative_migration_scenario': representative,
        'winners': winners,
        'figures_directory': evidence_dir,
        'figures': figures,
        'tables': [
            'case_parameters.csv',
            'localization_method_summary_with_ablation.csv',
            'diagonal_covariance_event_results.csv',
            'migration_event_level_metrics.csv',
            'migration_method_summary.csv',
            'joint_localization_migration_summary.csv',
        ],
        'report': report_file,
        'path_error_diagnostics': records['path_error_diagnostics'],
    }
    _atomic_write_json(
        os.path.join(output_dir, 'localization_migration_evidence_manifest.json'),
        manifest,
    )
    print(
        f">>> Localization + migration advantage evidence complete: {output_dir}"
    )
    return manifest


def _main_model_advantage_parameter_rows(records, physics, model_type):
    """Describe the exact main-run experiment represented by ``records``."""
    config = records['effective_configuration']
    velocity_counts = records['velocity_split_counts']
    event_counts = records['event_counts_per_velocity_realization']
    return [
        {
            'group': 'Main model', 'parameter': 'Model and grid',
            'value': f"{model_type}; {physics.dims}D; {tuple(physics.shape)}; "
                     f"spacing={tuple(map(float, physics.spacing))} m",
            'role': 'The same reference grid and velocity used by main.',
        },
        {
            'group': 'Velocity split', 'parameter': 'Independent realizations',
            'value': ', '.join(
                f'{key}={value}' for key, value in velocity_counts.items()
            ),
            'role': 'Training, interval calibration, design validation, and final test are disjoint.',
        },
        {
            'group': 'Event split', 'parameter': 'Events per velocity realization',
            'value': ', '.join(
                f'{key}={value}' for key, value in event_counts.items()
            ),
            'role': 'Position-disjoint target-near events; validation and test events are new.',
        },
        {
            'group': 'Velocity error', 'parameter': 'Target/background amplitudes',
            'value': (
                f"target RMS candidates={config['velocity_rms_fractions']}; "
                f"background fraction={config['velocity_background_fraction']:.4g}"
            ),
            'role': 'Pointwise random perturbations are smoothed and concentrated around the target.',
        },
        {
            'group': 'Observation design', 'parameter': 'Receivers + calibration sources',
            'value': (
                f"{config['receiver_count']} + "
                f"{config['calibration_source_count']}"
            ),
            'role': 'Joint robust design is compared at a matched receiver budget; shots count as cost.',
        },
        {
            'group': 'Uncertainty', 'parameter': 'Picking noise and interval levels',
            'value': (
                f"sigma={config['picking_noise_std_s']:.6g} s; "
                f"levels={config['confidence_levels']}"
            ),
            'role': 'Intervals are calibrated only on the independent interval split.',
        },
        {
            'group': 'Parallelism', 'parameter': 'Configured workers',
            'value': (
                f"velocity={config['parallel_workers']}; "
                f"design={config['design_parallel_workers']}; "
                f"simulation={config['simulation_parallel_workers']}"
            ),
            'role': 'Large velocity ensembles and independent blocks use bounded parallel workers.',
        },
    ]


def run_main_model_advantage_evidence_from_records(
        records, physics, model_type, output_dir):
    """Create both legacy evidence suites from the current main-model trial.

    This is deliberately a post-processing entry point: it reuses the exact
    arrival banks, layouts, calibration shots, discrepancy state, interval
    thresholds, held-out events, and paired localization results already
    produced by ``run_path_correlated_joint_design_validation``.
    """
    os.makedirs(output_dir, exist_ok=True)
    robust_figure_dir = os.path.join(
        output_dir, 'robust_advantage_demonstration_figures'
    )
    migration_figure_dir = os.path.join(
        output_dir, 'localization_migration_winner_figures'
    )
    os.makedirs(robust_figure_dir, exist_ok=True)
    os.makedirs(migration_figure_dir, exist_ok=True)
    context = records['_migration_context']
    config = records['effective_configuration']
    fast = bool(config.get('smoke_test', False))

    parameter_rows = _main_model_advantage_parameter_rows(
        records, physics, model_type
    )
    _write_csv(
        os.path.join(output_dir, 'main_model_advantage_parameters.csv'),
        _csv_safe_rows(parameter_rows),
    )
    _plot_advantage_parameter_table(
        parameter_rows, robust_figure_dir,
        title=f'{model_type} main-run parameters and fair-comparison roles',
    )
    test_source_nodes = [
        context['source_nodes'][int(index)]
        for index in context['test_truth_indices']
    ]
    last_test_residual = np.load(os.path.join(
        records['output_directory'], 'last_test_velocity_residual_fraction.npy'
    ))
    _plot_advantage_velocity_case(
        physics, context['candidate_pool'], test_source_nodes,
        records['selected_designs'], last_test_residual, robust_figure_dir,
    )
    _plot_advantage_error_distributions(
        records['event_level_results'], robust_figure_dir
    )
    _plot_advantage_coverage_sharpness(
        records['method_summary'], robust_figure_dir,
        spatial_dimensions=physics.dims,
    )
    _plot_advantage_tail_failure_cost(
        records['method_summary'], records['paired_block_bootstrap'],
        robust_figure_dir,
    )
    _plot_advantage_representative_confidence(
        records['event_level_results'], records['interval_calibration'],
        robust_figure_dir,
    )
    robust_figures = [
        'advantage_case_parameter_table.png',
        'advantage_case_velocity_and_geometry.png',
        'advantage_error_distribution_evidence.png',
        'advantage_coverage_sharpness_evidence.png',
        'advantage_tail_failure_cost_bootstrap.png',
        'advantage_representative_confidence_ellipses.png',
    ]

    diagonal_summary, diagonal_events, diagonal_thresholds, diagonal_state = (
        _evidence_diagonal_localization_ablation(records, physics)
    )
    localization_rows = list(records['method_summary']) + [diagonal_summary]
    _write_csv(
        os.path.join(output_dir, 'localization_method_summary_with_ablation.csv'),
        _csv_safe_rows(localization_rows),
    )
    _write_csv(
        os.path.join(output_dir, 'diagonal_covariance_event_results.csv'),
        _csv_safe_rows(diagonal_events),
    )
    _atomic_write_json(
        os.path.join(output_dir, 'diagonal_covariance_interval_thresholds.json'),
        diagonal_thresholds,
    )

    default_scenarios = 6 if fast else (32 if physics.dims == 3 else 64)
    maximum_scenarios = int(os.getenv(
        'MAIN_EVIDENCE_MAX_MIGRATION_SCENARIOS', str(default_scenarios)
    ))
    migration_event_rows, migration_summary, images, representative = (
        _run_paired_reference_velocity_migration(
            records, physics, fast=fast,
            maximum_scenarios=maximum_scenarios,
        )
    )
    _write_csv(
        os.path.join(output_dir, 'migration_event_level_metrics.csv'),
        _csv_safe_rows(migration_event_rows),
    )
    _write_csv(
        os.path.join(output_dir, 'migration_method_summary.csv'),
        _csv_safe_rows(migration_summary),
    )
    joint_rows = _joint_evidence_rows(localization_rows, migration_summary)
    _write_csv(
        os.path.join(output_dir, 'joint_localization_migration_summary.csv'),
        _csv_safe_rows(joint_rows),
    )
    proposed_state = context['proposed_context']['discrepancy_state']
    migration_figures = [
        _plot_evidence_localization_accuracy(
            localization_rows, migration_figure_dir
        ),
        _plot_evidence_coverage_sharpness(
            localization_rows, migration_figure_dir,
            spatial_dimensions=physics.dims,
        ),
        _plot_evidence_covariance_ablation(
            localization_rows, diagonal_state, proposed_state,
            migration_figure_dir,
        ),
        _plot_evidence_migration_images(
            migration_event_rows, images, representative, physics,
            migration_figure_dir,
        ),
        _plot_evidence_migration_metrics(
            migration_summary, migration_figure_dir,
            spatial_dimensions=physics.dims,
        ),
        _plot_evidence_migration_tail(
            migration_event_rows, migration_summary, migration_figure_dir
        ),
        _plot_evidence_joint_pareto(joint_rows, migration_figure_dir),
        _plot_evidence_failure_cost(localization_rows, migration_figure_dir),
        _plot_evidence_bootstrap(
            records['paired_block_bootstrap'], migration_figure_dir
        ),
    ]
    report_file = _write_localization_migration_report(
        records, localization_rows, migration_summary, joint_rows,
        migration_figures, output_dir, fast,
        model_type=model_type, spatial_dimensions=physics.dims,
    )
    winners = {
        'localization_mean_error': _evidence_winner(
            localization_rows, 'mean_error_m', True
        )['method_key'],
        'localization_p95_error': _evidence_winner(
            localization_rows, 'p95_error_m', True
        )['method_key'],
        'localization_cvar_error': _evidence_winner(
            localization_rows, 'cvar_error_m', True
        )['method_key'],
        'coverage_95_calibration': min(
            localization_rows,
            key=lambda row: abs(float(row['calibrated_coverage_95']) - 0.95),
        )['method_key'],
        'migration_mean_centroid_error': _evidence_winner(
            migration_summary, 'mean_centroid_error_m', True
        )['method_key'],
        'migration_cvar_centroid_error': _evidence_winner(
            migration_summary, 'cvar_centroid_error_m', True
        )['method_key'],
        'joint_normalized_loss': _evidence_winner(
            joint_rows, 'joint_normalized_loss', True
        )['method_key'],
    }
    manifest = {
        'model_type': model_type,
        'spatial_dimensions': int(physics.dims),
        'reuses_current_main_robust_records': True,
        'regenerates_velocity_models': False,
        'paired_methods_share_migration_blocks_and_noise': True,
        'migration_subset_selection': 'deterministic uniform span of held-out Cartesian blocks',
        'configured_maximum_migration_scenarios': int(maximum_scenarios),
        'evaluated_migration_scenarios': int(
            len(migration_event_rows) // len(_evidence_migration_method_specs(records))
        ),
        'representative_selection': (
            'nearest to conventional reference-posterior localization-error '
            '75th percentile; proposed result not consulted'
        ),
        'representative_migration_scenario': representative,
        'winners_are_data_driven_not_hard_coded': True,
        'winners': winners,
        'robust_advantage_figure_directory': robust_figure_dir,
        'robust_advantage_figures': robust_figures,
        'localization_migration_figure_directory': migration_figure_dir,
        'localization_migration_figures': migration_figures,
        'report': report_file,
        'velocity_split_counts': records['velocity_split_counts'],
        'event_counts_per_velocity_realization': (
            records['event_counts_per_velocity_realization']
        ),
    }
    _atomic_write_json(
        os.path.join(output_dir, 'main_model_advantage_evidence_manifest.json'),
        manifest,
    )
    print(
        f'>>> Main-model localization + migration evidence complete for '
        f'{model_type}: {output_dir}'
    )
    return manifest


def main():
    multiprocessing.freeze_support()
    np.random.seed(42)
    
    # ================= REQ 5 & 6 配置区 =================
    # 可选模型: 'Anomaly_2D', 'Anomaly_3D', 'Marmousi_2D', 'SEAM_3D'
    MODEL_TYPE = os.getenv('MODEL_TYPE', 'Marmousi_2D')
    ADD_WELL_SENSORS = os.getenv('ADD_WELL_SENSORS', '1') == '1'
    # ====================================================
    
    output_dir = os.getenv('OUTPUT_DIR', 'output_images')
    os.makedirs(output_dir, exist_ok=True)
    if os.getenv('RTM_REPLOT_ONLY', '0') == '1':
        replot_rtm_from_checkpoint(output_dir)
        return
    save_matlab_text_data = os.getenv('SAVE_MATLAB_TEXT_DATA', '0') != '0'
    matlab_data_dir = os.path.join(output_dir, 'matlab_text_data')
    if save_matlab_text_data:
        os.makedirs(matlab_data_dir, exist_ok=True)
        _write_matlab_loader(matlab_data_dir)
    analysis_config = reviewer_analysis_config()
    noise_std = analysis_config['picking_noise_std']
    reviewer_output_dir = os.path.join(output_dir, 'reviewer_analyses')
    os.makedirs(reviewer_output_dir, exist_ok=True)
    with open(os.path.join(reviewer_output_dir, 'analysis_configuration.json'),
              'w', encoding='utf-8') as stream:
        json.dump(analysis_config, stream, indent=2)
    write_polarization_scope_note(reviewer_output_dir)
    cost_records = []
    print(f">>> Selected Configuration: {MODEL_TYPE}. Wells Option: {ADD_WELL_SENSORS}")

    if MODEL_TYPE == 'Marmousi_2D':
        IS_3D_MODE = False
        shape, spacing = (681, 141), (12.5, 12.5) 
        velocity_file = os.getenv('MARMOUSI_VELOCITY_FILE', './marmousi.bin')
        nx, nz = shape
        candidates = [(x, 0) for x in range(10, nx-10, 5)] + [(100, z) for z in range(10, nz-10, 5)]
        if ADD_WELL_SENSORS:
            candidates += [(int(nx*0.1), z) for z in range(10, nz-10, 5)] 
        targets = [(x, z) for x in range(int(nx*0.4), int(nx*0.6), 5) for z in range(int(nz*0.5), int(nz*0.7), 5)]
        true_sources = [(int(nx*0.5), int(nz*0.6)), (int(nx*0.45), int(nz*0.65)), (int(nx*0.55), int(nz*0.55))]
        
    elif MODEL_TYPE == 'SEAM_3D':
        IS_3D_MODE = True
        shape, spacing = (50, 75, 75), (20.0, 20.0, 20.0) 
        velocity_file = os.getenv('SEAM_VELOCITY_FILE', './seam.bin')
        nx, ny, nz = shape
        candidates = [(x, y, 0) for x in range(5, nx-5, 2) for y in range(5, ny-5, 2)]
        if ADD_WELL_SENSORS:
            candidates += [(int(nx*0.1), int(ny*0.5), z) for z in range(5, nz-5, 5)]
        targets = [(x, y, int(nz*0.8)) for x in range(int(nx*0.4), int(nx*0.6), 2) for y in range(int(ny*0.4), int(ny*0.6), 2)]
        true_sources = [(int(nx*0.5), int(ny*0.5), int(nz*0.4)), 
                        (int(nx*0.45), int(ny*0.45), int(nz*0.6)), 
                        (int(nx*0.55), int(ny*0.55), int(nz*0.5))]
                        
    elif MODEL_TYPE == 'Anomaly_3D':
        IS_3D_MODE = True
        shape, spacing = (41, 41, 31), (20.0, 20.0, 20.0)
        velocity_file = None
        nx, ny, nz = shape
        candidates = [(x, y, 0) for x in range(2, 39, 6) for y in range(2, 39, 6)]
        if ADD_WELL_SENSORS:
            candidates += [(5, 5, z) for z in range(5, 25, 4)] + [(35, 35, z) for z in range(5, 25, 4)]
        targets = [(x, y, 20) for x in range(15, 25, 3) for y in range(15, 25, 3)]
        true_sources = [(20, 20, 20), (15, 15, 25), (25, 25, 15)]
        
    else:  # Anomaly_2D
        IS_3D_MODE = False
        shape, spacing = (81, 61), (10.0, 10.0)
        velocity_file = None
        nx, nz = shape
        candidates = [(x, 0) for x in range(5, nx-5, 3)]
        if ADD_WELL_SENSORS:
             candidates += [(10, z) for z in range(5, nz-5, 3)] + [(70, z) for z in range(5, nz-5, 3)]
        targets = [(x, z) for x in range(30, 50, 5) for z in range(35, 45, 2)]
        true_sources = [(40, 40), (35, 45), (45, 35)] 

    candidates, targets, resource_profile = _apply_marmousi_resource_profile(
        analysis_config, MODEL_TYPE, candidates, targets
    )
    _atomic_write_json(
        os.path.join(reviewer_output_dir, 'marmousi_resource_profile.json'),
        resource_profile,
    )
    # The profile may have changed safe defaults after MODEL_TYPE became known.
    _atomic_write_json(
        os.path.join(reviewer_output_dir, 'analysis_configuration.json'),
        analysis_config,
    )
    if resource_profile['enabled']:
        print(
            '>>> Marmousi resource profile: '
            f"{resource_profile['original_target_count']} -> "
            f"{resource_profile['design_target_count']} design targets; "
            f"{resource_profile['original_candidate_count']} -> "
            f"{resource_profile['design_candidate_count']} candidate sites."
        )

    phys = PhysicsEngine(shape, spacing, is_3d=IS_3D_MODE, velocity_file=velocity_file)
    optimizer = BayesianOptimizer(phys, candidates, targets)
    comparison_candidates = optimizer.candidates
    ensemble_records = None
    ensemble_rtm_context = None
    robust_records = None
    if analysis_config.get('run_path_correlated_joint_design', True):
        robust_start = time.perf_counter()
        robust_records = run_path_correlated_joint_design_validation(
            phys, comparison_candidates, targets, true_sources,
            reviewer_output_dir, analysis_config,
        )
        ensemble_records = robust_records
        cost_records.append({
            'stage': 'robust reference-velocity experimental design',
            'method': (
                'Path-correlated model discrepancy, joint receiver/'
                'calibration-source design, calibrated intervals, and '
                'four-way split twin validation'
            ),
            'wall_seconds': float(time.perf_counter() - robust_start),
            'number_of_geophones': int(
                robust_records['selected_designs'][
                    'selected_number_of_receivers'
                ]
            ),
            'number_of_velocity_cases': int(sum(
                robust_records['velocity_split_counts'].values()
            )),
        })
        if os.getenv('RUN_MAIN_MODEL_ADVANTAGE_EVIDENCE', '1') != '0':
            evidence_start = time.perf_counter()
            main_evidence_dir = os.path.join(
                reviewer_output_dir, 'main_model_advantage_evidence'
            )
            evidence_manifest = run_main_model_advantage_evidence_from_records(
                robust_records, phys, MODEL_TYPE, main_evidence_dir
            )
            robust_records['main_model_advantage_evidence'] = evidence_manifest
            cost_records.append({
                'stage': 'main-model advantage evidence figures',
                'method': (
                    'Reuse current paired robust records for localization, '
                    'coverage, covariance-ablation, migration, tail-risk, '
                    'failure, cost, and bootstrap evidence'
                ),
                'wall_seconds': float(time.perf_counter() - evidence_start),
                'number_of_velocity_cases': int(sum(
                    robust_records['velocity_split_counts'].values()
                )),
                'number_of_migration_scenarios': int(
                    evidence_manifest['evaluated_migration_scenarios']
                ),
            })

    # 5. Fast ray-tube constrained differential-traveltime coherence migration;
    # RUN_DEVITO_RTM remains a legacy fallback switch, but Devito and stored
    # time-domain wavefields are not required by the active imaging method.
    run_fast_psdm = os.getenv(
        'RUN_FAST_PSDM', os.getenv('RUN_DEVITO_RTM', '1')
    ) == '1'
    if run_fast_psdm:
        print(
            "\n>>> Fast ray-tube constrained differential-traveltime coherence "
            "migration is enabled; no time-domain wavefield will be generated."
        )
    else:
        print("\n>>> Fast PSDM is disabled; set RUN_FAST_PSDM=1 to enable it.")

    if run_fast_psdm:
        if ensemble_rtm_context is None:
            print(
                ">>> A separate legacy fast-PSDM pass is skipped because the "
                "posterior-objective design has already written the final "
                "comparisons without retaining a true velocity model in inversion."
            )
        else:
            rtm_start = time.perf_counter()
            rtm_inventory = run_four_design_velocity_rtm_comparison(
                phys,
                ensemble_rtm_context['cases'],
                ensemble_rtm_context['robust_sensors'],
                ensemble_rtm_context['nominal_sensors'],
                ensemble_rtm_context['random_sensors'],
                ensemble_rtm_context['uniform_sensors'],
                true_sources,
                ensemble_rtm_context['analysis_dir'],
                legacy_output_dir=output_dir,
                target_indices=targets,
            )
            cost_records.append({
                'stage': 'prestack depth migration imaging',
                'method': (
                    'Four-array smoothed-ray differential-traveltime coherence '
                    'migration of one new unknown-true-model data set with one '
                    'fixed reference migration velocity'
                ),
                'wall_seconds': float(time.perf_counter() - rtm_start),
                'number_of_sources': len(true_sources),
                'number_of_observation_systems': 4,
                'number_of_velocity_experiments': len(
                    rtm_inventory['experiments']
                ),
            })
            ensemble_records['four_design_rtm_comparison'] = rtm_inventory
            with open(
                    os.path.join(
                        ensemble_rtm_context['analysis_dir'],
                        'ensemble_velocity_design.json',
                    ),
                    'w', encoding='utf-8') as stream:
                json.dump(ensemble_records, stream, indent=2)
            write_computational_cost(reviewer_output_dir, cost_records)
    
    print(f"\n>>> Process Finished! All proofs, objective constraints, and separated visualizations have been executed. See '{output_dir}'.")

if __name__ == "__main__":
    if os.getenv('ROBUST_LOCALIZATION_MIGRATION_CASE_ONLY', '0') == '1':
        evidence_output = os.getenv(
            'LOCALIZATION_MIGRATION_OUTPUT_DIR',
            'localization_migration_advantage_output',
        )
        run_localization_migration_advantage_evidence(
            evidence_output,
            fast=os.getenv('LOCALIZATION_MIGRATION_CASE_FAST', '0') == '1',
        )
    elif os.getenv('ROBUST_ADVANTAGE_CASE_ONLY', '0') == '1':
        advantage_output = os.getenv(
            'ADVANTAGE_CASE_OUTPUT_DIR', 'advantage_case_output'
        )
        run_robust_advantage_demonstration_case(
            advantage_output,
            fast=os.getenv('ADVANTAGE_CASE_FAST', '0') == '1',
        )
    else:
        main()
